function loadLocalEnvFile(filePath) {
  if (process.env.BNA_SKIP_ENV_LOCAL === '1') return;

  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    for (const rawLine of raw.split(/\r?\n/)) {
      let line = rawLine.trim();
      if (!line || line.startsWith('#')) continue;
      if (line.startsWith('export ')) line = line.slice('export '.length).trim();
      const separator = line.indexOf('=');
      if (separator <= 0) continue;

      const key = line.slice(0, separator).trim();
      if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) continue;
      if (Object.prototype.hasOwnProperty.call(process.env, key)) continue;

      let value = line.slice(separator + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      process.env[key] = value;
    }
  } catch (error) {
    if (error && error.code !== 'ENOENT') {
      console.warn(`Could not load .env.local: ${error.message}`);
    }
  }
}

loadLocalEnvFile(path.join(__dirname, '.env.local'));

const app = express();
const PORT = process.env.PORT || 8080;
const HOST = process.env.HOST || process.env.BNA_BIND_HOST || '0.0.0.0';

app.disable('x-powered-by');
app.set('trust proxy', 1);
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Referrer-Policy', 'same-origin');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=(), clipboard-write=(self)');
  if (
    req.secure ||
    String(req.headers['x-forwarded-proto'] || '').split(',')[0].trim().toLowerCase() === 'https'
  ) {
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  }
  if (
    req.path === '/operations' ||
    req.path === '/operations-access' ||
    req.path === '/one-time-parent' ||
    req.path.startsWith('/api/bna/') ||
    req.path.startsWith('/api/parent') ||
    req.path.startsWith('/api/parent-portal') ||
    req.path.startsWith('/api/student-portal') ||
    req.path.startsWith('/api/provider-portal') ||
    req.path.startsWith('/api/member-portal') ||
    req.path.startsWith('/api/rabbi/member')
  ) {
    res.setHeader('X-Robots-Tag', 'noindex, nofollow, noarchive');
    res.setHeader('Cache-Control', 'no-store');
  }
  next();
});

