async function ensureAbandonedCheckoutTask({ signup, attempt, step = 'abandoned_checkout_1' } = {}, db = pool) {
  if (!signup?.id || !attempt?.id) return null;
  const project = await getProjectByKey(signup.project_key || DEFAULT_PROJECT_KEY, db);
  const title = `Follow up abandoned checkout for ${signup.parent_name || signup.parent_email || `signup #${signup.id}`}`;
  const existing = (await db.query(
    `SELECT *
     FROM bna_tasks
     WHERE related_signup_id = $1
       AND COALESCE(stage, '') NOT IN ('done', 'archive')
       AND lower(title) = lower($2)
     ORDER BY created_at DESC
     LIMIT 1`,
    [signup.id, title]
  )).rows[0] || null;
  if (existing) return existing;
  const result = await db.query(
    `INSERT INTO bna_tasks (
       project_id, project_key, title, summary, notes, stage, category, urgency,
       assigned_to, waiting_on, item_type, source, related_signup_id,
       created_by, source_context, ai_parsed, next_action_label, last_activity_at
     ) VALUES (
       $1, $2, $3, $4, $5, 'assigned', 'accounting', 'today',
       'Shloimie', 'Parent/payment processor', 'task', 'web', $6,
       'system', $7, $8, 'Follow up payment', NOW()
     )
     RETURNING *`,
    [
      project.id,
      project.project_key,
      title,
      'Credit checkout started but no payment webhook/success was recorded in the configured follow-up window.',
      [
        `Signup #${signup.id}`,
        `Checkout attempt #${attempt.id}`,
        `Parent: ${signup.parent_name || ''} <${signup.parent_email || ''}>`,
        `Student: ${signup.student_name || ''}`,
        `Step: ${step}`,
        'Do not send additional live messages unless approved and opt-out rules are respected.',
      ].join('\n'),
      signup.id,
      JSON.stringify({ checkout_attempt_id: attempt.id, step }),
      JSON.stringify({ parser: 'abandoned-checkout-sweep-v1', agent_executable: false }),
    ]
  );
  return result.rows[0] || null;
}

function nextAbandonedCheckoutStep({ signup, attempt, sentTypes = [] } = {}) {
  const startedAt = new Date(attempt.redirected_at || attempt.started_at || attempt.created_at || Date.now()).getTime();
  const ageHours = Math.max(0, (Date.now() - startedAt) / (60 * 60 * 1000));
  const sent = new Set(sentTypes);
  const schedule = [
    { type: 'abandoned_checkout_1', hours: ABANDONED_CHECKOUT_MINUTES / 60 },
    { type: 'abandoned_checkout_24h', hours: 24 },
    { type: 'abandoned_checkout_72h', hours: 72 },
  ];
  return schedule.find((item) => ageHours >= item.hours && !sent.has(item.type))?.type || null;
}

async function runAbandonedCheckoutSweep({ dryRun = true, sendEmails = false, limit = 50 } = {}, db = pool) {
  const candidates = (await db.query(
    `SELECT a.*,
            s.parent_name, s.parent_email, s.parent_phone, s.student_name,
            s.form_language, s.payment_amount, s.payment_status, s.project_id
     FROM bna_checkout_attempts a
     JOIN signups s ON s.id = a.signup_id
     WHERE a.status IN ('started', 'redirected', 'manual_followup')
       AND COALESCE(s.payment_status, 'pending') <> 'paid'
       AND COALESCE(a.redirected_at, a.started_at, a.created_at) <= NOW() - (($1::text || ' minutes')::interval)
     ORDER BY COALESCE(a.redirected_at, a.started_at, a.created_at) ASC
     LIMIT $2`,
    [ABANDONED_CHECKOUT_MINUTES, Math.min(Number(limit) || 50, 200)]
  )).rows;

  const processed = [];
  const failed = [];
  for (const row of candidates) {
    try {
      const sentRows = (await db.query(
        `SELECT email_type FROM bna_email_log WHERE signup_id = $1 AND email_type LIKE 'abandoned_checkout_%'`,
        [row.signup_id]
      )).rows.map((item) => item.email_type);
      const step = nextAbandonedCheckoutStep({ attempt: row, sentTypes: sentRows });
      const summary = {
        checkout_attempt_id: row.id,
        signup_id: row.signup_id,
        parent_email: row.parent_email,
        status: row.status,
        step,
        dryRun,
        email_sent: false,
      };
      if (!step) {
        processed.push({ ...summary, skipped: 'no_due_step' });
        continue;
      }
      if (!dryRun) {
        const updated = (await db.query(
          `UPDATE bna_checkout_attempts
           SET status = 'abandoned',
               abandoned_at = COALESCE(abandoned_at, NOW()),
               updated_at = NOW()
           WHERE id = $1
           RETURNING *`,
          [row.id]
        )).rows[0] || row;
        await ensureAbandonedCheckoutTask({ signup: row, attempt: updated, step }, db);
        await logCommunication({
          workspaceId: updated.workspace_id || null,
          signupId: row.signup_id,
          channel: 'system',
          direction: 'internal',
          communicationType: 'checkout_abandoned',
          subject: 'Checkout marked abandoned',
          bodyText: `Checkout attempt #${row.id} was marked abandoned after no payment webhook/success was recorded.`,
          status: 'abandoned',
          metadata: { checkout_attempt_id: row.id, step },
        });
        if (sendEmails && row.parent_email) {
          const email = abandonedCheckoutEmail(row, step, row.payment_link || '');
          const result = await sendEmail({
            to: row.parent_email,
            subject: email.subject,
            text: email.text,
            html: email.html,
          });
          await logEmail({
            signupId: row.signup_id,
            emailType: step,
            to: row.parent_email,
            subject: email.subject,
            text: email.text,
            html: email.html,
            language: row.form_language,
            providerMessageId: result.data.id,
            provider: result.provider,
            metadata: { checkout_attempt_id: row.id, abandoned_step: step },
          });
          await db.query('UPDATE bna_checkout_attempts SET last_reminder_at = NOW(), updated_at = NOW() WHERE id = $1', [row.id]);
          summary.email_sent = true;
        }
      }
      processed.push(summary);
    } catch (error) {
      failed.push({
        checkout_attempt_id: row.id,
        signup_id: row.signup_id,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return {
    success: failed.length === 0,
    dryRun,
    sendEmails,
    abandoned_after_minutes: ABANDONED_CHECKOUT_MINUTES,
    found: candidates.length,
    processed,
    failed,
  };
}

function startPaymentReminderScheduler() {
  if (!isPaymentReminderSchedulerLiveEnabled()) {
    if (String(process.env.PAYMENT_REMINDER_SCHEDULER || '').trim()) {
      console.log('Payment reminder scheduler is disabled until live opt-in and approval phrase are configured.');
    }
    return;
  }
  const intervalMs = Number(process.env.PAYMENT_REMINDER_SWEEP_MS || 6 * 60 * 60 * 1000);
  setInterval(() => {
    runPaymentReminderSweep({ dryRun: false })
      .then((result) => {
        if (result.found || result.failed.length) {
          console.log(`Payment reminder sweep: found=${result.found} sent=${result.sent.length} failed=${result.failed.length}`);
        }
      })
      .catch((error) => console.error('Payment reminder sweep failed:', error));
  }, intervalMs).unref();
}

async function findDriveFolder(drive, name, parentId = 'root') {
  const safeName = String(name).replace(/'/g, "\\'");
  const safeParent = String(parentId).replace(/'/g, "\\'");
  const result = await drive.files.list({
    q: [
      "mimeType='application/vnd.google-apps.folder'",
      'trashed=false',
      `name='${safeName}'`,
      `'${safeParent}' in parents`,
    ].join(' and '),
    fields: 'files(id,name,webViewLink)',
    pageSize: 10,
    supportsAllDrives: true,
    includeItemsFromAllDrives: true,
  });
  return result.data.files?.[0] || null;
}

async function ensureDriveFolder(drive, name, parentId = 'root') {
  const existing = await findDriveFolder(drive, name, parentId);
  if (existing) return { ...existing, created: false };

  const created = await drive.files.create({
    requestBody: {
      name,
      mimeType: 'application/vnd.google-apps.folder',
      parents: parentId === 'root' ? undefined : [parentId],
    },
    fields: 'id,name,webViewLink',
    supportsAllDrives: true,
  });
  return { ...created.data, created: true };
}

async function ensureGoogleDoc(drive, name, parentId) {
  const safeName = String(name).replace(/'/g, "\\'");
  const safeParent = String(parentId).replace(/'/g, "\\'");
  const existing = await drive.files.list({
    q: [
      "mimeType='application/vnd.google-apps.document'",
      'trashed=false',
      `name='${safeName}'`,
      `'${safeParent}' in parents`,
    ].join(' and '),
    fields: 'files(id,name,webViewLink)',
    pageSize: 10,
    supportsAllDrives: true,
    includeItemsFromAllDrives: true,
  });
  if (existing.data.files?.[0]) return { ...existing.data.files[0], created: false };

  const created = await drive.files.create({
    requestBody: {
      name,
      mimeType: 'application/vnd.google-apps.document',
      parents: [parentId],
    },
    fields: 'id,name,webViewLink',
    supportsAllDrives: true,
  });
  return { ...created.data, created: true };
}

async function ensureBnaDrivePipeline(auth) {
  const drive = google.drive({ version: 'v3', auth });
  const root = await ensureDriveFolder(drive, GOOGLE_DRIVE_PIPELINE_ROOT_NAME, 'root');
  const websiteMomentsIntake = await ensureDriveFolder(drive, '00 Upload Here - Website Images', root.id);
  const rawIntake = await ensureDriveFolder(drive, '00 Upload Here - Raw Media Intake', root.id);
  const processing = await ensureDriveFolder(drive, '10 Processing - Temporary', root.id);
  const processed = await ensureDriveFolder(drive, '20 Processed Recordings - Source Media', root.id);
  const approved = await ensureDriveFolder(drive, '30 Approved Website Assets', root.id);
  const failed = await ensureDriveFolder(drive, '90 Failed - Needs Review', root.id);
  const legacy = await ensureDriveFolder(drive, '_Archive - Legacy Pipeline Folders', root.id);

  const folders = {
    '01 Raw Intake': rawIntake,
    '02 Ingesting': processing,
    '03 Transcribed': processed,
    '04 Parsed': processed,
    '05 WhatsApp Ready': processed,
    '06 Newsletter Candidates': processed,
    '07 Social Candidates': processed,
    '08 Blog Candidates': processed,
    '09 Brand Kit Suggestions': legacy,
    '10 Approved': approved,
    '11 Published': approved,
    '99 Failed': failed,
  };

  const brandKit = await ensureDriveFolder(drive, 'GitHub Canonical - Drive Brand Mirror (Deprecated)', legacy.id);
  const brandDocs = {};
  for (const docName of [
    '01 Core Beliefs',
    '02 Teaching Voice',
    '03 Parent Messaging',
    '04 Student Growth Principles',
    '05 Phrases To Use',
    '06 Phrases To Avoid',
    '07 Brand Kit Suggestions Inbox',
  ]) {
    brandDocs[docName] = await ensureGoogleDoc(drive, docName, brandKit.id);
  }

  const platformMemory = await ensureDriveFolder(drive, 'Platform Memory', brandKit.id);
  const platformDocs = {};
  for (const docName of [
    'WhatsApp Prompt',
    'WhatsApp Approved Examples',
    'Facebook Prompt',
    'Facebook Approved Examples',
    'YouTube Prompt',
    'Blog Prompt',
    'Newsletter Prompt',
  ]) {
    platformDocs[docName] = await ensureGoogleDoc(drive, docName, platformMemory.id);
  }

  return {
    root,
    websiteMomentsIntake,
    folders,
    legacy,
    brandKit,
    brandDocs,
    platformMemory,
    platformDocs,
  };
}

function parseCookies(req) {
  const rawCookie = req.headers.cookie || '';
  if (!rawCookie) return {};

  return rawCookie
    .split(';')
    .map((part) => part.trim())
    .filter(Boolean)
    .reduce((acc, part) => {
      const separatorIndex = part.indexOf('=');
      if (separatorIndex <= 0) return acc;
      const key = part.slice(0, separatorIndex);
      const value = decodeURIComponent(part.slice(separatorIndex + 1));
      acc[key] = value;
      return acc;
    }, {});
}

function generateStudentAccessCode() {
  return crypto.randomBytes(9).toString('base64url');
}

function studentPortalUrl(req, code) {
  const forwardedProto = String(req.get('x-forwarded-proto') || '').split(',')[0].trim();
  const protocol = forwardedProto || req.protocol || 'https';
  const origin = `${protocol}://${req.get('host')}`;
  return `${origin}/student.html?code=${encodeURIComponent(code)}`;
}

async function ensureStudentAccessCode(studentId, { regenerate = false } = {}, db = pool) {
  const current = (await db.query(
    `SELECT id, name, student_access_code
     FROM bna_students
     WHERE id = $1
       AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')`,
    [studentId]
  )).rows[0];
  if (!current) {
    throw new Error('Student not found');
  }
  if (current.student_access_code && !regenerate) {
    return current.student_access_code;
  }

  for (let attempt = 0; attempt < 5; attempt += 1) {
    const code = generateStudentAccessCode();
    try {
      const result = await db.query(
        `UPDATE bna_students
         SET student_access_code = $2,
             student_access_enabled = TRUE,
             student_access_created_at = COALESCE(student_access_created_at, NOW()),
             updated_at = NOW()
         WHERE id = $1
         RETURNING student_access_code`,
        [studentId, code]
      );
      return result.rows[0].student_access_code;
    } catch (error) {
      if (error.code !== '23505') throw error;
    }
  }
  throw new Error('Could not generate a unique student access code');
}

async function findStudentByAccessCode(code, db = pool) {
  return (await db.query(
    `SELECT id, name, name_en, name_he, parent_name, parent_email, parent_phone, current_school, tags, status
     FROM bna_students
     WHERE student_access_code = $1
       AND COALESCE(student_access_enabled, TRUE) = TRUE
       AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')
     LIMIT 1`,
    [String(code || '').trim()]
  )).rows[0] || null;
}

const STUDENT_PORTAL_AUTH_WINDOW_MS = 15 * 60 * 1000;
const STUDENT_PORTAL_AUTH_MAX_FAILURES = 8;
const STUDENT_PORTAL_AUTH_WINDOW_SQL = '15 minutes';
const studentPortalAuthFailures = new Map();

function studentPortalAuthFailureKey(req, code) {
  return `${getRequestIp(req) || 'unknown'}:${sha256Hex(String(code || '').trim()).slice(0, 24)}`;
}

function studentPortalAuthAuditRoute(req) {
  const rawRoute = String(req?.originalUrl || req?.url || req?.path || '');
  try {
    const parsed = new URL(rawRoute, 'http://bna.local');
    return parsed.pathname.slice(0, 240);
  } catch {
    return rawRoute.split('?')[0].slice(0, 240);
  }
}

function studentPortalAuthAuditIdentity(req, code) {
  return {
    requestIpHash: sha256Hex(getRequestIp(req) || 'unknown'),
    accessCodeHash: sha256Hex(String(code || '').trim()),
    route: studentPortalAuthAuditRoute(req),
    userAgentHash: req?.headers?.['user-agent'] ? sha256Hex(req.headers['user-agent']) : null,
  };
}

async function countPersistentStudentPortalAuthFailures(req, code, db = pool) {
  const identity = studentPortalAuthAuditIdentity(req, code);
  try {
    const result = await db.query(
      `WITH last_success AS (
         SELECT MAX(attempted_at) AS attempted_at
         FROM bna_student_portal_auth_attempts
         WHERE request_ip_hash = $1
           AND access_code_hash = $2
           AND outcome = 'success'
       )
       SELECT COUNT(*)::int AS failure_count
       FROM bna_student_portal_auth_attempts attempts
       CROSS JOIN last_success
       WHERE attempts.request_ip_hash = $1
         AND attempts.access_code_hash = $2
         AND attempts.outcome = 'failure'
         AND attempts.attempted_at >= NOW() - ($3::interval)
         AND (
           last_success.attempted_at IS NULL
           OR attempts.attempted_at > last_success.attempted_at
         )`,
      [identity.requestIpHash, identity.accessCodeHash, STUDENT_PORTAL_AUTH_WINDOW_SQL]
    );
    return Number(result.rows[0]?.failure_count || 0);
  } catch (error) {
    console.warn('Student portal persistent auth failure count unavailable', error.message);
    return null;
  }
}

async function recordPersistentStudentPortalAuthAttempt(req, code, { outcome, studentId = null, metadata = {} } = {}, db = pool) {
  const safeOutcome = ['failure', 'success', 'throttled'].includes(outcome) ? outcome : 'failure';
  const identity = studentPortalAuthAuditIdentity(req, code);
  try {
    await db.query(
      `INSERT INTO bna_student_portal_auth_attempts (
         outcome, request_ip_hash, access_code_hash, student_id, route,
         user_agent_hash, metadata
       ) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
      [
        safeOutcome,
        identity.requestIpHash,
        identity.accessCodeHash,
        studentId,
        identity.route,
        identity.userAgentHash,
        JSON.stringify({
          ...metadata,
          auth_model: 'private_access_code_only',
          raw_access_code_stored: false,
          raw_ip_stored: false,
        }),
      ]
    );
  } catch (error) {
    console.warn('Student portal persistent auth attempt audit unavailable', error.message);
  }
}

function pruneStudentPortalAuthFailures(now = Date.now()) {
  for (const [key, entry] of studentPortalAuthFailures.entries()) {
    if (!entry || now - Number(entry.firstFailureAt || 0) > STUDENT_PORTAL_AUTH_WINDOW_MS) {
      studentPortalAuthFailures.delete(key);
    }
  }
}

function recordStudentPortalAuthFailure(req, code) {
  const now = Date.now();
  pruneStudentPortalAuthFailures(now);
  const key = studentPortalAuthFailureKey(req, code);
  const previous = studentPortalAuthFailures.get(key);
  const entry = previous && now - previous.firstFailureAt <= STUDENT_PORTAL_AUTH_WINDOW_MS
    ? { firstFailureAt: previous.firstFailureAt, count: previous.count + 1 }
    : { firstFailureAt: now, count: 1 };
  studentPortalAuthFailures.set(key, entry);
  return entry;
}

function clearStudentPortalAuthFailures(req, code) {
  studentPortalAuthFailures.delete(studentPortalAuthFailureKey(req, code));
}

async function getStudentForPortalSessionRequest(req, db = pool) {
  const cookies = parseCookies(req);
  const session = await getValidStudentSession(cookies[STUDENT_SESSION_COOKIE_NAME], db).catch(() => null);
  return session?.student || null;
}

async function getStudentForPortalCredential(req, res, code, db = pool) {
  const trimmedCode = String(code || '').trim();
  if (!trimmedCode) {
    const sessionStudent = await getStudentForPortalSessionRequest(req, db);
    if (sessionStudent) return sessionStudent;
    await recordPersistentStudentPortalAuthAttempt(req, trimmedCode, {
      outcome: 'failure',
      metadata: { reason: 'missing_code' },
    });
    res.status(401).json({ error: 'A valid student access code is required' });
    return null;
  }

  const persistentFailureCount = await countPersistentStudentPortalAuthFailures(req, trimmedCode);
  if (persistentFailureCount !== null && persistentFailureCount >= STUDENT_PORTAL_AUTH_MAX_FAILURES) {
    await recordPersistentStudentPortalAuthAttempt(req, trimmedCode, {
      outcome: 'throttled',
      metadata: {
        reason: 'persistent_rate_limit',
        failure_count: persistentFailureCount,
      },
    });
    res.status(429).json({ error: 'Too many failed access attempts. Please wait and try again.' });
    return null;
  }

  const key = studentPortalAuthFailureKey(req, trimmedCode);
  const previous = studentPortalAuthFailures.get(key);
  if (
    previous
    && previous.count >= STUDENT_PORTAL_AUTH_MAX_FAILURES
    && Date.now() - previous.firstFailureAt <= STUDENT_PORTAL_AUTH_WINDOW_MS
  ) {
    await recordPersistentStudentPortalAuthAttempt(req, trimmedCode, {
      outcome: 'throttled',
      metadata: {
        reason: 'memory_rate_limit',
        failure_count: previous.count,
      },
    });
    res.status(429).json({ error: 'Too many failed access attempts. Please wait and try again.' });
    return null;
  }

  const student = await findStudentByAccessCode(trimmedCode, db);
  if (!student) {
    recordStudentPortalAuthFailure(req, trimmedCode);
    await recordPersistentStudentPortalAuthAttempt(req, trimmedCode, {
      outcome: 'failure',
      metadata: { reason: 'invalid_or_expired_code' },
    });
    res.status(401).json({ error: 'Invalid or expired student access code' });
    return null;
  }

  clearStudentPortalAuthFailures(req, trimmedCode);
  await recordPersistentStudentPortalAuthAttempt(req, trimmedCode, {
    outcome: 'success',
    studentId: student.id,
    metadata: { reason: 'valid_code' },
  });
  return student;
}

function studentPasswordAuthAuditIdentity(req, usernameNormalized = '') {
  return {
    requestIpHash: sha256Hex(getRequestIp(req) || 'unknown'),
    usernameHash: sha256Hex(String(usernameNormalized || '').trim().toLowerCase()),
    routePath: studentPortalAuthAuditRoute(req),
    userAgentHash: req?.headers?.['user-agent'] ? sha256Hex(req.headers['user-agent']) : null,
  };
}

async function countPersistentStudentPasswordAuthFailures(req, usernameNormalized, db = pool) {
  const identity = studentPasswordAuthAuditIdentity(req, usernameNormalized);
  try {
    const result = await db.query(
      `WITH last_success AS (
         SELECT MAX(created_at) AS created_at
         FROM bna_student_password_auth_attempts
         WHERE request_ip_hash = $1
           AND username_hash = $2
           AND outcome = 'success'
       )
       SELECT COUNT(*)::int AS failure_count
       FROM bna_student_password_auth_attempts attempts
       CROSS JOIN last_success
       WHERE attempts.request_ip_hash = $1
         AND attempts.username_hash = $2
         AND attempts.outcome = 'failure'
         AND attempts.created_at >= NOW() - ($3::interval)
         AND (
           last_success.created_at IS NULL
           OR attempts.created_at > last_success.created_at
         )`,
      [identity.requestIpHash, identity.usernameHash, STUDENT_PORTAL_AUTH_WINDOW_SQL]
    );
    return Number(result.rows[0]?.failure_count || 0);
  } catch (error) {
    console.warn('Student password persistent auth failure count unavailable', error.message);
    return null;
  }
}

async function recordPersistentStudentPasswordAuthAttempt(req, usernameNormalized, { outcome, studentId = null, metadata = {} } = {}, db = pool) {
  const safeOutcome = ['failure', 'success', 'throttled'].includes(outcome) ? outcome : 'failure';
  const identity = studentPasswordAuthAuditIdentity(req, usernameNormalized);
  try {
    await db.query(
      `INSERT INTO bna_student_password_auth_attempts (
         outcome, request_ip_hash, username_hash, student_id, route_path,
         user_agent_hash, metadata
       ) VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb)`,
      [
        safeOutcome,
        identity.requestIpHash,
        identity.usernameHash,
        studentId,
        identity.routePath,
        identity.userAgentHash,
        JSON.stringify({
          ...metadata,
          auth_model: 'parent_managed_username_password',
          raw_password_stored: false,
          raw_username_stored: false,
          raw_username_password_combo_stored: false,
          raw_access_code_stored: false,
          raw_ip_stored: false,
        }),
      ]
    );
  } catch (error) {
    console.warn('Student password auth attempt audit unavailable', error.message);
  }
}

function studentPasswordAccountView(row = {}) {
  if (!row || !row.student_id) {
    return {
      has_account: false,
      username: '',
      status: 'not_set',
      password_set_at: null,
      last_login_at: null,
      updated_at: null,
    };
  }
  return {
    has_account: true,
    student_id: Number(row.student_id),
    username: row.username || '',
    status: row.status || 'active',
    password_set_at: row.password_set_at || null,
    last_login_at: row.last_login_at || null,
    updated_at: row.updated_at || null,
  };
}

async function getStudentPasswordAccountForParent(studentId, db = pool) {
  const row = (await db.query(
    `SELECT student_id, username, status, password_set_at, last_login_at, updated_at
     FROM bna_student_password_accounts
     WHERE student_id = $1
       AND status <> 'archived'
     LIMIT 1`,
    [Number(studentId)]
  )).rows[0] || null;
  return studentPasswordAccountView(row);
}

async function setStudentPasswordAccountForParent({ student, parentEmail, username, password }, db = pool) {
  const studentId = Number(student?.id || 0);
  if (!Number.isFinite(studentId) || studentId <= 0) {
    const error = new Error('Student was not found for this parent session');
    error.statusCode = 404;
    throw error;
  }
  const { username: displayUsername, usernameNormalized } = validateStudentLoginUsername(username);
  const rawPassword = validateParentPassword(password);
  const passwordHash = studentPasswordHash(rawPassword);
  try {
    const row = (await db.query(
      `INSERT INTO bna_student_password_accounts (
         student_id, username, username_normalized, password_hash,
         status, parent_set_by_email, password_set_at, updated_at
       ) VALUES ($1, $2, $3, $4, 'active', $5, NOW(), NOW())
       ON CONFLICT (student_id) DO UPDATE SET
         username = EXCLUDED.username,
         username_normalized = EXCLUDED.username_normalized,
         password_hash = EXCLUDED.password_hash,
         status = 'active',
         parent_set_by_email = EXCLUDED.parent_set_by_email,
         password_set_at = NOW(),
         updated_at = NOW()
       RETURNING student_id, username, status, password_set_at, last_login_at, updated_at`,
      [
        studentId,
        displayUsername,
        usernameNormalized,
        passwordHash,
        normalizeEmail(parentEmail) || null,
      ]
    )).rows[0];
    return studentPasswordAccountView(row);
  } catch (error) {
    if (error.code === '23505') {
      const conflict = new Error('That student username is already in use');
      conflict.statusCode = 409;
      throw conflict;
    }
    throw error;
  }
}

function goalBoardAdminView(row) {
  const goalBoard = normalizeGoalBoardMetadata(rawGoalBoardMetadata(row?.metadata), {
    category: row?.topic || '',
  });
  return {
    ...row,
    metadata: row?.metadata || {},
    goal_board: goalBoard,
    goal_board_status: goalBoardStatus(row),
    goal_board_bucket: goalBoardBucket(row),
    student_view: safeGoalBoardStudentView(row),
  };
}

function goalBoardMetadataFromPayload(payload = {}, previousMetadata = {}) {
  const existingGoalBoard = normalizeGoalBoardMetadata(rawGoalBoardMetadata(previousMetadata));
  const explicitGoalBoard = payload.goal_board && typeof payload.goal_board === 'object' ? payload.goal_board : {};
  const explicitAgreement = explicitGoalBoard.agreement && typeof explicitGoalBoard.agreement === 'object' ? explicitGoalBoard.agreement : {};
  const explicitConsequence = explicitGoalBoard.consequence && typeof explicitGoalBoard.consequence === 'object' ? explicitGoalBoard.consequence : {};
  const explicitIncentive = explicitGoalBoard.incentive && typeof explicitGoalBoard.incentive === 'object' ? explicitGoalBoard.incentive : {};
  const source = payload.source || explicitGoalBoard.source || existingGoalBoard.source || 'admin';
  const nextAgreement = {
    ...(existingGoalBoard.agreement || {}),
    ...explicitAgreement,
    type: payload.agreement_type ?? explicitGoalBoard.agreement_type ?? explicitAgreement.type ?? existingGoalBoard.agreement?.type,
    bedtime_time: payload.bedtime_time ?? explicitGoalBoard.bedtime_time ?? explicitAgreement.bedtime_time ?? existingGoalBoard.agreement?.bedtime_time,
    wake_time: payload.wake_time ?? explicitGoalBoard.wake_time ?? explicitAgreement.wake_time ?? existingGoalBoard.agreement?.wake_time,
    student_commitment: payload.student_commitment ?? explicitGoalBoard.student_commitment ?? explicitAgreement.student_commitment ?? existingGoalBoard.agreement?.student_commitment,
    chosen_consequence: payload.chosen_consequence ?? explicitGoalBoard.chosen_consequence ?? explicitAgreement.chosen_consequence ?? existingGoalBoard.agreement?.chosen_consequence,
  };
  const nextConsequence = {
    ...(existingGoalBoard.consequence || {}),
    ...explicitConsequence,
    status: payload.consequence_status ?? explicitGoalBoard.consequence_status ?? explicitConsequence.status ?? existingGoalBoard.consequence?.status,
    recovery_path: payload.recovery_path ?? explicitGoalBoard.recovery_path ?? explicitConsequence.recovery_path ?? existingGoalBoard.consequence?.recovery_path,
    device_access_state: payload.device_access_state ?? explicitGoalBoard.device_access_state ?? explicitConsequence.device_access_state ?? existingGoalBoard.consequence?.device_access_state,
    duration_minutes: payload.duration_minutes ?? explicitGoalBoard.duration_minutes ?? explicitConsequence.duration_minutes ?? existingGoalBoard.consequence?.duration_minutes,
    auto_apply_on_completion: payload.auto_apply_on_completion ?? explicitGoalBoard.auto_apply_on_completion ?? explicitConsequence.auto_apply_on_completion ?? existingGoalBoard.consequence?.auto_apply_on_completion,
    success_device_access_state: payload.success_device_access_state ?? explicitGoalBoard.success_device_access_state ?? explicitConsequence.success_device_access_state ?? existingGoalBoard.consequence?.success_device_access_state,
    success_duration_minutes: payload.success_duration_minutes ?? explicitGoalBoard.success_duration_minutes ?? explicitConsequence.success_duration_minutes ?? existingGoalBoard.consequence?.success_duration_minutes,
    success_applied_at: payload.success_applied_at ?? explicitGoalBoard.success_applied_at ?? explicitConsequence.success_applied_at ?? existingGoalBoard.consequence?.success_applied_at,
    success_applied_by: payload.success_applied_by ?? explicitGoalBoard.success_applied_by ?? explicitConsequence.success_applied_by ?? existingGoalBoard.consequence?.success_applied_by,
    review_reason: payload.review_reason ?? explicitGoalBoard.review_reason ?? explicitConsequence.review_reason ?? existingGoalBoard.consequence?.review_reason,
  };
  const merged = {
    ...existingGoalBoard,
    ...explicitGoalBoard,
    source,
    category: payload.category ?? payload.topic ?? explicitGoalBoard.category ?? existingGoalBoard.category,
    section: payload.section ?? payload.goal_section ?? explicitGoalBoard.section ?? existingGoalBoard.section,
    subsection: payload.subsection ?? payload.goal_subsection ?? explicitGoalBoard.subsection ?? existingGoalBoard.subsection,
    urgency: payload.urgency ?? explicitGoalBoard.urgency ?? existingGoalBoard.urgency,
    status: payload.status ?? explicitGoalBoard.status ?? existingGoalBoard.status,
    due_at: payload.due_at ?? explicitGoalBoard.due_at ?? existingGoalBoard.due_at,
    optional_scheduled_at: payload.optional_scheduled_at ?? explicitGoalBoard.optional_scheduled_at ?? existingGoalBoard.optional_scheduled_at,
    student_owned: payload.student_owned ?? explicitGoalBoard.student_owned ?? source === 'self',
    student_visible: payload.student_visible ?? payload.share_with_student ?? explicitGoalBoard.student_visible ?? explicitGoalBoard.share_with_student ?? existingGoalBoard.student_visible,
    parent_visible: payload.parent_visible ?? payload.share_with_parent ?? explicitGoalBoard.parent_visible ?? explicitGoalBoard.share_with_parent ?? existingGoalBoard.parent_visible,
    approval_required: payload.approval_required ?? explicitGoalBoard.approval_required ?? existingGoalBoard.approval_required,
    approval_status: payload.approval_status ?? explicitGoalBoard.approval_status ?? existingGoalBoard.approval_status,
    student_summary: payload.student_summary ?? explicitGoalBoard.student_summary ?? existingGoalBoard.student_summary,
    private_note: payload.private_note ?? explicitGoalBoard.private_note ?? existingGoalBoard.private_note,
    reflection_note: payload.reflection_note ?? explicitGoalBoard.reflection_note ?? existingGoalBoard.reflection_note,
    checklist: Array.isArray(payload.checklist) ? payload.checklist : explicitGoalBoard.checklist ?? existingGoalBoard.checklist,
    agreement: nextAgreement,
    consequence: nextConsequence,
    youtube_url: payload.youtube_url ?? explicitGoalBoard.youtube_url ?? existingGoalBoard.classroom?.youtube_url,
    classroom_link: payload.classroom_link ?? explicitGoalBoard.classroom_link ?? existingGoalBoard.classroom?.alternate_link,
    classroom_state: payload.classroom_state ?? explicitGoalBoard.classroom_state ?? existingGoalBoard.classroom?.state,
    work_type: payload.work_type ?? explicitGoalBoard.work_type ?? existingGoalBoard.classroom?.work_type,
    agreement_type: payload.agreement_type ?? explicitGoalBoard.agreement_type ?? explicitAgreement.type ?? existingGoalBoard.agreement?.type,
    bedtime_time: payload.bedtime_time ?? explicitGoalBoard.bedtime_time ?? explicitAgreement.bedtime_time ?? existingGoalBoard.agreement?.bedtime_time,
    wake_time: payload.wake_time ?? explicitGoalBoard.wake_time ?? explicitAgreement.wake_time ?? existingGoalBoard.agreement?.wake_time,
    student_commitment: payload.student_commitment ?? explicitGoalBoard.student_commitment ?? explicitAgreement.student_commitment ?? existingGoalBoard.agreement?.student_commitment,
    chosen_consequence: payload.chosen_consequence ?? explicitGoalBoard.chosen_consequence ?? explicitAgreement.chosen_consequence ?? existingGoalBoard.agreement?.chosen_consequence,
    incentive: explicitIncentive,
    incentive_text: payload.incentive_text ?? payload.reward_text ?? explicitGoalBoard.incentive_text ?? explicitIncentive.text ?? existingGoalBoard.incentive?.text,
    incentive_chosen_by: payload.incentive_chosen_by ?? explicitGoalBoard.incentive_chosen_by ?? explicitIncentive.chosen_by ?? existingGoalBoard.incentive?.chosen_by,
    incentive_percent_target: payload.incentive_percent_target ?? explicitGoalBoard.incentive_percent_target ?? explicitIncentive.percent_target ?? existingGoalBoard.incentive?.percent_target,
    recovery_path: payload.recovery_path ?? explicitGoalBoard.recovery_path ?? explicitConsequence.recovery_path ?? existingGoalBoard.consequence?.recovery_path,
    device_access_state: payload.device_access_state ?? explicitGoalBoard.device_access_state ?? explicitConsequence.device_access_state ?? existingGoalBoard.consequence?.device_access_state,
    duration_minutes: payload.duration_minutes ?? explicitGoalBoard.duration_minutes ?? explicitConsequence.duration_minutes ?? existingGoalBoard.consequence?.duration_minutes,
    auto_apply_on_completion: payload.auto_apply_on_completion ?? explicitGoalBoard.auto_apply_on_completion ?? explicitConsequence.auto_apply_on_completion ?? existingGoalBoard.consequence?.auto_apply_on_completion,
    success_device_access_state: payload.success_device_access_state ?? explicitGoalBoard.success_device_access_state ?? explicitConsequence.success_device_access_state ?? existingGoalBoard.consequence?.success_device_access_state,
    success_duration_minutes: payload.success_duration_minutes ?? explicitGoalBoard.success_duration_minutes ?? explicitConsequence.success_duration_minutes ?? existingGoalBoard.consequence?.success_duration_minutes,
    success_applied_at: payload.success_applied_at ?? explicitGoalBoard.success_applied_at ?? explicitConsequence.success_applied_at ?? existingGoalBoard.consequence?.success_applied_at,
    success_applied_by: payload.success_applied_by ?? explicitGoalBoard.success_applied_by ?? explicitConsequence.success_applied_by ?? existingGoalBoard.consequence?.success_applied_by,
    consequence_status: payload.consequence_status ?? explicitGoalBoard.consequence_status ?? explicitConsequence.status ?? existingGoalBoard.consequence?.status,
    review_reason: payload.review_reason ?? explicitGoalBoard.review_reason ?? explicitConsequence.review_reason ?? existingGoalBoard.consequence?.review_reason,
  };

  if (merged.approval_required && !payload.approval_status && !explicitGoalBoard.approval_status) {
    merged.approval_status = 'pending_review';
    merged.status = 'waiting';
  }

  return metadataWithGoalBoard(previousMetadata, merged);
}

async function getGoalBoardEvent(id, db = pool) {
  return (await db.query(
    `SELECT a.*, row_to_json(s.*) AS student
     FROM bna_accountability_events a
     LEFT JOIN bna_students s ON s.id = a.student_id
     WHERE a.id = $1
       AND a.event_type = 'student_goal'
     LIMIT 1`,
    [id]
  )).rows[0] || null;
}

function safeIsoDateInput(value) {
  const text = toIsoDateValue(value);
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : '';
}

async function getStudentNextMeetingDate(studentId, db = pool) {
  const result = await db.query(
    `SELECT MIN(next_check_in_date)::date AS next_meeting_date
     FROM bna_accountability_events
     WHERE student_id = $1
       AND next_check_in_date IS NOT NULL
       AND next_check_in_date >= CURRENT_DATE
       AND COALESCE((metadata->'goal_board'->>'status'), '') <> 'archived'`,
    [studentId]
  );
  return result.rows[0]?.next_meeting_date ? toIsoDateValue(result.rows[0].next_meeting_date) : null;
}

function studentTagKeys(student = {}) {
  return normalizeTextArray(student.tags)
    .map((tag) => tag.toLowerCase().replace(/_/g, '-'));
}

function studentIsExternalAccountabilityPerson(student = {}) {
  const tags = studentTagKeys(student);
  const school = String(student.current_school || '').toLowerCase();
  return tags.some((tag) => ['external', 'external-accountability', 'not-bna-school', 'non-school', 'not-school'].includes(tag))
    || /\b(external|not bna|non[-\s]?school|not[-\s]?school)\b/.test(school);
}

function studentGenderGroup(student = {}) {
  const tags = studentTagKeys(student);
  if (tags.includes('girl') || tags.includes('girls')) return 'girl';
  if (tags.includes('boy') || tags.includes('boys')) return 'boy';
  return 'boy';
}

function studentAccountabilityAudience(student = {}) {
  return studentIsExternalAccountabilityPerson(student) ? 'external' : 'internal';
}

function nextDateForIsoWeekday(isoWeekday, fromDate = getTodayDateInTimeZone()) {
  const from = toIsoDateValue(fromDate) || getTodayDateInTimeZone();
  const date = new Date(`${from}T00:00:00Z`);
  if (!Number.isFinite(date.getTime())) return from;
  const jsDay = date.getUTCDay();
  const todayIso = jsDay === 0 ? 7 : jsDay;
  const delta = (Number(isoWeekday) - todayIso + 7) % 7;
  date.setUTCDate(date.getUTCDate() + delta);
  return date.toISOString().slice(0, 10);
}

function meetingSlotView(student, slot = null) {
  const audience = studentAccountabilityAudience(student);
  const gender = studentGenderGroup(student);
  if (!slot) {
    return {
      assigned: false,
      audience,
      gender,
      label: audience === 'external'
        ? 'External accountability person - no BNA school meeting slot assigned'
        : 'Weekly private meeting is not assigned yet',
    };
  }
  const nextDate = nextDateForIsoWeekday(slot.iso_weekday);
  return {
    assigned: true,
    audience,
    gender,
    weekday: slot.weekday,
    weekday_label: slot.weekday_label,
    start_time: slot.start_time,
    end_time: slot.end_time,
    time_label: `${slot.start_time}-${slot.end_time}`,
    timezone: BNA_TIME_ZONE,
    next_date: nextDate,
    next_at: `${nextDate}T${slot.start_time}:00`,
    label: `${slot.weekday_label} ${slot.start_time}-${slot.end_time}`,
  };
}

async function getWeeklyPrivateMeetingSlotForStudent(studentId, db = pool) {
  const rosterResult = await db.query(
    `SELECT id, name, current_school, tags, status
     FROM bna_students
     WHERE COALESCE(status, 'active') = 'active'
     ORDER BY lower(name), id`
  );
  const internalBoys = rosterResult.rows
    .filter((student) => !studentIsExternalAccountabilityPerson(student))
    .filter((student) => studentGenderGroup(student) === 'boy');
  const index = internalBoys.findIndex((student) => Number(student.id) === Number(studentId));
  if (index < 0) return null;
  const weekdays = [
    { weekday: 'sunday', weekday_label: 'Sunday', iso_weekday: 7 },
    { weekday: 'monday', weekday_label: 'Monday', iso_weekday: 1 },
    { weekday: 'tuesday', weekday_label: 'Tuesday', iso_weekday: 2 },
    { weekday: 'wednesday', weekday_label: 'Wednesday', iso_weekday: 3 },
    { weekday: 'thursday', weekday_label: 'Thursday', iso_weekday: 4 },
  ];
  const day = weekdays[index % weekdays.length];
  return {
    ...day,
    start_time: '09:40',
    end_time: '10:00',
    duration_minutes: 20,
    school_start_time: '10:00',
    slot_policy: 'one_twenty_minute_slot_sunday_thursday',
    assignment_rule: 'active_internal_boys_one_per_weekday',
    roster_size: internalBoys.length,
  };
}

function rabbiShloimieContactView({ studentName = '' } = {}) {
  const message = [
    studentName ? `Hi Rabbi Shloimie, this is about ${studentName}.` : 'Hi Rabbi Shloimie.',
    'I have a parent/student portal question.',
  ].join('\n');
  return {
    name: 'Rabbi Shloimie',
    whatsapp_configured: Boolean(normalizePhoneDigits(RABBI_SHLOIMIE_WHATSAPP_NUMBER)),
    whatsapp_url: whatsAppComposeUrl(RABBI_SHLOIMIE_WHATSAPP_NUMBER, message),
  };
}

function attendanceStatusKey(value) {
  const normalized = String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (['absent', 'missing', 'not_present'].includes(normalized)) return 'absent';
  if (['late', 'partial'].includes(normalized)) return 'partial';
  if (['excused', 'notified'].includes(normalized)) return 'excused';
  if (['present', 'here', 'attended'].includes(normalized)) return 'present';
  return normalized || 'present';
}

function attendanceSummaryView(attendance = []) {
  const today = getTodayDateInTimeZone();
  const rows = Array.isArray(attendance) ? attendance : [];
  const todayRow = rows.find((item) => toIsoDateValue(item.occurred_at || item.created_at) === today);
  const presentCount = rows.filter((item) => attendanceStatusKey(item.attendance_status) === 'present').length;
  const countedRows = rows.filter((item) => item.attendance_status).length;
  const todayStatus = todayRow ? attendanceStatusKey(todayRow.attendance_status) : 'present';
  return {
    today,
    today_status: todayStatus,
    today_label: todayStatus === 'present'
      ? 'Present by default'
      : todayStatus.replace(/_/g, ' '),
    present_count: todayRow ? presentCount : presentCount + 1,
    recorded_count: todayRow ? countedRows : countedRows + 1,
    overall_percent: todayRow || countedRows
      ? Math.round(((todayRow ? presentCount : presentCount + 1) / Math.max(1, todayRow ? countedRows : countedRows + 1)) * 100)
      : 100,
    default_rule: 'Default present unless BNA was notified otherwise.',
  };
}

function paymentStatusKey(status) {
  const key = String(status || 'pending').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (key === 'paid') return 'paid';
  if (key === 'partial') return 'partial';
  if (key === 'needs_signup') return 'needs_signup';
  if (key === 'needs_matching') return 'needs_matching';
  return 'pending';
}

function signupFinancialSummaryView(signup = null) {
  if (!signup) {
    return {
      status: 'unknown',
      label: 'No signup billing record linked yet',
      yearly_amount_ils: DEFAULT_TUITION_AMOUNT * 12,
      monthly_amount_ils: DEFAULT_TUITION_AMOUNT,
      reminders: ['Ask BNA if billing details are missing from this portal.'],
      payment_link_status: PAYMENT_LINK ? 'configured' : 'unconfirmed',
      payment_link: PAYMENT_LINK || '',
    };
  }
  const status = paymentStatusKey(signup.payment_status);
  const amount = Number(signup.payment_amount || DEFAULT_TUITION_AMOUNT);
  const yearlyAmount = DEFAULT_TUITION_AMOUNT * 12;
  const balance = status === 'partial'
    ? Math.max(0, DEFAULT_TUITION_AMOUNT - amount)
    : status === 'paid'
      ? 0
      : DEFAULT_TUITION_AMOUNT;
  const reminders = [
    `Full tuition year: ILS ${yearlyAmount}.`,
    'Prior end-of-May payments cover June 2026; July 1 starts the next billing cycle.',
    signup.payment_due_date ? `Next due date: ${toIsoDateValue(signup.payment_due_date)}.` : 'Next due date is not set yet.',
    balance ? `Open balance/reminder: ILS ${balance}.` : 'Payment is up to date in the current BNA record.',
  ];
  return {
    status,
    label: status === 'paid'
      ? 'Up to date'
      : status === 'partial'
        ? 'Partially paid'
        : 'Payment due',
    yearly_amount_ils: yearlyAmount,
    monthly_amount_ils: DEFAULT_TUITION_AMOUNT,
    current_amount_ils: amount,
    open_balance_ils: balance,
    payment_due_date: signup.payment_due_date ? toIsoDateValue(signup.payment_due_date) : '',
    payment_method: signup.payment_method || '',
    reminders,
    payment_link_status: PAYMENT_LINK ? 'configured' : 'unconfirmed',
    payment_link: PAYMENT_LINK || '',
  };
}

async function getTorahHistoryForStudent(studentId, { limit = 30 } = {}, db = pool) {
  const result = await db.query(
    `SELECT date,
            daily_completion_percentage,
            daily_completed_boolean,
            total_trip_progress_percentage,
            total_completed_units,
            total_required_units
     FROM bna_torah_learning_entries
     WHERE student_id = $1
       AND date <= CURRENT_DATE
     ORDER BY date DESC
     LIMIT $2`,
    [studentId, Math.max(1, Math.min(Number(limit) || 30, 90))]
  );
  return result.rows
    .slice()
    .reverse()
    .map((row) => ({
      date: toIsoDateValue(row.date),
      daily_completion_percentage: Number(row.daily_completion_percentage || 0),
      daily_completed: Boolean(row.daily_completed_boolean),
      public_trip_percentage: Number(row.total_trip_progress_percentage || 0),
      total_completed_units: Number(row.total_completed_units || 0),
      total_required_units: Number(row.total_required_units || DEFAULT_TORAH_TRIP_REQUIRED_UNITS),
    }));
}

function eventMetadata(row = {}) {
  return parseJsonMaybe(row.metadata) || {};
}

function visibilityFlag(value, fallback = true) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  const normalized = String(value).trim().toLowerCase();
  if (['false', '0', 'no', 'hidden', 'private', 'admin_only'].includes(normalized)) return false;
  if (['true', '1', 'yes', 'visible', 'shared'].includes(normalized)) return true;
  return fallback;
}

function goalParentVisible(row = {}) {
  const metadata = eventMetadata(row);
  const goalBoard = rawGoalBoardMetadata(metadata);
  return visibilityFlag(
    goalBoard.parent_visible
      ?? goalBoard.share_with_parent
      ?? goalBoard.parent_share
      ?? metadata.parent_visible
      ?? metadata.share_with_parent,
    true
  );
}

function goalStudentVisible(row = {}) {
  const metadata = eventMetadata(row);
  const goalBoard = rawGoalBoardMetadata(metadata);
  return visibilityFlag(
    goalBoard.student_visible
      ?? goalBoard.share_with_student
      ?? metadata.student_visible
      ?? metadata.share_with_student,
    true
  );
}

function eventParentVisible(row = {}) {
  const metadata = eventMetadata(row);
  if (metadata.hide_from_portals || metadata.portal_hidden) return false;
  if (metadata.visibility === 'admin_only' || metadata.kind === 'student_analysis') return false;
  if (row.event_type === 'private_meeting') return false;
  if (row.event_type === 'student_goal') return goalParentVisible(row);
  return visibilityFlag(metadata.parent_visible ?? metadata.share_with_parent, true);
}

function eventStudentVisible(row = {}) {
  const metadata = eventMetadata(row);
  if (metadata.hide_from_portals || metadata.portal_hidden) return false;
  if (metadata.visibility === 'admin_only' || metadata.kind === 'student_analysis') return false;
  if (row.event_type === 'private_meeting') return false;
  if (row.event_type === 'student_goal') return goalStudentVisible(row);
  return visibilityFlag(metadata.student_visible ?? metadata.share_with_student, true);
}

function sefariaRefUrl(ref) {
  const cleaned = String(ref || '').trim();
  if (!cleaned) return '';
  return `https://www.sefaria.org/${encodeURIComponent(cleaned).replace(/%20/g, '_')}`;
}

function stripHtml(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function questionSearchText(row = {}) {
  return [
    row.question_text,
    row.title,
    row.topic,
    row.notes,
  ].filter(Boolean).join(' ').slice(0, 500);
}

async function searchSefariaSourcesForQuestion(row = {}, { limit = 5 } = {}) {
  const query = questionSearchText(row);
  if (!query) return [];
  const body = {
    size: Math.max(1, Math.min(Number(limit) || 5, 8)),
    highlight: {
      pre_tags: [''],
      post_tags: [''],
      fields: {
        exact: { fragment_size: 220 },
        naive_lemmatizer: { fragment_size: 220 },
      },
    },
    query: {
      multi_match: {
        query,
        fields: ['exact^3', 'naive_lemmatizer^2', 'ref^4', 'heRef'],
        type: 'best_fields',
        operator: 'or',
      },
    },
  };

  const response = await fetch('https://www.sefaria.org/api/search/text/_search', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    throw new Error(`Sefaria search failed: ${response.status}`);
  }
  const data = await response.json();
  const hits = Array.isArray(data?.hits?.hits) ? data.hits.hits : [];
  const seenRefs = new Set();
  return hits
    .map((hit) => {
      const source = hit._source || {};
      const highlight = hit.highlight?.exact?.[0] || hit.highlight?.naive_lemmatizer?.[0] || source.exact || source.naive_lemmatizer || '';
      const ref = source.ref || '';
      return {
        ref,
        heRef: source.heRef || '',
        url: sefariaRefUrl(ref),
        categories: Array.isArray(source.categories) ? source.categories.slice(0, 4) : [],
        snippet: stripHtml(highlight).slice(0, 360),
        lang: source.lang || '',
        score: Number(hit._score || 0),
      };
    })
    .filter((item) => {
      if (!item.ref || !item.url || seenRefs.has(item.ref)) return false;
      seenRefs.add(item.ref);
      return true;
    })
    .slice(0, Math.max(1, Math.min(Number(limit) || 5, 8)));
}

function suggestedAssignmentsForQuestion(row = {}, sources = []) {
  const topic = String(row.topic || row.title || 'this question').trim();
  const refs = sources.slice(0, 2).map((source) => source.ref).filter(Boolean);
  return [
    refs.length
      ? `Read ${refs.join(' and ')} and write one sentence about how it changes the question.`
      : `Write the question again in your own words and underline the part that still feels unclear.`,
    `Bring one follow-up question about ${topic} to the next check-in.`,
  ];
}

function compactPortalTextList(values = [], limit = 5) {
  const seen = new Set();
  const result = [];
  for (const item of values.flatMap((value) => toJsonArray(value))) {
    const text = (typeof item === 'object'
      ? [
          item.label,
          item.title,
          item.topic,
          item.text,
          item.body,
          item.question,
          item.summary,
          classContentItemText(item),
        ].filter(Boolean).join(' ')
      : String(item || '')
    ).replace(/\s+/g, ' ').trim();
    const key = text.toLowerCase();
    if (!text || seen.has(key)) continue;
    seen.add(key);
    result.push(text);
    if (result.length >= limit) break;
  }
  return result;
}

function defaultParentOpenEndedQuestions(topic) {
  const subject = String(topic || 'this topic').trim();
  return [
    `What about ${subject} caught your attention today?`,
    `Where does ${subject} feel clear, confusing, or hard to live with?`,
    `What choice do you want to practice the next time this comes up?`,
    'What would help you take ownership without needing to be pushed?',
  ];
}

function parentQuestionCoachingView(row = {}, baseView = {}) {
  const metadata = eventMetadata(row);
  const questionMeta = metadata.question && typeof metadata.question === 'object' ? metadata.question : {};
  const coachingMeta = {
    ...(metadata.parent_coaching && typeof metadata.parent_coaching === 'object' ? metadata.parent_coaching : {}),
    ...(questionMeta.parent_coaching && typeof questionMeta.parent_coaching === 'object' ? questionMeta.parent_coaching : {}),
  };
  const topic = row.topic || questionMeta.topic || baseView.topic || baseView.title || 'this topic';
  const interestTopics = compactPortalTextList([
    coachingMeta.interest_topics,
    coachingMeta.topics,
    questionMeta.interest_topics,
    metadata.interest_topics,
    row.topic,
    row.title,
  ], 5).map(parentVisibleText).filter(Boolean);
  const struggleSignals = compactPortalTextList([
    coachingMeta.struggles,
    coachingMeta.struggle_signals,
    coachingMeta.working_on,
    questionMeta.struggles,
    questionMeta.struggle_signals,
    metadata.struggles,
    metadata.struggle_signals,
    row.follow_up_required ? 'This topic may need follow-up in the next check-in.' : '',
  ], 5).map(parentVisibleText).filter(Boolean);
  const openEndedQuestions = compactPortalTextList([
    coachingMeta.open_ended_questions,
    coachingMeta.parent_questions,
    questionMeta.open_ended_questions,
    metadata.open_ended_questions,
    defaultParentOpenEndedQuestions(topic),
  ], 5).map(parentVisibleText).filter(Boolean);
  return {
    ...baseView,
    answer: '',
    sources: [],
    assignments: [],
    source_status: '',
    source_note: '',
    parent_coaching: {
      interest_topics: interestTopics,
      struggle_signals: struggleSignals,
      open_ended_questions: openEndedQuestions,
      note: '',
    },
  };
}

function safeQuestionView(row = {}, { audience = 'student' } = {}) {
  const metadata = eventMetadata(row);
  const questionMeta = metadata.question && typeof metadata.question === 'object' ? metadata.question : {};
  const parentResponses = Array.isArray(questionMeta.parent_responses)
    ? questionMeta.parent_responses
        .filter((response) => response && typeof response === 'object' && String(response.body || '').trim())
        .map((response) => ({
          body: String(response.body || '').trim(),
          parent_name: response.parent_name || '',
          created_at: response.created_at || null,
          source: response.source || 'parent_portal',
        }))
    : [];
  const view = {
    id: row.id,
    student_id: row.student_id,
    student_name: row.student_name,
    title: parentVisibleText(row.title || row.question_text || questionMeta.title) || 'Student question',
    title_he: parentVisibleText(questionMeta.title_he || metadata.title_he || ''),
    topic: parentVisibleText(row.topic || questionMeta.topic || ''),
    topic_he: parentVisibleText(questionMeta.topic_he || metadata.topic_he || ''),
    question_text: parentVisibleText(row.question_text || questionMeta.question_text || row.title || ''),
    question_text_he: parentVisibleText(questionMeta.question_text_he || metadata.question_text_he || ''),
    answer: questionMeta.answer || metadata.answer || '',
    sources: Array.isArray(questionMeta.sources) ? questionMeta.sources : Array.isArray(metadata.sources) ? metadata.sources : [],
    assignments: Array.isArray(questionMeta.assignments) ? questionMeta.assignments : [],
    parent_responses: parentResponses,
    source_status: questionMeta.source_status || '',
    source_note: questionMeta.source_note || '',
    occurred_at: row.occurred_at,
    created_at: row.created_at,
    updated_at: row.updated_at,
  };
  return audience === 'parent' ? parentQuestionCoachingView(row, view) : view;
}

function safeAttendanceView(row = {}) {
  return {
    id: row.id,
    student_id: row.student_id,
    student_name: row.student_name,
    title: row.title || 'Attendance',
    topic: row.topic || '',
    attendance_status: row.attendance_status || '',
    engagement_level: row.engagement_level || '',
    occurred_at: row.occurred_at,
    created_at: row.created_at,
  };
}

async function getStudentQuestionsForPortal(studentId, { audience = 'student' } = {}, db = pool) {
  const result = await db.query(
    `SELECT id, student_id, student_name, title, notes, topic, question_text, follow_up_required, metadata,
            occurred_at, created_at, updated_at
     FROM bna_accountability_events
     WHERE student_id = $1
       AND event_type = 'question'
     ORDER BY COALESCE(occurred_at, created_at) DESC, id DESC
     LIMIT 80`,
    [studentId]
  );
  return result.rows
    .filter((row) => audience === 'parent' ? eventParentVisible(row) && parentQuestionHasVisibleText(row) : eventStudentVisible(row))
    .map((row) => safeQuestionView(row, { audience }));
}

async function getStudentAttendanceForPortal(studentId, { audience = 'student' } = {}, db = pool) {
  const result = await db.query(
    `SELECT id, student_id, student_name, title, topic, attendance_status, engagement_level,
            metadata, occurred_at, created_at
     FROM bna_accountability_events
     WHERE student_id = $1
       AND attendance_status IS NOT NULL
       AND attendance_status <> ''
     ORDER BY COALESCE(occurred_at, created_at) DESC, id DESC
     LIMIT 40`,
    [studentId]
  );
  return result.rows
    .filter((row) => audience === 'parent' ? eventParentVisible(row) : eventStudentVisible(row))
    .map(safeAttendanceView);
}

async function enrichQuestionEventWithSefariaSources(eventId, { force = false, db = pool } = {}) {
  const row = (await db.query(
    `SELECT *
     FROM bna_accountability_events
     WHERE id = $1
       AND event_type = 'question'
     LIMIT 1`,
    [eventId]
  )).rows[0];
  if (!row) {
    const error = new Error('Question not found');
    error.statusCode = 404;
    throw error;
  }

  const metadata = eventMetadata(row);
  const questionMeta = metadata.question && typeof metadata.question === 'object' ? metadata.question : {};
  if (!force && Array.isArray(questionMeta.sources) && questionMeta.sources.length) {
    return { event: row, question: safeQuestionView(row), refreshed: false };
  }

  const sources = await searchSefariaSourcesForQuestion(row, { limit: 5 });
  const nextMetadata = {
    ...metadata,
    question: {
      ...questionMeta,
      sources,
      assignments: Array.isArray(questionMeta.assignments) && questionMeta.assignments.length
        ? questionMeta.assignments
        : suggestedAssignmentsForQuestion(row, sources),
      source_status: sources.length ? 'suggested' : 'not_found',
      source_note: 'Sefaria source suggestions for learning. Review before presenting as final psak or definitive source mapping.',
      sourced_at: new Date().toISOString(),
      source_provider: 'sefaria',
    },
  };
  const updated = (await db.query(
    `UPDATE bna_accountability_events
     SET metadata = $2,
         updated_at = NOW()
     WHERE id = $1
     RETURNING *`,
    [eventId, JSON.stringify(nextMetadata)]
  )).rows[0];
  return { event: updated, question: safeQuestionView(updated), refreshed: true };
}

async function getGoalBoardCheckinsForGoals(goalIds = [], db = pool) {
  const ids = [...new Set((goalIds || []).map((id) => Number(id)).filter(Number.isFinite))];
  if (!ids.length) return new Map();
  const result = await db.query(
    `SELECT id, goal_id, student_id, date, completed, note, created_at, updated_at
     FROM bna_goal_board_checkins
     WHERE goal_id = ANY($1::int[])
     ORDER BY date ASC`,
    [ids]
  );
  return result.rows.reduce((map, row) => {
    const key = Number(row.goal_id);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push({
      ...row,
      date: toIsoDateValue(row.date),
    });
    return map;
  }, new Map());
}

async function attachGoalBoardDailyCheckins(goalRows = [], { nextMeetingDate = null, today = null } = {}, db = pool) {
  const checkinsByGoal = await getGoalBoardCheckinsForGoals(goalRows.map((goal) => goal.id), db);
  return goalRows.map((goal) => ({
    ...safeGoalBoardStudentView(goal),
    daily_checkins: buildGoalBoardCheckinWeeks({
      goal,
      checkins: checkinsByGoal.get(Number(goal.id)) || [],
      nextMeetingDate: nextMeetingDate || goal.next_check_in_date || null,
      today: today || getTodayDateInTimeZone(),
    }),
  }));
}

async function recalculateGoalProgressFromDailyCheckins(goalId, db = pool) {
  const current = await getGoalBoardEvent(goalId, db);
  if (!current) return null;
  const nextMeetingDate = await getStudentNextMeetingDate(current.student_id, db);
  const checkinsByGoal = await getGoalBoardCheckinsForGoals([goalId], db);
  const weeks = buildGoalBoardCheckinWeeks({
    goal: current,
    checkins: checkinsByGoal.get(Number(goalId)) || [],
    nextMeetingDate,
    today: getTodayDateInTimeZone(),
  });
  const scheduledDays = weeks.flatMap((week) => week.days);
  const completedCount = scheduledDays.filter((day) => day.completed).length;
  const progressPercent = scheduledDays.length ? Math.round((completedCount / scheduledDays.length) * 100) : 0;
  const metadata = metadataAfterProgressUpdate(current, progressPercent);
  const result = await db.query(
    `UPDATE bna_accountability_events
     SET progress_percent = $2,
         goal_actual_value = CASE
           WHEN goal_target_value IS NULL THEN goal_actual_value
           ELSE ROUND((goal_target_value * $2::numeric / 100), 2)
         END,
         follow_up_required = $2 < 100,
         metadata = $3,
         updated_at = NOW()
     WHERE id = $1
       AND event_type = 'student_goal'
     RETURNING *`,
    [goalId, progressPercent, JSON.stringify(metadata)]
  );
  return result.rows[0] || current;
}

async function getStudentPortalPayload(student, { audience = 'student' } = {}, db = pool) {
  const explicitNextMeetingDate = await getStudentNextMeetingDate(student.id, db);
  const weeklyMeetingSlot = await getWeeklyPrivateMeetingSlotForStudent(student.id, db);
  const weeklyPrivateMeeting = meetingSlotView(student, weeklyMeetingSlot);
  const nextMeetingDate = explicitNextMeetingDate || weeklyPrivateMeeting.next_date || null;
  const goalRows = (await db.query(
    `SELECT
        id,
        title,
        topic,
        notes,
        goal_target_value,
        goal_actual_value,
        goal_unit,
        progress_percent,
        follow_up_required,
        next_check_in_date,
        metadata,
        occurred_at,
        updated_at
     FROM bna_accountability_events
     WHERE student_id = $1
       AND event_type = 'student_goal'
       AND COALESCE((metadata->'goal_board'->>'status'), '') <> 'archived'
     ORDER BY COALESCE(follow_up_required, FALSE) DESC,
              COALESCE(progress_percent, -1) ASC,
              occurred_at DESC,
              id DESC`,
    [student.id]
  )).rows;
  const goals = (await attachGoalBoardDailyCheckins(goalRows, { nextMeetingDate }, db))
    .filter((goal) => goal.status !== 'archived');
  const visibleGoals = audience === 'parent'
    ? goals.filter((goal) => goal.parent_visible !== false)
    : goals.filter((goal) => goal.student_visible !== false);

  const torahSummary = await getTorahLearningSummary(getTodayDateInTimeZone());
  const torahRecord = (torahSummary.students || []).find((item) => Number(item.id) === Number(student.id));
  const torahClassProgress = {
    class_trip_percentage: Number(torahSummary.group?.groupPercentage || 0),
    class_trip_percentage_raw: Number(torahSummary.group?.groupPercentageRaw || torahSummary.group?.groupPercentage || 0),
    class_trip_unlocked: Boolean(torahSummary.group?.tripUnlocked),
    class_student_count: Number(torahSummary.group?.activeStudentCount || 0),
  };
  const dailyCompletion = Number(torahRecord?.entry?.daily_completion_percentage || 0);
  const history = await getTorahHistoryForStudent(student.id, { limit: 30 }, db);
  const deviceAccess = await getStudentDeviceAccessSummary(student.id);
  const questions = await getStudentQuestionsForPortal(student.id, { audience }, db);
  const attendance = await getStudentAttendanceForPortal(student.id, { audience }, db);
  const assignments = await getAssignmentsForStudentPortal(student.id, { audience }, db);
  const calendarEvents = await getCalendarEventsForStudentPortal(student.id, { audience }, db);
  const ws11 = await getWs11StudentProgress(student.id, {
    audience,
    parentEmail: audience === 'parent' ? student.parent_email : '',
  }, db).catch(() => null);
  const localizedNames = studentLocalizedNames(student);
  const safeStudentIdentity = audience === 'parent'
    ? { ...student }
    : {
        id: student.id,
        name: student.name,
        name_en: student.name_en,
        name_he: student.name_he,
        current_school: student.current_school,
        tags: student.tags,
        status: student.status,
      };

  return {
    student: {
      ...safeStudentIdentity,
      name_en: localizedNames.en,
      name_he: localizedNames.he,
      localized_names: localizedNames,
      audience: studentAccountabilityAudience(student),
      gender: studentGenderGroup(student),
      preferred_language: recordPreferredLanguage(student),
    },
    goals: visibleGoals,
    questions,
    attendance,
    attendance_summary: attendanceSummaryView(attendance),
    assignments,
    ws11,
    calendar_events: calendarEvents,
    device_access: deviceAccess,
    next_meeting_date: nextMeetingDate,
    weekly_private_meeting: weeklyPrivateMeeting,
    rabbi_contact: rabbiShloimieContactView({ studentName: student.name }),
    torah: torahRecord
      ? {
          date: torahSummary.date,
          ...torahClassProgress,
          public_trip_percentage: torahRecord.percentage,
          daily_completion_percentage: dailyCompletion,
          morning_goal_status: dailyCompletion >= 100 ? 'done' : dailyCompletion > 0 ? 'in_progress' : 'not_yet',
          history,
        }
      : { ...torahClassProgress, history },
  };
}

async function findParentAccessRecords(parentEmail, db = pool) {
  const email = normalizeEmail(parentEmail);
  if (!email) return { email, signups: [], students: [], leads: [] };
  const signupsResult = await db.query(
    `SELECT *
     FROM signups
     WHERE (
          lower(COALESCE(parent_email, '')) = $1
       OR lower(COALESCE(parent2_email, '')) = $1
     )
       AND COALESCE(status, 'new') <> 'archived'
     ORDER BY updated_at DESC NULLS LAST, created_at DESC`,
    [email]
  );
  const studentsResult = await db.query(
    `SELECT *
     FROM bna_students
     WHERE lower(COALESCE(parent_email, '')) = $1
       AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')
     ORDER BY name ASC`,
    [email]
  );
  const leadsResult = await db.query(
    `SELECT *
     FROM bna_parent_leads
     WHERE lower(COALESCE(parent_email, '')) = $1
       AND COALESCE(status, 'interested') <> 'archived'
     ORDER BY updated_at DESC NULLS LAST, created_at DESC`,
    [email]
  );
  return {
    email,
    signups: signupsResult.rows,
    students: studentsResult.rows,
    leads: leadsResult.rows,
  };
}

function parentAccessEligible(records) {
  return Boolean(records?.students?.length || records?.signups?.length || records?.leads?.length);
}

async function oneTimeParentPasswordResetEligible(parentEmail, db = pool) {
  const email = normalizeEmail(parentEmail);
  if (!email) return false;
  const project = await getProjectByKey(ONE_TIME_PROJECT_KEY, db).catch(() => null);
  const result = await db.query(
    `SELECT 1
     FROM one_time_member_access
     WHERE lower(COALESCE(member_email, '')) = lower($1)
       AND status = 'active'
     UNION
     SELECT 1
     FROM bna_students
     WHERE lower(COALESCE(parent_email, '')) = lower($1)
       AND $2::int IS NOT NULL
       AND project_id = $2::int
       AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')
     UNION
     SELECT 1
     FROM bna_parent_leads
     WHERE lower(COALESCE(parent_email, '')) = lower($1)
       AND $2::int IS NOT NULL
       AND project_id = $2::int
       AND 'one-time-parent-trial' = ANY(COALESCE(tags, '{}'::text[]))
       AND COALESCE(status, 'interested') <> 'archived'
     LIMIT 1`,
    [email, project?.id || null]
  );
  return Boolean(result.rows.length);
}

const NEXT_YEAR_LOGIN_PREPARE_CONFIRM = 'PREPARE_NEXT_YEAR_LOGINS';
const PARENT_PASSWORD_SETUP_CONFIRM = 'SEND_PARENT_PASSWORD_SETUP';
const ONE_TIME_PARENT_TRIAL_INVITE_CONFIRM = 'SEND_ONE_TIME_PARENT_TRIAL_INVITE';

function nextYearLoginIssueLabels(item = {}) {
  const issues = [];
  if (!normalizeEmail(item.parent_email)) issues.push('missing_parent_email');
  if (item.student_access_enabled === false) issues.push('student_link_disabled');
  if (!item.student_access_code) issues.push('missing_student_link');
  if (!item.parent_password_set_at) issues.push('parent_password_not_set');
  if (!Number(item.assignment_count || 0)) issues.push('no_assignments');
  else if (!Number(item.visible_material_count || 0)) issues.push('no_visible_materials');
  return issues;
}

function nextYearLoginStudentReadinessView(row = {}, preparedStudentIds = new Set()) {
  const parentEmail = normalizeEmail(row.parent_email);
  const studentLinkReady = Boolean(row.student_access_code && row.student_access_enabled !== false);
  const loginReady = Boolean(parentEmail && studentLinkReady);
  const materialsReady = Number(row.visible_material_count || 0) > 0;
  const parentPasswordSet = Boolean(row.password_set_at);
  const view = {
    id: row.id,
    name: row.name,
    parent_name: row.parent_name || '',
    parent_email: parentEmail,
    parent_phone: row.parent_phone || '',
    current_school: row.current_school || '',
    grade: row.grade || '',
    status: row.status || 'active',
    audience: studentAccountabilityAudience(row),
    student_access_code: row.student_access_code || '',
    student_access_enabled: row.student_access_enabled !== false,
    student_access_created_at: row.student_access_created_at || null,
    student_link_ready: studentLinkReady,
    parent_link_ready: Boolean(parentEmail),
    parent_password_set: parentPasswordSet,
    parent_password_set_at: row.password_set_at || null,
    parent_last_login_at: row.last_login_at || null,
    assignment_count: Number(row.assignment_count || 0),
    visible_material_count: Number(row.visible_material_count || 0),
    worksheet_ready_count: Number(row.worksheet_ready_count || 0),
    scheduled_count: Number(row.scheduled_count || 0),
    classroom_ready_count: Number(row.classroom_ready_count || 0),
    login_ready: loginReady,
    materials_ready: materialsReady,
    rollout_ready: Boolean(loginReady && materialsReady),
    prepared_student_link: preparedStudentIds.has(Number(row.id)),
  };
  view.issues = nextYearLoginIssueLabels(view);
  return view;
}

function nextYearLoginReadinessSummary(items = [], preparedStudentIds = new Set()) {
  return {
    roster_count: items.length,
    login_ready: items.filter((item) => item.login_ready).length,
    rollout_ready: items.filter((item) => item.rollout_ready).length,
    missing_parent_email: items.filter((item) => !item.parent_email).length,
    missing_student_link: items.filter((item) => !item.student_access_code).length,
    disabled_student_link: items.filter((item) => item.student_access_enabled === false).length,
    parent_password_not_set: items.filter((item) => !item.parent_password_set).length,
    assignmentless: items.filter((item) => !item.assignment_count).length,
    no_visible_materials: items.filter((item) => item.assignment_count && !item.visible_material_count).length,
    prepared_student_links: preparedStudentIds.size,
  };
}

async function buildNextYearLoginReadiness({ req, prepareStudentLinks = false } = {}, db = pool) {
  await ensureStudentsFromSignups();
  const conditions = ["COALESCE(s.status, 'active') NOT IN ('inactive', 'archived')"];
  const params = [];
  appendScopeCondition(req, conditions, params, 's.project_id');
  const result = await db.query(
    `SELECT s.id, s.name, s.parent_name, s.parent_email, s.parent_phone,
            s.current_school, s.grade, s.tags, s.status, s.student_access_code,
            s.student_access_enabled, s.student_access_created_at,
            ppa.password_set_at, ppa.last_login_at,
            COALESCE(assignments.assignment_count, 0) AS assignment_count,
            COALESCE(assignments.visible_material_count, 0) AS visible_material_count,
            COALESCE(assignments.worksheet_ready_count, 0) AS worksheet_ready_count,
            COALESCE(assignments.scheduled_count, 0) AS scheduled_count,
            COALESCE(assignments.classroom_ready_count, 0) AS classroom_ready_count
     FROM bna_students s
     LEFT JOIN bna_parent_password_accounts ppa
       ON lower(ppa.parent_email) = lower(COALESCE(s.parent_email, ''))
     LEFT JOIN LATERAL (
       SELECT COUNT(*)::int AS assignment_count,
              COUNT(*) FILTER (
                WHERE COALESCE(
                  NULLIF(ast.edited_worksheet, ''),
                  NULLIF(ast.worksheet_body, ''),
                  NULLIF(ast.generated_worksheet, ''),
                  NULLIF(a.edited_worksheet, ''),
                  NULLIF(a.worksheet_body, ''),
                  NULLIF(a.generated_worksheet, ''),
                  NULLIF(a.material_url, ''),
                  NULLIF(a.youtube_url, ''),
                  NULLIF(ast.classroom_alternate_link, ''),
                  NULLIF(ast.calendar_html_link, ''),
                  ''
                ) <> ''
              )::int AS visible_material_count,
              COUNT(*) FILTER (
                WHERE COALESCE(
                  NULLIF(ast.edited_worksheet, ''),
                  NULLIF(ast.worksheet_body, ''),
                  NULLIF(ast.generated_worksheet, ''),
                  NULLIF(a.edited_worksheet, ''),
                  NULLIF(a.worksheet_body, ''),
                  NULLIF(a.generated_worksheet, ''),
                  ''
                ) <> ''
              )::int AS worksheet_ready_count,
              COUNT(*) FILTER (
                WHERE ast.scheduled_start_at IS NOT NULL
                   OR ast.due_at IS NOT NULL
                   OR COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(a.schedule_plan->'sessions') = 'array' THEN a.schedule_plan->'sessions' ELSE '[]'::jsonb END), 0) > 0
              )::int AS scheduled_count,
              COUNT(*) FILTER (
                WHERE ast.classroom_coursework_id IS NOT NULL
                   OR COALESCE(ast.classroom_alternate_link, '') <> ''
              )::int AS classroom_ready_count
       FROM bna_assignment_students ast
       JOIN bna_assignments a ON a.id = ast.assignment_id
       WHERE ast.student_id = s.id
         AND COALESCE(a.status, 'draft') <> 'archived'
         AND COALESCE(ast.status, 'assigned') <> 'archived'
     ) assignments ON TRUE
     WHERE ${conditions.join(' AND ')}
     ORDER BY lower(s.name), s.id`,
    params
  );
  const preparedStudentIds = new Set();
  const rows = result.rows.filter((student) => !studentIsExternalAccountabilityPerson(student));

  if (prepareStudentLinks) {
    for (const row of rows) {
      if (row.student_access_code) continue;
      const code = await ensureStudentAccessCode(row.id, {}, db);
      row.student_access_code = code;
      row.student_access_enabled = true;
      row.student_access_created_at = row.student_access_created_at || new Date().toISOString();
      preparedStudentIds.add(Number(row.id));
    }
  }

  const students = rows.map((row) => nextYearLoginStudentReadinessView(row, preparedStudentIds));
  return {
    success: true,
    cohort: 'next_year_group',
    checked_at: new Date().toISOString(),
    confirm_required: NEXT_YEAR_LOGIN_PREPARE_CONFIRM,
    summary: nextYearLoginReadinessSummary(students, preparedStudentIds),
    students,
  };
}

