// Admin auth middleware - case insensitive
async function requireAdmin(req, res, next) {
  const viewAsAuth = applyOneTimeViewAsRabbiRequest(req, res);
  if (viewAsAuth.handled) {
    if (viewAsAuth.authenticated) return next();
    return;
  }

  const cookies = parseCookies(req);
  const session = await getValidSession(cookies[SESSION_COOKIE_NAME]);
  if (session) {
    const identity = identifyOpsUser(session.username);
    if (!identity) {
      await clearSession(cookies[SESSION_COOKIE_NAME]);
      clearSessionCookie(res);
      return res.status(401).json({ error: 'Session user is no longer allowed' });
    }
    if (identity.scope.type !== 'all' && !isScopedOpsPathAllowed(req, identity)) {
      return res.status(403).json({ error: 'This login is scoped to One Time Mishnah Class records.' });
    }
    if (!enforceOneTimeViewAsReadOnly(req, res)) return;
    req.opsUser = identity.username;
    req.opsIdentity = identity;
    return next();
  }

  const providerOpsIdentity = await identifyOneTimeProviderOpsSession(req).catch(() => null);
  if (providerOpsIdentity) {
    if (providerOpsIdentity.scope.type !== 'all' && !isScopedOpsPathAllowed(req, providerOpsIdentity)) {
      return res.status(403).json({ error: 'This login is scoped to One Time Mishnah Class records.' });
    }
    req.opsUser = providerOpsIdentity.username;
    req.opsIdentity = providerOpsIdentity;
    return next();
  }

  const authHeader = req.headers.authorization;

  // If no auth header, redirect to login page
  if (!authHeader || !authHeader.startsWith('Basic ')) {
    // Check if request wants HTML (browser) or JSON (API)
    const acceptHeader = req.headers.accept || '';
    if (acceptHeader.includes('text/html')) {
      return res.redirect(operationsLoginUrlForRequest(req));
    }
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const creds = Buffer.from(authHeader.slice(6), 'base64').toString();
  const [user, pass] = creds.split(':');

  const identity = identifyOpsUser(user, pass);
  if (!identity) {
    const acceptHeader = req.headers.accept || '';
    if (acceptHeader.includes('text/html')) {
      return res.redirect(operationsLoginUrlForRequest(req));
    }
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  if (identity.scope.type !== 'all' && !isScopedOpsPathAllowed(req, identity)) {
    return res.status(403).json({ error: 'This login is scoped to One Time Mishnah Class records.' });
  }
  if (!enforceOneTimeViewAsReadOnly(req, res)) return;
  req.opsUser = identity.username;
  req.opsIdentity = identity;
  next();
}

async function identifyAdminRequest(req) {
  const cookies = parseCookies(req);
  const session = await getValidSession(cookies[SESSION_COOKIE_NAME]);
  if (session) {
    const identity = identifyOpsUser(session.username);
    return identity?.scope?.type === 'all' ? identity : null;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Basic ')) return null;

  const creds = Buffer.from(authHeader.slice(6), 'base64').toString();
  const [user, pass] = creds.split(':');
  const identity = identifyOpsUser(user, pass);
  return identity?.scope?.type === 'all' ? identity : null;
}

async function identifyOpsAssistantRequest(req) {
  if (req?.opsIdentity) return req.opsIdentity;
  const viewAsToken = oneTimeViewAsTokenFromRequest(req);
  if (viewAsToken && !isOneTimeViewAsControlEndpoint(req)) {
    const payload = verifyOneTimeViewAsToken(viewAsToken);
    try {
      assertOneTimeViewAsRequestScope(req);
    } catch (err) {
      return null;
    }
    if (payload) return oneTimeViewAsRabbiIdentity(payload);
  }
  const cookies = parseCookies(req);
  const session = await getValidSession(cookies[SESSION_COOKIE_NAME]);
  if (session) return identifyOpsUser(session.username) || null;
  const providerOpsIdentity = await identifyOneTimeProviderOpsSession(req).catch(() => null);
  if (providerOpsIdentity) return providerOpsIdentity;

  const authHeader = req.headers?.authorization;
  if (!authHeader || !authHeader.startsWith('Basic ')) return null;
  const creds = Buffer.from(authHeader.slice(6), 'base64').toString();
  const [user, pass] = creds.split(':');
  return identifyOpsUser(user, pass) || null;
}

