let stripeSdk = null;

function getStripeClient(secretKey = '') {
  const key = String(secretKey || '').trim();
  if (!key) return null;
  if (!stripeSdk) {
    // Loaded lazily so local preview mode still works without Stripe secrets.
    stripeSdk = require('stripe');
  }
  return stripeSdk(key);
}

