function readOptionalSqlFile(filename) {
  try {
    return fs.readFileSync(path.join(__dirname, filename), 'utf8');
  } catch (err) {
    if (err.code !== 'ENOENT') {
      console.warn(`Could not read optional SQL file ${filename}:`, err.message);
    }
    return '';
  }
}

