const createWs11CommunityGamificationSQL = `
ALTER TABLE bna_learning_communities ADD COLUMN IF NOT EXISTS project_key TEXT NOT NULL DEFAULT '${DEFAULT_PROJECT_KEY}';
ALTER TABLE bna_learning_communities ADD COLUMN IF NOT EXISTS workspace_id TEXT;
ALTER TABLE bna_learning_communities ADD COLUMN IF NOT EXISTS slug TEXT;
ALTER TABLE bna_learning_communities ADD COLUMN IF NOT EXISTS name TEXT;
ALTER TABLE bna_learning_communities ADD COLUMN IF NOT EXISTS short_name TEXT;
ALTER TABLE bna_learning_communities ADD COLUMN IF NOT EXISTS primary_teacher TEXT;

UPDATE bna_learning_communities lc
SET project_key = COALESCE(NULLIF(lc.project_key, ''), p.project_key, '${DEFAULT_PROJECT_KEY}'),
    slug = COALESCE(NULLIF(lc.slug, ''), lc.community_key),
    name = COALESCE(NULLIF(lc.name, ''), lc.title),
    short_name = COALESCE(NULLIF(lc.short_name, ''), lc.title),
    primary_teacher = COALESCE(NULLIF(lc.primary_teacher, ''), lc.owner_name)
FROM bna_projects p
WHERE lc.project_id = p.id;

UPDATE bna_learning_communities
SET slug = COALESCE(NULLIF(slug, ''), community_key),
    name = COALESCE(NULLIF(name, ''), title),
    short_name = COALESCE(NULLIF(short_name, ''), title),
    primary_teacher = COALESCE(NULLIF(primary_teacher, ''), owner_name),
    project_key = COALESCE(NULLIF(project_key, ''), '${DEFAULT_PROJECT_KEY}');

CREATE UNIQUE INDEX IF NOT EXISTS idx_bna_learning_communities_slug_unique
  ON bna_learning_communities(slug)
  WHERE slug IS NOT NULL AND trim(slug) <> '';
CREATE INDEX IF NOT EXISTS idx_bna_learning_communities_project_key ON bna_learning_communities(project_key, status);

CREATE TABLE IF NOT EXISTS bna_courses (
  id SERIAL PRIMARY KEY,
  community_id INTEGER REFERENCES bna_learning_communities(id) ON DELETE SET NULL,
  project_id INTEGER REFERENCES bna_projects(id) ON DELETE SET NULL,
  project_key TEXT NOT NULL DEFAULT '${ONE_TIME_PROJECT_KEY}',
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  short_title TEXT,
  description TEXT,
  primary_teacher TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('draft', 'active', 'published', 'paused', 'archived')),
  visibility TEXT NOT NULL DEFAULT 'student' CHECK (visibility IN ('private', 'student', 'parent', 'student_parent', 'community', 'public')),
  sort_order INTEGER NOT NULL DEFAULT 100,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_courses_project_key ON bna_courses(project_key, status);
CREATE INDEX IF NOT EXISTS idx_bna_courses_community ON bna_courses(community_id, status);

CREATE TABLE IF NOT EXISTS bna_course_enrollments (
  id SERIAL PRIMARY KEY,
  course_id INTEGER NOT NULL REFERENCES bna_courses(id) ON DELETE CASCADE,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'invited', 'paused', 'completed', 'dropped', 'archived')),
  progress_percent NUMERIC(5,2) NOT NULL DEFAULT 0,
  points_total INTEGER NOT NULL DEFAULT 0,
  started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  completed_at TIMESTAMP,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (course_id, student_id)
);
CREATE INDEX IF NOT EXISTS idx_bna_course_enrollments_student ON bna_course_enrollments(student_id, status);

CREATE TABLE IF NOT EXISTS bna_course_lessons (
  id SERIAL PRIMARY KEY,
  course_id INTEGER NOT NULL REFERENCES bna_courses(id) ON DELETE CASCADE,
  class_session_id INTEGER REFERENCES bna_class_sessions(id) ON DELETE SET NULL,
  content_job_id INTEGER REFERENCES bna_content_jobs(id) ON DELETE SET NULL,
  assignment_id INTEGER REFERENCES bna_assignments(id) ON DELETE SET NULL,
  slug TEXT,
  title TEXT NOT NULL,
  summary TEXT,
  sort_order INTEGER NOT NULL DEFAULT 100,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'published', 'archived')),
  visibility TEXT NOT NULL DEFAULT 'student' CHECK (visibility IN ('private', 'student', 'parent', 'student_parent', 'community', 'public')),
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_course_lessons_course ON bna_course_lessons(course_id, status, sort_order);
CREATE UNIQUE INDEX IF NOT EXISTS idx_bna_course_lessons_slug_unique
  ON bna_course_lessons(course_id, slug)
  WHERE slug IS NOT NULL AND trim(slug) <> '';

CREATE TABLE IF NOT EXISTS bna_worksheets (
  id SERIAL PRIMARY KEY,
  course_id INTEGER REFERENCES bna_courses(id) ON DELETE SET NULL,
  lesson_id INTEGER REFERENCES bna_course_lessons(id) ON DELETE SET NULL,
  assignment_id INTEGER REFERENCES bna_assignments(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  instructions TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'published', 'archived')),
  visibility TEXT NOT NULL DEFAULT 'student' CHECK (visibility IN ('private', 'student', 'parent', 'student_parent', 'community', 'public')),
  approval_status TEXT NOT NULL DEFAULT 'draft' CHECK (approval_status IN ('draft', 'pending', 'approved', 'rejected', 'archived')),
  parent_visible BOOLEAN NOT NULL DEFAULT FALSE,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_worksheets_course ON bna_worksheets(course_id, status);
CREATE INDEX IF NOT EXISTS idx_bna_worksheets_lesson ON bna_worksheets(lesson_id, status);
ALTER TABLE bna_worksheets ADD COLUMN IF NOT EXISTS due_at TIMESTAMP;
CREATE INDEX IF NOT EXISTS idx_bna_worksheets_due_at ON bna_worksheets(due_at);

CREATE TABLE IF NOT EXISTS bna_worksheet_questions (
  id SERIAL PRIMARY KEY,
  worksheet_id INTEGER NOT NULL REFERENCES bna_worksheets(id) ON DELETE CASCADE,
  prompt TEXT NOT NULL,
  question_type TEXT NOT NULL DEFAULT 'short_answer' CHECK (question_type IN ('short_answer', 'long_answer', 'multiple_choice', 'reflection', 'source_lookup')),
  choices JSONB DEFAULT '[]',
  answer_key TEXT,
  points INTEGER NOT NULL DEFAULT 0,
  sort_order INTEGER NOT NULL DEFAULT 100,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_worksheet_questions_worksheet ON bna_worksheet_questions(worksheet_id, sort_order);

CREATE TABLE IF NOT EXISTS bna_worksheet_submissions (
  id SERIAL PRIMARY KEY,
  worksheet_id INTEGER NOT NULL REFERENCES bna_worksheets(id) ON DELETE CASCADE,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  assignment_student_id INTEGER REFERENCES bna_assignment_students(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('draft', 'submitted', 'reviewed', 'completed', 'rejected', 'archived')),
  answer_snapshot JSONB DEFAULT '{}',
  score_percent NUMERIC(5,2),
  parent_visible BOOLEAN NOT NULL DEFAULT FALSE,
  approval_status TEXT NOT NULL DEFAULT 'pending' CHECK (approval_status IN ('draft', 'pending', 'approved', 'rejected', 'archived')),
  reviewed_by TEXT,
  reviewed_at TIMESTAMP,
  metadata JSONB DEFAULT '{}',
  submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_worksheet_submissions_student ON bna_worksheet_submissions(student_id, submitted_at DESC);
CREATE INDEX IF NOT EXISTS idx_bna_worksheet_submissions_parent ON bna_worksheet_submissions(student_id, parent_visible, approval_status);

CREATE TABLE IF NOT EXISTS bna_worksheet_answers (
  id SERIAL PRIMARY KEY,
  submission_id INTEGER NOT NULL REFERENCES bna_worksheet_submissions(id) ON DELETE CASCADE,
  question_id INTEGER REFERENCES bna_worksheet_questions(id) ON DELETE SET NULL,
  answer_text TEXT,
  answer_json JSONB DEFAULT '{}',
  is_correct BOOLEAN,
  points_awarded INTEGER NOT NULL DEFAULT 0,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_worksheet_answers_submission ON bna_worksheet_answers(submission_id);

CREATE TABLE IF NOT EXISTS bna_course_questions (
  id SERIAL PRIMARY KEY,
  course_id INTEGER REFERENCES bna_courses(id) ON DELETE SET NULL,
  lesson_id INTEGER REFERENCES bna_course_lessons(id) ON DELETE SET NULL,
  class_session_id INTEGER REFERENCES bna_class_sessions(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  prompt TEXT NOT NULL,
  question_type TEXT NOT NULL DEFAULT 'short_answer' CHECK (question_type IN ('short_answer', 'long_answer', 'reflection', 'source_lookup')),
  due_at TIMESTAMP,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'published', 'archived')),
  visibility TEXT NOT NULL DEFAULT 'student' CHECK (visibility IN ('private', 'student', 'parent', 'student_parent', 'community', 'public')),
  approval_status TEXT NOT NULL DEFAULT 'draft' CHECK (approval_status IN ('draft', 'pending', 'approved', 'rejected', 'archived')),
  student_visible BOOLEAN NOT NULL DEFAULT TRUE,
  parent_visible BOOLEAN NOT NULL DEFAULT FALSE,
  public_visible BOOLEAN NOT NULL DEFAULT FALSE,
  assigned_to_all BOOLEAN NOT NULL DEFAULT TRUE,
  points INTEGER NOT NULL DEFAULT 0,
  source TEXT NOT NULL DEFAULT 'operations',
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_course_questions_course ON bna_course_questions(course_id, status, due_at);
CREATE INDEX IF NOT EXISTS idx_bna_course_questions_parent ON bna_course_questions(parent_visible, approval_status, due_at);

CREATE TABLE IF NOT EXISTS bna_course_question_responses (
  id SERIAL PRIMARY KEY,
  question_id INTEGER NOT NULL REFERENCES bna_course_questions(id) ON DELETE CASCADE,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  response_text TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('draft', 'submitted', 'reviewed', 'completed', 'rejected', 'archived')),
  score_percent NUMERIC(5,2),
  parent_visible BOOLEAN NOT NULL DEFAULT FALSE,
  approval_status TEXT NOT NULL DEFAULT 'pending' CHECK (approval_status IN ('draft', 'pending', 'approved', 'rejected', 'archived')),
  reviewed_by TEXT,
  reviewed_at TIMESTAMP,
  metadata JSONB DEFAULT '{}',
  submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (question_id, student_id)
);
CREATE INDEX IF NOT EXISTS idx_bna_course_question_responses_student ON bna_course_question_responses(student_id, submitted_at DESC);
CREATE INDEX IF NOT EXISTS idx_bna_course_question_responses_parent ON bna_course_question_responses(student_id, parent_visible, approval_status);

CREATE TABLE IF NOT EXISTS bna_badges (
  id SERIAL PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  description TEXT,
  event_type TEXT CHECK (event_type IN (${gamificationEventSqlValues})),
  points_required INTEGER NOT NULL DEFAULT 0,
  icon TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'archived')),
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS bna_gamification_events (
  id SERIAL PRIMARY KEY,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  course_id INTEGER REFERENCES bna_courses(id) ON DELETE SET NULL,
  lesson_id INTEGER REFERENCES bna_course_lessons(id) ON DELETE SET NULL,
  worksheet_id INTEGER REFERENCES bna_worksheets(id) ON DELETE SET NULL,
  worksheet_submission_id INTEGER REFERENCES bna_worksheet_submissions(id) ON DELETE SET NULL,
  class_session_id INTEGER REFERENCES bna_class_sessions(id) ON DELETE SET NULL,
  reference_id INTEGER,
  event_type TEXT NOT NULL CHECK (event_type IN (${gamificationEventSqlValues})),
  title TEXT NOT NULL,
  notes TEXT,
  points INTEGER NOT NULL DEFAULT 0,
  visibility TEXT NOT NULL DEFAULT 'student' CHECK (visibility IN ('private', 'student', 'parent', 'student_parent', 'community', 'public')),
  parent_visible BOOLEAN NOT NULL DEFAULT FALSE,
  approval_status TEXT NOT NULL DEFAULT 'approved' CHECK (approval_status IN ('draft', 'pending', 'approved', 'rejected', 'archived')),
  idempotency_key TEXT NOT NULL UNIQUE,
  source TEXT NOT NULL DEFAULT 'manual',
  source_ref TEXT,
  metadata JSONB DEFAULT '{}',
  occurred_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_gamification_events_student ON bna_gamification_events(student_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_bna_gamification_events_parent ON bna_gamification_events(student_id, parent_visible, approval_status);
CREATE INDEX IF NOT EXISTS idx_bna_gamification_events_type ON bna_gamification_events(event_type, occurred_at DESC);

CREATE TABLE IF NOT EXISTS bna_student_badges (
  id SERIAL PRIMARY KEY,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  badge_id INTEGER NOT NULL REFERENCES bna_badges(id) ON DELETE CASCADE,
  awarded_event_id INTEGER REFERENCES bna_gamification_events(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked', 'archived')),
  awarded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  metadata JSONB DEFAULT '{}',
  UNIQUE (student_id, badge_id)
);
ALTER TABLE bna_student_badges ADD COLUMN IF NOT EXISTS awarded_by TEXT;
ALTER TABLE bna_student_badges ADD COLUMN IF NOT EXISTS revoked_at TIMESTAMP;
ALTER TABLE bna_student_badges ADD COLUMN IF NOT EXISTS revoked_by TEXT;
ALTER TABLE bna_student_badges ADD COLUMN IF NOT EXISTS reversal_reason TEXT;
ALTER TABLE bna_student_badges ADD COLUMN IF NOT EXISTS audit_json JSONB DEFAULT '[]';
CREATE INDEX IF NOT EXISTS idx_bna_student_badges_student ON bna_student_badges(student_id, status);

CREATE TABLE IF NOT EXISTS bna_badge_audit_events (
  id SERIAL PRIMARY KEY,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  badge_id INTEGER REFERENCES bna_badges(id) ON DELETE SET NULL,
  student_badge_id INTEGER REFERENCES bna_student_badges(id) ON DELETE SET NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('award_preview', 'awarded', 'revocation_preview', 'revoked', 'restored')),
  source_event_id INTEGER REFERENCES bna_gamification_events(id) ON DELETE SET NULL,
  idempotency_key TEXT NOT NULL UNIQUE,
  reason TEXT,
  parent_safe_explanation TEXT,
  actor_label TEXT,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_badge_audit_events_student ON bna_badge_audit_events(student_id, created_at DESC);

CREATE TABLE IF NOT EXISTS bna_student_references (
  id SERIAL PRIMARY KEY,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  course_id INTEGER REFERENCES bna_courses(id) ON DELETE SET NULL,
  lesson_id INTEGER REFERENCES bna_course_lessons(id) ON DELETE SET NULL,
  class_session_id INTEGER REFERENCES bna_class_sessions(id) ON DELETE SET NULL,
  reference_type TEXT NOT NULL DEFAULT 'shoutout' CHECK (reference_type IN ('shoutout', 'reference', 'question', 'class_mention', 'worksheet')),
  title TEXT NOT NULL,
  body TEXT,
  visibility TEXT NOT NULL DEFAULT 'parent' CHECK (visibility IN ('private', 'student', 'parent', 'student_parent', 'community', 'public')),
  parent_visible BOOLEAN NOT NULL DEFAULT FALSE,
  community_visible BOOLEAN NOT NULL DEFAULT FALSE,
  public_visible BOOLEAN NOT NULL DEFAULT FALSE,
  approval_status TEXT NOT NULL DEFAULT 'pending' CHECK (approval_status IN ('draft', 'pending', 'approved', 'rejected', 'archived')),
  approved_by TEXT,
  approved_at TIMESTAMP,
  source TEXT NOT NULL DEFAULT 'manual',
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_student_references_student ON bna_student_references(student_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_bna_student_references_parent ON bna_student_references(student_id, parent_visible, approval_status);

CREATE TABLE IF NOT EXISTS bna_parent_student_links (
  id SERIAL PRIMARY KEY,
  parent_account_id INTEGER REFERENCES bna_parent_accounts(id) ON DELETE CASCADE,
  parent_email TEXT,
  household_id INTEGER REFERENCES bna_households(id) ON DELETE SET NULL,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  relationship TEXT DEFAULT 'parent',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'pending', 'paused', 'archived')),
  source TEXT NOT NULL DEFAULT 'operations',
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_bna_parent_student_links_account_student
  ON bna_parent_student_links(parent_account_id, student_id)
  WHERE parent_account_id IS NOT NULL AND status <> 'archived';
CREATE UNIQUE INDEX IF NOT EXISTS idx_bna_parent_student_links_email_student
  ON bna_parent_student_links(lower(parent_email), student_id)
  WHERE parent_email IS NOT NULL AND status <> 'archived';
CREATE INDEX IF NOT EXISTS idx_bna_parent_student_links_student ON bna_parent_student_links(student_id, status);

CREATE TABLE IF NOT EXISTS bna_parent_progress_reports (
  id SERIAL PRIMARY KEY,
  parent_account_id INTEGER REFERENCES bna_parent_accounts(id) ON DELETE SET NULL,
  parent_email TEXT,
  student_id INTEGER NOT NULL REFERENCES bna_students(id) ON DELETE CASCADE,
  report_start_date DATE,
  report_end_date DATE,
  title TEXT NOT NULL,
  summary TEXT,
  metrics_json JSONB DEFAULT '{}',
  highlights_json JSONB DEFAULT '[]',
  source_event_ids INTEGER[] DEFAULT '{}',
  parent_visible BOOLEAN NOT NULL DEFAULT FALSE,
  approval_status TEXT NOT NULL DEFAULT 'draft' CHECK (approval_status IN ('draft', 'pending', 'approved', 'rejected', 'archived')),
  approved_by TEXT,
  approved_at TIMESTAMP,
  generated_by TEXT DEFAULT 'system',
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bna_parent_progress_reports_student ON bna_parent_progress_reports(student_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_bna_parent_progress_reports_parent ON bna_parent_progress_reports(parent_account_id, parent_email, parent_visible, approval_status);
`;

