async function ensureDefaultServiceProviderDirectory(db = pool) {
  const oneTimeDriveSocialMap = oneTimeDriveSocialIngestionMap();
  const project = await ensureDefaultProjects(db);
  const oneTimeProjectId = project?.oneTime?.id || null;
  const bnaProjectId = project?.bna?.id || project?.id || null;
  const provider = (await db.query(
    `INSERT INTO bna_service_providers (
       project_id, provider_name, contact_name, status, public_notes,
       provider_status, commercial_model, entitlement_plan, source_of_truth,
       integration_status, setup_package, managed_services, public_listing_enabled,
       public_signup_enabled, claim_listing_enabled, internal_owner, commercial_notes,
       private_notes, marketing_management_enabled, billing_management_enabled,
       admin_fee_notes, metadata, approved_at
     )
     SELECT
       $1, 'Rabbi Elie Scheller', 'Rabbi Elie Scheller', 'approved',
       'Rabbi-led Mishnah learning option connected to the BNA provider network.',
       'active_partner', 'revenue_share', 'revenue_share_partner', 'hybrid',
       'access_requested', 'Partner launch and managed growth setup',
       $2::jsonb, TRUE, TRUE, FALSE, 'Shloimie',
       'Partner/revenue-share provider. Existing Replit/Vimeo delivery app stays external until inspected.',
       'Seeded as the first provider-directory class option from the 2026-06-10 operator request.',
       FALSE, FALSE,
       'No live billing or payout automation is enabled. Admin-fee/payment handling needs separate typed approval.',
       $3, NOW()
     WHERE NOT EXISTS (
       SELECT 1 FROM bna_service_providers
       WHERE lower(provider_name) = lower('Rabbi Elie Scheller')
     )
    RETURNING *`,
    [
      oneTimeProjectId || bnaProjectId,
      JSON.stringify({
        funnel_setup: true,
        lead_pipeline: true,
        email_whatsapp_social: true,
        content_workflow: true,
        reporting: true,
        payment_links_manual: true,
      }),
      JSON.stringify({
        seed: '2026-06-10-provider-directory',
        provider_type: 'rabbi_learning',
        commercial_model: 'revenue_share',
        external_delivery_system: 'Replit/Vimeo app',
        drive_social_ingestion: {
          root_folder_id: oneTimeDriveSocialMap.root.id,
          root_folder_url: oneTimeDriveSocialMap.root.webViewLink,
          content_media_folder_id: oneTimeDriveSocialMap.content_media_folder?.id || null,
          folder_links: oneTimeDriveSocialMap.folder_links || [],
          rabbi_facing_dropoff_links: oneTimeDriveSocialMap.rabbi_facing_dropoff_links || [],
          map_path: 'ops/one-time-mishnah-class/drive-social-ingestion-map.json',
        },
        login_release_guard: oneTimeDriveSocialMap.login_release_guard,
      }),
    ]
  )).rows[0] || (await db.query(
    `SELECT *
     FROM bna_service_providers
     WHERE provider_name = 'Rabbi Elie Scheller'
     ORDER BY id ASC
     LIMIT 1`
  )).rows[0];

  if (!provider) return null;

  const providerCommercialUpdate = await db.query(
    `UPDATE bna_service_providers
     SET project_id = COALESCE($4, project_id),
         provider_status = 'active_partner',
         commercial_model = 'revenue_share',
         entitlement_plan = 'revenue_share_partner',
         source_of_truth = 'hybrid',
         integration_status = CASE
           WHEN integration_status IN ('full_access', 'api_available', 'integrated') THEN integration_status
           ELSE 'access_requested'
         END,
         setup_package = COALESCE(setup_package, 'Partner launch and managed growth setup'),
         managed_services = COALESCE(managed_services, '{}'::jsonb) || $2::jsonb,
         public_listing_enabled = TRUE,
         public_signup_enabled = TRUE,
         claim_listing_enabled = FALSE,
         internal_owner = COALESCE(internal_owner, 'Shloimie'),
         commercial_notes = COALESCE(commercial_notes, 'Partner/revenue-share provider. Existing Replit/Vimeo delivery app stays external until inspected.'),
         metadata = COALESCE(metadata, '{}'::jsonb) || $3::jsonb,
         updated_at = NOW()
     WHERE id = $1
     RETURNING *`,
    [
      provider.id,
      JSON.stringify({
        funnel_setup: true,
        lead_pipeline: true,
        email_whatsapp_social: true,
        content_workflow: true,
        reporting: true,
        payment_links_manual: true,
      }),
      JSON.stringify({
        commercial_model: 'revenue_share',
        entitlement_plan: 'revenue_share_partner',
        external_delivery_system: 'Replit/Vimeo app',
        drive_social_ingestion: {
          root_folder_id: oneTimeDriveSocialMap.root.id,
          root_folder_url: oneTimeDriveSocialMap.root.webViewLink,
          content_media_folder_id: oneTimeDriveSocialMap.content_media_folder?.id || null,
          folder_links: oneTimeDriveSocialMap.folder_links || [],
          rabbi_facing_dropoff_links: oneTimeDriveSocialMap.rabbi_facing_dropoff_links || [],
          map_path: 'ops/one-time-mishnah-class/drive-social-ingestion-map.json',
        },
        login_release_guard: oneTimeDriveSocialMap.login_release_guard,
        project_key: ONE_TIME_PROJECT_KEY,
        workspace_key: 'rabbi_sheller_provider',
      }),
      oneTimeProjectId,
    ]
  );
  const commercialProvider = providerCommercialUpdate.rows[0] || provider;

  const service = (await db.query(
    `INSERT INTO bna_provider_services (
       provider_id, title, service_type, description, status, price_amount,
       currency, billing_period, age_min, age_max, group_size_min, group_size_max,
       capacity, city, tags, metadata, approved_at
     )
     SELECT $1, '7:00 Rabbi Scheller Mishnah class', 'mishnah_class',
       'Approved Rabbi-led Mishnah class option for families looking for a structured evening learning add-on.',
       'approved', NULL, 'ILS', 'class', 8, 16, 1, 12, 12, 'Beit Shemesh',
       ARRAY['rabbi-scheller', 'mishnah', 'evening-class', 'bna-approved'],
       $2, NOW()
     WHERE NOT EXISTS (
       SELECT 1 FROM bna_provider_services
       WHERE provider_id = $1 AND lower(title) = lower('7:00 Rabbi Scheller Mishnah class')
     )
     RETURNING *`,
    [provider.id, JSON.stringify({ seed: '2026-06-10-provider-directory', billing_guard: 'display_only_no_charges' })]
  )).rows[0] || (await db.query(
    `SELECT *
     FROM bna_provider_services
     WHERE provider_id = $1 AND lower(title) = lower('7:00 Rabbi Scheller Mishnah class')
     LIMIT 1`,
    [provider.id]
  )).rows[0];

  if (service) {
    await db.query(
      `INSERT INTO bna_provider_service_sessions (
         service_id, title, weekday, start_time, timezone, location, capacity, status, metadata
       )
       SELECT $1, '7:00 Mishnah class', 'weekday', '19:00', 'Asia/Jerusalem',
         'Provider location / online details pending', 12, 'active', $2
       WHERE NOT EXISTS (
         SELECT 1 FROM bna_provider_service_sessions
         WHERE service_id = $1 AND title = '7:00 Mishnah class'
       )`,
      [service.id, JSON.stringify({ seed: '2026-06-10-provider-directory' })]
    );
    await db.query(
      `INSERT INTO bna_provider_rabbi_links (
         service_id, rabbi_name, discount_type, discount_value, eligibility_rules, status, metadata
       )
       SELECT $1, 'Rabbi Elie Scheller', 'custom', NULL,
         'Discount eligibility is display-only until BNA defines Rabbi subscription rules and billing provider.',
         'active', $2
       WHERE NOT EXISTS (
         SELECT 1 FROM bna_provider_rabbi_links
         WHERE service_id = $1 AND rabbi_name = 'Rabbi Elie Scheller'
       )`,
      [service.id, JSON.stringify({ seed: '2026-06-10-provider-directory', billing_guard: 'no_live_charge' })]
    );
  }

  const membershipTiers = [
    {
      title: 'Mishnayos Membership - Video Library',
      price_amount: 67,
      metadata: { tier: 'video_library', external_delivery_system: 'Replit/Vimeo app', manual_link_mode: true },
      description: 'Video-library membership tier. Delivery remains in Rabbi Sheller external app/Vimeo until access is inspected.',
    },
    {
      title: 'Mishnayos Membership - Live Membership',
      price_amount: 149,
      metadata: { tier: 'live_membership', external_delivery_system: 'Replit/Vimeo app', manual_link_mode: true },
      description: 'Live membership tier with live classes and recordings. Payment/access sync is pending backend access.',
    },
  ];

  for (const tier of membershipTiers) {
    await db.query(
      `INSERT INTO bna_provider_services (
         provider_id, title, service_type, description, status, price_amount,
         currency, billing_period, age_min, age_max, group_size_min, group_size_max,
         capacity, city, tags, metadata, approved_at
       )
       SELECT $1, $2, 'mishnayos_membership', $3, 'approved', $4,
         'USD', 'month', 8, 18, 1, NULL, NULL, 'Online',
         ARRAY['rabbi-scheller', 'mishnayos-membership', 'external-delivery', 'manual-links'],
         $5::jsonb, NOW()
       WHERE NOT EXISTS (
         SELECT 1 FROM bna_provider_services
         WHERE provider_id = $1 AND lower(title) = lower($2)
       )`,
      [
        provider.id,
        tier.title,
        tier.description,
        tier.price_amount,
        JSON.stringify({ seed: '2026-06-11-provider-commercial-model', ...tier.metadata }),
      ]
    );
  }

  await seedProviderCommercialRows(commercialProvider, {
    planKey: 'revenue_share_partner',
    externalSystem: 'Replit/Vimeo app',
    accessStatus: 'requested',
    db,
  });

  return commercialProvider;
}

function serviceProviderFiltersFromQuery(query = {}) {
  return {
    city: String(query.city || '').trim(),
    service_type: String(query.service_type || query.type || '').trim(),
    max_price: query.max_price === undefined || query.max_price === '' ? null : Number(query.max_price),
    child_age: query.child_age === undefined || query.child_age === '' ? null : Number(query.child_age),
    approved_only: String(query.approved_only ?? 'true') !== 'false',
  };
}

async function getServiceProviderDirectory(filters = {}, db = pool) {
  const conditions = [];
  const params = [];

  if (filters.approved_only) {
    conditions.push(`p.status = 'approved'`);
    conditions.push(`s.status = 'approved'`);
  }
  if (filters.city) {
    params.push(`%${filters.city.toLowerCase()}%`);
    conditions.push(`lower(COALESCE(s.city, '')) LIKE $${params.length}`);
  }
  if (filters.service_type) {
    params.push(filters.service_type);
    conditions.push(`s.service_type = $${params.length}`);
  }
  if (Number.isFinite(filters.max_price)) {
    params.push(filters.max_price);
    conditions.push(`(s.price_amount IS NULL OR s.price_amount <= $${params.length})`);
  }
  if (Number.isFinite(filters.child_age)) {
    params.push(filters.child_age);
    const ageParam = `$${params.length}`;
    conditions.push(`(s.age_min IS NULL OR s.age_min <= ${ageParam})`);
    conditions.push(`(s.age_max IS NULL OR s.age_max >= ${ageParam})`);
  }

  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  const result = await db.query(
    `SELECT
       p.*,
       COALESCE((
         SELECT json_agg(ent.* ORDER BY ent.entitlement_key)
         FROM bna_provider_entitlements ent
         WHERE ent.provider_id = p.id
       ), '[]'::json) AS entitlements,
       COALESCE((
         SELECT json_agg(integration.* ORDER BY integration.integration_key)
         FROM bna_provider_integrations integration
         WHERE integration.provider_id = p.id
       ), '[]'::json) AS integrations,
       COALESCE((
         SELECT json_agg(checklist.* ORDER BY checklist.item_key)
         FROM bna_provider_access_checklist checklist
         WHERE checklist.provider_id = p.id
       ), '[]'::json) AS access_checklist,
       COALESCE(
         json_agg(
           json_build_object(
             'id', s.id,
             'title', s.title,
             'service_type', s.service_type,
             'description', s.description,
             'status', s.status,
             'price_amount', s.price_amount,
             'currency', s.currency,
             'billing_period', s.billing_period,
             'age_min', s.age_min,
             'age_max', s.age_max,
             'group_size_min', s.group_size_min,
             'group_size_max', s.group_size_max,
             'capacity', s.capacity,
             'city', s.city,
             'address', s.address,
             'latitude', s.latitude,
             'longitude', s.longitude,
             'tags', s.tags,
             'sessions', COALESCE((
               SELECT json_agg(sess.* ORDER BY sess.start_time NULLS LAST, sess.id)
               FROM bna_provider_service_sessions sess
               WHERE sess.service_id = s.id AND sess.status <> 'archived'
             ), '[]'::json),
             'rabbi_links', COALESCE((
               SELECT json_agg(link.* ORDER BY link.id)
               FROM bna_provider_rabbi_links link
               WHERE link.service_id = s.id AND link.status <> 'archived'
             ), '[]'::json)
           )
           ORDER BY s.title
         ) FILTER (WHERE s.id IS NOT NULL),
         '[]'::json
       ) AS services
     FROM bna_service_providers p
     JOIN bna_provider_services s ON s.provider_id = p.id
     ${whereClause}
     GROUP BY p.id
     ORDER BY p.provider_name ASC`,
    params
  );

  return result.rows;
}

