function oneTimeActor(req, body = {}) {
  return limitText(body.actor || body.updated_by || body.updatedBy || req.opsUser || 'dashboard', 120) || 'dashboard';
}

function oneTimeLongText(value = '', max = 20000) {
  return String(value || '').trim().slice(0, max);
}

function oneTimeJsonField(value, fallback) {
  if (value === undefined || value === null || value === '') return JSON.stringify(fallback);
  if (typeof value === 'string') {
    try {
      return JSON.stringify(JSON.parse(value));
    } catch {
      return JSON.stringify(fallback);
    }
  }
  return JSON.stringify(value);
}

function oneTimeOptionalUrl(value = '', fieldName = 'hosted URL') {
  return hostedHttpUrl(value || '', fieldName, { required: false });
}

function tierCanViewItem(memberTier = '', itemRequiredTier = '') {
  const tier = normalizeOneTimeMemberTier(memberTier);
  const required = normalizeOneTimeRequiredTier(itemRequiredTier);
  if (tier === 'admin_preview') return required !== 'smoke';
  if (required === 'smoke') return tier === 'smoke';
  if (required === 'admin_preview') return tier === 'admin_preview';
  if (required === 'all_members') return ['library_only', 'live_class'].includes(tier);
  if (required === 'live_class') return tier === 'live_class';
  return ['library_only', 'live_class'].includes(tier);
}

function libraryVisibilityAllowsMember(visibility = '', memberTier = '', requiredTier = '') {
  const normalizedVisibility = normalizeOneTimeLibraryVisibility(visibility);
  const tier = normalizeOneTimeMemberTier(memberTier);
  if (normalizedVisibility === 'smoke') return tier === 'smoke' && normalizeOneTimeRequiredTier(requiredTier) === 'smoke';
  if (normalizedVisibility !== 'tier') return false;
  return tierCanViewItem(tier, requiredTier);
}

