function buildOneTimeClassPackage(classSession, assets = [], libraryItems = []) {
  const session = oneTimeClassSessionView(classSession);
  const activeAssets = assets
    .map(oneTimeClassAssetView)
    .filter((asset) => asset.status !== 'archived');
  return {
    id: session.id,
    class_session: session,
    title: session.title,
    description: session.description,
    class_date: session.class_date,
    media_provider: session.media_provider,
    media_url: session.media_url,
    vimeo_id: session.vimeo_id,
    thumbnail_url: session.thumbnail_url,
    masechta: session.masechta,
    perek: session.perek,
    mishnah_range: session.mishnah_range,
    duration_seconds: session.duration_seconds,
    transcript: {
      status: session.transcript_status,
      text: session.transcript_text,
      notes: session.transcript_notes,
    },
    source_sheet_draft: session.source_sheet_draft,
    assets: activeAssets,
    library_items: libraryItems.map(oneTimeLibraryItemView),
    package_status: session.package_status,
    private_admin_only: {
      transcript_notes: session.transcript_notes,
      updated_by: session.updated_by,
    },
  };
}

function isOneTimeEditableSlideAsset(asset = {}) {
  const type = String(asset.asset_type || '').toLowerCase();
  if (!['slideshow', 'slide_deck'].includes(type)) return false;
  const url = String(asset.file_url || '');
  const metadata = asset.metadata && typeof asset.metadata === 'object' ? asset.metadata : {};
  return metadata.editable_source === true || /\.(pptx?|key)(?:[?#]|$)/i.test(url);
}

function buildMemberLibraryItemSnapshot(packageView = {}) {
  const safeAssets = (packageView.assets || [])
    .filter((asset) => asset.status !== 'archived')
    .filter((asset) => ['worksheet', 'source_sheet', 'slideshow', 'slide_deck', 'thumbnail', 'example', 'other'].includes(asset.asset_type))
    .filter((asset) => !isOneTimeEditableSlideAsset(asset))
    .map((asset) => ({
      id: asset.id,
      asset_type: asset.asset_type,
      title: asset.title,
      description: asset.description,
      file_url: asset.file_url,
      source_type: asset.source_type,
      status: asset.status,
    }));
  return {
    title: packageView.title || '',
    description: packageView.description || '',
    class_date: packageView.class_date || null,
    media_provider: packageView.media_provider || 'manual_url',
    media_url: packageView.media_url || '',
    vimeo_id: packageView.vimeo_id || '',
    thumbnail_url: packageView.thumbnail_url || '',
    masechta: packageView.masechta || '',
    perek: packageView.perek || '',
    mishnah_range: packageView.mishnah_range || '',
    duration_seconds: packageView.duration_seconds || null,
    assets: safeAssets,
    source_sheet_draft: packageView.source_sheet_draft || '',
    transcript_status: packageView.transcript?.status || 'draft',
  };
}

function clampOneTimeWatchPercent(value) {
  const number = Math.round(Number(value || 0));
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(100, number));
}

function clampOneTimeWatchSeconds(value) {
  const number = Math.round(Number(value || 0));
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(24 * 60 * 60, number));
}

function normalizeOneTimeWatchEventType(value = '') {
  const normalized = String(value || '').trim().toLowerCase().replace(/[-\s]+/g, '_');
  return ['open_media', 'progress', 'timeupdate', 'mark_complete', 'heartbeat'].includes(normalized) ? normalized : 'progress';
}

function oneTimeMemberWatchProgressView(row = {}) {
  return {
    watch_progress_seconds: clampOneTimeWatchSeconds(row.watch_seconds),
    watch_progress_percent: clampOneTimeWatchPercent(row.progress_percent),
    open_count: Number(row.open_count || 0),
    completed_at: row.completed_at || null,
    last_event_at: row.last_event_at || row.updated_at || null,
  };
}

function oneTimeMemberLibraryPublicView(row = {}, progress = {}) {
  const item = oneTimeLibraryItemView(row);
  const snapshot = item.package_snapshot || {};
  const assets = Array.isArray(snapshot.assets) ? snapshot.assets : [];
  const watchProgress = oneTimeMemberWatchProgressView(progress || {});
  return {
    id: item.id,
    class_session_id: item.class_session_id,
    title: item.title || snapshot.title || '',
    description: item.description || snapshot.description || '',
    class_date: item.class_date || snapshot.class_date || null,
    media_provider: item.media_provider || snapshot.media_provider || 'manual_url',
    media_url: item.media_url || snapshot.media_url || '',
    vimeo_id: item.vimeo_id || snapshot.vimeo_id || '',
    thumbnail_url: item.thumbnail_url || snapshot.thumbnail_url || '',
    masechta: snapshot.masechta || '',
    perek: snapshot.perek || '',
    mishnah_range: snapshot.mishnah_range || '',
    duration_seconds: snapshot.duration_seconds || null,
    watch_progress_seconds: watchProgress.watch_progress_seconds,
    watch_progress_percent: watchProgress.watch_progress_percent,
    watch_open_count: watchProgress.open_count,
    watch_completed_at: watchProgress.completed_at,
    watch_last_event_at: watchProgress.last_event_at,
    review_state: snapshot.transcript_status === 'approved' ? 'review_ready' : 'needs_review',
    assets: assets
      .filter((asset) => asset && asset.status !== 'archived')
      .filter((asset) => ['worksheet', 'source_sheet', 'slideshow', 'slide_deck', 'example', 'other'].includes(asset.asset_type))
      .filter((asset) => asset.file_url)
      .map((asset) => ({
        asset_type: normalizeOneTimeAssetType(asset.asset_type),
        title: asset.title || '',
        description: asset.description || '',
        file_url: asset.file_url || '',
      })),
    published_at: item.published_at || null,
  };
}

