function oneTimeParticipationEventView(row = {}) {
  return {
    id: row.id ? Number(row.id) : null,
    project_id: row.project_id ? Number(row.project_id) : null,
    curriculum_unit_id: row.curriculum_unit_id ? Number(row.curriculum_unit_id) : null,
    class_session_id: row.class_session_id ? Number(row.class_session_id) : null,
    community_thread_id: row.community_thread_id ? Number(row.community_thread_id) : null,
    community_message_id: row.community_message_id ? Number(row.community_message_id) : null,
    question_review_id: row.question_review_id ? Number(row.question_review_id) : null,
    assignment_id: row.assignment_id ? Number(row.assignment_id) : null,
    assignment_student_id: row.assignment_student_id ? Number(row.assignment_student_id) : null,
    actor_type: row.actor_type || 'member',
    actor_id: row.actor_id ? Number(row.actor_id) : null,
    actor_label: row.actor_label || 'Participant',
    event_type: normalizeOneTimeClassroomEventType(row.event_type),
    points: Number(row.points || 0),
    visibility: row.visibility || 'classroom',
    status: row.status || 'approved',
    featured: Boolean(row.featured),
    metadata: parseJsonMaybe(row.metadata),
    created_at: row.created_at || null,
  };
}

function oneTimeClassroomAssignmentView(row = {}) {
  return {
    id: row.id ? Number(row.id) : null,
    project_id: row.project_id ? Number(row.project_id) : null,
    class_session_id: row.class_session_id ? Number(row.class_session_id) : null,
    curriculum_unit_id: row.curriculum_unit_id ? Number(row.curriculum_unit_id) : null,
    title: row.title || '',
    instructions: row.instructions || '',
    source_type: row.source_type || 'manual',
    youtube_url: row.youtube_url || '',
    material_url: row.material_url || '',
    language_mode: row.language_mode || 'mixed',
    worksheet_type: row.worksheet_type || 'reflection',
    schedule_text: row.schedule_text || '',
    natural_language_request: row.natural_language_request || '',
    schedule_plan: parseJsonMaybe(row.schedule_plan),
    sync_mode: row.sync_mode || 'app_only',
    status: row.status || 'draft',
    classroom_visibility: row.classroom_visibility || 'students_parents',
    schedule_items: parseJsonArrayMaybe(row.schedule_items),
    created_at: row.created_at || null,
    updated_at: row.updated_at || null,
  };
}

function oneTimeClassroomParticipationSummary(events = []) {
  const map = new Map();
  for (const event of events.map(oneTimeParticipationEventView)) {
    if (event.status !== 'approved' || event.visibility !== 'classroom') continue;
    const key = `${event.actor_type}:${event.actor_id || event.actor_label}`;
    const current = map.get(key) || {
      actor_type: event.actor_type,
      actor_id: event.actor_id,
      actor_label: event.actor_label || 'Participant',
      approved_questions: 0,
      approved_responses: 0,
      rabbi_featured: 0,
      assignment_participation: 0,
      public_points: 0,
      reward_labels: [],
      latest_at: event.created_at,
    };
    if (event.event_type === 'approved_question') current.approved_questions += 1;
    if (event.event_type === 'approved_response') current.approved_responses += 1;
    if (event.event_type === 'rabbi_featured') current.rabbi_featured += 1;
    if (event.event_type === 'assignment_participation') current.assignment_participation += 1;
    current.public_points += Number(ONE_TIME_CLASSROOM_REWARD_WEIGHTS[event.event_type] || 0);
    current.latest_at = event.created_at || current.latest_at;
    map.set(key, current);
  }
  return [...map.values()]
    .sort((a, b) => Number(b.public_points || 0) - Number(a.public_points || 0) || String(b.latest_at || '').localeCompare(String(a.latest_at || '')))
    .slice(0, 12)
    .map((entry, index) => ({
      ...entry,
      public_rank: index + 1,
      reward_labels: oneTimeClassroomRewardLabels(entry),
    }));
}

function oneTimeClassroomRewardLabels(entry = {}) {
  const labels = [];
  if (Number(entry.rabbi_featured || 0) > 0) labels.push('Rabbi Featured');
  if (Number(entry.approved_questions || 0) > 0) labels.push('Published Question');
  if (Number(entry.approved_responses || 0) > 0) labels.push('Published Answer');
  if (Number(entry.assignment_participation || 0) > 0) labels.push('Review Participant');
  if (Number(entry.public_points || 0) >= 10) labels.push('Classroom Contributor');
  return labels.slice(0, 4);
}

function oneTimeClassroomRewardsScoreboard(events = []) {
  return oneTimeClassroomParticipationSummary(events)
    .filter((entry) => Number(entry.public_points || 0) > 0)
    .map((entry) => ({
      public_rank: entry.public_rank,
      actor_type: entry.actor_type,
      actor_id: entry.actor_id,
      actor_label: entry.actor_label || 'Approved participant',
      public_points: entry.public_points,
      approved_questions: entry.approved_questions,
      approved_responses: entry.approved_responses,
      rabbi_featured: entry.rabbi_featured,
      assignment_participation: entry.assignment_participation,
      reward_labels: entry.reward_labels,
      latest_at: entry.latest_at,
    }));
}

function oneTimeClassroomRewardPolicy() {
  return {
    title: 'Approved classroom rewards',
    member_visible: true,
    positive_only: true,
    source: 'approved classroom participation events',
    weights: ONE_TIME_CLASSROOM_REWARD_WEIGHTS,
    allowed_event_types: [...ONE_TIME_CLASSROOM_EVENT_TYPES],
    guardrails: [
      'Only approved classroom-visible events count.',
      'Raw private replies, held responses, rejected messages, and unreviewed student text are not exposed.',
      'No negative points, automatic prizes, coupons, discounts, access grants, or external notifications are created from the scoreboard.',
    ],
  };
}

function oneTimeClassroomScreenResponse(text = '') {
  const body = String(text || '').trim();
  const lower = body.toLowerCase();
  const flags = [];
  if (body.length > 2000) flags.push('too_long');
  if (/\b(stupid|idiot|hate|shut up|kill|die|curse|swear|bad word)\b/i.test(lower)) flags.push('inappropriate_language');
  if (/\b(phone|email|address|whatsapp|telegram|meet me|dm me|message me)\b/i.test(lower)) flags.push('personal_contact_or_direct_chat');
  if (/(?:\d[\s().-]?){7,}/.test(body) || /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(body)) flags.push('contact_info');
  const parentVisibleSafety = flags.some((flag) => ['inappropriate_language', 'personal_contact_or_direct_chat', 'contact_info'].includes(flag));
  return {
    status: flags.length ? 'held_for_parent_review' : 'needs_review',
    flags,
    parent_visible_safety: parentVisibleSafety,
    parent_escalation_status: parentVisibleSafety ? 'flagged' : 'none',
    safe_for_auto_publish: false,
    no_student_to_student_chat: true,
    screened_at: new Date().toISOString(),
  };
}

async function ensureOneTimeClassroomCommunity(db = pool) {
  const project = await getProjectByKey(ONE_TIME_PROJECT_KEY, db);
  const existing = (await db.query(
    `SELECT *
     FROM bna_learning_communities
     WHERE workspace_key = 'rabbi_sheller_provider'
       AND community_key = 'one-time-classroom'
     LIMIT 1`
  )).rows[0];
  if (existing) return existing;
  return (await db.query(
    `INSERT INTO bna_learning_communities (
       workspace_key, project_id, community_key, title, description, owner_name,
       visibility, status, metadata_json
     ) VALUES (
       'rabbi_sheller_provider', $1, 'one-time-classroom', 'One Time Mishnah Classroom',
       'Rabbi-led Mishnah classroom threads, questions, and approved participation.',
       'Rabbi Elie Scheller', 'members', 'active', $2::jsonb
     )
     ON CONFLICT (workspace_key, community_key)
     DO UPDATE SET
       project_id = COALESCE(bna_learning_communities.project_id, EXCLUDED.project_id),
       title = EXCLUDED.title,
       description = EXCLUDED.description,
       updated_at = NOW()
     RETURNING *`,
    [
      project.id,
      JSON.stringify({ seeded_by: 'one_time_classroom', no_open_student_chat: true }),
    ]
  )).rows[0];
}

async function getOneTimeClassroomCurriculum(db = pool) {
  const project = await getProjectByKey(ONE_TIME_PROJECT_KEY, db);
  const rows = (await db.query(
    `SELECT *
     FROM bna_curriculum_units
     WHERE workspace_key = 'rabbi_sheller_provider'
       AND curriculum_key = 'one-time-mishnah'
       AND project_id = $1
       AND status <> 'archived'
     ORDER BY sequence_index ASC, id ASC`,
    [project.id]
  )).rows;
  return rows.map(oneTimeCurriculumUnitView);
}

async function getOneTimeClassroomAssignments(projectId, db = pool, { memberSafe = false } = {}) {
  const conditions = ['a.project_id = $1', "COALESCE(a.status, 'draft') <> 'archived'"];
  if (memberSafe) {
    conditions.push("COALESCE(a.status, 'draft') IN ('scheduled', 'published', 'completed')");
    conditions.push("COALESCE(a.classroom_visibility, 'students_parents') IN ('members', 'students_parents', 'students')");
  }
  const rows = (await db.query(
    `SELECT a.*,
      COALESCE(
        (
          SELECT json_agg(json_build_object(
            'id', si.id,
            'title', si.title,
            'start_at', si.start_at,
            'end_at', si.end_at,
            'timezone', si.timezone,
            'display_label', si.display_label,
            'class_session_id', si.class_session_id,
            'curriculum_unit_id', si.curriculum_unit_id,
            'source', si.source
          ) ORDER BY si.start_at ASC NULLS LAST, si.id ASC)
          FROM bna_schedule_items si
          WHERE si.assignment_id = a.id
        ),
        '[]'
      ) AS schedule_items
     FROM bna_assignments a
     WHERE ${conditions.join(' AND ')}
     ORDER BY COALESCE((a.schedule_plan->>'scheduled_start_at')::timestamp, a.created_at) ASC NULLS LAST, a.id DESC
     LIMIT 80`,
    [projectId]
  )).rows;
  return rows.map(oneTimeClassroomAssignmentView);
}

async function getOneTimeClassroomThreads(projectId, db = pool, { memberSafe = false } = {}) {
  const threadConditions = ['t.project_id = $1', "t.status <> 'archived'"];
  if (memberSafe) {
    threadConditions.push("COALESCE(t.moderation_status, 'approved') = 'approved'");
  }
  const threads = (await db.query(
    `SELECT t.*
     FROM bna_community_threads t
     WHERE ${threadConditions.join(' AND ')}
     ORDER BY COALESCE(t.featured_rank, 999999) ASC, t.updated_at DESC, t.id DESC
     LIMIT 80`,
    [projectId]
  )).rows;
  const ids = threads.map((thread) => Number(thread.id)).filter(Boolean);
  const messages = ids.length
    ? (await db.query(
      `SELECT *
       FROM bna_community_messages
       WHERE thread_id = ANY($1::int[])
         ${memberSafe ? "AND status = 'visible' AND COALESCE(moderation_status, 'approved') = 'approved'" : ''}
       ORDER BY created_at ASC, id ASC`,
      [ids]
    )).rows
    : [];
  const byThread = new Map();
  for (const message of messages) {
    const key = Number(message.thread_id);
    if (!byThread.has(key)) byThread.set(key, []);
    byThread.get(key).push(message);
  }
  return threads.map((thread) => oneTimeClassroomThreadView(thread, byThread.get(Number(thread.id)) || [], { includePrivate: !memberSafe }));
}

async function getOneTimeClassroomParticipation(projectId, db = pool, { memberSafe = false } = {}) {
  const rows = (await db.query(
    `SELECT *
     FROM bna_classroom_participation_events
     WHERE project_id = $1
       AND status = 'approved'
       ${memberSafe ? "AND visibility = 'classroom'" : ''}
     ORDER BY created_at DESC, id DESC
     LIMIT 200`,
    [projectId]
  )).rows;
  const events = rows.map(oneTimeParticipationEventView);
  return {
    events: memberSafe ? events.slice(0, 40) : events,
    participation_summary: oneTimeClassroomParticipationSummary(events),
    leaderboard: oneTimeClassroomRewardsScoreboard(events),
    reward_policy: oneTimeClassroomRewardPolicy(),
  };
}

function oneTimeClassroomTopQa(threads = [], participation = {}) {
  const featuredMessages = [];
  for (const thread of threads || []) {
    for (const message of thread.messages || []) {
      if (message.leaderboard_eligible || message.featured_rank !== null) {
        featuredMessages.push({
          thread_id: thread.id,
          thread_title: thread.title,
          message_id: message.id,
          author_label: message.author_type === 'admin' || message.author_type === 'rabbi' ? message.author_name : 'Approved participant',
          body_preview: message.body_preview || message.body || '',
          featured_rank: message.featured_rank,
          created_at: message.created_at,
        });
      }
    }
  }
  return featuredMessages
    .sort((a, b) => Number(a.featured_rank ?? 999999) - Number(b.featured_rank ?? 999999) || String(b.created_at || '').localeCompare(String(a.created_at || '')))
    .slice(0, 12);
}

function oneTimeClassroomUpdateEventLabel(eventType = '') {
  const normalized = normalizeOneTimeClassroomEventType(eventType);
  if (normalized === 'approved_question') return 'Published question';
  if (normalized === 'approved_response') return 'Published answer';
  if (normalized === 'rabbi_featured') return 'Rabbi featured';
  if (normalized === 'assignment_participation') return 'Review participation';
  return 'Classroom progress';
}

function oneTimeClassroomUpdates(threads = [], participation = {}) {
  const updates = [];
  for (const thread of threads || []) {
    for (const message of thread.messages || []) {
      if (message.status !== 'visible' || message.moderation_status !== 'approved') continue;
      const isRabbi = message.author_type === 'admin' || message.author_type === 'rabbi';
      updates.push({
        id: `message:${message.id}`,
        update_type: message.leaderboard_eligible || message.featured_rank !== null ? 'featured_comment' : 'published_comment',
        title: isRabbi ? 'Rabbi posted an update' : 'Published classroom response',
        status_label: message.leaderboard_eligible || message.featured_rank !== null ? 'Published + scoreboard' : 'Published',
        actor_label: isRabbi ? message.author_name || 'Rabbi' : 'Approved participant',
        thread_id: thread.id,
        thread_title: thread.title || '',
        message_id: message.id,
        body_preview: message.body_preview || message.body || '',
        reward_labels: message.leaderboard_eligible || message.featured_rank !== null ? ['Published', 'Scoreboard eligible'] : ['Published'],
        points: message.leaderboard_eligible ? Number(ONE_TIME_CLASSROOM_REWARD_WEIGHTS.approved_response || 0) : 0,
        created_at: message.approved_at || message.created_at || thread.updated_at || thread.created_at || null,
      });
    }
  }
  for (const event of participation.events || []) {
    if (event.status !== 'approved' || event.visibility !== 'classroom') continue;
    const label = oneTimeClassroomUpdateEventLabel(event.event_type);
    updates.push({
      id: `event:${event.id}`,
      update_type: event.featured || event.event_type === 'rabbi_featured' ? 'award' : 'progress',
      title: event.featured || event.event_type === 'rabbi_featured' ? 'Good job - Rabbi featured this' : 'Good job - classroom progress',
      status_label: label,
      actor_label: event.actor_label || 'Approved participant',
      thread_id: event.community_thread_id || null,
      message_id: event.community_message_id || null,
      event_id: event.id,
      body_preview: `${label} counted toward the classroom scoreboard after review.`,
      reward_labels: oneTimeClassroomRewardLabels({
        approved_questions: event.event_type === 'approved_question' ? 1 : 0,
        approved_responses: event.event_type === 'approved_response' ? 1 : 0,
        rabbi_featured: event.event_type === 'rabbi_featured' ? 1 : 0,
        assignment_participation: event.event_type === 'assignment_participation' ? 1 : 0,
        public_points: Number(event.points || ONE_TIME_CLASSROOM_REWARD_WEIGHTS[event.event_type] || 0),
      }),
      points: Number(event.points || ONE_TIME_CLASSROOM_REWARD_WEIGHTS[event.event_type] || 0),
      created_at: event.created_at || null,
    });
  }
  return updates
    .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')))
    .slice(0, 16);
}

async function getOneTimeClassroomData({ db = pool, memberLibrary = null, memberSafe = false } = {}) {
  const project = await getProjectByKey(ONE_TIME_PROJECT_KEY, db);
  await ensureOneTimeClassroomCommunity(db);
  const curriculum = await getOneTimeClassroomCurriculum(db);
  const classRows = (await db.query(
    `SELECT cs.*
     FROM bna_class_sessions cs
     LEFT JOIN bna_curriculum_units cu ON cu.id = cs.curriculum_unit_id
     WHERE cs.project_id = $1
       ${memberSafe ? "AND COALESCE(cs.package_status, 'draft') = 'published'" : ''}
     ORDER BY COALESCE(cu.sequence_index, 999999) ASC, COALESCE(cs.classroom_sequence, 999999) ASC, COALESCE(cs.class_date, cs.created_at::date) DESC, cs.id DESC
     LIMIT 200`,
    [project.id]
  )).rows;
  const classIds = classRows.map((row) => Number(row.id)).filter(Boolean);
  const assignments = await getOneTimeClassroomAssignments(project.id, db, { memberSafe });
  const threads = await getOneTimeClassroomThreads(project.id, db, { memberSafe });
  const participation = await getOneTimeClassroomParticipation(project.id, db, { memberSafe });
  const memberItems = memberLibrary?.items || [];
  const visibleClassIds = new Set(memberItems.map((item) => Number(item.class_session_id)).filter(Boolean));
  const classes = classRows
    .map(oneTimeClassSessionView)
    .filter((session) => !memberSafe || visibleClassIds.has(Number(session.id)))
    .map((session) => ({
      ...session,
      transcript_text: memberSafe ? '' : session.transcript_text,
      transcript_notes: memberSafe ? '' : session.transcript_notes,
      transcript_segments: memberSafe ? [] : session.transcript_segments,
      transcript_versions: memberSafe ? {} : session.transcript_versions,
      transcript_glossary: memberSafe ? [] : session.transcript_glossary,
      transcript_release_audit: memberSafe ? {} : session.transcript_release_audit,
      member_library_item: memberItems.find((item) => Number(item.class_session_id) === Number(session.id)) || null,
    }));
  const todayKey = getTodayDateInTimeZone();
  const todayClass = classes.find((item) => item.daily_video || String(item.class_date || '').slice(0, 10) === todayKey) || classes[0] || null;
  return {
    project_key: ONE_TIME_PROJECT_KEY,
    workspace_key: 'rabbi_sheller_provider',
    curriculum,
    classes,
    visible_class_ids: classes.map((item) => Number(item.id)).filter(Boolean),
    today_video: todayClass,
    assignments,
    calendar_items: assignments.flatMap((assignment) => (assignment.schedule_items || []).map((item) => ({
      ...item,
      assignment_id: assignment.id,
      assignment_title: assignment.title,
      class_session_id: item.class_session_id || assignment.class_session_id,
      curriculum_unit_id: item.curriculum_unit_id || assignment.curriculum_unit_id,
    }))).sort((a, b) => String(a.start_at || '').localeCompare(String(b.start_at || ''))),
    threads,
    top_questions: oneTimeClassroomTopQa(threads, participation),
    class_updates: oneTimeClassroomUpdates(threads, participation),
    participation_summary: participation.participation_summary,
    leaderboard: participation.leaderboard,
    reward_policy: participation.reward_policy,
    participation_events: memberSafe ? [] : participation.events,
    bot_policy: {
      source_grounded_only: true,
      allowed_sources: ['approved class transcripts', 'source sheets/assets', 'assignments', 'internal calendar items', 'live-session eligibility', 'member access records'],
      unsupported_answer: 'route_to_rabbi_or_moderation',
      invented_sources_allowed: false,
    },
    guardrails: {
      no_student_to_student_chat: true,
      student_responses_require_moderation: true,
      google_writes_enabled: false,
      external_writes_enabled: false,
    },
  };
}

async function getOneTimeClassroomForAccessCode(accessCode = '', db = pool) {
  const memberLibrary = await getOneTimeMemberLibraryForAccessCode(accessCode, db);
  const classroom = await getOneTimeClassroomData({ db, memberLibrary, memberSafe: true });
  return {
    access: memberLibrary.access,
    member_library_items: memberLibrary.items,
    ...classroom,
  };
}

function oneTimeClassroomSourceMatches(query = '', source = {}) {
  const text = `${source.title || ''} ${source.body || ''} ${source.kind || ''}`.toLowerCase();
  const terms = String(query || '').toLowerCase().split(/[^a-z0-9]+/).filter((term) => term.length >= 3).slice(0, 10);
  if (!terms.length) return 0;
  return terms.reduce((score, term) => score + (text.includes(term) ? 1 : 0), 0);
}

async function buildOneTimeClassroomBotReply({ accessCode = '', message = '', db = pool } = {}) {
  const classroom = await getOneTimeClassroomForAccessCode(accessCode, db);
  const text = String(message || '').trim();
  if (!text) {
    const error = new Error('Message is required');
    error.statusCode = 400;
    throw error;
  }
  const lower = text.toLowerCase();
  if (/\b(zoom|live|next class|class link|meeting link)\b/.test(lower)) {
    const liveRows = (await db.query(
      `SELECT *
       FROM bna_live_class_sessions
       WHERE status IN ('scheduled', 'live')
       ORDER BY start_at ASC NULLS LAST, id ASC
       LIMIT 4`
    )).rows;
    const next = liveRows[0] || null;
    if (next) {
      const canShowZoom = ['live_class', 'live_plus_library'].includes(String(classroom.access.tier || '').toLowerCase());
      return {
        body: canShowZoom && next.zoom_meeting_url
          ? `The next live class is ${next.title || 'the next One Time class'} at ${next.start_at || 'the scheduled time'}. Your live access allows the Zoom link: ${next.zoom_meeting_url}`
          : `The next live class is ${next.title || 'the next One Time class'} at ${next.start_at || 'the scheduled time'}. Zoom links are shown only to live-access members.`,
        sources: [{ kind: 'live_session', id: next.id, title: next.title || 'Live class', start_at: next.start_at || null, zoom_link_allowed: canShowZoom }],
        unsupported: false,
      };
    }
  }
  if (/\b(due|assignment|homework|schedule|calendar|today|tomorrow)\b/.test(lower)) {
    const items = (classroom.calendar_items || []).slice(0, 5);
    if (items.length) {
      return {
        body: `Here are the next classroom calendar items: ${items.map((item) => `${item.assignment_title || item.title} (${item.start_at || 'scheduled'})`).join('; ')}.`,
        sources: items.map((item) => ({ kind: 'assignment_calendar', id: item.id, assignment_id: item.assignment_id, title: item.assignment_title || item.title, start_at: item.start_at })),
        unsupported: false,
      };
    }
  }
  const sources = [];
  for (const item of classroom.member_library_items || []) {
    sources.push({ kind: 'video', id: item.id, class_session_id: item.class_session_id, title: item.title, body: `${item.description || ''} ${(item.assets || []).map((asset) => `${asset.title} ${asset.description}`).join(' ')}` });
  }
  for (const cls of classroom.classes || []) {
    sources.push({ kind: 'class_session', id: cls.id, title: cls.title, body: `${cls.description || ''} ${cls.summary || ''} ${(cls.sources || []).map(classContentItemText).join(' ')}` });
  }
  for (const assignment of classroom.assignments || []) {
    sources.push({ kind: 'assignment', id: assignment.id, class_session_id: assignment.class_session_id, title: assignment.title, body: `${assignment.instructions || ''} ${assignment.schedule_text || ''}` });
  }
  const ranked = sources
    .map((source) => ({ ...source, score: oneTimeClassroomSourceMatches(text, source) }))
    .filter((source) => source.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 3);
  if (ranked.length) {
    return {
      body: `I can answer only from approved One Time classroom sources. The closest source is "${ranked[0].title}". ${limitText(ranked[0].body, 420)}\n\nA good critical-thinking question: What exact words in the Mishnah or source make you think that, and what is one alternate explanation?`,
      sources: ranked.map((source) => ({ kind: source.kind, id: source.id, class_session_id: source.class_session_id || null, title: source.title })),
      unsupported: false,
    };
  }
  return {
    body: 'I do not have an approved One Time source for that answer yet. I can help you turn it into a question for Rabbi review, but I should not invent a Torah answer or cite sources that are not in the class materials.',
    sources: [],
    unsupported: true,
    route_to: 'rabbi_moderation',
  };
}

function requireOneTimeLibraryApprovalFlag(body = {}) {
  const approvalFlag = String(body.approval_flag || body.approvalFlag || body.confirmation || '').trim();
  if (approvalFlag !== ONE_TIME_LIBRARY_APPROVAL_FLAG) {
    const error = new Error(`Publishing requires exact approval flag: ${ONE_TIME_LIBRARY_APPROVAL_FLAG}`);
    error.statusCode = 400;
    throw error;
  }
  return approvalFlag;
}

