async function ensureProjectOwnershipBackfill(bna, db = pool) {
  if (!bna?.id) return;
  const directProjectTables = [
    'signups',
    'bna_parent_leads',
    'bna_contact_communications',
    'bna_students',
    'bna_student_bot_settings',
    'bna_payment_log',
    'bna_payment_intake',
    'bna_accountability_events',
    'bna_group_goals',
    'bna_content_jobs',
    'bna_project_meetings',
    'bna_class_sessions',
    'bna_content_bundles',
    'bna_assignments',
  ];
  for (const tableName of directProjectTables) {
    await db.query(`UPDATE ${tableName} SET project_id = $1 WHERE project_id IS NULL`, [bna.id]);
  }
  await db.query(
    `UPDATE bna_students s
     SET project_id = signups.project_id
     FROM signups
     WHERE s.signup_id = signups.id
       AND signups.project_id IS NOT NULL
       AND s.project_id <> signups.project_id`
  );
  await db.query(
    `UPDATE bna_payment_log p
     SET project_id = s.project_id
     FROM signups s
     WHERE p.signup_id = s.id
       AND s.project_id IS NOT NULL
       AND p.project_id <> s.project_id`
  );
  await db.query(
    `UPDATE bna_payment_intake i
     SET project_id = s.project_id
     FROM signups s
     WHERE i.signup_id = s.id
       AND s.project_id IS NOT NULL
       AND i.project_id <> s.project_id`
  );
  await db.query(
    `UPDATE bna_student_bot_settings b
     SET project_id = s.project_id
     FROM bna_students s
     WHERE b.student_id = s.id
       AND s.project_id IS NOT NULL
       AND (b.project_id IS NULL OR b.project_id <> s.project_id)`
  );
}

function oneTimeProposalSeedTasks() {
  const proposalScheduleForIndex = (index) => {
    const dayOffset = Math.floor(index / 3);
    const hourOffset = (index % 3) * 2;
    const planned = new Date(Date.UTC(2026, 5, 10 + dayOffset, 7 + hourOffset, 0, 0));
    const due = new Date(planned);
    due.setUTCDate(due.getUTCDate() + (index < 9 ? 1 : 3));
    return {
      planned_at: planned.toISOString(),
      due_date: due.toISOString().slice(0, 10),
    };
  };
  const workflowDetailLines = (workflow) => {
    const sections = [
      workflow.task ? [`Workflow card task: ${workflow.task}`] : [],
      workflow.objective ? [`Objective: ${workflow.objective}`] : [],
      Array.isArray(workflow.required_fields) && workflow.required_fields.length
        ? [`${workflow.required_fields_label || 'Required lead fields'}:`, ...workflow.required_fields.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.membership_intent_options) && workflow.membership_intent_options.length
        ? ['Membership intent options:', ...workflow.membership_intent_options.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.proposed_tags) && workflow.proposed_tags.length
        ? ['Proposed community tags:', ...workflow.proposed_tags.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.market_versions) && workflow.market_versions.length
        ? ['Market versions:', ...workflow.market_versions.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.routing_rules) && workflow.routing_rules.length
        ? ['Routing rules:', ...workflow.routing_rules.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.tracking_fields) && workflow.tracking_fields.length
        ? ['Tracking fields:', ...workflow.tracking_fields.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.intake_channels) && workflow.intake_channels.length
        ? ['Intake channels:', ...workflow.intake_channels.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.support_categories) && workflow.support_categories.length
        ? ['Support categories:', ...workflow.support_categories.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.ticket_lifecycle) && workflow.ticket_lifecycle.length
        ? ['Ticket lifecycle:', ...workflow.ticket_lifecycle.map((item) => `- ${item}`)]
        : [],
      Array.isArray(workflow.current_state_checklist) && workflow.current_state_checklist.length
        ? ['Observe current state before approval:', ...workflow.current_state_checklist.map((item) => `- ${item}`)]
        : [],
      workflow.approval_gate ? [`Approval gate: ${workflow.approval_gate}`] : [],
      Array.isArray(workflow.smoke_tests) && workflow.smoke_tests.length
        ? ['Smoke-test criteria:', ...workflow.smoke_tests.map((item) => `- ${item}`)]
        : [],
    ].flat();
    return sections;
  };
  const decisionTasks = ONE_TIME_OPEN_DECISIONS.map((decision, index) => ({
    key: `decision-${index + 1}`,
    title: `Decide One Time ${decision}`,
    notes: `Final proposal remaining decision: ${decision}. Capture the answer before public launch.`,
    stage: 'needs_decision',
    category: decision.includes('software') || decision.includes('legal') ? 'legal' : 'admin',
    urgency: index < 3 ? 'today' : 'this_week',
    assigned_to: 'Shloimie',
    decision_required: true,
    ...proposalScheduleForIndex(index),
  }));
  const accessOffset = decisionTasks.length;
  const accessTasks = ONE_TIME_REQUIRED_ACCESS.map((item, index) => ({
    key: `access-${index + 1}`,
    title: `One Time access/materials: ${item.split(':')[0].slice(0, 120)}`,
    notes: item,
    stage: 'assigned',
    category: index === 2 ? 'technology' : 'admin',
    urgency: index === 0 ? 'today' : 'this_week',
    assigned_to: index === 2 ? 'Codex' : 'Rabbi Elie Scheller',
    decision_required: false,
    ...proposalScheduleForIndex(accessOffset + index),
  }));
  const workflowOffset = accessOffset + accessTasks.length;
  const workflowTasks = ONE_TIME_WORKFLOW_MAP.map((workflow, index) => ({
    key: `workflow-${workflow.code.toLowerCase()}`,
    title: `Workflow ${workflow.code}: ${workflow.name}`,
    notes: [
      `Proposal workflow ${workflow.code}: ${workflow.summary}`,
      `Owner: ${workflow.owner}.`,
      'Build or document this as a One Time workflow card. Observe current state first, write only after approval, and smoke-test the workflow after implementation.',
      ...workflowDetailLines(workflow),
    ].join('\n'),
    stage: workflow.assignee === 'Rabbi Elie Scheller' ? 'assigned' : 'assigned',
    category: safeTaskCategory(workflow.category),
    urgency: ['A', 'B', 'C', 'N', 'T'].includes(workflow.code) ? 'today' : 'this_week',
    assigned_to: workflow.assignee,
    decision_required: false,
    workflow_detail: workflow,
    ...proposalScheduleForIndex(workflowOffset + index),
  }));
  return [...decisionTasks, ...accessTasks, ...workflowTasks];
}

async function ensureOneTimeProposalTasks(oneTime, db = pool) {
  if (!oneTime?.id) return;
  const tasks = oneTimeProposalSeedTasks();
  for (const task of tasks) {
    await db.query(
      `INSERT INTO bna_tasks (
         title, notes, stage, category, urgency, source, source_context,
         created_by, assigned_to, ai_parsed, project_id, decision_required, author, due_date, planned_at
       )
       SELECT $1, $2, $3, $4, $5, 'google_drive', $6, 'system', $7, $8::jsonb, $9, $10, 'proposal-seed', $11::date, $12::timestamp
       WHERE NOT EXISTS (
         SELECT 1
         FROM bna_tasks existing
         WHERE existing.project_id = $9
           AND existing.ai_parsed->>'proposal_seed' = $13
           AND existing.ai_parsed->>'seed_key' = $14
       )`,
      [
        task.title,
        task.notes,
        task.stage,
        safeTaskCategory(task.category),
        safeTaskUrgency(task.urgency),
        `Seeded from ${ONE_TIME_FINAL_PROPOSAL.filename}`,
        normalizeTaskAssignee(task.assigned_to),
        JSON.stringify({
          proposal_seed: ONE_TIME_PROPOSAL_SEED,
          seed_key: task.key,
          source_proposal: ONE_TIME_FINAL_PROPOSAL,
          workflow_map: task.key.startsWith('workflow-'),
          workflow_detail: task.workflow_detail || null,
          proposal_schedule_source: 'tasks_schedule',
          proposal_schedule_label: 'One Time task schedule',
          planned_at: task.planned_at,
          due_date: task.due_date,
        }),
        oneTime.id,
        Boolean(task.decision_required),
        task.due_date,
        task.planned_at,
        ONE_TIME_PROPOSAL_SEED,
        task.key,
      ]
    );
    await db.query(
      `UPDATE bna_tasks existing
       SET due_date = COALESCE(existing.due_date, $1::date),
           planned_at = COALESCE(existing.planned_at, $2::timestamp),
           ai_parsed = COALESCE(existing.ai_parsed, '{}'::jsonb) || $3::jsonb,
           updated_at = CASE
             WHEN existing.due_date IS NULL
               OR existing.planned_at IS NULL
               OR COALESCE(existing.ai_parsed, '{}'::jsonb)->>'proposal_schedule_source' IS DISTINCT FROM $4
             THEN NOW()
             ELSE existing.updated_at
           END
       WHERE existing.project_id = $5
         AND existing.ai_parsed->>'proposal_seed' = $6
         AND existing.ai_parsed->>'seed_key' = $7`,
      [
        task.due_date,
        task.planned_at,
        JSON.stringify({
          proposal_schedule_source: 'tasks_schedule',
          proposal_schedule_label: 'One Time task schedule',
          source_proposal: ONE_TIME_FINAL_PROPOSAL,
          workflow_map: task.key.startsWith('workflow-'),
          workflow_detail: task.workflow_detail || null,
          planned_at: task.planned_at,
          due_date: task.due_date,
        }),
        'tasks_schedule',
        oneTime.id,
        ONE_TIME_PROPOSAL_SEED,
        task.key,
      ]
    );
    if (task.key === 'workflow-b' || ['workflow-d', 'workflow-e', 'workflow-f', 'workflow-h', 'workflow-i', 'workflow-j', 'workflow-k', 'workflow-l', 'workflow-n', 'workflow-p', 'workflow-q', 'workflow-s', 'workflow-t'].includes(task.key) || task.key === 'workflow-r' || task.key === 'workflow-g' || task.key === 'workflow-m' || task.key === 'workflow-o') {
      await db.query(
        `UPDATE bna_tasks existing
         SET notes = $1,
             category = $2,
             urgency = $3,
             assigned_to = $4,
             ai_parsed = COALESCE(existing.ai_parsed, '{}'::jsonb) || $5::jsonb,
             updated_at = NOW()
         WHERE existing.project_id = $6
           AND existing.ai_parsed->>'proposal_seed' = $7
           AND existing.ai_parsed->>'seed_key' = $8
           AND (
             existing.notes IS DISTINCT FROM $1
             OR COALESCE(existing.ai_parsed, '{}'::jsonb)->'workflow_detail' IS DISTINCT FROM ($5::jsonb)->'workflow_detail'
           )`,
        [
          task.notes,
          safeTaskCategory(task.category),
          safeTaskUrgency(task.urgency),
          normalizeTaskAssignee(task.assigned_to),
          JSON.stringify({
            source_proposal: ONE_TIME_FINAL_PROPOSAL,
            workflow_map: true,
            workflow_detail: task.workflow_detail || null,
          }),
          oneTime.id,
          ONE_TIME_PROPOSAL_SEED,
          task.key,
        ]
      );
    }
  }
}

async function backfillOneTimeTaskDialogueFields(oneTime, db = pool) {
  if (!oneTime?.id) return;
  await db.query(
    `UPDATE bna_tasks
     SET waiting_on = CASE
           WHEN waiting_on IS NULL OR trim(waiting_on) = '' THEN NULL
           WHEN lower(waiting_on) ~ '(rabbi|elie|scheller|sheller)' THEN 'rabbi'
           WHEN lower(waiting_on) ~ '(shloimie|shlomo|operator|manager|myself)' THEN 'shloimie'
           WHEN lower(waiting_on) ~ '(codex|kimi|agent|system|automation)' THEN NULL
           ELSE 'external'
         END,
         task_kind = CASE
           WHEN completed_at IS NOT NULL OR verified_at IS NOT NULL OR stage IN ('done', 'archive') THEN 'history'
           WHEN COALESCE(item_type, 'task') = 'decision' OR COALESCE(decision_required, FALSE) OR stage = 'needs_decision' THEN 'decision'
           WHEN COALESCE(waiting_on, '') <> ''
             AND lower(COALESCE(waiting_on, '')) !~ '(codex|kimi|agent|system|automation)' THEN 'pending_access'
           WHEN lower(COALESCE(assigned_to, '')) ~ '(codex|kimi|agent|system|automation)'
             OR COALESCE(agent_status, 'none') IN ('queued', 'running', 'failed', 'blocked_needs_human_decision') THEN 'agent_job'
           ELSE 'task'
         END,
         display_title = COALESCE(NULLIF(display_title, ''), NULLIF(ai_parsed->>'display_title', ''), title),
         raw_message = COALESCE(NULLIF(raw_message, ''), NULLIF(original_raw_message, ''), NULLIF(ai_parsed->>'original_text', '')),
         cleaned_summary = COALESCE(NULLIF(cleaned_summary, ''), NULLIF(summary, ''), NULLIF(notes, '')),
         bot_created = COALESCE(bot_created, FALSE)
           OR source IN ('telegram', 'ramble', 'web', 'content_job', 'import', 'google_drive')
           OR lower(COALESCE(created_by, '')) ~ '(bot|telegram|agent|codex|kimi|system)',
         why_exists = COALESCE(NULLIF(why_exists, ''), CASE
           WHEN completed_at IS NOT NULL OR verified_at IS NOT NULL OR stage IN ('done', 'archive') THEN 'Completed work is kept for project history.'
           WHEN COALESCE(item_type, 'task') = 'decision' OR COALESCE(decision_required, FALSE) OR stage = 'needs_decision' THEN 'A human choice is needed before this can move.'
           WHEN COALESCE(waiting_on, '') <> ''
             AND lower(COALESCE(waiting_on, '')) !~ '(codex|kimi|agent|system|automation)' THEN 'Missing access, assets, or outside input is blocking progress.'
           WHEN lower(COALESCE(assigned_to, '')) ~ '(codex|kimi|agent|system|automation)' THEN 'Machine work is tracked as an observable agent job.'
           ELSE 'Actionable work for the One Time workspace.'
         END),
         next_action = COALESCE(NULLIF(next_action, ''), NULLIF(next_action_label, ''), CASE
           WHEN COALESCE(item_type, 'task') = 'decision' OR COALESCE(decision_required, FALSE) OR stage = 'needs_decision' THEN 'Choose a path or ask for more information'
           WHEN COALESCE(waiting_on, '') <> ''
             AND lower(COALESCE(waiting_on, '')) !~ '(codex|kimi|agent|system|automation)' THEN 'Request the missing access or material'
           WHEN lower(COALESCE(assigned_to, '')) ~ '(codex|kimi|agent|system|automation)' THEN 'Watch agent job status'
           ELSE 'Start the next task step'
         END),
         last_activity_at = COALESCE(last_activity_at, updated_at, created_at),
         updated_at = NOW()
     WHERE project_id = $1`,
    [oneTime.id]
  );
}

async function ensureOneTimePendingAccessDialogueCards(oneTime, db = pool) {
  if (!oneTime?.id) return [];
  const specs = [
    {
      key: 'stripe-pending-access',
      pattern: 'stripe|payment processor|checkout',
      title: 'Get Stripe or payment-processor access',
      summary: 'Payment setup cannot be audited or configured until Shloimie has the active processor/login path.',
      notes: 'Manual placeholder only. Do not create payment products, checkout links, or live billing writes until access, processor choice, and approval are confirmed.',
      category: 'accounting',
      next_action: 'Ask Rabbi for processor/login access or confirm the alternate processor',
    },
    {
      key: 'vimeo-pending-access',
      pattern: 'vimeo|video library',
      title: 'Get Vimeo or video-library access',
      summary: 'Existing video assets and embeds need a manual audit before any member-library migration plan.',
      notes: 'Manual placeholder only. Do not upload to Vimeo, change privacy, or publish member-library assets from this card.',
      category: 'content',
      next_action: 'Ask Rabbi for Vimeo/library access or an export list',
    },
    {
      key: 'website-assets-pending-access',
      pattern: 'website assets|site assets|landing page assets|current website|homepage assets',
      title: 'Get website and landing-page assets',
      summary: 'The One Time launch page needs existing copy, images, brand assets, testimonials, and source URLs gathered before implementation.',
      notes: 'Manual placeholder only. This does not publish the website or push assets to external hosts.',
      category: 'marketing',
      next_action: 'Ask Rabbi for current website assets and approved launch copy',
    },
    {
      key: 'zoom-pending-access',
      pattern: 'zoom|live class link|meeting link',
      title: 'Get Zoom/manual live-class meeting details',
      summary: 'Live class operations need the manual Zoom link, host rules, reminder times, and recording handoff plan.',
      notes: 'Manual placeholder only. Do not schedule Zoom meetings or call the Zoom API from this task.',
      category: 'technology',
      next_action: 'Ask Rabbi for the Zoom/manual meeting link and host process',
    },
    {
      key: 'resend-pending-access',
      pattern: 'resend|sender domain|email sender',
      title: 'Get Resend sender access or domain status',
      summary: 'Warm launch email cannot move until sender ownership, domain authentication, and account access are clear.',
      notes: 'Manual placeholder only. Do not send emails or import lists from this card.',
      category: 'communications',
      next_action: 'Ask Rabbi for Resend access or sender-domain status',
    },
  ];
  const touched = [];
  for (const spec of specs) {
    const existing = (await db.query(
      `SELECT *
       FROM bna_tasks
       WHERE project_id = $1
         AND COALESCE(stage, '') NOT IN ('done', 'archive')
         AND lower(COALESCE(title, '') || ' ' || COALESCE(notes, '') || ' ' || COALESCE(summary, '')) ~ $2
       ORDER BY created_at ASC
       LIMIT 1`,
      [oneTime.id, spec.pattern]
    )).rows[0] || null;
    if (existing) {
      touched.push(existing);
      continue;
    }
    const created = await createTaskFromText({
      title: spec.title,
      raw_text: spec.summary,
      notes: spec.notes,
      summary: spec.summary,
      category: spec.category,
      urgency: spec.key.includes('zoom') ? 'today' : 'this_week',
      assigned_to: 'Rabbi Elie Scheller',
      waiting_on: 'rabbi',
      task_kind: 'pending_access',
      display_title: spec.title,
      why_exists: defaultWhyExistsForTaskKind('pending_access'),
      next_action: spec.next_action,
      next_action_label: spec.next_action,
      project: ONE_TIME_PROJECT_KEY,
      source: 'manual',
      source_channel: 'seed',
      created_by: 'system',
      bot_created: true,
      ai_parsed: {
        parser: 'rabbi-task-dialogue-pending-access-seed',
        seed_key: spec.key,
        kind: 'task',
        task_kind: 'pending_access',
        display_title: spec.title,
        original_text: spec.summary,
        no_external_write: true,
        manual_placeholder_only: true,
      },
    }, {}, db);
    touched.push(created);
  }
  return touched;
}

