function normalizedTaskTitleKey(title) {
  return String(title || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function taskIsTerminalHistory(task = {}) {
  return Boolean(
    task.completed_at
    || task.verified_at
    || ['done', 'archive'].includes(normalizeTaskStage(task.stage))
    || safeTaskKind(task.task_kind, null) === 'history'
  );
}

async function ensureRabbiSchellerLaunchTasks(oneTime, db = pool) {
  if (!oneTime?.id) return [];
  const specs = rabbiLaunchTaskSpecs();
  const touched = [];
  for (const spec of specs) {
    const titleKey = normalizedTaskTitleKey(spec.title);
    let existing = (await db.query(
      `SELECT t.*, p.project_key, p.name AS project_name, p.short_name AS project_short_name
       FROM bna_tasks t
       LEFT JOIN bna_projects p ON p.id = t.project_id
       WHERE t.project_id = $1
         AND COALESCE(t.stage, '') <> 'archive'
         AND (
           COALESCE(t.ai_parsed, '{}'::jsonb)->>'rabbi_launch_seed' = $2
           AND COALESCE(t.ai_parsed, '{}'::jsonb)->>'seed_key' = $3
         )
       ORDER BY t.created_at ASC
       LIMIT 1`,
      [oneTime.id, RABBI_SCHELLER_LAUNCH_SEED, spec.key]
    )).rows[0];
    if (!existing) {
      existing = (await db.query(
        `SELECT t.*, p.project_key, p.name AS project_name, p.short_name AS project_short_name
         FROM bna_tasks t
         LEFT JOIN bna_projects p ON p.id = t.project_id
         WHERE t.project_id = $1
           AND COALESCE(t.stage, '') <> 'archive'
           AND trim(regexp_replace(lower(regexp_replace(COALESCE(t.title, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $2
         ORDER BY t.created_at ASC
         LIMIT 1`,
        [oneTime.id, titleKey]
      )).rows[0];
    }

    const aiParsedPatch = {
      rabbi_launch_seed: RABBI_SCHELLER_LAUNCH_SEED,
      seed_key: spec.key,
      parser: 'rabbi-scheller-launch-seed',
      kind: spec.item_type === 'decision' ? 'decision' : 'task',
      display_title: spec.title,
      original_text: spec.summary || spec.title,
      agent_executable: Boolean(spec.agent_executable),
    };
    const specWaitingOn = spec.waiting_on ? normalizeTaskWaitingOnKey(spec.waiting_on, 'external') : null;
    const specTaskKind = spec.item_type === 'decision'
      ? 'decision'
      : specWaitingOn
        ? 'pending_access'
        : isAgentAssignee(spec.assigned_to)
          ? 'agent_job'
          : 'task';
    if (!existing) {
      const created = await createTaskFromText({
        title: spec.title,
        raw_text: spec.summary || spec.title,
        notes: spec.notes,
        summary: spec.summary,
        item_type: spec.item_type,
        stage: spec.stage,
        category: spec.category,
        urgency: spec.urgency,
        assigned_to: spec.assigned_to,
        decision_owner: spec.decision_owner,
        waiting_on: specWaitingOn || spec.waiting_on,
        decision_prompt: spec.decision_prompt,
        decision_options_json: spec.decision_options_json,
        due_date: spec.due_date || null,
        next_action_label: spec.next_action_label,
        task_kind: specTaskKind,
        display_title: spec.title,
        why_exists: defaultWhyExistsForTaskKind(specTaskKind),
        next_action: spec.next_action_label,
        cleaned_summary: spec.summary,
        bot_created: true,
        source: 'manual',
        source_channel: 'seed',
        created_by: 'system',
        project: ONE_TIME_PROJECT_KEY,
        agent_executable: Boolean(spec.agent_executable),
        ai_parsed: aiParsedPatch,
      }, {}, db);
      touched.push({ ...created, launch_seed_created: true });
      continue;
    }

    const nextOptions = normalizeDecisionOptions(spec.decision_options_json);
    const existingOptions = normalizeDecisionOptions(existing.decision_options_json);
    const existingTerminal = taskIsTerminalHistory(existing);
    const nextItemType = existingTerminal ? (existing.item_type || spec.item_type || 'task') : (spec.item_type || 'task');
    const nextStage = existingTerminal
      ? (normalizeTaskStage(existing.stage) === 'archive' ? 'archive' : 'done')
      : (spec.stage || 'assigned');
    const nextTaskKind = existingTerminal ? 'history' : specTaskKind;
    const nextDecisionRequired = existingTerminal ? false : spec.item_type === 'decision';
    const nextWhyExists = existingTerminal ? defaultWhyExistsForTaskKind('history') : defaultWhyExistsForTaskKind(specTaskKind);
    const nextAction = existingTerminal
      ? 'Review completed result'
      : (spec.next_action_label || defaultNextActionForDialogue({ taskKind: specTaskKind, waitingOn: specWaitingOn, assignedTo: spec.assigned_to }));
    const changed = [
      ['title', spec.title],
      ['summary', spec.summary || null],
      ['notes', spec.notes || null],
      ['item_type', nextItemType],
      ['stage', nextStage],
      ['category', safeTaskCategory(spec.category)],
      ['urgency', safeTaskUrgency(spec.urgency)],
      ['assigned_to', normalizeTaskAssignee(spec.assigned_to)],
      ['decision_owner', normalizeTaskPerson(spec.decision_owner)],
      ['waiting_on', specWaitingOn],
      ['decision_prompt', spec.decision_prompt || null],
      ['due_date', spec.due_date || null],
      ['next_action_label', spec.next_action_label || null],
      ['task_kind', nextTaskKind],
      ['display_title', spec.title],
      ['why_exists', nextWhyExists],
      ['next_action', nextAction],
      ['cleaned_summary', spec.summary || null],
      ...(existingTerminal ? [['agent_status', 'completed']] : []),
    ].some(([key, value]) => String(existing[key] ?? '') !== String(value ?? ''))
      || JSON.stringify(existingOptions) !== JSON.stringify(nextOptions)
      || (existing.ai_parsed || {})?.rabbi_launch_seed !== RABBI_SCHELLER_LAUNCH_SEED;

    let task = existing;
    if (changed) {
      const updated = await db.query(
        `UPDATE bna_tasks
         SET title = $1,
             summary = $2,
             notes = $3,
             item_type = $4,
             stage = $5,
             category = $6,
             urgency = $7,
             assigned_to = $8,
             decision_owner = $9,
             waiting_on = $10,
             decision_required = $11,
             decision_prompt = $12,
             decision_options_json = $13::jsonb,
             due_date = $14::date,
             next_action_label = $15,
             task_kind = $16,
             display_title = $17,
             why_exists = $18,
             next_action = $19,
             cleaned_summary = $20,
             agent_status = CASE WHEN $21::boolean THEN 'completed' ELSE agent_status END,
             raw_message = COALESCE(raw_message, $22),
             bot_created = TRUE,
             ai_parsed = COALESCE(ai_parsed, '{}'::jsonb) || $23::jsonb,
             last_activity_at = COALESCE(last_activity_at, created_at),
             updated_at = NOW()
         WHERE id = $24
         RETURNING *`,
        [
          spec.title,
          spec.summary || null,
          spec.notes || null,
          nextItemType,
          nextStage,
          safeTaskCategory(spec.category),
          safeTaskUrgency(spec.urgency),
          normalizeTaskAssignee(spec.assigned_to),
          normalizeTaskPerson(spec.decision_owner),
          specWaitingOn,
          nextDecisionRequired,
          spec.decision_prompt || null,
          JSON.stringify(nextOptions),
          spec.due_date || null,
          spec.next_action_label || null,
          nextTaskKind,
          spec.title,
          nextWhyExists,
          nextAction,
          spec.summary || null,
          existingTerminal,
          spec.summary || spec.title,
          JSON.stringify(aiParsedPatch),
          existing.id,
        ]
      );
      task = updated.rows[0] || existing;
      await recordTaskActivity(task.id, 'rabbi_launch_seed_updated', {
        actor: 'system',
        summary: 'Rabbi Scheller launch seed clarified this workspace task.',
        metadata: { seed_key: spec.key, seed: RABBI_SCHELLER_LAUNCH_SEED },
      }, db);
    }
    if (!taskIsTerminalHistory(task) && (spec.agent_executable || isAgentAssignee(task.assigned_to))) {
      await ensureAgentJobForTask(task, { agent_executable: true, source: 'rabbi_launch_seed' }, db);
      task = await fetchTaskWithProject(task.id, db) || task;
    }
    touched.push({ ...task, launch_seed_created: false, launch_seed_updated: changed });
  }
  return touched;
}

