async function ensureAssistantPortalReadinessTasks(bna, db = pool) {
  if (!bna?.id) return [];
  const touched = [];
  for (const spec of assistantPortalReadinessTaskSpecs()) {
    const titleKey = normalizedTaskTitleKey(spec.title);
    const existing = (await db.query(
      `SELECT *
       FROM bna_tasks
       WHERE project_id = $1
         AND COALESCE(stage, '') <> 'archive'
         AND (
           COALESCE(ai_parsed, '{}'::jsonb)->>'assistant_portal_seed' = '2026-06-14'
           AND COALESCE(ai_parsed, '{}'::jsonb)->>'seed_key' = $2
           OR trim(regexp_replace(lower(regexp_replace(COALESCE(title, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $3
         )
       ORDER BY created_at ASC
       LIMIT 1`,
      [bna.id, spec.key, titleKey]
    )).rows[0] || null;
    const aiParsed = {
      assistant_portal_seed: '2026-06-14',
      seed_key: spec.key,
      parser: 'assistant-portal-readiness-seed',
      agent_executable: Boolean(spec.agent_executable),
    };
    if (!existing) {
      const created = await createTaskFromText({
        title: spec.title,
        raw_text: spec.summary || spec.title,
        summary: spec.summary,
        notes: spec.notes || spec.summary,
        item_type: spec.item_type || 'task',
        stage: spec.stage || 'assigned',
        category: spec.category || 'operations',
        urgency: spec.urgency || 'this_week',
        assigned_to: spec.assigned_to || 'Shloimie',
        decision_owner: spec.decision_owner,
        waiting_on: spec.waiting_on,
        next_action_label: spec.next_action_label,
        source: 'manual',
        source_channel: 'seed',
        created_by: 'system',
        project: DEFAULT_PROJECT_KEY,
        agent_executable: Boolean(spec.agent_executable),
        ai_parsed: aiParsed,
      }, {}, db);
      touched.push(created);
      continue;
    }
    const existingTerminal = taskIsTerminalHistory(existing);
    const nextItemType = existingTerminal ? (existing.item_type || spec.item_type || 'task') : (spec.item_type || 'task');
    const nextStage = existingTerminal
      ? (normalizeTaskStage(existing.stage) === 'archive' ? 'archive' : 'done')
      : (spec.stage || 'assigned');
    const nextDecisionRequired = existingTerminal ? false : (spec.item_type || 'task') === 'decision';
    const nextActionLabel = existingTerminal ? (existing.next_action_label || 'Review completed result') : (spec.next_action_label || null);
    const updated = (await db.query(
      `UPDATE bna_tasks
       SET summary = COALESCE($2, summary),
           notes = COALESCE($3, notes),
           item_type = $4,
           stage = $5,
           category = $6,
           urgency = $7,
           assigned_to = $8,
           waiting_on = $9,
           decision_owner = $10,
           decision_required = $11,
           next_action_label = $12,
           task_kind = CASE WHEN $14::boolean THEN 'history' ELSE task_kind END,
           agent_status = CASE WHEN $14::boolean THEN 'completed' ELSE agent_status END,
           completed_at = CASE WHEN $14::boolean THEN COALESCE(completed_at, NOW()) ELSE completed_at END,
           next_action = CASE WHEN $14::boolean THEN COALESCE(next_action, 'Review completed result') ELSE next_action END,
           why_exists = CASE WHEN $14::boolean THEN COALESCE(why_exists, $15) ELSE why_exists END,
           ai_parsed = COALESCE(ai_parsed, '{}'::jsonb) || $13::jsonb,
           updated_at = NOW()
       WHERE id = $1
       RETURNING *`,
      [
        existing.id,
        spec.summary || null,
        spec.notes || null,
        nextItemType,
        nextStage,
        safeTaskCategory(spec.category || 'operations'),
        safeTaskUrgency(spec.urgency || 'this_week'),
        normalizeTaskAssignee(spec.assigned_to || 'Shloimie'),
        spec.waiting_on ? normalizeTaskPerson(spec.waiting_on) : null,
        normalizeTaskPerson(spec.decision_owner),
        nextDecisionRequired,
        nextActionLabel,
        JSON.stringify(aiParsed),
        existingTerminal,
        defaultWhyExistsForTaskKind('history'),
      ]
    )).rows[0] || existing;
    if (!taskIsTerminalHistory(updated) && (spec.agent_executable || isAgentAssignee(updated.assigned_to))) {
      await ensureAgentJobForTask(updated, { agent_executable: true, source: 'assistant_portal_seed' }, db);
    }
    touched.push(updated);
  }
  return touched;
}

async function ensureDefaultProjects(db = pool) {
  const bna = await upsertProject({
    projectKey: DEFAULT_PROJECT_KEY,
    name: 'BNA',
    shortName: 'BNA',
    description: 'Bnei Neviim Academy operations, students, content, contacts, and accounting.',
  }, db);
  const oneTime = await upsertProject({
    projectKey: ONE_TIME_PROJECT_KEY,
    name: 'One Time Mishnah Class',
    shortName: 'One Time',
    description: 'Rabbi Elie Scheller task manager, comments, Torah class prep, and Mishnah class planning.',
    metadata: {
      agent: 'rabbi-elie-scheller',
      preferred_source_lookup: 'sefaria',
    },
  }, db);

  await ensureProjectMember(bna, 'Shloimie', { role: 'operator', access_level: 'owner' }, db);
  const oneTimeAssignments = oneTimeOwnerAssignments();
  const oneTimeCanonicalAssignments = oneTimeCanonicalOwnerAssignments();
  const oneTimeOwnerAssignment = oneTimeAssignments.find((assignment) => assignment.access_level === 'owner')
    || oneTimeAssignments[0]
    || { person_name: 'Rabbi Elie Scheller', role: 'project owner', access_level: 'owner' };
  const oneTimeManagerAssignment = oneTimeAssignments.find((assignment) => assignment.person_name === 'Shloimie')
    || oneTimeAssignments.find((assignment) => assignment.access_level === 'manager')
    || { person_name: 'Shloimie', role: 'project admin', access_level: 'manager' };
  const oneTimeOwnerCanonical = oneTimeCanonicalAssignments.find((assignment) => assignment.person_name === oneTimeOwnerAssignment.person_name)
    || oneTimeCanonicalAssignments[0]
    || {};
  const oneTimeManagerCanonical = oneTimeCanonicalAssignments.find((assignment) => assignment.person_name === oneTimeManagerAssignment.person_name)
    || oneTimeCanonicalAssignments[1]
    || {};
  await ensureProjectMember(oneTime, oneTimeOwnerAssignment.person_name, {
    role: oneTimeOwnerAssignment.role,
    access_level: oneTimeOwnerAssignment.access_level,
    login_username: ONE_TIME_OWNER_USERNAME || null,
    metadata: {
      account_type: 'external_user',
      project_scope: ONE_TIME_PROJECT_KEY,
      workspace_scope: 'rabbi_sheller_provider',
      canonical_role: oneTimeOwnerCanonical.canonical_role || 'workspace_owner',
      canonical_role_label: oneTimeOwnerCanonical.canonical_role_label || 'Workspace Owner',
      compatibility_role: oneTimeOwnerCanonical.compatibility_role || oneTimeOwnerAssignment.role,
      role_contract: 'one-time-role-model-v1',
      account_owner: true,
      allowed_views: ['dashboard', 'watchdog', 'pipelines', 'tasks', 'agents', 'contacts', 'community', 'studio', 'content', 'calendar', 'service_providers', 'communications', 'internal_dialogue', 'api_usage', 'integrations', 'settings'],
    },
  }, db);
  await ensureProjectMember(oneTime, oneTimeManagerAssignment.person_name, {
    role: oneTimeManagerAssignment.role,
    access_level: oneTimeManagerAssignment.access_level,
    login_username: ONE_TIME_MANAGER_USERNAME || ONE_TIME_OPS_USERNAME || null,
    metadata: {
      account_type: 'internal_admin',
      project_scope: ONE_TIME_PROJECT_KEY,
      workspace_scope: 'rabbi_sheller_provider',
      canonical_role: oneTimeManagerCanonical.canonical_role || 'workspace_manager',
      canonical_role_label: oneTimeManagerCanonical.canonical_role_label || 'Workspace Manager',
      platform_role: oneTimeManagerCanonical.platform_role || 'platform_super_admin',
      platform_role_label: oneTimeManagerCanonical.platform_role_label || 'Platform Super Admin',
      compatibility_role: oneTimeManagerCanonical.compatibility_role || oneTimeManagerAssignment.role,
      role_contract: 'one-time-role-model-v1',
      admin_for_owner: 'Rabbi Elie Scheller',
      admin_for_owner_source: oneTimeOwnerAssignment.person_name,
    },
  }, db);

  await ensureProjectOwnershipBackfill(bna, db);

  if (oneTime?.id) {
    await db.query(
      `UPDATE bna_tasks
       SET project_id = $1
       WHERE
         project_id IS NULL
         AND (
           category IN ('torah_class_prep', 'shiur_ideas', 'community_setup', 'community')
           OR lower(COALESCE(title, '') || ' ' || COALESCE(notes, '')) ~ '(one time|mishnah|mishna|rabbi elie scheller|elie scheller|shiur)'
         )`,
      [oneTime.id]
    );
  }
  if (bna?.id) {
    await db.query(
      `UPDATE bna_tasks
       SET project_id = $1
       WHERE project_id IS NULL`,
      [bna.id]
    );
  }
  await ensureOneTimeProposalTasks(oneTime, db);
  await ensureRabbiSchellerLaunchTasks(oneTime, db);
  await ensureOneTimePendingAccessDialogueCards(oneTime, db);
  await backfillOneTimeTaskDialogueFields(oneTime, db);
  await ensureAssistantPortalReadinessTasks(bna, db);

  return { bna, oneTime };
}

