const WORKSPACE_USER_PLATFORM_ROLES = new Set([
  'platform_super_admin',
  'platform_manager',
  'support_admin',
  'technical_agent',
]);

const WORKSPACE_USER_WORKSPACE_ROLES = new Set([
  'workspace_owner',
  'workspace_admin',
  'workspace_manager',
  'provider_staff',
  'moderator',
]);

const WORKSPACE_USER_MEMBER_ROLES = new Set(['parent', 'student']);

function normalizeWorkspaceUserRoleKey(value = '') {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/['"]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function normalizeWorkspaceUserCanonicalRole(value = '') {
  const key = normalizeWorkspaceUserRoleKey(value);
  const oneTimeRole = normalizeOneTimeRole(key);
  if (
    WORKSPACE_USER_PLATFORM_ROLES.has(oneTimeRole) ||
    WORKSPACE_USER_WORKSPACE_ROLES.has(oneTimeRole) ||
    WORKSPACE_USER_MEMBER_ROLES.has(oneTimeRole)
  ) {
    return oneTimeRole;
  }
  const aliases = {
    super_admin: 'platform_super_admin',
    platform: 'platform_super_admin',
    owner: 'workspace_owner',
    project_owner: 'workspace_owner',
    rabbi: 'workspace_owner',
    admin: 'workspace_admin',
    one_time_admin: 'workspace_admin',
    project_admin: 'workspace_admin',
    manager: 'workspace_manager',
    project_manager: 'workspace_manager',
    service_provider: 'provider_staff',
    teacher: 'provider_staff',
    child: 'student',
    member_parent: 'parent',
  };
  return aliases[key] || (WORKSPACE_USER_MEMBER_ROLES.has(key) ? key : 'provider_staff');
}

function workspaceUserRoleLabel(role = '') {
  const canonical = normalizeWorkspaceUserCanonicalRole(role);
  return oneTimeRoleLabel(canonical);
}

function workspaceUserRoleScope(role = '') {
  const canonical = normalizeWorkspaceUserCanonicalRole(role);
  if (WORKSPACE_USER_PLATFORM_ROLES.has(canonical)) return 'platform';
  if (WORKSPACE_USER_MEMBER_ROLES.has(canonical)) return 'member';
  return 'workspace';
}

function workspaceUserAccessLevelForRole(role = '', fallback = '') {
  const canonical = normalizeWorkspaceUserCanonicalRole(role);
  const requested = String(fallback || '').trim().toLowerCase();
  if (['owner', 'admin', 'manager', 'member', 'viewer'].includes(requested)) return requested;
  if (canonical === 'platform_super_admin' || canonical === 'workspace_owner') return 'owner';
  if (['platform_manager', 'support_admin', 'workspace_admin'].includes(canonical)) return 'admin';
  if (['technical_agent', 'workspace_manager'].includes(canonical)) return 'manager';
  if (['provider_staff', 'moderator', 'parent', 'student'].includes(canonical)) return 'member';
  return 'viewer';
}

function workspaceUserInputMetadata(body = {}, canonicalRole = '') {
  const metadata = body.metadata && typeof body.metadata === 'object' ? body.metadata : {};
  const roleScope = workspaceUserRoleScope(canonicalRole);
  const allowedViews = normalizeTextArray(body.allowed_views || body.allowedViews || metadata.allowed_views || []);
  return {
    ...metadata,
    role_contract: 'workspace-membership-role-model-v1',
    canonical_role: canonicalRole,
    canonical_role_label: workspaceUserRoleLabel(canonicalRole),
    role_scope: roleScope,
    account_type: normalizeWorkspaceUserRoleKey(body.account_type || body.accountType || metadata.account_type || (
      roleScope === 'member' ? `one_time_${canonicalRole}` : 'workspace_user'
    )),
    project_scope: metadata.project_scope,
    workspace_scope: metadata.workspace_scope,
    provider_staff_management: ['provider_staff', 'moderator', 'workspace_manager', 'workspace_admin', 'workspace_owner'].includes(canonicalRole),
    access_entitlement_status: normalizeWorkspaceUserRoleKey(body.access_entitlement_status || body.accessEntitlementStatus || metadata.access_entitlement_status || 'not_configured'),
    login_state: normalizeWorkspaceUserRoleKey(body.login_state || body.loginState || metadata.login_state || 'not_configured'),
    parent_child_relationship: body.parent_child_relationship || body.parentChildRelationship || metadata.parent_child_relationship || null,
    enrollment_relationship: body.enrollment_relationship || body.enrollmentRelationship || metadata.enrollment_relationship || null,
    allowed_views: allowedViews,
    no_send: true,
  };
}

function workspaceUserView(row = {}) {
  if (!row) return null;
  const metadata = parseJsonMaybe(row.metadata);
  const projectMemberMetadata = parseJsonMaybe(row.project_member_metadata);
  const canonicalRole = normalizeWorkspaceUserCanonicalRole(row.canonical_role || metadata.canonical_role || projectMemberMetadata.canonical_role || row.role);
  const active = row.active !== false && row.person_status !== 'archived';
  const loginUsername = row.login_username || projectMemberMetadata.login_username || metadata.login_username || '';
  return {
    id: row.id,
    membership_id: row.id,
    person_id: row.person_id,
    person_name: oneTimeDisplayName(row.person_name || row.preferred_name || row.full_name || row.login_username || ''),
    full_name: row.full_name || '',
    email: row.email || projectMemberMetadata.email || metadata.email || '',
    phone: row.phone || projectMemberMetadata.phone || metadata.phone || '',
    workspace_id: row.workspace_id,
    workspace_key: workspaceKeyForProject(row.project_key || row.workspace_key),
    project_key: row.project_key || row.workspace_key,
    workspace_name: row.workspace_name || row.project_name || '',
    workspace_type: row.workspace_type || '',
    role: row.role,
    canonical_role: canonicalRole,
    canonical_role_label: workspaceUserRoleLabel(canonicalRole),
    role_scope: workspaceUserRoleScope(canonicalRole),
    access_level: row.access_level || workspaceUserAccessLevelForRole(canonicalRole),
    invitation_state: row.invitation_state || metadata.invitation_state || (active ? 'active' : 'disabled'),
    active,
    disabled_at: row.disabled_at || null,
    last_activity_at: row.last_activity_at || projectMemberMetadata.last_activity_at || metadata.last_activity_at || row.updated_at || null,
    login_state: row.login_state || metadata.login_state || projectMemberMetadata.login_state || (loginUsername ? 'configured' : 'not_configured'),
    login_username: loginUsername || '',
    relationship_to_owner: row.relationship_to_owner || '',
    parent_child_relationship: metadata.parent_child_relationship || null,
    enrollment_relationship: metadata.enrollment_relationship || null,
    access_entitlement_status: metadata.access_entitlement_status || projectMemberMetadata.access_entitlement_status || 'not_configured',
    tags: Array.isArray(row.tags) ? row.tags : [],
    metadata: {
      ...metadata,
      canonical_role: canonicalRole,
      canonical_role_label: workspaceUserRoleLabel(canonicalRole),
    },
    created_at: row.created_at,
    updated_at: row.updated_at,
  };
}

async function workspaceUserRowByMembershipId(membershipId, db = pool) {
  const result = await db.query(
    `SELECT wm.*,
            p.project_key,
            p.name AS workspace_name,
            p.workspace_type,
            people.preferred_name AS person_name,
            people.full_name,
            people.email,
            people.phone,
            people.status AS person_status,
            pm.login_username,
            pm.metadata AS project_member_metadata
     FROM bna_workspace_memberships wm
     JOIN bna_projects p ON p.id = wm.workspace_id
     JOIN bna_people people ON people.id = wm.person_id
     LEFT JOIN bna_project_members pm
       ON pm.project_id = p.id
      AND lower(pm.person_name) = lower(people.preferred_name)
     WHERE wm.id = $1
     LIMIT 1`,
    [membershipId]
  );
  return result.rows[0] || null;
}

function requireWorkspaceUserPermission(req, action, workspaceKey, targetRole = '') {
  const key = assertWorkspaceAccess(req, workspaceKey, action);
  const identity = req.opsIdentity || identifyOpsUser(req.opsUser || OPS_USERNAME);
  if (!identity || identity.scope?.type === 'all') return key;
  const canonicalTargetRole = normalizeWorkspaceUserCanonicalRole(targetRole || 'provider_staff');
  const oneTimeAction = action === 'read_role_audit_log'
    ? 'read_role_audit_log'
    : action === 'remove_workspace_user'
      ? 'remove_workspace_user'
      : action === 'deactivate_workspace_user'
        ? 'deactivate_workspace_user'
        : action === 'invite_workspace_user'
          ? 'invite_workspace_user'
          : 'change_workspace_role';
  const permission = canOneTimeIdentity(oneTimeAction, identity, {
    workspace_key: key,
    project_key: workspaceProjectKey(key),
    target_role: canonicalTargetRole,
  });
  if (!permission.allowed) {
    const error = new Error(permission.reason);
    error.statusCode = 403;
    throw error;
  }
  return key;
}

async function insertWorkspaceRoleAuditEvent({
  workspace_id = null,
  membership_id = null,
  actor_person_id = null,
  target_person_id = null,
  event_type = 'workspace_role_changed',
  from_role = '',
  to_role = '',
  reason = '',
  metadata = {},
} = {}, db = pool) {
  try {
    const result = await db.query(
      `INSERT INTO bna_platform_role_audit_events (
         workspace_id, membership_id, actor_person_id, target_person_id,
         event_type, from_role, to_role, reason, metadata
       ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb)
       RETURNING *`,
      [
        workspace_id || null,
        membership_id || null,
        actor_person_id || null,
        target_person_id || null,
        limitText(event_type, 120) || 'workspace_role_changed',
        from_role || null,
        to_role || null,
        limitText(reason, 600) || null,
        JSON.stringify(metadata || {}),
      ]
    );
    return result.rows[0] || null;
  } catch (err) {
    console.warn('Workspace role audit insert failed:', err.message);
    return null;
  }
}

function householdView(row = {}, members = []) {
  if (!row) return null;
  return {
    id: row.id,
    workspace_id: row.workspace_id,
    workspace_key: row.workspace_key || row.project_key,
    household_name: row.household_name,
    primary_parent_person_id: row.primary_parent_person_id,
    status: row.status,
    filter_setup_status: row.filter_setup_status || 'not_started',
    filter_setup_code: row.filter_setup_code || null,
    filter_setup_notes: row.filter_setup_notes || null,
    metadata: parseJsonMaybe(row.metadata),
    members,
    created_at: row.created_at,
    updated_at: row.updated_at,
  };
}

function personLookupName(value = '') {
  return normalizeLooseText(value).replace(/\s+/g, ' ').trim();
}

async function upsertCanonicalPerson({
  preferred_name,
  full_name = '',
  email = '',
  phone = '',
  primary_language = 'en',
  avatar_url = '',
  status = 'active',
  metadata = {},
} = {}, db = pool) {
  const preferredName = limitText(preferred_name || full_name || email || phone || '', 180);
  if (!preferredName) {
    const error = new Error('preferred_name is required for bna_people');
    error.statusCode = 400;
    throw error;
  }
  const normalizedEmail = normalizeEmail(email) || null;
  const normalizedPhone = normalizePhoneDigits(phone) || null;
  const normalizedName = personLookupName(preferredName);
  let existing = null;
  if (normalizedEmail) {
    existing = (await db.query(
      `SELECT * FROM bna_people WHERE lower(email) = lower($1) ORDER BY id ASC LIMIT 1`,
      [normalizedEmail]
    )).rows[0] || null;
  }
  if (!existing && normalizedPhone) {
    existing = (await db.query(
      `SELECT *
       FROM bna_people
       WHERE regexp_replace(COALESCE(phone, ''), '\\D', '', 'g') = $1
       ORDER BY id ASC
       LIMIT 1`,
      [normalizedPhone]
    )).rows[0] || null;
  }
  if (!existing && normalizedName) {
    existing = (await db.query(
      `SELECT *
       FROM bna_people
       WHERE trim(regexp_replace(lower(regexp_replace(COALESCE(preferred_name, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $1
          OR trim(regexp_replace(lower(regexp_replace(COALESCE(full_name, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $1
       ORDER BY id ASC
       LIMIT 1`,
      [normalizedName]
    )).rows[0] || null;
  }
  if (existing) {
    return (await db.query(
      `UPDATE bna_people
       SET preferred_name = COALESCE(NULLIF($2, ''), preferred_name),
           full_name = COALESCE(NULLIF($3, ''), full_name),
           email = COALESCE($4, email),
           phone = COALESCE($5, phone),
           primary_language = $6,
           avatar_url = COALESCE(NULLIF($7, ''), avatar_url),
           status = $8,
           metadata = COALESCE(metadata, '{}'::jsonb) || $9::jsonb,
           updated_at = NOW()
       WHERE id = $1
       RETURNING *`,
      [
        existing.id,
        preferredName,
        limitText(full_name, 220) || null,
        normalizedEmail,
        normalizedPhone || limitText(phone, 80) || null,
        ['en', 'he'].includes(primary_language) ? primary_language : 'en',
        limitText(avatar_url, 520) || null,
        ['active', 'pending', 'inactive', 'archived'].includes(status) ? status : 'active',
        JSON.stringify(metadata || {}),
      ]
    )).rows[0];
  }
  return (await db.query(
    `INSERT INTO bna_people (
       preferred_name, full_name, email, phone, primary_language,
       avatar_url, status, metadata
     ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8::jsonb)
     RETURNING *`,
    [
      preferredName,
      limitText(full_name, 220) || null,
      normalizedEmail,
      normalizedPhone || limitText(phone, 80) || null,
      ['en', 'he'].includes(primary_language) ? primary_language : 'en',
      limitText(avatar_url, 520) || null,
      ['active', 'pending', 'inactive', 'archived'].includes(status) ? status : 'active',
      JSON.stringify(metadata || {}),
    ]
  )).rows[0];
}

async function ensureWorkspaceProject({
  projectKey,
  name,
  shortName,
  description = '',
  workspaceType = 'project',
  ownerPersonId = null,
  visibility = 'private',
  languageDefault = 'en',
  slug = '',
  settings = {},
  metadata = {},
} = {}, db = pool) {
  const project = await upsertProject({
    projectKey,
    name,
    shortName: shortName || name,
    description,
    metadata,
  }, db);
  if (!project?.id) return project || fallbackWorkspaceProjectRow(projectKey);
  return (await db.query(
    `UPDATE bna_projects
     SET workspace_type = $2,
         owner_person_id = COALESCE($3, owner_person_id),
         visibility = $4,
         language_default = $5,
         slug = COALESCE(NULLIF($6, ''), slug),
         settings = COALESCE(settings, '{}'::jsonb) || $7::jsonb,
         updated_at = NOW()
     WHERE id = $1
     RETURNING *`,
    [
      project.id,
      workspaceType,
      ownerPersonId || null,
      ['private', 'workspace', 'public'].includes(visibility) ? visibility : 'private',
      ['en', 'he'].includes(languageDefault) ? languageDefault : 'en',
      limitText(slug || projectKey, 160),
      JSON.stringify(settings || {}),
    ]
  )).rows[0];
}

async function ensureWorkspaceMembership(workspace, person, {
  role = 'viewer',
  access_level = 'member',
  relationship_to_owner = '',
  tags = [],
  metadata = {},
} = {}, db = pool) {
  if (!workspace?.id || !person?.id) return null;
  const result = await db.query(
    `INSERT INTO bna_workspace_memberships (
       workspace_id, person_id, role, access_level, relationship_to_owner, tags, metadata
     ) VALUES ($1, $2, $3, $4, $5, $6::text[], $7::jsonb)
     ON CONFLICT (workspace_id, person_id, role) DO UPDATE SET
       access_level = EXCLUDED.access_level,
       relationship_to_owner = COALESCE(EXCLUDED.relationship_to_owner, bna_workspace_memberships.relationship_to_owner),
       tags = (
         SELECT ARRAY(
           SELECT DISTINCT tag
           FROM unnest(COALESCE(bna_workspace_memberships.tags, '{}'::text[]) || COALESCE(EXCLUDED.tags, '{}'::text[])) AS tag
           WHERE COALESCE(tag, '') <> ''
           ORDER BY tag
         )
       ),
       metadata = COALESCE(bna_workspace_memberships.metadata, '{}'::jsonb) || EXCLUDED.metadata,
       active = TRUE,
       updated_at = NOW()
     RETURNING *`,
    [
      workspace.id,
      person.id,
      role,
      ['owner', 'admin', 'manager', 'member', 'viewer'].includes(access_level) ? access_level : 'member',
      limitText(relationship_to_owner, 120) || null,
      normalizeTextArray(tags),
      JSON.stringify(metadata || {}),
    ]
  );
  const membership = result.rows[0];
  await ensurePersonWorkspaceRole(workspace, person, {
    role,
    access_level,
    relationship_to_owner,
    tags,
    metadata: { ...(metadata || {}), source_membership_id: membership.id },
  }, db).catch(() => {});
  return membership;
}

function identityWorkspaceKeyForProject(projectOrWorkspace = {}) {
  const key = projectOrWorkspace.project_key || projectOrWorkspace.workspace_key || '';
  if (key === DEFAULT_PROJECT_KEY || key === 'bna') return 'bna_school';
  if (key === 'dratler_family' || key === 'family_app') return 'family_app';
  return normalizeProjectKey(key || projectOrWorkspace.slug || projectOrWorkspace.name || 'workspace');
}

async function upsertPersonContact(person, {
  contact_type = 'email',
  contact_value = '',
  label = '',
  is_primary = false,
  metadata = {},
} = {}, db = pool) {
  if (!person?.id || !contact_value) return null;
  const type = ['email', 'phone', 'whatsapp', 'telegram', 'other'].includes(contact_type) ? contact_type : 'other';
  const normalized = type === 'email'
    ? normalizeEmail(contact_value)
    : ['phone', 'whatsapp'].includes(type)
      ? normalizeIdentityPhone(contact_value)
      : limitText(contact_value, 240);
  if (!normalized) return null;
  const result = await db.query(
    `INSERT INTO bna_person_contacts (
       person_id, contact_type, contact_value, normalized_value, label, is_primary, metadata
     ) VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb)
     ON CONFLICT (person_id, contact_type, normalized_value) WHERE normalized_value IS NOT NULL
     DO UPDATE SET
       contact_value = EXCLUDED.contact_value,
       label = COALESCE(EXCLUDED.label, bna_person_contacts.label),
       is_primary = bna_person_contacts.is_primary OR EXCLUDED.is_primary,
       metadata = COALESCE(bna_person_contacts.metadata, '{}'::jsonb) || EXCLUDED.metadata,
       updated_at = NOW()
     RETURNING *`,
    [
      person.id,
      type,
      limitText(contact_value, 240),
      normalized,
      limitText(label, 120) || null,
      Boolean(is_primary),
      JSON.stringify(metadata || {}),
    ]
  );
  return result.rows[0];
}

async function ensureIdentityWorkspace(workspace = {}, db = pool) {
  const projectId = workspace.project_id || workspace.id || null;
  const workspaceKey = identityWorkspaceKeyForProject(workspace);
  const displayName = workspace.display_name || workspace.name || workspace.short_name || workspaceKey;
  const workspaceType = workspace.workspace_type || (workspaceKey === 'bna_school' ? 'school' : workspaceKey === 'family_app' ? 'family' : 'project');
  const result = await db.query(
    `INSERT INTO bna_identity_workspaces (
       workspace_key, project_id, display_name, workspace_type, metadata
     ) VALUES ($1, $2, $3, $4, $5::jsonb)
     ON CONFLICT (workspace_key) DO UPDATE SET
       project_id = COALESCE(EXCLUDED.project_id, bna_identity_workspaces.project_id),
       display_name = EXCLUDED.display_name,
       workspace_type = EXCLUDED.workspace_type,
       metadata = COALESCE(bna_identity_workspaces.metadata, '{}'::jsonb) || EXCLUDED.metadata,
       updated_at = NOW()
     RETURNING *`,
    [
      workspaceKey,
      Number.isFinite(Number(projectId)) ? Number(projectId) : null,
      limitText(displayName, 180),
      limitText(workspaceType, 60) || 'project',
      JSON.stringify({ source: 'ensure_identity_workspace', project_key: workspace.project_key || workspace.workspace_key || null }),
    ]
  );
  return result.rows[0];
}

