async function createMergeReview({
  review_type = 'possible_duplicate',
  person_id = null,
  candidate_person_id = null,
  household_id = null,
  reason = '',
  signals = {},
  metadata = {},
} = {}, db = pool) {
  const existing = (await db.query(
    `SELECT *
     FROM bna_identity_merge_reviews
     WHERE status = 'open'
       AND COALESCE(person_id, 0) = COALESCE($1, 0)
       AND COALESCE(candidate_person_id, 0) = COALESCE($2, 0)
       AND COALESCE(household_id, 0) = COALESCE($3, 0)
       AND COALESCE(reason, '') = COALESCE($4, '')
     ORDER BY created_at DESC
     LIMIT 1`,
    [person_id, candidate_person_id, household_id, reason]
  )).rows[0];
  if (existing) return existing;
  return (await db.query(
    `INSERT INTO bna_identity_merge_reviews (
       review_type, person_id, candidate_person_id, household_id, reason, signals, metadata
     ) VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7::jsonb)
     RETURNING *`,
    [
      limitText(review_type, 80) || 'possible_duplicate',
      person_id || null,
      candidate_person_id || null,
      household_id || null,
      limitText(reason, 500) || null,
      JSON.stringify(signals || {}),
      JSON.stringify(metadata || {}),
    ]
  )).rows[0];
}

async function ensureAccountabilitySection({ household_id = null, workspace_id = null, section_key = '', label = '', sort_order = 100, metadata = {} } = {}, db = pool) {
  const key = slugifySectionKey(section_key || label || 'custom');
  const displayLabel = limitText(label || key.replace(/_/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase()), 120);
  const result = await db.query(
    `INSERT INTO bna_accountability_sections (
       household_id, workspace_id, section_key, label, sort_order, metadata
     ) VALUES ($1, $2, $3, $4, $5, $6::jsonb)
     ON CONFLICT (COALESCE(household_id, 0), section_key) WHERE status <> 'archived'
     DO UPDATE SET
       workspace_id = COALESCE(EXCLUDED.workspace_id, bna_accountability_sections.workspace_id),
       label = EXCLUDED.label,
       sort_order = LEAST(COALESCE(bna_accountability_sections.sort_order, EXCLUDED.sort_order), EXCLUDED.sort_order),
       status = 'active',
       metadata = COALESCE(bna_accountability_sections.metadata, '{}'::jsonb) || EXCLUDED.metadata,
       updated_at = NOW()
     RETURNING *`,
    [
      household_id || null,
      workspace_id || null,
      key,
      displayLabel,
      Number.isFinite(Number(sort_order)) ? Number(sort_order) : 100,
      JSON.stringify(metadata || {}),
    ]
  );
  return result.rows[0];
}

