async function ensureHouseholdChildPerson(household, {
  name = '',
  primary_language = 'en',
  relationship = '',
  tags = [],
  metadata = {},
} = {}, db = pool) {
  if (!household?.id || !name) return null;
  const nameKey = normalizePersonNameKey(name);
  if (!nameKey) return null;
  const existing = (await db.query(
    `SELECT p.*
     FROM bna_household_members hm
     JOIN bna_people p ON p.id = hm.person_id
     WHERE hm.household_id = $1
       AND hm.role = 'child'
       AND hm.active = TRUE
       AND (
         trim(regexp_replace(lower(regexp_replace(COALESCE(p.preferred_name, ''), '[^a-zA-Z0-9\u0590-\u05ff]+', ' ', 'g')), '\\s+', ' ', 'g')) = $2
         OR trim(regexp_replace(lower(regexp_replace(COALESCE(p.full_name, ''), '[^a-zA-Z0-9\u0590-\u05ff]+', ' ', 'g')), '\\s+', ' ', 'g')) = $2
       )
     ORDER BY p.id ASC
     LIMIT 1`,
    [household.id, nameKey]
  )).rows[0] || null;
  const person = existing || (await db.query(
    `INSERT INTO bna_people (
       preferred_name, full_name, primary_language, status, metadata
     ) VALUES ($1, $2, $3, 'active', $4::jsonb)
     RETURNING *`,
    [
      limitText(name, 180),
      limitText(name, 220),
      ['en', 'he'].includes(primary_language) ? primary_language : 'en',
      JSON.stringify({ ...(metadata || {}), child_name_only_merge_scope: 'household' }),
    ]
  )).rows[0];
  await ensureHouseholdMember(household, person, {
    role: 'child',
    relationship,
    tags: ['household:child', ...normalizeTextArray(tags)],
    metadata,
  }, db);
  return person;
}

async function findPersonByExactContact({ email = '', phone = '' } = {}, db = pool) {
  const normalizedEmail = normalizeEmail(email);
  const normalizedPhone = normalizeIdentityPhone(phone);
  const existingByEmail = normalizedEmail ? (await db.query(
    `SELECT * FROM bna_people WHERE lower(COALESCE(email, '')) = $1 ORDER BY id ASC LIMIT 1`,
    [normalizedEmail]
  )).rows[0] || null : null;
  const existingByPhone = normalizedPhone ? (await db.query(
    `SELECT *
     FROM bna_people
     WHERE regexp_replace(COALESCE(phone, ''), '\\D', '', 'g') = $1
        OR EXISTS (
          SELECT 1
          FROM bna_person_contacts pc
          WHERE pc.person_id = bna_people.id
            AND pc.contact_type IN ('phone', 'whatsapp')
            AND pc.normalized_value = $1
        )
     ORDER BY id ASC
     LIMIT 1`,
    [normalizedPhone]
  )).rows[0] || null : null;
  return { existingByEmail, existingByPhone, normalizedEmail, normalizedPhone };
}

async function resolveParentPersonByContact({
  name = '',
  email = '',
  phone = '',
  household_id = null,
  metadata = {},
} = {}, db = pool) {
  const lookup = await findPersonByExactContact({ email, phone }, db);
  if (!lookup.normalizedEmail && !lookup.normalizedPhone) {
    return (await db.query(
      `INSERT INTO bna_people (
         preferred_name, full_name, primary_language, status, metadata
       ) VALUES ($1, $2, 'en', 'active', $3::jsonb)
       RETURNING *`,
      [
        limitText(name || 'Parent', 180),
        limitText(name || 'Parent', 220),
        JSON.stringify({ source: 'identity_linking_parent_no_contact', no_name_only_merge: true, ...(metadata || {}) }),
      ]
    )).rows[0];
  }
  const decision = parentMergeDecision(lookup);
  if (decision.action === 'review') {
    await createMergeReview({
      review_type: 'parent_contact_conflict',
      person_id: decision.person_id,
      candidate_person_id: decision.candidate_person_id,
      household_id,
      reason: decision.reason,
      signals: { email: lookup.normalizedEmail, phone: lookup.normalizedPhone },
      metadata,
    }, db);
    return lookup.existingByEmail;
  }
  const person = decision.action === 'use_existing'
    ? (lookup.existingByEmail || lookup.existingByPhone)
    : await upsertCanonicalPerson({
      preferred_name: name || email || phone,
      full_name: name || email || phone,
      email,
      phone,
      metadata: { source: 'identity_linking_parent', ...(metadata || {}) },
    }, db);
  if (email) await upsertPersonContact(person, { contact_type: 'email', contact_value: email, is_primary: true, metadata }, db).catch(() => {});
  if (phone) await upsertPersonContact(person, { contact_type: 'phone', contact_value: phone, is_primary: !email, metadata }, db).catch(() => {});
  return person;
}

async function ensureDefaultAccountabilitySections({ household_id = null, workspace_id = null } = {}, db = pool) {
  const rows = [];
  for (const section of DEFAULT_ACCOUNTABILITY_SECTIONS) {
    rows.push(await ensureAccountabilitySection({
      household_id,
      workspace_id,
      ...section,
      metadata: { seed: 'identity_linking_default_sections' },
    }, db));
  }
  return rows;
}

async function linkSignupIdentity(signup = {}, signupStudent = null, db = pool) {
  if (!signup?.id) return null;
  const parentEmail = normalizeEmail(signup.parent_email);
  const parentPhone = signup.parent_phone || '';
  if (!parentEmail && !parentPhone) return null;
  const context = parentEmail
    ? await getCurrentHouseholdForParentEmail(parentEmail, db)
    : null;
  const workspace = context?.workspace || await getProjectByKey(DEFAULT_PROJECT_KEY, db);
  const household = context?.household || await ensureHousehold(workspace, {
    household_name: `${signup.parent_name || signup.parent_email || 'Parent'} Household`,
    status: 'active',
    metadata: { source: 'signup_identity_link', signup_id: signup.id },
  }, db);
  const primaryParent = await resolveParentPersonByContact({
    name: signup.parent_name,
    email: signup.parent_email,
    phone: signup.parent_phone,
    household_id: household?.id,
    metadata: { signup_id: signup.id, role: 'primary_parent' },
  }, db);
  if (primaryParent && household) {
    await ensureHouseholdMember(household, primaryParent, { role: 'parent', relationship: 'parent', tags: ['household:parent'], metadata: { signup_id: signup.id } }, db);
  }
  const secondaryParent = (signup.parent2_email || signup.parent2_phone || signup.parent2_name)
    ? await resolveParentPersonByContact({
      name: signup.parent2_name,
      email: signup.parent2_email,
      phone: signup.parent2_phone,
      household_id: household?.id,
      metadata: { signup_id: signup.id, role: 'secondary_parent' },
    }, db)
    : null;
  if (secondaryParent && household) {
    await ensureHouseholdMember(household, secondaryParent, { role: 'parent', relationship: 'parent', tags: ['household:parent', 'secondary_parent'], metadata: { signup_id: signup.id } }, db);
  }
  const childPerson = household && signup.student_name
    ? await ensureHouseholdChildPerson(household, {
      name: signup.student_name,
      primary_language: recordPreferredLanguage(signup) || 'en',
      tags: ['signup:student'],
      metadata: { signup_id: signup.id, source: 'signups' },
    }, db)
    : null;
  if (workspace && primaryParent) {
    await ensurePersonWorkspaceRole(workspace, primaryParent, { role: 'parent', access_level: 'member', tags: ['bna:parent'], metadata: { signup_id: signup.id } }, db).catch(() => {});
  }
  if (workspace && childPerson) {
    await ensurePersonWorkspaceRole(workspace, childPerson, { role: 'student', access_level: 'member', tags: ['bna:student'], metadata: { signup_id: signup.id } }, db).catch(() => {});
  }
  await ensureDefaultAccountabilitySections({ household_id: household?.id, workspace_id: workspace?.id }, db).catch(() => {});
  await db.query(
    `UPDATE signups
     SET primary_parent_person_id = COALESCE(primary_parent_person_id, $2),
         secondary_parent_person_id = COALESCE(secondary_parent_person_id, $3),
         parent_person_id = COALESCE(parent_person_id, $2),
         student_person_id = COALESCE(student_person_id, $4),
         household_id = COALESCE(household_id, $5),
         workspace_id = COALESCE(workspace_id, $6),
         project_id = COALESCE(project_id, $6),
         identity_backfilled_at = COALESCE(identity_backfilled_at, NOW()),
         updated_at = NOW()
     WHERE id = $1`,
    [signup.id, primaryParent?.id || null, secondaryParent?.id || null, childPerson?.id || null, household?.id || null, workspace?.id || null]
  );
  if (signupStudent?.id && childPerson) {
    await db.query(
      `UPDATE bna_students
       SET person_id = COALESCE(person_id, $2),
           household_id = COALESCE(household_id, $3),
           workspace_id = COALESCE(workspace_id, $4),
           project_id = COALESCE(project_id, $4),
           updated_at = NOW()
       WHERE id = $1`,
      [signupStudent.id, childPerson.id, household?.id || null, workspace?.id || null]
    );
  }
  return { primaryParent, secondaryParent, childPerson, household, workspace };
}

async function linkStudentIdentityFields(student = {}, db = pool) {
  if (!student?.id) return null;
  const parentEmail = normalizeEmail(student.parent_email);
  if (!parentEmail && !student.parent_phone) return null;
  const context = parentEmail ? await getCurrentHouseholdForParentEmail(parentEmail, db) : null;
  if (!context?.household) return null;
  const childPerson = await ensureHouseholdChildPerson(context.household, {
    name: student.name,
    primary_language: recordPreferredLanguage(student) || 'en',
    tags: ['bna:student'],
    metadata: { source: 'bna_students', student_id: student.id },
  }, db);
  if (childPerson) {
    await ensurePersonWorkspaceRole(context.workspace, childPerson, {
      role: 'student',
      access_level: 'member',
      tags: ['bna:student'],
      metadata: { student_id: student.id },
    }, db).catch(() => {});
    await db.query(
      `UPDATE bna_students
       SET person_id = COALESCE(person_id, $2),
           household_id = COALESCE(household_id, $3),
           workspace_id = COALESCE(workspace_id, $4),
           project_id = COALESCE(project_id, $4),
           updated_at = NOW()
       WHERE id = $1`,
      [student.id, childPerson.id, context.household.id, context.workspace?.id || null]
    );
  }
  return { ...context, childPerson };
}

function normalizeStudentIdentitySourceRecords(value = []) {
  const rows = Array.isArray(value) ? value : [];
  const seen = new Set();
  return rows
    .filter((row) => row && typeof row === 'object')
    .map((row) => ({
      type: limitText(row.type || row.source || 'record', 80),
      id: row.id || row.signup_id || row.student_id || row.payment_intake_id || null,
      student_name: limitText(row.student_name || row.name || row.alias || '', 180) || null,
      source: limitText(row.source || row.type || 'identity_resolver', 120),
      captured_at: row.captured_at || row.created_at || new Date().toISOString(),
      metadata: row.metadata && typeof row.metadata === 'object' ? row.metadata : {},
    }))
    .filter((row) => row.type || row.id || row.student_name)
    .filter((row) => {
      const key = `${row.type}:${row.id || ''}:${normalizeLooseText(row.student_name || '')}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 80);
}

function mergeStudentSourceRecords(existing = [], incoming = []) {
  return normalizeStudentIdentitySourceRecords([...normalizeStudentIdentitySourceRecords(existing), ...normalizeStudentIdentitySourceRecords(incoming)]);
}

function studentIdentitySourceRecord(type, row = {}, metadata = {}) {
  if (!row) return null;
  return {
    type,
    id: row.id || null,
    student_name: row.student_name || row.name || null,
    source: type,
    created_at: row.created_at || null,
    captured_at: new Date().toISOString(),
    metadata,
  };
}

function studentIdentityFieldsFor(student = {}, extra = {}) {
  const mergedSourceRecords = mergeStudentSourceRecords(student.source_records, extra.source_records);
  const aliases = buildStudentAliases({
    ...student,
    aliases: [...normalizeTextArray(student.aliases), ...normalizeTextArray(extra.aliases)],
    source_records: mergedSourceRecords,
  });
  const normalizedNames = buildNormalizedStudentNames({
    ...student,
    aliases,
    source_records: mergedSourceRecords,
  });
  const englishName = limitText(
    extra.english_name || student.english_name || student.name_en || aliases.find((alias) => /[a-z]/i.test(alias)) || '',
    180
  ) || null;
  const hebrewName = limitText(
    extra.hebrew_name || student.hebrew_name || student.name_he || aliases.find(containsHebrewText) || '',
    180
  ) || null;
  const canonicalDisplayName = limitText(
    extra.canonical_display_name
      || student.canonical_display_name
      || (!containsHebrewText(student.name) ? student.name : englishName)
      || aliases[0]
      || student.name
      || 'Student',
    180
  );
  return {
    canonical_display_name: canonicalDisplayName,
    english_name: englishName,
    hebrew_name: hebrewName,
    aliases,
    normalized_names: normalizedNames,
    source_records: mergedSourceRecords,
  };
}

async function syncStudentIdentityAliases(studentId, fields = {}, db = pool) {
  const id = Number(studentId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const rows = [];
  for (const alias of normalizeTextArray(fields.aliases)) {
    const normalized = buildNormalizedStudentNames({ name: alias })[0] || normalizeLooseText(alias);
    if (!normalized) continue;
    const result = await db.query(
      `INSERT INTO bna_student_identity_aliases (
         student_id, alias, normalized_alias, language, source, confidence, metadata
       ) VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb)
       ON CONFLICT (student_id, normalized_alias) DO UPDATE SET
         alias = EXCLUDED.alias,
         language = COALESCE(EXCLUDED.language, bna_student_identity_aliases.language),
         active = TRUE,
         metadata = COALESCE(bna_student_identity_aliases.metadata, '{}'::jsonb) || EXCLUDED.metadata,
         updated_at = NOW()
       RETURNING *`,
      [
        id,
        alias,
        normalized,
        containsHebrewText(alias) ? 'he' : /[a-z]/i.test(alias) ? 'en' : null,
        'identity_resolver',
        1,
        JSON.stringify({ source: 'student_identity_fields' }),
      ]
    );
    if (result.rows[0]) rows.push(result.rows[0]);
  }
  return rows;
}

async function refreshStudentIdentityFields(studentId, extra = {}, db = pool) {
  const id = Number(studentId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const student = (await db.query('SELECT * FROM bna_students WHERE id = $1 LIMIT 1', [id])).rows[0] || null;
  if (!student) return null;
  const fields = studentIdentityFieldsFor(student, extra);
  const result = await db.query(
    `UPDATE bna_students
     SET canonical_display_name = $2,
         english_name = $3,
         hebrew_name = $4,
         name_en = COALESCE(name_en, $3),
         name_he = COALESCE(name_he, $4),
         aliases = $5::text[],
         normalized_names = $6::text[],
         source_records = $7::jsonb,
         updated_at = NOW()
     WHERE id = $1
     RETURNING *`,
    [
      id,
      fields.canonical_display_name,
      fields.english_name,
      fields.hebrew_name,
      fields.aliases,
      fields.normalized_names,
      JSON.stringify(fields.source_records),
    ]
  );
  const refreshed = result.rows[0] || student;
  await syncStudentIdentityAliases(id, fields, db).catch((error) => {
    console.warn('Student identity alias sync failed:', error.message);
  });
  return refreshed;
}

async function findStudentIdentityCandidates(input = {}, options = {}, db = pool) {
  const normalizedNames = buildNormalizedStudentNames(input);
  const parentEmail = normalizeEmail(input.parent_email || input.parentEmail);
  const parentPhone = normalizePhoneDigits(input.parent_phone || input.parentPhone);
  const signupId = Number(input.signup_id || input.signupId || 0);
  const canonicalStudentId = Number(input.canonical_student_id || input.canonicalStudentId || 0);
  const excludeStudentId = Number(options.excludeStudentId || input.exclude_student_id || 0);
  const projectId = Number(input.project_id || input.projectId || options.projectId || 0);
  const clauses = [];
  const conditions = ["COALESCE(status, 'active') NOT IN ('inactive', 'archived')"];
  const params = [];

  if (normalizedNames.length) {
    params.push(normalizedNames);
    clauses.push(`COALESCE(normalized_names, '{}'::text[]) && $${params.length}::text[]`);
    clauses.push(`trim(regexp_replace(lower(regexp_replace(COALESCE(name, ''), '[^[:alnum:]]+', ' ', 'g')), '\\s+', ' ', 'g')) = ANY($${params.length}::text[])`);
  }
  if (parentEmail) {
    params.push(parentEmail);
    clauses.push(`lower(COALESCE(parent_email, '')) = $${params.length}`);
  }
  if (parentPhone) {
    params.push(parentPhone);
    clauses.push(`regexp_replace(COALESCE(parent_phone, ''), '\\D', '', 'g') = $${params.length}`);
  }
  if (Number.isFinite(signupId) && signupId > 0) {
    params.push(signupId);
    clauses.push(`signup_id = $${params.length}`);
  }
  if (Number.isFinite(canonicalStudentId) && canonicalStudentId > 0) {
    params.push(canonicalStudentId);
    clauses.push(`id = $${params.length}`);
  }
  if (!clauses.length) return [];
  conditions.push(`(${clauses.join(' OR ')})`);
  if (Number.isFinite(excludeStudentId) && excludeStudentId > 0) {
    params.push(excludeStudentId);
    conditions.push(`id <> $${params.length}`);
  }
  if (Number.isFinite(projectId) && projectId > 0) {
    params.push(projectId);
    conditions.push(`COALESCE(project_id, $${params.length}) = $${params.length}`);
  }
  params.push(Math.max(1, Math.min(Number(options.limit) || 25, 100)));
  const result = await db.query(
    `SELECT *
     FROM bna_students
     WHERE ${conditions.join(' AND ')}
     ORDER BY status = 'active' DESC, updated_at DESC NULLS LAST, created_at DESC
     LIMIT $${params.length}`,
    params
  );
  return result.rows;
}

function studentIdentityReviewKey(target = {}, candidate = {}, sourceContext = {}) {
  const ids = [Number(target?.id || 0), Number(candidate?.id || 0)].filter((id) => Number.isFinite(id) && id > 0).sort((a, b) => a - b);
  if (ids.length === 2) return `student-pair:${ids[0]}:${ids[1]}`;
  if (sourceContext.signup_id) return `signup:${sourceContext.signup_id}:target:${target?.id || 'none'}`;
  return `student-review:${target?.id || 'none'}:${normalizeLooseText(candidate?.name || candidate?.student_name || sourceContext.student_name || '')}`;
}

function safeStudentDisplayName(student = {}) {
  return limitText(student.canonical_display_name || student.name || student.student_name || student.english_name || student.name_en || 'student', 120);
}

async function ensureStudentIdentityReviewTask({
  target = null,
  candidate = null,
  input = {},
  confidence = 0,
  evidence = {},
  sourceContext = {},
  reason = '',
  assignedTo = 'Shloimie',
} = {}, db = pool) {
  const targetStudentId = Number(target?.id || input.target_student_id || 0) || null;
  const candidateStudentId = Number(candidate?.id || input.candidate_student_id || 0) || null;
  const key = studentIdentityReviewKey(target, candidate, sourceContext || input);
  if (targetStudentId && candidateStudentId) {
    const existing = (await db.query(
      `SELECT *
       FROM bna_identity_review_tasks
       WHERE status IN ('open', 'needs_decision', 'blocked')
         AND review_type = 'possible_duplicate_student'
         AND LEAST(COALESCE(target_student_id, 0), COALESCE(candidate_student_id, 0)) = LEAST($1::int, $2::int)
         AND GREATEST(COALESCE(target_student_id, 0), COALESCE(candidate_student_id, 0)) = GREATEST($1::int, $2::int)
       ORDER BY created_at DESC
       LIMIT 1`,
      [targetStudentId, candidateStudentId]
    )).rows[0] || null;
    if (existing) return existing;
  }
  if (!targetStudentId && !candidateStudentId) return null;

  const evidenceSummary = evidenceLabels(evidence).join(', ') || reason || 'possible duplicate student identity';
  const targetLabel = safeStudentDisplayName(target || {});
  const candidateLabel = safeStudentDisplayName(candidate || input || {});
  const projectId = target?.project_id || candidate?.project_id || input.project_id || (await getProjectByKey(DEFAULT_PROJECT_KEY, db))?.id || null;
  const title = limitText(`Review possible duplicate student identity: ${targetLabel} / ${candidateLabel}`, 180);
  const notes = [
    'Possible Hebrew/English duplicate was detected.',
    'No automatic merge was performed.',
    `Evidence categories: ${evidenceSummary}.`,
    'Review in Operations > Students > Identity Review.',
  ].join('\n');
  const taskPayload = {
    identity_review_key: key,
    identity_review_type: 'possible_duplicate_student',
    target_student_id: targetStudentId,
    candidate_student_id: candidateStudentId,
    confidence,
    evidence_categories: evidenceLabels(evidence),
  };
  const existingTask = (await db.query(
    `SELECT *
     FROM bna_tasks
     WHERE COALESCE(stage, '') <> 'archive'
       AND COALESCE(ai_parsed, '{}'::jsonb)->>'identity_review_key' = $1
     ORDER BY created_at DESC
     LIMIT 1`,
    [key]
  )).rows[0] || null;
  const task = existingTask || (await db.query(
    `INSERT INTO bna_tasks (
       project_id, project_key, title, summary, notes, stage, category, urgency,
       assigned_to, waiting_on, decision_required, needs_review, item_type, task_kind,
       source, created_by, source_context, ai_parsed, next_action_label, last_activity_at
     ) VALUES (
       $1, $2, $3, $4, $5, 'needs_decision', 'student_operations', 'today',
       $6, $6, TRUE, TRUE, 'decision', 'decision',
       'import', 'identity_dedupe', $7::jsonb, $8::jsonb, 'Review identity match', NOW()
     )
     RETURNING *`,
    [
      projectId,
      DEFAULT_PROJECT_KEY,
      title,
      reason || 'Review possible duplicate student identity before merging.',
      notes,
      assignedTo,
      JSON.stringify({ ...sourceContext, identity_review_key: key }),
      JSON.stringify(taskPayload),
    ]
  )).rows[0];

  const result = await db.query(
    `INSERT INTO bna_identity_review_tasks (
       review_type, status, target_student_id, candidate_student_id,
       target_person_id, candidate_person_id, confidence, evidence_summary,
       evidence_json, source_context, task_id, assigned_to, created_by
     ) VALUES (
       'possible_duplicate_student', 'open', $1, $2,
       $3, $4, $5, $6, $7::jsonb, $8::jsonb, $9, $10, 'identity_dedupe'
     )
     ON CONFLICT DO NOTHING
     RETURNING *`,
    [
      targetStudentId,
      candidateStudentId,
      target?.person_id || null,
      candidate?.person_id || input.person_id || null,
      Number(confidence || 0),
      evidenceSummary,
      JSON.stringify(evidence || {}),
      JSON.stringify({ ...sourceContext, identity_review_key: key }),
      task?.id || null,
      assignedTo,
    ]
  );
  const review = result.rows[0] || (await db.query(
    `SELECT *
     FROM bna_identity_review_tasks
     WHERE COALESCE(source_context, '{}'::jsonb)->>'identity_review_key' = $1
     ORDER BY created_at DESC
     LIMIT 1`,
    [key]
  )).rows[0] || null;
  if (review?.id && task?.id && !review.task_id) {
    await db.query('UPDATE bna_identity_review_tasks SET task_id = $2, updated_at = NOW() WHERE id = $1', [review.id, task.id]);
  }
  return review;
}

async function resolveStudentIdentity(input = {}, options = {}, db = pool) {
  const candidates = await findStudentIdentityCandidates(input, options, db);
  const scored = candidates
    .map((candidate) => scoreStudentIdentityCandidate(candidate, input))
    .filter((item) => item.confidence > 0)
    .sort((a, b) => b.confidence - a.confidence);
  const best = scored[0] || null;
  if (!best) {
    return { status: 'new', confidence: 0, candidates: [], aliases: buildStudentAliases(input), normalized_names: buildNormalizedStudentNames(input) };
  }
  const closeSecond = scored[1] && Number(scored[1].confidence || 0) >= Number(best.confidence || 0) - 5;
  if (best.safe_auto_match && !closeSecond) {
    return {
      status: 'matched',
      target: best.candidate,
      confidence: best.confidence,
      evidence: best.evidence,
      candidates: scored,
      aliases: buildStudentAliases(input),
      normalized_names: buildNormalizedStudentNames(input),
    };
  }
  if (best.confidence >= 55 && options.createReviewTask !== false) {
    const review = await ensureStudentIdentityReviewTask({
      target: best.candidate,
      candidate: input.id ? input : null,
      input,
      confidence: best.confidence,
      evidence: best.evidence,
      sourceContext: options.sourceContext || {},
      reason: options.reason || 'Ambiguous student identity match requires review.',
    }, db);
    return {
      status: 'review_required',
      target: best.candidate,
      confidence: best.confidence,
      evidence: best.evidence,
      candidates: scored,
      review,
      aliases: buildStudentAliases(input),
      normalized_names: buildNormalizedStudentNames(input),
    };
  }
  return {
    status: 'new',
    confidence: best.confidence,
    evidence: best.evidence,
    candidates: scored,
    aliases: buildStudentAliases(input),
    normalized_names: buildNormalizedStudentNames(input),
  };
}

async function relationColumnExists(tableName, columnName, db = pool) {
  if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(tableName) || !/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(columnName)) return false;
  const result = await db.query(
    `SELECT 1
     FROM information_schema.columns
     WHERE table_schema = 'public'
       AND table_name = $1
       AND column_name = $2
     LIMIT 1`,
    [tableName, columnName]
  );
  return Boolean(result.rows[0]);
}

async function updateStudentReferenceIfPresent(client, tableName, columnName, targetId, sourceId, fieldsPreserved = {}) {
  if (!(await relationColumnExists(tableName, columnName, client))) return;
  const savepoint = `merge_${tableName}_${columnName}`;
  await client.query(`SAVEPOINT ${savepoint}`);
  try {
    const result = await client.query(
      `UPDATE ${tableName}
       SET ${columnName} = $1
       WHERE ${columnName} = $2`,
      [targetId, sourceId]
    );
    fieldsPreserved[`${tableName}.${columnName}`] = { updated: result.rowCount || 0 };
    await client.query(`RELEASE SAVEPOINT ${savepoint}`);
  } catch (error) {
    await client.query(`ROLLBACK TO SAVEPOINT ${savepoint}`);
    fieldsPreserved[`${tableName}.${columnName}`] = { updated: 0, skipped: true, reason: error.message };
    await client.query(`RELEASE SAVEPOINT ${savepoint}`);
  }
}

async function mergeTorahEntriesForStudents(client, targetId, sourceId, fieldsPreserved = {}) {
  const sourceEntries = (await client.query(
    `SELECT *
     FROM bna_torah_learning_entries
     WHERE student_id = $1
     ORDER BY date ASC, id ASC`,
    [sourceId]
  )).rows;
  const mergedEntries = [];
  const movedEntries = [];
  for (const sourceEntry of sourceEntries) {
    const targetEntry = (await client.query(
      `SELECT *
       FROM bna_torah_learning_entries
       WHERE student_id = $1
         AND date = $2::date
       ORDER BY id ASC
       LIMIT 1`,
      [targetId, sourceEntry.date]
    )).rows[0] || null;
    if (!targetEntry) {
      await client.query(
        `UPDATE bna_torah_learning_entries
         SET student_id = $1,
             updated_at = NOW()
         WHERE id = $2`,
        [targetId, sourceEntry.id]
      );
      movedEntries.push(sourceEntry.id);
      continue;
    }
    const note = [targetEntry.note, sourceEntry.note && `Merged from duplicate entry #${sourceEntry.id}: ${sourceEntry.note}`]
      .filter(Boolean)
      .join('\n');
    await client.query(
      `UPDATE bna_torah_learning_entries
       SET engaged_listening_minutes = GREATEST(COALESCE(engaged_listening_minutes, 0), COALESCE($2, 0)),
           inside_engaged_minutes = GREATEST(COALESCE(inside_engaged_minutes, 0), COALESCE($3, 0)),
           listening_without_following_minutes = GREATEST(COALESCE(listening_without_following_minutes, 0), COALESCE($4, 0)),
           counted_minutes = GREATEST(COALESCE(counted_minutes, 0), COALESCE($5, 0)),
           individual_percentage = GREATEST(COALESCE(individual_percentage, 0), COALESCE($6, 0)),
           individual_complete = COALESCE(individual_complete, FALSE) OR COALESCE($7, FALSE),
           daily_completion_percentage = GREATEST(COALESCE(daily_completion_percentage, 0), COALESCE($8, 0)),
           daily_completed_boolean = COALESCE(daily_completed_boolean, FALSE) OR COALESCE($9, FALSE),
           completed_daily_units = GREATEST(COALESCE(completed_daily_units, 0), COALESCE($10, 0)),
           carried_over_completed_units = GREATEST(COALESCE(carried_over_completed_units, 0), COALESCE($11, 0)),
           total_completed_units = GREATEST(COALESCE(total_completed_units, 0), COALESCE($12, 0)),
           total_required_units = GREATEST(COALESCE(total_required_units, 0), COALESCE($13, 0)),
           total_trip_progress_percentage = GREATEST(COALESCE(total_trip_progress_percentage, 0), COALESCE($14, 0)),
           note = COALESCE(NULLIF($15, ''), note),
           updated_at = NOW()
       WHERE id = $1`,
      [
        targetEntry.id,
        sourceEntry.engaged_listening_minutes,
        sourceEntry.inside_engaged_minutes,
        sourceEntry.listening_without_following_minutes,
        sourceEntry.counted_minutes,
        sourceEntry.individual_percentage,
        sourceEntry.individual_complete,
        sourceEntry.daily_completion_percentage,
        sourceEntry.daily_completed_boolean,
        sourceEntry.completed_daily_units,
        sourceEntry.carried_over_completed_units,
        sourceEntry.total_completed_units,
        sourceEntry.total_required_units,
        sourceEntry.total_trip_progress_percentage,
        note,
      ]
    );
    await client.query('DELETE FROM bna_torah_learning_entries WHERE id = $1', [sourceEntry.id]);
    mergedEntries.push({ source_entry_id: sourceEntry.id, target_entry_id: targetEntry.id, date: sourceEntry.date });
  }
  fieldsPreserved.torah_entries = { moved: movedEntries, conflict_merged: mergedEntries };
}

async function mergeStudentsSafely({
  targetStudentId,
  sourceStudentId,
  reviewTaskId = null,
  evidence = {},
  confidence = 0,
  reviewedBy = 'admin',
} = {}, db = pool) {
  const targetId = Number(targetStudentId);
  const sourceId = Number(sourceStudentId);
  if (!Number.isFinite(targetId) || targetId <= 0 || !Number.isFinite(sourceId) || sourceId <= 0 || targetId === sourceId) {
    const error = new Error('A distinct target_student_id and source_student_id are required');
    error.statusCode = 400;
    throw error;
  }
  const client = db.connect ? await db.connect() : db;
  const release = Boolean(db.connect);
  const fieldsPreserved = {};
  try {
    await client.query('BEGIN');
    const target = (await client.query('SELECT * FROM bna_students WHERE id = $1 FOR UPDATE', [targetId])).rows[0] || null;
    const source = (await client.query('SELECT * FROM bna_students WHERE id = $1 FOR UPDATE', [sourceId])).rows[0] || null;
    if (!target || !source) {
      const error = new Error('Target or source student was not found');
      error.statusCode = 404;
      throw error;
    }
    if (Number(source.archived_duplicate_of || 0) === targetId) {
      await client.query('COMMIT');
      return { success: true, merged: false, already_merged: true, target_student_id: targetId, source_student_id: sourceId };
    }

    const idempotencyKey = `student-merge:${targetId}:${sourceId}`;
    const existingEvent = (await client.query('SELECT * FROM bna_student_merge_events WHERE idempotency_key = $1 LIMIT 1', [idempotencyKey])).rows[0] || null;
    if (existingEvent) {
      await client.query('COMMIT');
      return { success: true, merged: false, already_merged: true, target_student_id: targetId, source_student_id: sourceId, merge_event_id: existingEvent.id };
    }

    await mergeTorahEntriesForStudents(client, targetId, sourceId, fieldsPreserved);
    await updateStudentReferenceIfPresent(client, 'bna_torah_learning_goals', 'student_id', targetId, sourceId, fieldsPreserved);
    const referenceUpdates = [
      ['bna_accountability_events', 'student_id'],
      ['bna_group_goal_entries', 'student_id'],
      ['bna_accountability_items', 'student_id'],
      ['bna_section_records', 'student_id'],
      ['bna_parent_permission_profiles', 'student_id'],
      ['bna_parent_accountability_pipelines', 'student_id'],
      ['bna_user_accounts', 'student_id'],
      ['bna_student_bot_settings', 'student_id'],
      ['bna_devices', 'student_id'],
      ['bna_device_access_rules', 'student_id'],
      ['bna_device_access_sessions', 'student_id'],
      ['bna_assignment_students', 'student_id'],
      ['bna_members', 'student_id'],
      ['bna_access_grants', 'student_id'],
      ['bna_assistant_threads', 'student_id'],
      ['bna_google_connections', 'student_id'],
      ['bna_green_invoice_webhook_log', 'matched_student_id'],
    ];
    for (const [tableName, columnName] of referenceUpdates) {
      await updateStudentReferenceIfPresent(client, tableName, columnName, targetId, sourceId, fieldsPreserved);
    }
    await client.query(
      `UPDATE bna_accountability_events
       SET student_name = COALESCE(student_name, $2),
           updated_at = NOW()
       WHERE student_id = $1
         AND (student_name IS NULL OR trim(student_name) = '')`,
      [targetId, target.name]
    );
    await client.query(
      `UPDATE bna_group_goal_entries
       SET student_name = COALESCE(student_name, $2),
           updated_at = NOW()
       WHERE student_id = $1
         AND (student_name IS NULL OR trim(student_name) = '')`,
      [targetId, target.name]
    );

    const sourceSignupIds = [source.signup_id].filter(Boolean);
    const targetSignupIds = [target.signup_id].filter(Boolean);
    const allSignupIds = [...new Set([...sourceSignupIds, ...targetSignupIds])];
    if (allSignupIds.length) {
      await client.query(
        `UPDATE signups
         SET canonical_student_id = $1,
             identity_review_status = 'clear',
             updated_at = NOW()
         WHERE id = ANY($2::int[])
            OR canonical_student_id = $3`,
        [targetId, allSignupIds, sourceId]
      );
    }
    if (!target.signup_id && source.signup_id) {
      await client.query('UPDATE bna_students SET signup_id = NULL, updated_at = NOW() WHERE id = $1', [sourceId]);
      await client.query('UPDATE bna_students SET signup_id = $2, updated_at = NOW() WHERE id = $1 AND signup_id IS NULL', [targetId, source.signup_id]);
    } else if (source.signup_id) {
      await client.query('UPDATE bna_students SET signup_id = NULL, updated_at = NOW() WHERE id = $1', [sourceId]);
    }

    const extraAliases = buildStudentAliases(source);
    const mergedSourceRecords = mergeStudentSourceRecords(target.source_records, [
      ...normalizeStudentIdentitySourceRecords(source.source_records),
      studentIdentitySourceRecord('merged_student', source, { merged_into_student_id: targetId }),
    ]);
    const mergedFields = studentIdentityFieldsFor(target, {
      aliases: extraAliases,
      source_records: mergedSourceRecords,
      canonical_display_name: target.canonical_display_name || target.name,
    });
    const targetMergeHistory = Array.isArray(target.merge_history) ? target.merge_history : [];
    const mergeHistory = [
      ...targetMergeHistory,
      {
        source_student_id: sourceId,
        source_name: source.name,
        merged_at: new Date().toISOString(),
        reviewed_by: reviewedBy,
        review_task_id: reviewTaskId || null,
        evidence_categories: evidenceLabels(evidence),
      },
    ].slice(-80);
    const moveSourceAccessCode = !target.student_access_code && source.student_access_code;
    if (moveSourceAccessCode) {
      await client.query(
        `UPDATE bna_students
         SET student_access_code = NULL,
             student_access_enabled = FALSE,
             updated_at = NOW()
         WHERE id = $1`,
        [sourceId]
      );
    }
    const targetBefore = target;
    const sourceSnapshot = source;
    const targetUpdate = await client.query(
      `UPDATE bna_students
       SET canonical_display_name = $2,
           english_name = $3,
           hebrew_name = $4,
           name_en = COALESCE(name_en, $3),
           name_he = COALESCE(name_he, $4),
           aliases = $5::text[],
           normalized_names = $6::text[],
           source_records = $7::jsonb,
           merge_history = $8::jsonb,
           parent_name = COALESCE(parent_name, $9),
           parent_email = COALESCE(parent_email, $10),
           parent_phone = COALESCE(parent_phone, $11),
           legacy_crm_contact_id = COALESCE(legacy_crm_contact_id, $12),
           student_access_code = COALESCE(student_access_code, $13),
           student_access_enabled = CASE WHEN student_access_enabled IS FALSE AND $13 IS NOT NULL THEN TRUE ELSE student_access_enabled END,
           identity_review_status = 'clear',
           updated_at = NOW()
       WHERE id = $1
       RETURNING *`,
      [
        targetId,
        mergedFields.canonical_display_name,
        mergedFields.english_name,
        mergedFields.hebrew_name,
        mergedFields.aliases,
        mergedFields.normalized_names,
        JSON.stringify(mergedFields.source_records),
        JSON.stringify(mergeHistory),
        source.parent_name || null,
        source.parent_email || null,
        source.parent_phone || null,
        source.legacy_crm_contact_id || null,
        moveSourceAccessCode ? source.student_access_code : null,
      ]
    );
    const targetAfter = targetUpdate.rows[0] || target;
    await client.query(
      `UPDATE bna_students
       SET signup_id = NULL,
           status = 'inactive',
           archived_duplicate_of = $1,
           merged_at = NOW(),
           merged_by = $2,
           identity_review_status = 'merged',
           student_access_code = NULL,
           student_access_enabled = FALSE,
           notes = CONCAT(COALESCE(notes, ''), CASE WHEN COALESCE(notes, '') = '' THEN '' ELSE E'\n' END, $3::text),
           updated_at = NOW()
       WHERE id = $4`,
      [
        targetId,
        reviewedBy,
        `Merged into ${targetAfter.canonical_display_name || targetAfter.name} (#${targetId}) on ${new Date().toISOString().slice(0, 10)}.`,
        sourceId,
      ]
    );
    const mergeEvent = (await client.query(
      `INSERT INTO bna_student_merge_events (
         idempotency_key, target_student_id, source_student_id, review_task_id,
         evidence_json, confidence, source_snapshot, target_snapshot_before,
         target_snapshot_after, fields_preserved, created_by
       ) VALUES ($1, $2, $3, $4, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9::jsonb, $10::jsonb, $11)
       RETURNING *`,
      [
        idempotencyKey,
        targetId,
        sourceId,
        reviewTaskId || null,
        JSON.stringify(evidence || {}),
        Number(confidence || 0),
        JSON.stringify(sourceSnapshot),
        JSON.stringify(targetBefore),
        JSON.stringify(targetAfter),
        JSON.stringify(fieldsPreserved),
        reviewedBy,
      ]
    )).rows[0];
    if (reviewTaskId) {
      await client.query(
        `UPDATE bna_identity_review_tasks
         SET status = 'merged',
             resolved_at = NOW(),
             resolved_by = $2,
             resolution_notes = COALESCE(resolution_notes, 'Merged through safe student merge.'),
             updated_at = NOW()
         WHERE id = $1`,
        [reviewTaskId, reviewedBy]
      );
    }
    await syncStudentIdentityAliases(targetId, mergedFields, client).catch(() => {});
    await client.query('COMMIT');
    await refreshTorahTripProgressSnapshots(targetId, {}, db).catch(() => {});
    return {
      success: true,
      merged: true,
      target_student_id: targetId,
      source_student_id: sourceId,
      merge_event_id: mergeEvent?.id || null,
      aliases_preserved: mergedFields.aliases,
      review_task_id: reviewTaskId || null,
      fields_preserved: fieldsPreserved,
    };
  } catch (error) {
    try { await client.query('ROLLBACK'); } catch {}
    throw error;
  } finally {
    if (release) client.release();
  }
}

async function scanStudentIdentityDuplicates({ limit = 250, createReviews = true } = {}, db = pool) {
  const result = await db.query(
    `SELECT *
     FROM bna_students
     WHERE COALESCE(status, 'active') NOT IN ('inactive', 'archived')
     ORDER BY updated_at DESC NULLS LAST, created_at DESC
     LIMIT $1`,
    [Math.max(1, Math.min(Number(limit) || 250, 500))]
  );
  const studentsToScan = result.rows;
  const reviews = [];
  const candidates = [];
  for (let i = 0; i < studentsToScan.length; i += 1) {
    for (let j = i + 1; j < studentsToScan.length; j += 1) {
      const scored = scoreStudentIdentityCandidate(studentsToScan[j], studentsToScan[i]);
      if (scored.confidence < 55) continue;
      candidates.push({
        target: studentsToScan[i],
        candidate: studentsToScan[j],
        confidence: scored.confidence,
        evidence: scored.evidence,
      });
      if (createReviews) {
        const review = await ensureStudentIdentityReviewTask({
          target: studentsToScan[i],
          candidate: studentsToScan[j],
          confidence: scored.confidence,
          evidence: scored.evidence,
          sourceContext: { source: 'identity_scan' },
          reason: 'Duplicate scan found a possible student identity match.',
        }, db);
        if (review) reviews.push(review);
      }
    }
  }
  if (studentsToScan.length) {
    await db.query(
      `UPDATE bna_students
       SET last_identity_scan_at = NOW()
       WHERE id = ANY($1::int[])`,
      [studentsToScan.map((student) => student.id)]
    ).catch(() => {});
  }
  return { students_scanned: studentsToScan.length, candidates, reviews };
}

function studentIdentityReviewView(row = {}) {
  const evidence = row.evidence_json && typeof row.evidence_json === 'object' ? row.evidence_json : {};
  const sourceContext = row.source_context && typeof row.source_context === 'object' ? row.source_context : {};
  return {
    id: row.id,
    review_type: row.review_type,
    status: row.status,
    target_student_id: row.target_student_id,
    candidate_student_id: row.candidate_student_id,
    target_name: row.target_name || null,
    candidate_name: row.candidate_name || sourceContext.student_name || null,
    confidence: Number(row.confidence || 0),
    evidence_summary: row.evidence_summary || evidenceLabels(evidence).join(', '),
    evidence_chips: evidenceLabels(evidence),
    language_chips: evidence.language_chips || [],
    masked_parent_email: maskEmail(row.target_parent_email || row.candidate_parent_email || ''),
    masked_parent_phone: maskPhone(row.target_parent_phone || row.candidate_parent_phone || ''),
    task_id: row.task_id,
    created_at: row.created_at,
    resolved_at: row.resolved_at,
    source_context: {
      source: sourceContext.source || null,
      signup_id: sourceContext.signup_id || null,
      payment_intake_id: sourceContext.payment_intake_id || null,
    },
  };
}

async function backfillIdentityLinks({ dryRun = false, limit = 50 } = {}, db = pool) {
  const stats = { dryRun: Boolean(dryRun), signups_seen: 0, signups_linked: 0, students_seen: 0, students_linked: 0, reviews: 0 };
  await ensurePersonalWorkspacesAndPeople(db);
  if (dryRun) {
    stats.signups_seen = Number((await db.query(
      `SELECT COUNT(*) AS count FROM signups WHERE identity_backfilled_at IS NULL`
    )).rows[0]?.count || 0);
    stats.students_seen = Number((await db.query(
      `SELECT COUNT(*) AS count FROM bna_students WHERE person_id IS NULL AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')`
    )).rows[0]?.count || 0);
    return stats;
  }
  const signupRows = (await db.query(
    `SELECT *
     FROM signups
     WHERE identity_backfilled_at IS NULL
     ORDER BY id ASC
     LIMIT $1`,
    [Math.max(1, Math.min(Number(limit) || 50, 250))]
  )).rows;
  for (const signup of signupRows) {
    stats.signups_seen += 1;
    const student = signup.student_name ? (await db.query(
      `SELECT *
       FROM bna_students
       WHERE lower(COALESCE(parent_email, '')) = lower(COALESCE($1, ''))
         AND trim(regexp_replace(lower(regexp_replace(COALESCE(name, ''), '[^a-zA-Z0-9\u0590-\u05ff]+', ' ', 'g')), '\\s+', ' ', 'g')) = $2
       ORDER BY id ASC
       LIMIT 1`,
      [signup.parent_email || '', normalizePersonNameKey(signup.student_name)]
    )).rows[0] || null : null;
    await linkSignupIdentity(signup, student, db).catch(async (error) => {
      stats.reviews += 1;
      await createMergeReview({
        review_type: 'identity_backfill_error',
        reason: error.message,
        signals: { signup_id: signup.id },
        metadata: { source: 'backfill_identity_links' },
      }, db).catch(() => {});
    });
    stats.signups_linked += 1;
  }
  const studentRows = (await db.query(
    `SELECT *
     FROM bna_students
     WHERE person_id IS NULL
       AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')
     ORDER BY id ASC
     LIMIT $1`,
    [Math.max(1, Math.min(Number(limit) || 50, 250))]
  )).rows;
  for (const student of studentRows) {
    stats.students_seen += 1;
    const linked = await linkStudentIdentityFields(student, db).catch(async (error) => {
      stats.reviews += 1;
      await createMergeReview({
        review_type: 'student_identity_backfill_error',
        reason: error.message,
        signals: { student_id: student.id },
        metadata: { source: 'backfill_identity_links' },
      }, db).catch(() => {});
      return null;
    });
    if (linked) stats.students_linked += 1;
  }
  return stats;
}

async function ensureWorkspaceSetupTask({ project, key, title, summary, notes, category = 'technology', urgency = 'this_week', assigned_to = 'Shloimie' }, db = pool) {
  const titleKey = normalizedTaskTitleKey(title);
  const existing = (await db.query(
    `SELECT *
     FROM bna_tasks
     WHERE COALESCE(stage, '') <> 'archive'
       AND (
         (COALESCE(ai_parsed, '{}'::jsonb)->>'personal_workspace_seed' = '2026-06-14'
          AND COALESCE(ai_parsed, '{}'::jsonb)->>'seed_key' = $1)
         OR trim(regexp_replace(lower(regexp_replace(COALESCE(title, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $2
       )
     ORDER BY created_at ASC
     LIMIT 1`,
    [key, titleKey]
  )).rows[0] || null;
  const aiParsed = {
    personal_workspace_seed: '2026-06-14',
    seed_key: key,
    parser: 'workspace-person-household-seed',
  };
  if (!existing) {
    return createTaskFromText({
      title,
      raw_text: summary || title,
      summary,
      notes: notes || summary,
      stage: 'assigned',
      category,
      urgency,
      assigned_to,
      waiting_on: assigned_to === 'Shloimie' ? 'Shloimie' : null,
      next_action_label: assigned_to === 'Codex' ? 'Agent working' : 'Needs setup',
      source: 'manual',
      source_channel: 'seed',
      created_by: 'system',
      project: project?.project_key || DEFAULT_PROJECT_KEY,
      ai_parsed: aiParsed,
    }, {}, db);
  }
  return existing;
}

async function linkExactStudentPerson({ person, name, workspaceId, householdId = null, createAmbiguousTask = true }, db = pool) {
  const normalized = personLookupName(name || person?.preferred_name || '');
  if (!person?.id || !normalized) return { linked: false, matches: [] };
  const matches = (await db.query(
    `SELECT id, name, parent_email, status
     FROM bna_students
     WHERE trim(regexp_replace(lower(regexp_replace(COALESCE(name, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $1
       AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')
     ORDER BY id ASC`,
    [normalized]
  )).rows;
  if (matches.length === 1) {
    await db.query(
      `UPDATE bna_students
       SET person_id = $2,
           workspace_id = COALESCE(workspace_id, $3),
           project_id = COALESCE(project_id, $3),
           household_id = COALESCE(household_id, $4),
           updated_at = NOW()
       WHERE id = $1`,
      [matches[0].id, person.id, workspaceId || null, householdId || null]
    );
    return { linked: true, matches };
  }
  if (matches.length > 1 && createAmbiguousTask) {
    const bnaProject = await getProjectByKey(DEFAULT_PROJECT_KEY, db);
    await ensureWorkspaceSetupTask({
      project: bnaProject,
      key: `merge-review-${normalized}`,
      title: `Review possible duplicate person records for ${person.preferred_name || name}`,
      summary: `Multiple BNA student rows matched ${name}. Do not merge automatically; review rows ${matches.map((row) => `#${row.id}`).join(', ')}.`,
      notes: 'Canonical person dedupe rule: exact email, then exact phone, then normalized name plus workspace/relationship context. Ambiguous matches require human review.',
      category: 'operations',
      urgency: 'this_week',
      assigned_to: 'Shloimie',
    }, db);
  }
  return { linked: false, matches };
}

async function ensurePersonalWorkspacesAndPeople(db = pool) {
  const { bna: seededBna, oneTime } = await ensureDefaultProjects(db);
  const bna = seededBna || fallbackWorkspaceProjectRow('bna');
  const shloimie = (await upsertCanonicalPerson({
    preferred_name: 'Shloimie',
    full_name: 'Shloimie Dratler',
    primary_language: 'en',
    metadata: { seed: 'personal-workspaces-2026-06-14', tags: ['super_admin', 'bna:rabbi', 'family:parent'] },
  }, db)) || { id: null, preferred_name: 'Shloimie', full_name: 'Shloimie Dratler' };
  const superAdmin = (await ensureWorkspaceProject({
    projectKey: 'super_admin',
    name: 'Super Admin',
    shortName: 'Super Admin',
    description: "Shloimie's global operator/admin control center.",
    workspaceType: 'super_admin',
    ownerPersonId: shloimie.id,
    visibility: 'private',
    languageDefault: 'en',
    slug: 'super-admin',
    settings: { primary_role_label: 'Operator', accountability_mode: 'admin' },
    metadata: { source: 'personal_workspace_seed' },
  }, db)) || fallbackWorkspaceProjectRow('super_admin');
  const family = (await ensureWorkspaceProject({
    projectKey: 'dratler_family',
    name: 'Dratler Family',
    shortName: 'Family',
    description: "Private family workspace for Shloimie's household.",
    workspaceType: 'family',
    ownerPersonId: shloimie.id,
    visibility: 'private',
    languageDefault: 'en',
    slug: 'dratler-family',
    settings: { accountability_mode: 'family' },
    metadata: { source: 'personal_workspace_seed', public: false },
  }, db)) || fallbackWorkspaceProjectRow('dratler_family');
  const bnaWorkspace = (await ensureWorkspaceProject({
    projectKey: DEFAULT_PROJECT_KEY,
    name: bna.name || 'BNA',
    shortName: bna.short_name || 'BNA',
    description: bna.description || 'Bnei Neviim Academy school workspace.',
    workspaceType: 'school',
    ownerPersonId: shloimie.id,
    visibility: 'workspace',
    languageDefault: 'en',
    slug: 'bna',
    settings: { primary_role_label: 'Rabbi', accountability_mode: 'school' },
  }, db)) || bna;
  let oneTimeWorkspace = oneTime || null;
  if (oneTime?.id) {
    await db.query(
      `UPDATE bna_projects
       SET workspace_type = 'service_provider',
           visibility = 'workspace',
           slug = COALESCE(slug, 'one-time-mishnah-class'),
           settings = COALESCE(settings, '{}'::jsonb) || '{"accountability_mode":"provider","provider_workspace":true}'::jsonb,
           updated_at = NOW()
       WHERE id = $1`,
      [oneTime.id]
    );
    oneTimeWorkspace = await getProjectByKey('one_time_mishnah_class', db).catch(() => oneTime);
  }

  const menachem = (await upsertCanonicalPerson({
    preferred_name: 'Menachem',
    full_name: 'Menachem Mendel Dratler',
    primary_language: 'en',
    metadata: { seed: 'personal-workspaces-2026-06-14', tags: ['family:son', 'school:student', 'bna:student'] },
  }, db)) || { id: null, preferred_name: 'Menachem', full_name: 'Menachem Mendel Dratler' };
  const esty = (await upsertCanonicalPerson({
    preferred_name: 'Esty',
    full_name: 'Esty',
    primary_language: 'en',
    metadata: { seed: 'personal-workspaces-2026-06-14', family_name: 'Dratler', tags: ['family:daughter', 'dratler_family'] },
  }, db)) || { id: null, preferred_name: 'Esty', full_name: 'Esty' };

  await ensureWorkspaceMembership(superAdmin, shloimie, { role: 'super_admin', access_level: 'owner', tags: ['super_admin'] }, db);
  await ensureWorkspaceMembership(superAdmin, shloimie, { role: 'owner', access_level: 'owner', tags: ['super_admin'] }, db);
  await ensureWorkspaceMembership(bnaWorkspace, shloimie, { role: 'owner', access_level: 'owner', tags: ['bna:owner'] }, db);
  await ensureWorkspaceMembership(bnaWorkspace, shloimie, { role: 'rabbi', access_level: 'admin', tags: ['bna:rabbi'] }, db);
  await ensureWorkspaceMembership(bnaWorkspace, shloimie, { role: 'admin', access_level: 'admin', tags: ['bna:admin'] }, db);
  if (oneTimeWorkspace?.id) {
    await ensureWorkspaceMembership(oneTimeWorkspace, shloimie, {
      role: 'owner',
      access_level: 'owner',
      tags: ['service_provider:owner', 'one_time:owner', 'rabbi_sheller_provider'],
      metadata: { seed: 'personal-workspaces-2026-06-17', canonical_workspace: 'rabbi_sheller_provider' },
    }, db);
  }
  await ensureWorkspaceMembership(family, shloimie, { role: 'owner', access_level: 'owner', tags: ['family:parent'] }, db);
  await ensureWorkspaceMembership(family, shloimie, { role: 'parent', access_level: 'owner', tags: ['family:parent'] }, db);
  await ensureWorkspaceMembership(family, menachem, { role: 'child', access_level: 'member', relationship_to_owner: 'son', tags: ['family:son'] }, db);
  await ensureWorkspaceMembership(bnaWorkspace, menachem, { role: 'student', access_level: 'member', tags: ['school:student', 'bna:student'] }, db);
  await ensureWorkspaceMembership(family, esty, { role: 'child', access_level: 'member', relationship_to_owner: 'daughter', tags: ['family:daughter'] }, db);

  const household = await ensureHousehold(family, {
    household_name: 'Dratler Family',
    primary_parent_person_id: shloimie.id,
    status: 'active',
    metadata: { seed: 'personal-workspaces-2026-06-14' },
  }, db);
  await ensureHouseholdMember(household, shloimie, { role: 'parent', relationship: 'parent', tags: ['family:parent'] }, db);
  await ensureHouseholdMember(household, menachem, { role: 'child', relationship: 'son', tags: ['family:son'] }, db);
  await ensureHouseholdMember(household, esty, { role: 'child', relationship: 'daughter', tags: ['family:daughter'] }, db);

  if (menachem?.id && bnaWorkspace?.id) {
    await linkExactStudentPerson({ person: menachem, name: 'Menachem', workspaceId: bnaWorkspace.id }, db);
  }
  const estySchoolMatches = (await db.query(
    `SELECT id, name, parent_email, status
     FROM bna_students
     WHERE trim(regexp_replace(lower(regexp_replace(COALESCE(name, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $1
       AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')
     ORDER BY id ASC`,
    [personLookupName('Esty')]
  )).rows;
  if (estySchoolMatches.length) {
    await ensureWorkspaceSetupTask({
      project: bnaWorkspace,
      key: 'review-esty-school-membership',
      title: 'Review whether Esty should have a BNA student membership',
      summary: `Existing BNA student row(s) matched Esty by normalized name: ${estySchoolMatches.map((row) => `#${row.id}`).join(', ')}. Review before adding any BNA school membership.`,
      notes: 'The personal family seed intentionally creates Esty as family child/daughter only. Add BNA membership only if this student row is confirmed as the same person and a current BNA student.',
      category: 'operations',
      urgency: 'this_week',
      assigned_to: 'Shloimie',
    }, db);
  }

  await db.query(
    `INSERT INTO bna_logins (person_id, login_email, username, role_type, status, metadata)
     VALUES ($1, $2, $3, 'super_admin', 'active', $4::jsonb)
     ON CONFLICT DO NOTHING`,
    [
      shloimie.id,
      OPS_USERNAME && OPS_USERNAME.includes('@') ? normalizeEmail(OPS_USERNAME) : null,
      OPS_USERNAME || null,
      JSON.stringify({ source: 'env_ops_login', seed: 'personal-workspaces-2026-06-14' }),
    ]
  ).catch(() => {});

  const setupTasks = [
    {
      key: 'google-oauth-app-verification-readiness',
      title: 'Prepare Google OAuth app verification for BNA workspaces',
      summary: 'Create consent-screen checklist, minimum scopes, privacy/terms/support URLs, test users, and demo evidence before public Google integration use.',
      notes: 'Keep sensitive/restricted scopes minimal. Google Business Profile access remains blocked/manual until approval and enabled APIs are confirmed.',
    },
    {
      key: 'google-business-profile-api-access-readiness',
      title: 'Confirm Google Business Profile API access before live provider reviews',
      summary: 'Confirm API approval, OAuth scopes, account ownership, and location access. Use manual profile/review fallback until live access exists.',
      notes: 'Do not fake live Google review data. Provider pages must show manual fallback when disconnected.',
      category: 'marketing',
    },
    {
      key: 'parent-pwa-tablet-filter-setup-flow',
      title: 'Verify parent PWA tablet install and filter setup flow',
      summary: 'Smoke parent portal at phone/tablet widths, install prompt, setup wizard resume, and parent-submitted setup code/status handling.',
      assigned_to: 'Codex',
    },
    {
      key: 'provider-upgrade-url-placeholder',
      title: 'Configure provider upgrade interest URL',
      summary: 'Provider paid-feature clicks show a safe not-configured state until PROVIDER_UPGRADE_URL is set.',
      notes: 'Do not require checkout for free signup/listing. Add the configured interest URL and smoke the upgrade intent route.',
      category: 'accounting',
      assigned_to: 'Shloimie',
    },
    {
      key: 'hebrew-i18n-rtl-audit',
      title: 'Audit Hebrew RTL UI labels across parent, student, signup, and provider surfaces',
      summary: 'Hebrew mode must be real Hebrew with RTL layout. English fallback labels inside Hebrew UI are bugs except brand names, URLs, code values, and user-entered content.',
      assigned_to: 'Codex',
    },
  ];
  if (bnaWorkspace?.id) {
    for (const spec of setupTasks) {
      await ensureWorkspaceSetupTask({ project: bnaWorkspace, category: spec.category || 'technology', urgency: 'this_week', assigned_to: spec.assigned_to || 'Shloimie', ...spec }, db);
    }
  }

  return { superAdmin, bna: bnaWorkspace, family, people: { shloimie, menachem, esty }, household };
}

async function getProjectByKey(projectKey, db = pool) {
  const normalized = normalizeProjectKey(projectKey || DEFAULT_PROJECT_KEY) || DEFAULT_PROJECT_KEY;
  const result = await db.query('SELECT * FROM bna_projects WHERE project_key = $1 LIMIT 1', [normalized]);
  if (result.rows[0]) return result.rows[0];
  const seeded = await ensureDefaultProjects(db);
  return normalized === ONE_TIME_PROJECT_KEY ? seeded.oneTime : seeded.bna;
}

async function ensureDefaultLearningCommunity(db = pool) {
  const project = await getProjectByKey(DEFAULT_PROJECT_KEY, db);
  if (!project?.id) return null;
  const result = await db.query(
    `INSERT INTO bna_learning_communities (
       workspace_key, project_id, community_key, title, description,
       owner_name, visibility, status, metadata_json
     ) VALUES (
       'bna', $1, 'bna-main', 'Bnei Neviim Learning Community',
       'Default moderated community space for BNA parents, students, rabbis, and service providers.',
       'Rabbi Shloimie', 'members', 'active', $2::jsonb
     )
     ON CONFLICT (workspace_key, community_key) DO UPDATE SET
       project_id = COALESCE(bna_learning_communities.project_id, EXCLUDED.project_id),
       title = EXCLUDED.title,
       description = EXCLUDED.description,
       owner_name = EXCLUDED.owner_name,
       metadata_json = bna_learning_communities.metadata_json || EXCLUDED.metadata_json,
       updated_at = NOW()
     RETURNING *`,
    [
      project.id,
      JSON.stringify({
        auto_include_bna_portal: true,
        moderation: 'staff_visible',
        source: 'default_seed',
      }),
    ]
  );
  return result.rows[0];
}

async function ensureWs11CommunityFoundation(db = pool) {
  const project = await getProjectByKey(ONE_TIME_PROJECT_KEY, db);
  if (!project?.id) return null;
  const community = (await db.query(
    `INSERT INTO bna_learning_communities (
       workspace_key, project_id, project_key, workspace_id, community_key,
       slug, title, name, short_name, description, owner_name,
       primary_teacher, visibility, status, metadata_json
     ) VALUES (
       $1, $2, $3, $4, $5,
       $5, $6, $6, $7, $8, $9,
       $9, 'members', 'active', $10::jsonb
     )
     ON CONFLICT (workspace_key, community_key) DO UPDATE SET
       project_id = EXCLUDED.project_id,
       project_key = EXCLUDED.project_key,
       workspace_id = EXCLUDED.workspace_id,
       slug = EXCLUDED.slug,
       title = EXCLUDED.title,
       name = EXCLUDED.name,
       short_name = EXCLUDED.short_name,
       description = EXCLUDED.description,
       owner_name = EXCLUDED.owner_name,
       primary_teacher = EXCLUDED.primary_teacher,
       status = 'active',
       metadata_json = COALESCE(bna_learning_communities.metadata_json, '{}'::jsonb) || EXCLUDED.metadata_json,
       updated_at = NOW()
     RETURNING *`,
    [
      ONE_TIME_PROJECT_KEY,
      project.id,
      ONE_TIME_PROJECT_KEY,
      ONE_TIME_PROJECT_KEY,
      'rabbi-mishnah-learning-community',
      'Rabbi Mishnah Learning Community',
      'Mishnah Community',
      'A moderated One Time Mishnayos class space for lessons, worksheets, student questions, parent-safe wins, and Rabbi-approved progress.',
      'Rabbi Elie Scheller',
      JSON.stringify({
        source: 'ws11_seed',
        product_layer: 'gamification_parent_progress_course_library',
        spec_visibility: 'student',
        approval_required_for_parent_or_public: true,
      }),
    ]
  )).rows[0];

  const course = (await db.query(
    `INSERT INTO bna_courses (
       community_id, project_id, project_key, slug, title, short_title,
       description, primary_teacher, status, visibility, sort_order, metadata
     ) VALUES (
       $1, $2, $3, 'mishnah-foundations', 'Mishnah Foundations', 'Foundations',
       'The first One Time Mishnayos course shell for reviewed classes, source sheets, questions, and student participation.',
       'Rabbi Elie Scheller', 'active', 'student', 10, $4::jsonb
     )
     ON CONFLICT (slug) DO UPDATE SET
       community_id = EXCLUDED.community_id,
       project_id = EXCLUDED.project_id,
       project_key = EXCLUDED.project_key,
       title = EXCLUDED.title,
       short_title = EXCLUDED.short_title,
       description = EXCLUDED.description,
       primary_teacher = EXCLUDED.primary_teacher,
       status = 'active',
       visibility = EXCLUDED.visibility,
       metadata = COALESCE(bna_courses.metadata, '{}'::jsonb) || EXCLUDED.metadata,
       updated_at = NOW()
     RETURNING *`,
    [
      community.id,
      project.id,
      ONE_TIME_PROJECT_KEY,
      JSON.stringify({ source: 'ws11_seed', first_course: true }),
    ]
  )).rows[0];

  const badgeSeeds = oneTimeBadgeDefinitions().map((badge) => ({
    ...badge,
    icon: badge.icon || String(badge.title || badge.slug || 'B').slice(0, 2).toUpperCase(),
  }));
  for (const badge of badgeSeeds) {
    await db.query(
      `INSERT INTO bna_badges (
         slug, title, description, event_type, points_required, icon, status, metadata
       ) VALUES ($1, $2, $3, $4, $5, $6, 'active', $7::jsonb)
       ON CONFLICT (slug) DO UPDATE SET
         title = EXCLUDED.title,
         description = EXCLUDED.description,
         event_type = EXCLUDED.event_type,
         points_required = EXCLUDED.points_required,
         icon = EXCLUDED.icon,
         status = 'active',
         metadata = COALESCE(bna_badges.metadata, '{}'::jsonb) || EXCLUDED.metadata,
         updated_at = NOW()`,
      [
        badge.slug,
        badge.title,
        badge.description,
        badge.event_type,
        badge.points_required,
        badge.icon,
        JSON.stringify({
          source: 'ws11_seed',
          requirement_id: 'REQ-20260619-310',
          award_mode: badge.award_mode,
          threshold_key: badge.threshold_key,
          parent_safe_explanation: badge.parent_safe_explanation,
          no_public_individual_leaderboard: true,
        }),
      ]
    );
  }

  return { community, course };
}

function ws11CourseView(row = {}) {
  const enrollmentRows = Array.isArray(row.enrollments) ? row.enrollments : [];
  const fallbackEnrollment = row.enrollment_status
    ? [{ status: row.enrollment_status, progress_percent: row.enrollment_progress_percent }]
    : [];
  return {
    id: row.id,
    community_id: row.community_id,
    project_id: row.project_id,
    project_key: row.project_key,
    slug: row.slug,
    title: row.title,
    short_title: row.short_title,
    description: row.description || '',
    primary_teacher: row.primary_teacher || '',
    status: row.status,
    visibility: row.visibility,
    sort_order: Number(row.sort_order || 100),
    lesson_count: Number(row.lesson_count || 0),
    worksheet_count: Number(row.worksheet_count || 0),
    enrollment_summary: courseEnrollmentSummary(enrollmentRows.length ? enrollmentRows : fallbackEnrollment),
    enrollment: row.enrollment_id ? {
      id: row.enrollment_id,
      student_id: row.enrollment_student_id,
      status: row.enrollment_status,
      progress_percent: Number(row.enrollment_progress_percent || 0),
      points_total: Number(row.enrollment_points_total || 0),
    } : null,
    metadata: parseJsonMaybe(row.metadata),
    created_at: row.created_at,
    updated_at: row.updated_at,
  };
}

