async function createInAppNotification(input = {}, db = pool) {
  const eventType = safeNotificationEventType(input.eventType || input.event_type);
  const projectId = input.projectId || input.project_id || null;
  const workspaceKey = normalizeWorkspaceKey(input.workspaceKey || input.workspace_key || workspaceKeyForProject(input.projectKey || input.project_key) || '') || 'bna';
  const recipientLabel = limitText(input.recipientLabel || input.recipient_label || 'Shloimie', 160) || 'Shloimie';
  const recipientRole = limitText(input.recipientRole || input.recipient_role || 'operator', 120) || 'operator';
  const title = limitText(input.title || '', 220);
  if (!title) return null;
  const sourceContext = {
    ...(input.sourceContext || input.source_context || {}),
    in_app_notification_only: true,
    no_send: true,
    external_write_performed: false,
  };
  const key = limitText(input.notificationKey || input.notification_key || notificationKeyFor({
    eventType,
    recipientLabel,
    sourceTable: input.sourceTable || input.source_table || input.relatedType || input.related_type,
    sourceId: input.sourceId || input.source_id || input.relatedId || input.related_id,
  }), 320);
  const result = await db.query(
    `INSERT INTO bna_in_app_notifications (
       notification_key, project_id, workspace_key, recipient_label, recipient_role,
       event_type, title, body, priority, status, related_type, related_id,
       source_table, source_id, source_context, delivery_state, no_send,
       external_write_performed, created_by
     ) VALUES (
       $1, $2, $3, $4, $5,
       $6, $7, $8, $9, 'unread', $10, $11,
       $12, $13, $14::jsonb, 'in_app_only', TRUE,
       FALSE, $15
     )
     ON CONFLICT (notification_key) DO UPDATE SET
       project_id = COALESCE(EXCLUDED.project_id, bna_in_app_notifications.project_id),
       workspace_key = EXCLUDED.workspace_key,
       recipient_label = EXCLUDED.recipient_label,
       recipient_role = EXCLUDED.recipient_role,
       title = EXCLUDED.title,
       body = EXCLUDED.body,
       priority = EXCLUDED.priority,
       related_type = EXCLUDED.related_type,
       related_id = EXCLUDED.related_id,
       source_context = COALESCE(bna_in_app_notifications.source_context, '{}'::jsonb) || EXCLUDED.source_context,
       delivery_state = 'in_app_only',
       no_send = TRUE,
       external_write_performed = FALSE,
       updated_at = NOW()
     RETURNING *, (xmax = 0) AS inserted`,
    [
      key,
      projectId,
      workspaceKey,
      recipientLabel,
      recipientRole,
      eventType,
      title,
      limitText(input.body || '', 1200) || null,
      safeNotificationPriority(input.priority),
      limitText(input.relatedType || input.related_type || '', 80) || null,
      input.relatedId || input.related_id ? String(input.relatedId || input.related_id) : null,
      limitText(input.sourceTable || input.source_table || '', 120) || null,
      input.sourceId || input.source_id ? Number(input.sourceId || input.source_id) : null,
      JSON.stringify(sourceContext),
      limitText(input.createdBy || input.created_by || 'system', 120) || 'system',
    ]
  );
  const row = result.rows[0];
  const notification = inAppNotificationView(row);
  const sourceTable = String(input.sourceTable || input.source_table || '').trim().toLowerCase();
  const relatedType = String(input.relatedType || input.related_type || '').trim().toLowerCase();
  if (
    row?.inserted &&
    sourceContext.telegram_notification_allowed !== false &&
    (sourceTable === 'bna_support_tickets' || relatedType === 'support_ticket') &&
    ['support_ticket_created', 'safety_moderation_flag'].includes(eventType)
  ) {
    notifyTelegramRoleAlias({
      roleAlias: sourceContext.telegram_role_alias || 'platform_support_shloimie',
      ticket: {
        id: input.relatedId || input.related_id || input.sourceId || input.source_id || null,
        title,
        severity: sourceContext.severity || input.priority || 'normal',
        category: sourceContext.category || 'other',
        workspace_key: workspaceKey,
        project_key: input.projectKey || input.project_key || sourceContext.project_key || null,
        source: sourceContext.source || eventType,
      },
      context: {
        source: sourceContext.source || eventType,
        workspaceKey,
        projectKey: input.projectKey || input.project_key || sourceContext.project_key || null,
        reviewPath: '/operations?view=admin&section=tickets',
      },
    }).catch((error) => console.error('Support ticket Telegram alert error:', error.message || error));
  }
  return notification;
}

