async function upsertParentAccountabilityPipeline(parentEmail, studentId, input = {}, db = pool) {
  const student = await getParentPortalStudentForSession(parentEmail, studentId, db);
  if (!student) {
    const error = new Error('Student was not found for this parent session');
    error.statusCode = 404;
    throw error;
  }
  const parserInstructions = String(input.parser_instructions || input.instructions || '').trim().slice(0, 5000)
    || defaultParentAccountabilityInstructions(student);
  const sectionPreferences = input.section_preferences && typeof input.section_preferences === 'object' && !Array.isArray(input.section_preferences)
    ? input.section_preferences
    : {};
  const language = normalizeLanguage(input.language || recordPreferredLanguage(student));
  const result = await db.query(
    `INSERT INTO bna_parent_accountability_pipelines (
       parent_email, student_id, parser_instructions, section_preferences, language
     ) VALUES ($1, $2, $3, $4, $5)
     ON CONFLICT (parent_email, student_id) DO UPDATE SET
       parser_instructions = EXCLUDED.parser_instructions,
       section_preferences = EXCLUDED.section_preferences,
       language = EXCLUDED.language,
       updated_at = NOW()
     RETURNING *`,
    [
      normalizeEmail(parentEmail),
      Number(student.id),
      parserInstructions,
      JSON.stringify(sectionPreferences),
      language,
    ]
  );
  return parentAccountabilityPipelineView(result.rows[0], { parentEmail, student });
}

