function googleIntegrationReadinessPayload() {
  const oauthConfigured = googleOAuthClientConfigured();
  const configuredScopes = googleAuthService.parseGoogleScopeList(GOOGLE_SCOPES);
  const broadConfiguredScopes = configuredScopes.filter((scope) => (
    /\/auth\/drive$|gmail\.send|classroom\.rosters|classroom\.profile\.emails|classroom\.guardians|classroom\.profile\.photos|classroom\.student-submissions/i
  ).test(scope));
  return {
    success: true,
    oauth: {
      configured: oauthConfigured,
      redirect_uri: GOOGLE_REDIRECT_URI,
      default_scopes: DEFAULT_GOOGLE_SCOPES,
      required_scopes: DEFAULT_GOOGLE_SCOPES,
      configured_scopes: configuredScopes,
      configured_scope_warnings: broadConfiguredScopes.map((scope) => ({
        scope,
        warning: 'Configured in the environment but not requested by a bare OAuth start. Use only for an explicit approved smoke or remove from Railway env.',
      })),
      scope_request_policy: 'Bare OAuth starts request identity only; broader Calendar, Classroom, Drive, or Business Profile scopes require an explicit feature/scope/setup request and the owner approval packet.',
      sensitive_scope_guard: 'Use minimum scopes and complete Google verification before public/provider use.',
    },
    maps: {
      configured: Boolean(GOOGLE_MAPS_API_KEY),
      fallback: GOOGLE_MAPS_API_KEY ? 'Maps key configured for allowed map/place features.' : 'Plain text service area fields stay active until a Maps/Places key is configured.',
    },
    business_profile: {
      configured: oauthConfigured,
      approved: false,
      status: oauthConfigured ? 'pending_approval' : 'not_configured',
      fallback: 'Manual Google profile/review fields are used until Business Profile API access is approved. No live reviews are faked.',
    },
  };
}

async function sendGoogleIntegrationStatus(req, res) {
  try {
    const [integrationResult, oauthResult] = await Promise.all([
      pool.query(
      `SELECT id, integration, status, scopes, external_account_id, external_location_id, metadata, created_at, updated_at
       FROM bna_integration_connections
       WHERE integration IN ('google_oauth', 'google_business_profile', 'google_calendar', 'google_classroom', 'google_maps')
       ORDER BY updated_at DESC NULLS LAST, created_at DESC
       LIMIT 50`
      ),
      pool.query(
      `SELECT id, connection_role, account_email, google_sub, scope_text, refresh_token, status, metadata, connected_at, updated_at
       FROM bna_google_connections
       WHERE COALESCE(status, 'connected') <> 'revoked'
       ORDER BY updated_at DESC NULLS LAST, connected_at DESC NULLS LAST, id DESC
       LIMIT 50`
      ),
    ]);
    const integrationConnections = integrationResult.rows.map((row) => ({
      ...row,
      integration_connection_id: row.id,
      scopes: Array.isArray(row.scopes) ? row.scopes : [],
      source: 'integration_connection',
    }));
    const oauthConnections = oauthResult.rows.flatMap(googleIntegrationRowsFromOAuthConnection);
    const connections = [...oauthConnections, ...integrationConnections];
    res.json({ ...googleIntegrationReadinessPayload(), connections });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
}

