function jsonArrayValue(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined || value === '') return [];
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed;
    } catch {}
    return trimmed.split(/[,\n]+/).map((item) => item.trim()).filter(Boolean);
  }
  return [value];
}

function normalizeStringArray(value, maxItemLength = 500) {
  return jsonArrayValue(value)
    .map((item) => String(item || '').trim().slice(0, maxItemLength))
    .filter(Boolean);
}

function normalizeEmailArray(value) {
  return normalizeStringArray(value, 320).map(normalizeEmail).filter(Boolean);
}

function sanitizeIntegrationMetadata(value, depth = 0) {
  if (!value || depth > 4) return {};
  const input = typeof value === 'object' ? value : safeJsonParse(value);
  if (!input || typeof input !== 'object' || Array.isArray(input)) return {};
  const output = {};
  for (const [key, rawValue] of Object.entries(input)) {
    if (/api[_-]?key|token|secret|password|authorization|credential/i.test(key)) continue;
    if (rawValue && typeof rawValue === 'object' && !Array.isArray(rawValue)) {
      output[key] = sanitizeIntegrationMetadata(rawValue, depth + 1);
    } else if (Array.isArray(rawValue)) {
      output[key] = rawValue.slice(0, 50).map((item) => {
        if (item && typeof item === 'object') return sanitizeIntegrationMetadata(item, depth + 1);
        return String(item || '').slice(0, 1000);
      });
    } else {
      output[key] = String(rawValue ?? '').slice(0, 2000);
    }
  }
  return output;
}

