function confirmationTokenHash(token) {
  return crypto.createHash('sha256').update(String(token || '')).digest('hex');
}

function looksLikeTruncatedDnsValue(value = '') {
  const text = String(value || '').trim();
  return /(\.\.\.|…)$/.test(text) || /\[truncated\]/i.test(text);
}

function fileExistsSafe(filePath) {
  try {
    return fs.existsSync(filePath);
  } catch {
    return false;
  }
}

function runtimeFileStatSafe(filePath) {
  try {
    const stat = fs.statSync(filePath);
    return {
      present: true,
      updated_at: stat.mtime.toISOString(),
      age_minutes: Math.round((Date.now() - stat.mtime.getTime()) / 60000),
    };
  } catch {
    return { present: false, updated_at: null, age_minutes: null };
  }
}

async function loadAgentRuntimeStatus(agentKey) {
  if (!agentKey) return null;
  try {
    const result = await pool.query(
      `SELECT *,
              CASE
                WHEN last_seen_at IS NULL THEN true
                ELSE last_seen_at < NOW() - (COALESCE(stale_after_ms, 180000) * INTERVAL '1 millisecond')
              END AS stale
       FROM bna_agent_runtime_status
       WHERE agent_key = $1
       ORDER BY last_seen_at DESC
       LIMIT 1`,
      [agentKey]
    );
    return result.rows[0] || null;
  } catch {
    return null;
  }
}

