function buildKeyholderStatusCard() {
  const roots = integrationSecretLoader.defaultKeyholderRoots(__dirname);
  const existingRoots = roots.filter((root) => root && fileExistsSafe(root));
  const checked = [
    configuredSecretStatus('STRIPE_SECRET_KEY', { names: ['stripe-secret-key', 'stripe'] }),
    configuredSecretStatus('RABBI_STRIPE_SECRET_KEY', { names: ['rabbi-stripe-secret-key', 'stripe'] }),
    configuredSecretStatus('BUFFER_API_KEY', { names: ['buffer-api-key', 'buffer'] }),
    configuredSecretStatus('RESEND_API_KEY', { names: ['resend-api-key', 'resend'] }),
    configuredSecretStatus('ZOOM_CLIENT_SECRET', { names: ['zoom-client-secret', 'zoom'] }),
    configuredSecretStatus('VIMEO_ACCESS_TOKEN', { names: ['vimeo-access-token', 'vimeo'] }),
  ];
  return integrationStatusCard({
    provider: 'keyholder',
    label: 'Keyholder / Secrets',
    configured: Boolean(existingRoots.length || checked.some((item) => item.configured)),
    status: existingRoots.length || checked.some((item) => item.configured) ? 'configured' : 'not_configured',
    mode: 'env_keyholder_secrets',
    accountOwner: 'operator',
    safeActions: ['readiness_check', 'redacted_source_check'],
    blockedActions: ['print_secret', 'copy_secret_without_request', 'commit_secret'],
    blockers: existingRoots.length ? [] : ['BNA_KEYHOLDER_DIR or the default local keyholder folder is not visible to this process.'],
    details: {
      visible_secret_roots_count: existingRoots.length,
      configured_secret_count: checked.filter((item) => item.configured).length,
      allowed_sources: ['env', 'keyholder', '.secrets'],
    },
  });
}

