  const pipelineConfigPresent = Boolean(process.env.GOOGLE_DRIVE_PIPELINE_CONFIG || process.env.GOOGLE_DRIVE_PIPELINE_FOLDER_ID)
    || fileExistsSafe(path.join(__dirname, '.secrets', 'google-drive-pipeline.json'));
