async function buildIntegrationStatusPayload() {
  const bufferReadiness = await getBufferReadinessForResponse();
  const resendReadiness = await getResendReadinessForResponse();
  const bufferCard = integrationStatusCard({
    provider: 'buffer',
    label: 'Buffer',
    configured: bufferReadiness.configured,
    status: bufferReadiness.configured
      ? (bufferReadiness.connected ? 'configured' : 'configured_but_invalid')
      : 'not_configured',
    mode: 'draft_and_schedule_gate',
    accountOwner: 'bna',
    safeActions: ['health_check', 'channel_list', 'local_draft', 'provider_draft'],
    blockedActions: ['schedule_without_preview_token', 'publish_now'],
    blockers: [bufferReadiness.blocker],
    details: {
      connected: bufferReadiness.connected,
      organization_id_configured: bufferReadiness.organization_id_configured,
      channels_count: bufferReadiness.channels_count || 0,
    },
  });
  const resendCard = integrationStatusCard({
    provider: 'resend',
    label: 'Resend',
    configured: resendReadiness.configured,
    status: resendReadiness.configured
      ? (resendReadiness.connected ? 'configured' : 'configured_but_invalid')
      : 'not_configured',
    mode: resendReadiness.domain_verified ? 'verified_domain' : 'draft_preview_only',
    accountOwner: resendReadiness.account_owner || 'unknown',
    safeActions: ['health_check', 'domain_status', 'email_preview'],
    blockedActions: ['send_without_verified_domain', 'campaign_without_approval', 'dns_guess_from_screenshot'],
    blockers: [resendReadiness.blocker, resendReadiness.domain_verified ? null : 'Exact Resend DNS records must be copied from the dashboard before production send.'],
    details: {
      connected: resendReadiness.connected,
      provider_account_set: Boolean(resendReadiness.provider_account),
      domain_configured: Boolean(resendReadiness.domain),
      domain_verified: Boolean(resendReadiness.domain_verified),
      send_allowed: Boolean(resendReadiness.send_allowed),
      fallback_approved: Boolean(resendReadiness.fallback_approved),
    },
  });
  const cards = [
    buildKeyholderStatusCard(),
    buildGoogleDriveStatusCard(),
    await buildTelegramStatusCard(),
    buildGmailReminderStatusCard(),
    resendCard,
    stripeIntegration.getStripeReadiness({ config: stripeRuntimeConfig }),
    await buildGreenInvoiceStatusCard(),
    bufferCard,
    buildWapiStatusCard(),
    buildGodaddyDnsStatusCard(),
    buildProviderScopedIntegrationsStatusCard(),
    zoomIntegration.getZoomReadiness({ config: zoomRuntimeConfig }),
    videoHostingIntegration.getVideoHostingReadiness({ config: videoHostingRuntimeConfig }),
    buildGhlSocialStatusCard(),
    buildExternalActionGatesStatusCard(),
  ].map((card) => integrationSecretLoader.redactSecrets(card, [
    BUFFER_API_KEY,
    RESEND_API_KEY,
    RESEND_WEBHOOK_SECRET,
    stripeRuntimeConfig.secretKey,
    zoomRuntimeConfig.clientSecret,
    videoHostingRuntimeConfig.vimeoToken,
  ]));
  return {
    success: true,
    generated_at: new Date().toISOString(),
    preview_first: true,
    external_write_performed: false,
    cards,
  };
}

