function scopedDraftContextForRequest(req, input = {}) {
  const projectKey = requestedProjectKeyForInput(req, {
    ...(req?.query || {}),
    ...(input || {}),
  }) || '';
  return {
    projectKey,
    workspaceKey: normalizeWorkspaceKey(
      input.workspace_key ||
      input.workspace ||
      req?.query?.workspace_key ||
      req?.query?.workspace ||
      workspaceKeyForProject(projectKey)
    ),
  };
}

function appendJsonbProjectMetadataScope(req, conditions, params, columnRef = 'metadata') {
  const projectKey = requestedProjectKeyForScopedList(req);
  if (!projectKey) return '';
  const workspaceKey = workspaceKeyForProject(projectKey);
  params.push(projectKey);
  const projectRef = `$${params.length}`;
  params.push(workspaceKey);
  const workspaceRef = `$${params.length}`;
  const condition = `(COALESCE(${columnRef}->>'project_key', '') = ${projectRef} OR COALESCE(${columnRef}->>'workspace_key', '') = ${workspaceRef})`;
  conditions.push(condition);
  return condition;
}

function appendDnsWorkspaceScope(req, conditions, params) {
  const projectKey = requestedProjectKeyForScopedList(req);
  if (!projectKey) return '';
  params.push(workspaceKeyForProject(projectKey));
  const condition = `workspace_id = (SELECT id FROM bna_workspace_settings WHERE workspace_key = $${params.length} LIMIT 1)`;
  conditions.push(condition);
  return condition;
}

async function workspaceSettingsIdForKey(workspaceKey, db = pool) {
  const key = normalizeWorkspaceKey(workspaceKey);
  if (!key) return null;
  const row = (await db.query('SELECT id FROM bna_workspace_settings WHERE workspace_key = $1 LIMIT 1', [key])).rows[0];
  return row?.id || null;
}

function assertScopedDraftMetadataAccess(req, metadata = {}) {
  const scopedProjectKey = opsScopeProjectKey(req);
  if (!scopedProjectKey) return;
  const projectKey = normalizeProjectKey(metadata?.project_key || metadata?.project || DEFAULT_PROJECT_KEY);
  assertProjectAccess(req, { project_key: projectKey });
}

async function findCrossWorkspaceEmailRecipientConflicts(req, emails = [], draftContext = {}, db = pool) {
  const projectKey = normalizeProjectKey(draftContext.projectKey || requestedProjectKeyForInput(req, draftContext) || '');
  const normalizedEmails = [...new Set((emails || []).map(normalizeEmail).filter(Boolean))];
  if (!projectKey || !normalizedEmails.length) return [];
  const result = await db.query(
    `WITH known_emails AS (
       SELECT LOWER(c.primary_email) AS email,
              CASE COALESCE(ws.workspace_key, '')
                WHEN 'rabbi_sheller_provider' THEN 'one_time_mishnah_class'
                WHEN 'bna' THEN '${DEFAULT_PROJECT_KEY}'
                ELSE COALESCE(ws.workspace_key, '')
              END AS project_key,
              'contact' AS source
       FROM bna_contacts c
       LEFT JOIN bna_workspace_settings ws ON ws.id = c.workspace_id
       WHERE c.primary_email IS NOT NULL
       UNION ALL
       SELECT LOWER(s.parent_email) AS email, COALESCE(p.project_key, '') AS project_key, 'signup' AS source
       FROM signups s
       LEFT JOIN bna_projects p ON p.id = s.project_id
       WHERE s.parent_email IS NOT NULL
       UNION ALL
       SELECT LOWER(st.parent_email) AS email, COALESCE(p.project_key, '') AS project_key, 'student' AS source
       FROM bna_students st
       LEFT JOIN bna_projects p ON p.id = st.project_id
       WHERE st.parent_email IS NOT NULL
     )
     SELECT email, project_key, source
     FROM known_emails
     WHERE email = ANY($1::text[])
       AND project_key <> ''
       AND project_key <> $2
     ORDER BY email, source
     LIMIT 20`,
    [normalizedEmails, projectKey]
  );
  return result.rows;
}

