async function createSocialDraft(req, res) {
  const body = req.body || {};
  const provider = String(body.provider || 'buffer').trim().toLowerCase() === 'manual' ? 'manual' : 'buffer';
  const text = String(body.text || body.body || '').trim();
  if (!text) return res.status(400).json({ error: 'text is required' });
  const channelIds = normalizeStringArray(body.channel_ids || body.channelIds || bufferRuntimeConfig.defaultChannelIds, 160);
  const media = jsonArrayValue(body.media).map((item) => (item && typeof item === 'object' ? sanitizeIntegrationMetadata(item) : { url: String(item || '') })).filter(Boolean);
  const draftContext = scopedDraftContextForRequest(req, body);
  const metadata = sanitizeIntegrationMetadata({
    ...(body.metadata || {}),
    project_key: draftContext.projectKey || DEFAULT_PROJECT_KEY,
    workspace_key: draftContext.workspaceKey || workspaceKeyForProject(draftContext.projectKey || DEFAULT_PROJECT_KEY),
  });
  const created = (await pool.query(
    `INSERT INTO bna_social_posts (
       provider, provider_account, account_owner, status, channel_ids, body, media, link,
       source, source_id, metadata, created_by, updated_at
     ) VALUES ($1, $2, $3, 'draft', $4::jsonb, $5, $6::jsonb, $7, $8, $9, $10::jsonb, $11, NOW())
     RETURNING *`,
    [
      provider,
      SOCIAL_POST_PROVIDER,
      'bna',
      JSON.stringify(channelIds),
      text,
      JSON.stringify(media),
      body.link || null,
      body.source || 'manual',
      body.source_id || body.sourceId || null,
      JSON.stringify(metadata),
      req.opsUser || 'operations',
    ]
  )).rows[0];

  let draft = created;
  let providerDraft = null;
  let setupBlocker = null;
  let readiness = null;
  if (provider === 'buffer' && (body.create_provider_draft === true || body.createProviderDraft === true || body.provider_draft === true)) {
    readiness = await getBufferReadinessForResponse();
    try {
      providerDraft = await bufferIntegration.createBufferDraftPost({
        channelIds,
        text,
        media,
        metadata,
      }, { config: bufferServerRuntimeConfig(), fetchImpl: fetch });
      const providerIds = providerDraft.posts.map((post) => post.id).filter(Boolean).join(',');
      draft = (await pool.query(
        `UPDATE bna_social_posts
         SET status = 'provider_draft',
             provider_post_id = $1,
             metadata = COALESCE(metadata, '{}'::jsonb) || $2::jsonb,
             updated_at = NOW()
         WHERE id = $3
         RETURNING *`,
        [providerIds || null, JSON.stringify({ buffer_post_ids: providerDraft.posts.map((post) => post.id).filter(Boolean) }), created.id]
      )).rows[0];
    } catch (err) {
      const safe = safeIntegrationError(err, 'Buffer draft creation failed');
      setupBlocker = safe.blocker;
      draft = (await pool.query(
        `UPDATE bna_social_posts
         SET error = $1,
             updated_at = NOW()
         WHERE id = $2
         RETURNING *`,
        [safe.blocker, created.id]
      )).rows[0];
    }
  }

  res.json({
    success: true,
    draft: socialPostView(draft),
    provider_draft: providerDraft ? { provider: 'buffer', post_ids: providerDraft.posts.map((post) => post.id).filter(Boolean) } : null,
    readiness,
    setup_blocker: setupBlocker,
  });
}

