async function createBufferSchedulePreview(req, res) {
  const body = req.body || {};
  const text = String(body.text || body.body || '').trim();
  const channelIds = normalizeStringArray(body.channel_ids || body.channelIds || bufferRuntimeConfig.defaultChannelIds, 160);
  const scheduledAt = new Date(body.scheduled_at || body.scheduledAt || '');
  if (!text) return res.status(400).json({ error: 'text is required' });
  if (!channelIds.length) return res.status(400).json({ error: 'channel_ids are required before scheduling' });
  if (!Number.isFinite(scheduledAt.getTime())) return res.status(400).json({ error: 'scheduled_at must be a valid timestamp' });
  const token = crypto.randomBytes(18).toString('base64url');
  const expiresAt = new Date(Date.now() + 10 * 60 * 1000);
  const draftContext = scopedDraftContextForRequest(req, body);
  const created = (await pool.query(
    `INSERT INTO bna_social_posts (
       provider, provider_account, account_owner, status, channel_ids, body, media, link,
       scheduled_at, confirmation_token_hash, confirmation_expires_at,
       source, source_id, metadata, created_by, updated_at
     ) VALUES ('buffer', $1, 'bna', 'schedule_preview', $2::jsonb, $3, $4::jsonb, $5,
       $6::timestamp, $7, $8::timestamp, $9, $10, $11::jsonb, $12, NOW())
     RETURNING *`,
    [
      SOCIAL_POST_PROVIDER,
      JSON.stringify(channelIds),
      text,
      JSON.stringify(jsonArrayValue(body.media).map((item) => (item && typeof item === 'object' ? sanitizeIntegrationMetadata(item) : { url: String(item || '') }))),
      body.link || null,
      scheduledAt.toISOString(),
      confirmationTokenHash(token),
      expiresAt.toISOString(),
      body.source || 'manual',
      body.source_id || body.sourceId || null,
      JSON.stringify(sanitizeIntegrationMetadata({
        ...(body.metadata || {}),
        project_key: draftContext.projectKey || DEFAULT_PROJECT_KEY,
        workspace_key: draftContext.workspaceKey || workspaceKeyForProject(draftContext.projectKey || DEFAULT_PROJECT_KEY),
      })),
      req.opsUser || 'operations',
    ]
  )).rows[0];
  res.json({
    success: true,
    preview: socialPostView(created),
    confirmation_token: token,
    confirmation_expires_at: expiresAt.toISOString(),
    human_preview: `Schedule Buffer post for ${channelIds.length} channel(s) at ${scheduledAt.toISOString()}.`,
    external_write_performed: false,
  });
}

app.post('/api/bna/communications/social/schedule/preview', requireAdmin, createBufferSchedulePreview);
app.post('/api/bna/integrations/buffer/schedules', requireAdmin, async (req, res) => {
  const body = req.body || {};
  if (body.preview_id || body.draft_id || body.id || body.confirmation_token || body.token) {
    return confirmBufferSchedule(req, res);
  }
  return createBufferSchedulePreview(req, res);
});

async function confirmBufferSchedule(req, res) {
  const body = req.body || {};
  const id = Number(body.preview_id || body.draft_id || body.id);
  const token = String(body.confirmation_token || body.token || '').trim();
  const confirmed = body.confirmed === true || String(body.confirmation_phrase || '').trim() === 'SCHEDULE BUFFER POST';
  if (!Number.isFinite(id) || id <= 0) return res.status(400).json({ error: 'preview_id is required' });
  if (!token || !confirmed) return res.status(409).json({ error: 'Schedule confirmation requires confirmed:true and the preview token, or phrase SCHEDULE BUFFER POST' });
  const row = (await pool.query('SELECT * FROM bna_social_posts WHERE id = $1 LIMIT 1', [id])).rows[0];
  if (!row) return res.status(404).json({ error: 'Social schedule preview was not found' });
  assertScopedDraftMetadataAccess(req, row.metadata || {});
  if (row.confirmation_token_hash !== confirmationTokenHash(token)) return res.status(409).json({ error: 'Confirmation token does not match this preview' });
  if (row.confirmation_expires_at && Date.parse(row.confirmation_expires_at) < Date.now()) return res.status(409).json({ error: 'Confirmation token expired; create a fresh preview' });
  try {
    const result = await bufferIntegration.scheduleBufferPost({
      channelIds: row.channel_ids,
      text: row.body,
      scheduledAt: row.scheduled_at,
      media: row.media,
      confirmation: { confirmed: true },
    }, { config: bufferServerRuntimeConfig(), fetchImpl: fetch });
    const providerIds = result.posts.map((post) => post.id).filter(Boolean).join(',');
    const updated = (await pool.query(
      `UPDATE bna_social_posts
       SET status = 'scheduled',
           provider_post_id = $1,
           confirmed_by = $2,
           confirmed_at = NOW(),
           metadata = COALESCE(metadata, '{}'::jsonb) || $3::jsonb,
           updated_at = NOW()
       WHERE id = $4
       RETURNING *`,
      [providerIds || null, req.opsUser || 'operations', JSON.stringify({ buffer_post_ids: result.posts.map((post) => post.id).filter(Boolean) }), id]
    )).rows[0];
    res.json({ success: true, scheduled: true, draft: socialPostView(updated), provider_post_id: providerIds || null });
  } catch (err) {
    const safe = safeIntegrationError(err, 'Buffer scheduling failed');
    const updated = (await pool.query(
      `UPDATE bna_social_posts
       SET status = 'blocked',
           error = $1,
           updated_at = NOW()
       WHERE id = $2
       RETURNING *`,
      [safe.blocker, id]
    )).rows[0];
    res.status(safe.status).json({ success: false, scheduled: false, setup_blocker: safe.blocker, draft: socialPostView(updated) });
  }
}

