async function createResendEmailDraft(req, res) {
  const body = req.body || {};
  const to = normalizeEmailArray(body.to || body.to_emails || body.toEmails);
  const cc = normalizeEmailArray(body.cc || body.cc_emails || body.ccEmails);
  const bcc = normalizeEmailArray(body.bcc || body.bcc_emails || body.bccEmails);
  const subject = String(body.subject || '').trim();
  const text = String(body.text || body.text_body || body.textBody || '').trim();
  const html = String(body.html || body.html_body || body.htmlBody || '').trim();
  const replyTo = normalizeEmail(body.reply_to || body.replyTo || body.metadata?.reply_to || '');
  if (!to.length) return res.status(400).json({ error: 'At least one recipient is required' });
  if (!subject || (!text && !html)) return res.status(400).json({ error: 'subject and text/html are required' });
  const readiness = await getResendReadinessForResponse();
  const draftContext = scopedDraftContextForRequest(req, body);
  const recipientConflicts = await findCrossWorkspaceEmailRecipientConflicts(req, [...to, ...cc, ...bcc], draftContext);
  if (recipientConflicts.length) {
    return res.status(403).json({
      success: false,
      error: 'Recipient belongs to a different workspace/project',
      cross_workspace_recipients: recipientConflicts.map((item) => ({
        email: item.email,
        project_key: item.project_key,
        source: item.source,
      })),
      send_blocked: true,
    });
  }
  const created = (await pool.query(
    `INSERT INTO bna_email_drafts (
       provider, provider_account, account_owner, from_email, to_emails, cc_emails, bcc_emails,
       subject, text_body, html_body, status, send_blocker, source, source_id, metadata, created_by, updated_at
     ) VALUES ('resend', $1, $2, $3, $4::jsonb, $5::jsonb, $6::jsonb,
       $7, $8, $9, 'draft', $10, $11, $12, $13::jsonb, $14, NOW())
     RETURNING *`,
    [
      RESEND_PROVIDER_ACCOUNT || null,
      body.account_owner || RESEND_ACCOUNT_OWNER || 'unknown',
      normalizeEmail(body.from || body.from_email || RESEND_FROM_EMAIL) || RESEND_FROM_EMAIL || null,
      JSON.stringify(to),
      JSON.stringify(cc),
      JSON.stringify(bcc),
      subject,
      text || null,
      html || null,
      readiness.send_allowed ? null : readiness.blocker,
      body.source || 'manual',
      body.source_id || body.sourceId || null,
      JSON.stringify(sanitizeIntegrationMetadata({
        ...(body.metadata || {}),
        ...(replyTo ? { reply_to: replyTo } : {}),
        project_key: draftContext.projectKey || DEFAULT_PROJECT_KEY,
        workspace_key: draftContext.workspaceKey || workspaceKeyForProject(draftContext.projectKey || DEFAULT_PROJECT_KEY),
      })),
      req.opsUser || 'operations',
    ]
  )).rows[0];
  res.json({ success: true, draft: emailDraftView(created), readiness, send_blocked: !readiness.send_allowed, blocker: readiness.send_allowed ? null : readiness.blocker });
}

