async function sendResendEmailDraft(req, res) {
  const body = req.body || {};
  let draft = null;
  if (body.draft_id || body.draftId) {
    draft = (await pool.query('SELECT * FROM bna_email_drafts WHERE id = $1 LIMIT 1', [Number(body.draft_id || body.draftId)])).rows[0] || null;
    if (!draft) return res.status(404).json({ error: 'Email draft not found' });
    assertScopedDraftMetadataAccess(req, draft.metadata || {});
  } else if (body.reviewed !== true) {
    return res.status(409).json({ error: 'Send requires an existing draft_id or reviewed:true explicit payload' });
  }
  const payload = draft ? emailDraftView(draft) : {
    id: null,
    from_email: normalizeEmail(body.from || body.from_email || RESEND_FROM_EMAIL) || RESEND_FROM_EMAIL,
    to_emails: normalizeEmailArray(body.to || body.to_emails || body.toEmails),
    cc_emails: normalizeEmailArray(body.cc || body.cc_emails || body.ccEmails),
    bcc_emails: normalizeEmailArray(body.bcc || body.bcc_emails || body.bccEmails),
    subject: String(body.subject || '').trim(),
    text_body: String(body.text || body.text_body || '').trim(),
    html_body: String(body.html || body.html_body || '').trim(),
    metadata: sanitizeIntegrationMetadata(body.metadata || {}),
  };
  const payloadMetadata = sanitizeIntegrationMetadata(payload.metadata || {});
  const replyTo = normalizeEmail(body.reply_to || body.replyTo || payload.reply_to || payloadMetadata.reply_to || '');
  const resendRuntimeConfig = resendServerRuntimeConfig();
  const resendConfirm = body.confirm || body.confirmation_phrase || body.confirmationPhrase || body.approval_phrase;
  try {
    const sent = await resendIntegration.sendResendEmail({
      from: payload.from_email ? (RESEND_FROM || payload.from_email) : RESEND_FROM,
      to: payload.to_emails,
      cc: payload.cc_emails,
      bcc: payload.bcc_emails,
      replyTo,
      subject: payload.subject,
      text: payload.text_body,
      html: payload.html_body,
      metadata: { draft_id: payload.id || null },
    }, {
      config: resendRuntimeConfig,
      fetchImpl: fetch,
      confirm: resendConfirm,
    });
    await externalActions.recordExternalActionAudit(pool, {
      provider: 'resend',
      action: 'send',
      riskLevel: 'high',
      previewOnly: false,
      approvalPhrase: resendConfirm,
      accountOwner: resendRuntimeConfig.accountOwner,
      mode: resendRuntimeConfig.domain || 'unknown_domain',
      resultSummary: {
        provider_message_id: sent.id || null,
        recipient_count: payload.to_emails.length,
        cc_count: payload.cc_emails.length,
        bcc_count: payload.bcc_emails.length,
      },
      secrets: [resendRuntimeConfig.apiKey],
    }).catch(() => null);
    if (payload.id) {
      await pool.query(
        `UPDATE bna_email_drafts
         SET status = 'sent',
             provider_message_id = $1,
             reviewed_by = COALESCE(reviewed_by, $2),
             reviewed_at = COALESCE(reviewed_at, NOW()),
             sent_at = NOW(),
             updated_at = NOW()
         WHERE id = $3`,
        [sent.id, req.opsUser || 'operations', payload.id]
      );
    }
    const logProjectKey = normalizeProjectKey(payloadMetadata.project_key || payloadMetadata.project || '');
    const logWorkspaceKey = normalizeWorkspaceKey(payloadMetadata.workspace_key || payloadMetadata.workspace || workspaceKeyForProject(logProjectKey));
    const logProject = logProjectKey ? await getProjectByKey(logProjectKey).catch(() => null) : null;
    const logWorkspaceId = logProjectKey
      ? await getWorkspaceIdForProjectKey(logProjectKey).catch(() => null)
      : null;
    await logEmail({
      emailType: 'resend_email_draft_send',
      to: payload.to_emails.join(', '),
      subject: payload.subject,
      provider: 'resend',
      providerMessageId: sent.id,
      status: 'sent',
      projectId: logProject?.id || null,
      workspaceId: logWorkspaceId || null,
      metadata: {
        ...payloadMetadata,
        draft_id: payload.id || null,
        recipient_count: payload.to_emails.length,
        cc_count: payload.cc_emails.length,
        bcc_count: payload.bcc_emails.length,
        account_owner: RESEND_ACCOUNT_OWNER,
        provider_account: RESEND_PROVIDER_ACCOUNT || null,
        domain: RESEND_DOMAIN || null,
        workspace_key: logWorkspaceKey || payloadMetadata.workspace_key || null,
        project_key: logProjectKey || payloadMetadata.project_key || null,
      },
    });
    res.json({ success: true, sent: true, provider: 'resend', provider_message_id: sent.id, readiness: sent.readiness });
  } catch (err) {
    await externalActions.recordExternalActionAudit(pool, {
      provider: 'resend',
      action: 'send',
      riskLevel: 'high',
      previewOnly: true,
      approvalPhrase: resendConfirm,
      accountOwner: resendRuntimeConfig.accountOwner,
      mode: resendRuntimeConfig.domain || 'unknown_domain',
      errorSummary: externalActions.redactedExternalError(err, [resendRuntimeConfig.apiKey]),
      secrets: [resendRuntimeConfig.apiKey],
    }).catch(() => null);
    const readiness = err.readiness || await getResendReadinessForResponse();
    const blocker = readiness.blocker || safeIntegrationError(err, 'Resend send failed').blocker;
    if (payload.id) {
      await pool.query(
        `UPDATE bna_email_drafts
         SET status = 'send_blocked',
             send_blocker = $1,
             updated_at = NOW()
         WHERE id = $2`,
        [blocker, payload.id]
      );
    }
    res.status(err.status || err.statusCode || 409).json({ success: false, send_blocked: true, blocker, readiness });
  }
}

