// BNA dashboard: signups
app.get('/api/bna/signups', requireAdmin, async (req, res) => {
  const { status, payment_status } = req.query;
  const conditions = [];
  const params = [];
  appendScopeCondition(req, conditions, params, 's.project_id');

  if (status) {
    params.push(status);
    conditions.push(`s.status = $${params.length}`);
  } else {
    conditions.push(`COALESCE(s.status, 'new') <> 'archived'`);
  }

  if (payment_status) {
    params.push(payment_status);
    conditions.push(`s.payment_status = $${params.length}`);
  }

  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

  try {
    const result = await pool.query(
      `SELECT s.*,
              COALESCE(comms.communication_count, 0)::int AS communication_count,
              comms.last_communication_at,
              comms.last_inbound_at,
              comms.last_outbound_at
       FROM signups s
       LEFT JOIN (
         SELECT signup_id,
                COUNT(*) AS communication_count,
                MAX(COALESCE(occurred_at, created_at)) AS last_communication_at,
                MAX(CASE WHEN direction = 'inbound' THEN COALESCE(occurred_at, created_at) END) AS last_inbound_at,
                MAX(CASE WHEN direction IN ('outbound', 'call') THEN COALESCE(occurred_at, created_at) END) AS last_outbound_at
         FROM bna_contact_communications
         WHERE signup_id IS NOT NULL
         GROUP BY signup_id
       ) comms ON comms.signup_id = s.id
       ${whereClause}
       ORDER BY s.created_at DESC`,
      params
    );
    res.json({ signups: result.rows });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.patch('/api/bna/signups/:id', requireAdmin, async (req, res) => {
  const { id } = req.params;
  const allowedFields = [
    'parent_name',
    'parent_email',
    'parent_phone',
    'parent2_name',
    'parent2_email',
    'parent2_phone',
    'student_name',
    'student_age',
    'student_grade',
    'previous_school',
    'reason_applying',
    'special_needs',
    'payment_method',
    'payment_status',
    'payment_amount',
    'cash_notes',
    'status',
    'notes',
    'tags',
  ];
  const fields = [];
  const values = [];

  for (const [key, value] of Object.entries(req.body || {})) {
    if (!allowedFields.includes(key)) continue;
    values.push(key === 'tags' ? value || [] : value);
    fields.push(`${key} = $${values.length}`);
  }

  if (!fields.length) {
    return res.status(400).json({ error: 'No valid signup fields provided' });
  }

  values.push(id);

  try {
    await assertProjectOwnedRowAccess(req, 'signups', id);
    if (Object.prototype.hasOwnProperty.call(req.body || {}, 'parent_email')) {
      const email = normalizeEmail((req.body || {}).parent_email);
      if (email) {
        const duplicate = (await pool.query(
          `SELECT id, parent_name, student_name, parent_email, status
           FROM signups
           WHERE lower(COALESCE(parent_email, '')) = $1
             AND id <> $2
             AND COALESCE(status, 'new') <> 'archived'
             AND project_id = (SELECT project_id FROM signups WHERE id = $2)
           ORDER BY updated_at DESC NULLS LAST, created_at DESC
           LIMIT 1`,
          [email, id]
        )).rows[0];
        if (duplicate) {
          return res.status(409).json({
            error: 'Another active signup already uses that parent email. Merge/archive the duplicate instead of creating a second active record.',
            matched_signup: duplicate,
          });
        }
      }
    }

    const result = await pool.query(
      `UPDATE signups SET ${fields.join(', ')}, updated_at = NOW() WHERE id = $${values.length} RETURNING *`,
      values
    );
    res.json({ success: true, signup: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// BNA dashboard: parent leads / internal CRM
app.get('/api/bna/parent-leads', requireAdmin, async (req, res) => {
  const { lead_type, status, interest_level } = req.query;
  const conditions = [];
  const params = [];
  appendRequestedProjectScopeCondition(req, conditions, params, 'l.project_id');

  if (lead_type) {
    params.push(lead_type);
    conditions.push(`l.lead_type = $${params.length}`);
  }
  if (status) {
    params.push(status);
    conditions.push(`l.status = $${params.length}`);
  } else {
    conditions.push(`COALESCE(l.status, 'interested') <> 'archived'`);
  }
  if (interest_level) {
    params.push(interest_level);
    conditions.push(`l.interest_level = $${params.length}`);
  }

  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

  try {
    const result = await pool.query(
      `SELECT l.*, p.project_key, p.name AS project_name
       FROM bna_parent_leads l
       LEFT JOIN bna_projects p ON p.id = l.project_id
       ${whereClause}
       ORDER BY
         CASE l.interest_level
           WHEN 'hot' THEN 1
           WHEN 'warm' THEN 2
           WHEN 'cool' THEN 3
           ELSE 4
         END,
         COALESCE(l.next_follow_up_date, CURRENT_DATE + INTERVAL '365 days') ASC,
         l.updated_at DESC`,
      params
    );
    res.json({ leads: result.rows });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

async function updateExistingParentLeadFromBody(leadId, parentName, body = {}, duplicateGuard = 'manual') {
  const otherPhones = normalizeTextArray(body.other_phones || body.otherPhones);
  const tags = normalizeTextArray(body.tags);
  const result = await pool.query(
    `UPDATE bna_parent_leads
     SET parent_name = COALESCE($2, parent_name),
         parent_phone = COALESCE(parent_phone, $3),
         other_phones = CASE
           WHEN cardinality($16::text[]) > 0 THEN ARRAY(
             SELECT DISTINCT phone_value
             FROM unnest(COALESCE(other_phones, '{}'::text[]) || $16::text[]) AS phone_values(phone_value)
             WHERE trim(phone_value) <> ''
           )
           ELSE other_phones
         END,
         student_name = COALESCE($4, student_name),
         student_age = COALESCE($5, student_age),
         student_grade = COALESCE($6, student_grade),
         lead_type = COALESCE($7, lead_type),
         status = COALESCE($8, status),
         interest_level = COALESCE($9, interest_level),
         source = COALESCE($17, source),
         source_detail = COALESCE($10, source_detail),
         next_follow_up_date = COALESCE($11, next_follow_up_date),
         owner = COALESCE($12, owner),
         tags = CASE WHEN cardinality($13::text[]) > 0 THEN ARRAY(
           SELECT DISTINCT tag_value
           FROM unnest(COALESCE(tags, '{}'::text[]) || $13::text[]) AS tag_values(tag_value)
           WHERE trim(tag_value) <> ''
         ) ELSE tags END,
         notes = COALESCE($14, notes),
         metadata = COALESCE(metadata, '{}'::jsonb) || $15::jsonb,
         updated_at = NOW()
     WHERE id = $1
     RETURNING *`,
    [
      leadId,
      parentName || null,
      body.parent_phone || null,
      body.student_name || null,
      body.student_age || null,
      body.student_grade || null,
      body.lead_type || null,
      body.status || null,
      body.interest_level || null,
      body.source_detail || null,
      body.next_follow_up_date || null,
      body.owner || null,
      tags,
      body.notes || null,
      JSON.stringify({
        ...(body.metadata || {}),
        duplicate_guard: duplicateGuard,
        duplicate_guard_at: new Date().toISOString(),
      }),
      otherPhones,
      body.source || null,
    ]
  );
  return result.rows[0];
}

app.post('/api/bna/parent-leads', requireAdmin, async (req, res) => {
  const body = req.body || {};
  const parentName = String(body.parent_name || '').trim();
  if (!parentName) return res.status(400).json({ error: 'parent_name is required' });

  try {
    const project = await resolveProjectForScopedWrite(req, body);
    assertProjectAccess(req, project);
    const email = normalizeEmail(body.parent_email);
    if (email) {
      const canonical = opsScopeProjectKey(req) ? [] : await findActiveRecordsByParentEmail(email);
      const existingLead = canonical.find((row) => row.kind === 'lead');
      const existingSignupOrStudent = canonical.find((row) => row.kind === 'signup' || row.kind === 'student');
      if (existingLead) {
        const lead = await updateExistingParentLeadFromBody(existingLead.id, parentName, body, 'updated_existing_parent_lead_by_email');
        return res.json({ success: true, lead, merged_existing: true, duplicate_guard: 'email' });
      }
      if (existingSignupOrStudent) {
        return res.json({
          success: true,
          lead: null,
          matched_existing: existingSignupOrStudent,
          merged_existing: true,
          duplicate_guard: 'email',
        });
      }
    }

    if (body.parent_phone) {
      const canonical = opsScopeProjectKey(req) ? [] : await findActiveRecordsByParentPhone(body.parent_phone);
      const existingLead = canonical.find((row) => row.kind === 'lead');
      const existingSignupOrStudent = canonical.find((row) => row.kind === 'signup' || row.kind === 'student');
      if (existingLead) {
        const lead = await updateExistingParentLeadFromBody(existingLead.id, parentName, body, 'updated_existing_parent_lead_by_phone');
        return res.json({ success: true, lead, merged_existing: true, duplicate_guard: 'phone' });
      }
      if (existingSignupOrStudent) {
        return res.json({
          success: true,
          lead: null,
          matched_existing: existingSignupOrStudent,
          merged_existing: true,
          duplicate_guard: 'phone',
        });
      }
    }

    const existingLeadByName = (await pool.query(
      `SELECT id
       FROM bna_parent_leads
       WHERE lower(COALESCE(parent_name, '')) = lower($1)
         AND COALESCE(status, 'interested') <> 'archived'
         AND project_id = $2
       ORDER BY updated_at DESC NULLS LAST, created_at DESC
       LIMIT 1`,
      [parentName, project.id]
    )).rows[0];
    if (existingLeadByName) {
      const lead = await updateExistingParentLeadFromBody(existingLeadByName.id, parentName, body, 'updated_existing_parent_lead_by_name');
      return res.json({ success: true, lead, merged_existing: true, duplicate_guard: 'name' });
    }

    const result = await pool.query(
      `INSERT INTO bna_parent_leads (
        project_id,
        parent_name, parent_phone, other_phones, parent_email, student_name, student_age,
        student_grade, lead_type, status, interest_level, source, source_detail,
        legacy_crm_contact_id, legacy_crm_conversation_id, last_inbound_at, last_outbound_at,
        next_follow_up_date, owner, tags, notes, metadata
      ) VALUES (
        $1,
        $2, $3, COALESCE($4::text[], '{}'::text[]), $5, $6, $7,
        $8, COALESCE($9, 'school_interest'), COALESCE($10, 'interested'),
        COALESCE($11, 'unknown'), COALESCE($12, 'manual'), $13,
        $14, $15, $16, $17,
        $18, COALESCE($19, 'Shloimie'), COALESCE($20::text[], '{}'::text[]), $21, $22
      )
      RETURNING *`,
      [
        project.id,
        parentName,
        body.parent_phone || null,
        normalizeTextArray(body.other_phones || body.otherPhones),
        body.parent_email || null,
        body.student_name || null,
        body.student_age || null,
        body.student_grade || null,
        body.lead_type || 'school_interest',
        body.status || 'interested',
        body.interest_level || 'unknown',
        body.source || 'manual',
        body.source_detail || null,
        body.legacy_crm_contact_id || null,
        body.legacy_crm_conversation_id || null,
        body.last_inbound_at || null,
        body.last_outbound_at || null,
        body.next_follow_up_date || null,
        body.owner || 'Shloimie',
        Array.isArray(body.tags) ? body.tags : [],
        body.notes || null,
        JSON.stringify(body.metadata || {}),
      ]
    );
    await createInAppNotification({
      eventType: 'parent_lead_submitted',
      projectId: project.id,
      workspaceKey: workspaceKeyForProject(project.project_key),
      recipientLabel: body.owner || 'Shloimie',
      recipientRole: 'operator',
      title: `New parent lead: ${parentName}`,
      body: limitText(body.notes || body.source_detail || body.student_name || 'Review the parent lead and choose the next follow-up.', 900),
      priority: body.interest_level === 'hot' ? 'high' : 'normal',
      relatedType: 'parent_lead',
      relatedId: result.rows[0].id,
      sourceTable: 'bna_parent_leads',
      sourceId: result.rows[0].id,
      sourceContext: {
        lead_type: result.rows[0].lead_type,
        source: result.rows[0].source,
        contact_email_present: Boolean(result.rows[0].parent_email),
        contact_phone_present: Boolean(result.rows[0].parent_phone),
      },
      createdBy: req.opsUser || 'dashboard',
    }).catch((error) => console.error('Parent lead notification error:', error));
    res.json({ success: true, lead: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

