app.patch('/api/bna/providers/:id', requireAdmin, async (req, res) => {
  try {
    const provider = await getProviderIndexProviderByIdOrSlug(req.params.id, { approvedOnly: false });
    if (!provider) return res.status(404).json({ error: 'Provider not found' });
    const body = req.body || {};
    const allowed = new Set([
      'display_name',
      'contact_name',
      'email',
      'phone',
      'whatsapp',
      'website_url',
      'profile_photo_url',
      'hero_image_url',
      'short_description',
      'about',
      'city',
      'neighborhood',
      'service_area',
      'location_label',
      'publish_contact',
      'free_setup',
      'free_listing',
      'upgrade_status',
      'notes',
      'private_admin_notes',
      'seo_title',
      'seo_description',
    ]);
    const fields = [];
    const values = [];
    for (const [key, rawValue] of Object.entries(body)) {
      if (!allowed.has(key)) continue;
      let value = rawValue;
      if (key === 'email') value = normalizeEmail(rawValue) || null;
      else if (['publish_contact', 'free_setup', 'free_listing'].includes(key)) value = Boolean(rawValue);
      else if (['notes', 'private_admin_notes', 'about'].includes(key)) value = limitText(rawValue, 2200) || null;
      else value = limitText(rawValue, 900) || null;
      values.push(value);
      fields.push(`${key} = $${values.length}`);
      if (key === 'email') {
        fields.push(`contact_email = $${values.length}`);
      } else if (key === 'phone') {
        fields.push(`contact_phone = $${values.length}`);
      } else if (key === 'whatsapp') {
        fields.push(`whatsapp_phone = $${values.length}`);
      } else if (key === 'profile_photo_url') {
        fields.push(`profile_image_url = $${values.length}`);
      } else if (key === 'about') {
        fields.push(`full_description = $${values.length}`);
      } else if (key === 'notes') {
        fields.push(`public_notes = $${values.length}`);
      } else if (key === 'private_admin_notes') {
        fields.push(`private_notes = $${values.length}`);
      }
    }
    if (body.languages !== undefined || body.language !== undefined) {
      values.push(normalizeProviderLanguages(body.languages || body.language));
      fields.push(`languages = $${values.length}::text[]`);
    }
    if (body.categories !== undefined || body.category_slugs !== undefined || body.category !== undefined) {
      await syncProviderCategories(provider.id, providerCategorySlugsFromAny(body.categories || body.category_slugs || body.category));
    }
    if (!fields.length && body.categories === undefined && body.category_slugs === undefined && body.category === undefined) {
      return res.status(400).json({ error: 'No supported provider fields supplied' });
    }
    if (fields.length) {
      values.push(provider.id);
      await pool.query(
        `UPDATE bna_service_providers
         SET ${fields.join(', ')},
             updated_at = NOW()
         WHERE id = $${values.length}`,
        values
      );
    }
    await updateProviderCompleteness(provider.id);
    const updated = await getProviderIndexProviderByIdOrSlug(provider.id, { approvedOnly: false });
    res.json({ success: true, provider: adminProviderSelect(updated) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

