app.post('/api/bna/provider-categories', requireAdmin, async (req, res) => {
  const slug = slugifyProviderName(req.body?.slug || req.body?.name || '', '');
  const name = limitText(req.body?.name, 120);
  if (!slug || !name) return res.status(400).json({ error: 'Category slug and name are required' });
  try {
    const category = (await pool.query(
      `INSERT INTO bna_provider_categories (
         slug, name, description, sort_order, active, seo_title, seo_description
       ) VALUES ($1, $2, $3, $4, $5, $6, $7)
       ON CONFLICT (slug) DO UPDATE SET
         name = EXCLUDED.name,
         description = EXCLUDED.description,
         sort_order = EXCLUDED.sort_order,
         active = EXCLUDED.active,
         seo_title = EXCLUDED.seo_title,
         seo_description = EXCLUDED.seo_description,
         updated_at = NOW()
       RETURNING *`,
      [
        slug,
        name,
        limitText(req.body?.description, 500) || null,
        Number.isFinite(Number(req.body?.sort_order)) ? Number(req.body.sort_order) : 99,
        req.body?.active === undefined ? true : Boolean(req.body.active),
        limitText(req.body?.seo_title, 160) || null,
        limitText(req.body?.seo_description, 320) || null,
      ]
    )).rows[0];
    res.json({ success: true, category });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

