async function handleProviderUpgradeInterestRequest(req, res) {
  try {
    const provider = await getProviderIndexProviderByIdOrSlug(req.params.id, { approvedOnly: false });
    if (provider) {
      const upgradeType = limitText(req.body?.upgrade_type || req.body?.type || 'marketing_help', 120) || 'marketing_help';
      const allowedType = PROVIDER_UPSELL_OPTIONS.includes(upgradeType) ? upgradeType : 'marketing_help';
      const event = (await pool.query(
        `INSERT INTO bna_provider_upgrade_events (
           provider_id, upgrade_type, status, notes
         ) VALUES ($1, $2, 'interested', $3)
         RETURNING *`,
        [
          provider.id,
          allowedType,
          limitText(req.body?.notes || req.body?.message || '', 1200) || null,
        ]
      )).rows[0];
      const upgrade = providerUpgradeStatus();
      await pool.query(
        `UPDATE bna_service_providers
         SET upgrade_status = 'interested',
             upgrade_interest = COALESCE(upgrade_interest, '{}'::jsonb) || $2::jsonb,
             updated_at = NOW()
         WHERE id = $1`,
        [provider.id, JSON.stringify({ latest_type: allowedType, latest_event_id: event.id, requested_at: new Date().toISOString() })]
      );
      return res.json({
        success: true,
        configured: upgrade.configured,
        upgrade,
        url: upgrade.link,
        event,
        message: upgrade.configured
          ? 'Upgrade interest saved.'
          : 'Upgrade interest saved. Free listing remains available while BNA follows up.',
      });
    }
    const profile = await providerProfileByIdOrSlug(req.params.id);
    if (!profile) return res.status(404).json({ error: 'Provider profile was not found' });
    const access = await assertProviderProfileAccess(req, profile).catch(() => null);
    const upgrade = providerUpgradeStatus();
    if (!upgrade.configured) {
      const bna = await getProjectByKey(DEFAULT_PROJECT_KEY);
      await ensureWorkspaceSetupTask({
        project: bna,
        key: 'provider-upgrade-url-placeholder',
        title: 'Configure provider upgrade interest URL',
        summary: `${profile.display_name} requested a provider upgrade, but PROVIDER_UPGRADE_URL is not configured.`,
        notes: 'Set PROVIDER_UPGRADE_URL for the provider upgrade/interest destination. Do not require payment for free signup/listing.',
        category: 'accounting',
        urgency: 'this_week',
        assigned_to: 'Shloimie',
      });
      return res.json({ success: true, configured: false, upgrade, message: 'Upgrade is not configured yet.' });
    }
    res.json({ success: true, configured: true, upgrade, url: upgrade.link, actor: access?.actor || 'unknown' });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
}

