app.get('/api/bna/identity/merge-reviews', requireAdmin, async (req, res) => {
  const status = ['open', 'resolved', 'rejected', 'archived', 'all'].includes(String(req.query.status || 'open'))
    ? String(req.query.status || 'open')
    : 'open';
  const limit = Math.max(1, Math.min(Number(req.query.limit) || 100, 250));
  try {
    const params = [limit];
    const where = status === 'all' ? '' : 'WHERE review.status = $2';
    if (status !== 'all') params.push(status);
    const reviews = (await pool.query(
      `SELECT review.*,
              person.preferred_name AS person_name,
              candidate.preferred_name AS candidate_person_name,
              household.household_name
       FROM bna_identity_merge_reviews review
       LEFT JOIN bna_people person ON person.id = review.person_id
       LEFT JOIN bna_people candidate ON candidate.id = review.candidate_person_id
       LEFT JOIN bna_households household ON household.id = review.household_id
       ${where}
       ORDER BY review.created_at DESC, review.id DESC
       LIMIT $1`,
      params
    )).rows;
    res.json({ success: true, reviews });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

