app.get('/api/bna/identity/duplicates', requireAdmin, async (req, res) => {
  const status = ['open', 'needs_decision', 'blocked', 'merged', 'rejected', 'archived', 'all'].includes(String(req.query.status || 'open'))
    ? String(req.query.status || 'open')
    : 'open';
  const limit = Math.max(1, Math.min(Number(req.query.limit) || 100, 250));
  try {
    const params = [limit];
    const where = status === 'all'
      ? ''
      : status === 'open'
        ? "WHERE review.status IN ('open', 'needs_decision', 'blocked')"
        : `WHERE review.status = $2`;
    if (!['all', 'open'].includes(status)) params.push(status);
    const reviews = (await pool.query(
      `SELECT review.*,
              target.name AS target_name,
              target.parent_email AS target_parent_email,
              target.parent_phone AS target_parent_phone,
              target.aliases AS target_aliases,
              candidate.name AS candidate_name,
              candidate.parent_email AS candidate_parent_email,
              candidate.parent_phone AS candidate_parent_phone,
              candidate.aliases AS candidate_aliases
       FROM bna_identity_review_tasks review
       LEFT JOIN bna_students target ON target.id = review.target_student_id
       LEFT JOIN bna_students candidate ON candidate.id = review.candidate_student_id
       ${where}
       ORDER BY review.created_at DESC, review.id DESC
       LIMIT $1`,
      params
    )).rows.map(studentIdentityReviewView);
    res.json({ success: true, reviews });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

