app.get('/api/bna/students/:id/identity', requireAdmin, async (req, res) => {
  try {
    await assertStudentAccess(req, req.params.id);
    const student = (await pool.query('SELECT * FROM bna_students WHERE id = $1', [req.params.id])).rows[0] || null;
    if (!student) return res.status(404).json({ error: 'Student not found' });
    const aliases = (await pool.query(
      `SELECT id, alias, normalized_alias, language, source, confidence, active, created_at, updated_at
       FROM bna_student_identity_aliases
       WHERE student_id = $1
       ORDER BY active DESC, alias ASC`,
      [student.id]
    )).rows;
    const reviews = (await pool.query(
      `SELECT review.*,
              target.name AS target_name,
              candidate.name AS candidate_name
       FROM bna_identity_review_tasks review
       LEFT JOIN bna_students target ON target.id = review.target_student_id
       LEFT JOIN bna_students candidate ON candidate.id = review.candidate_student_id
       WHERE review.target_student_id = $1
          OR review.candidate_student_id = $1
       ORDER BY review.created_at DESC
       LIMIT 50`,
      [student.id]
    )).rows.map(studentIdentityReviewView);
    const mergeEvents = (await pool.query(
      `SELECT id, target_student_id, source_student_id, review_task_id,
              confidence, evidence_json, fields_preserved, created_by, created_at
       FROM bna_student_merge_events
       WHERE target_student_id = $1 OR source_student_id = $1
       ORDER BY created_at DESC
       LIMIT 50`,
      [student.id]
    )).rows.map((event) => ({
      ...event,
      evidence_chips: evidenceLabels(event.evidence_json || {}),
    }));
    const candidates = (await findStudentIdentityCandidates(student, { excludeStudentId: student.id, limit: 25 }))
      .map((candidate) => scoreStudentIdentityCandidate(candidate, student))
      .filter((item) => item.confidence >= 40)
      .sort((a, b) => b.confidence - a.confidence)
      .map((item) => ({
        student_id: item.candidate.id,
        name: item.candidate.name,
        confidence: item.confidence,
        evidence_chips: evidenceLabels(item.evidence),
      }));
    res.json({
      success: true,
      student: {
        id: student.id,
        name: student.name,
        canonical_display_name: student.canonical_display_name,
        english_name: student.english_name || student.name_en,
        hebrew_name: student.hebrew_name || student.name_he,
        aliases: normalizeTextArray(student.aliases),
        normalized_names: normalizeTextArray(student.normalized_names),
        identity_review_status: student.identity_review_status || 'clear',
        archived_duplicate_of: student.archived_duplicate_of || null,
        source_records: normalizeStudentIdentitySourceRecords(student.source_records),
        merge_history: Array.isArray(student.merge_history) ? student.merge_history : [],
      },
      aliases,
      reviews,
      merge_events: mergeEvents,
      duplicate_candidates: candidates,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

