app.post('/api/student-portal/login', async (req, res) => {
  const username = String((req.body || {}).username || (req.body || {}).login_username || '').trim();
  const password = String((req.body || {}).password || '');
  const usernameNormalized = normalizeStudentLoginUsername(username);
  if (!username || !password) {
    await recordPersistentStudentPasswordAuthAttempt(req, usernameNormalized, {
      outcome: 'failure',
      metadata: { reason: 'missing_username_or_password' },
    });
    return res.status(400).json({ error: 'Username and password are required' });
  }

  const persistentFailureCount = await countPersistentStudentPasswordAuthFailures(req, usernameNormalized);
  if (persistentFailureCount !== null && persistentFailureCount >= STUDENT_PORTAL_AUTH_MAX_FAILURES) {
    await recordPersistentStudentPasswordAuthAttempt(req, usernameNormalized, {
      outcome: 'throttled',
      metadata: {
        reason: 'persistent_rate_limit',
        failure_count: persistentFailureCount,
      },
    });
    return res.status(429).json({ error: 'Too many failed login attempts. Please wait and try again.' });
  }

  const client = await pool.connect();
  try {
    const account = (await client.query(
      `SELECT a.student_id, a.username, a.password_hash, a.status,
              s.id, s.name, s.name_en, s.name_he, s.parent_name,
              s.parent_email, s.parent_phone, s.current_school, s.tags, s.status AS student_status
       FROM bna_student_password_accounts a
       JOIN bna_students s ON s.id = a.student_id
       WHERE a.username_normalized = $1
         AND a.status = 'active'
         AND COALESCE(s.status, 'active') NOT IN ('inactive', 'archived')
       LIMIT 1`,
      [usernameNormalized]
    )).rows[0];
    if (!account || !verifyStudentPassword(password, account.password_hash)) {
      const handled = await maybeHandleOtherPortalLogin(req, res, {
        username,
        password,
        currentPortal: 'student',
        returnTo: req.body?.returnTo || req.body?.return_to || '/student',
        source: 'student_portal_login',
        db: client,
      });
      if (handled) return;
      await recordPersistentStudentPasswordAuthAttempt(req, usernameNormalized, {
        outcome: 'failure',
        metadata: { reason: 'invalid_username_or_password' },
      });
      return res.status(401).json({ error: 'Invalid username or password' });
    }
    const sessionId = await issueStudentSession(account.student_id, client, {
      login_method: 'username_password',
      raw_password_stored: false,
    });
    await client.query(
      `UPDATE bna_student_password_accounts
       SET last_login_at = NOW(),
           updated_at = NOW()
       WHERE student_id = $1`,
      [account.student_id]
    );
    await recordPersistentStudentPasswordAuthAttempt(req, usernameNormalized, {
      outcome: 'success',
      studentId: account.student_id,
      metadata: { reason: 'valid_username_password' },
    });
    setStudentSessionCookie(res, sessionId);
    res.json({
      success: true,
      student: {
        id: account.id,
        name: account.name,
        name_en: account.name_en,
        name_he: account.name_he,
      },
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

