app.post('/api/student-portal/course-questions/:id/answer', async (req, res) => {
  const code = String((req.body || {}).access_code || (req.body || {}).accessCode || '').trim();
  const questionId = Number(req.params.id);
  const responseText = limitText((req.body || {}).response_text || (req.body || {}).answer || (req.body || {}).response || '', 5000);
  if (!Number.isFinite(questionId)) return res.status(404).json({ error: 'Question was not found' });
  if (!responseText) return res.status(400).json({ error: 'response_text is required' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const student = await getStudentForPortalCredential(req, res, code, client);
    if (!student) {
      await client.query('ROLLBACK');
      return;
    }
    const question = (await client.query(
      `SELECT q.*, c.project_key
       FROM bna_course_questions q
       JOIN bna_courses c ON c.id = q.course_id
       WHERE q.id = $1
         AND q.status IN ('active', 'published')
         AND q.approval_status = 'approved'
         AND q.student_visible = TRUE
         AND q.visibility IN ('student', 'student_parent', 'community', 'public')
         AND c.project_key = $2
       LIMIT 1`,
      [questionId, ONE_TIME_PROJECT_KEY]
    )).rows[0];
    if (!question) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Question was not found for this student' });
    }
    const response = (await client.query(
      `INSERT INTO bna_course_question_responses (
         question_id, student_id, response_text, status,
         parent_visible, approval_status, metadata, submitted_at
       ) VALUES (
         $1, $2, $3, 'submitted',
         FALSE, 'pending', $4::jsonb, NOW()
       )
       ON CONFLICT (question_id, student_id) DO UPDATE SET
         response_text = EXCLUDED.response_text,
         status = 'submitted',
         parent_visible = FALSE,
         approval_status = 'pending',
         metadata = COALESCE(bna_course_question_responses.metadata, '{}'::jsonb) || EXCLUDED.metadata,
         submitted_at = NOW(),
         updated_at = NOW()
       RETURNING *`,
      [
        question.id,
        student.id,
        responseText,
        JSON.stringify({ source: 'student_portal_course_question_answer' }),
      ]
    )).rows[0];
    const gamification = await createGamificationEvent({
      student_id: student.id,
      course_id: question.course_id,
      lesson_id: question.lesson_id,
      class_session_id: question.class_session_id,
      event_type: 'answer_question',
      title: `Answered ${question.title}`,
      notes: question.title,
      points: Number(question.points || 0) || undefined,
      visibility: 'student',
      parent_visible: false,
      approval_status: 'approved',
      source: 'course_question_response',
      source_ref: `bna_course_question_responses:${response.id}`,
      idempotency_key: `answer_question:student_${student.id}:course_question_response_${response.id}`,
      metadata: { question_id: question.id, response_id: response.id },
    }, client);
    await client.query('COMMIT');
    res.json({
      success: true,
      question: ws11CourseQuestionView(question),
      response: ws11CourseQuestionResponseView({
        response_id: response.id,
        question_id: response.question_id,
        response_student_id: response.student_id,
        response_text: response.response_text,
        response_status: response.status,
        response_score_percent: response.score_percent,
        response_parent_visible: response.parent_visible,
        response_approval_status: response.approval_status,
        response_submitted_at: response.submitted_at,
        response_reviewed_at: response.reviewed_at,
      }),
      gamification_event: ws11GamificationEventView(gamification),
    });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/student-portal/worksheets/:id/submit', async (req, res) => {
  const code = String((req.body || {}).access_code || (req.body || {}).accessCode || '').trim();
  const worksheetId = Number(req.params.id);
  if (!Number.isFinite(worksheetId)) return res.status(404).json({ error: 'Worksheet was not found' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const student = await getStudentForPortalCredential(req, res, code, client);
    if (!student) {
      await client.query('ROLLBACK');
      return;
    }
    const worksheet = (await client.query(
      `SELECT *
       FROM bna_worksheets
       WHERE id = $1
         AND status IN ('active', 'published')
         AND visibility IN ('student', 'student_parent', 'community', 'public')
       LIMIT 1`,
      [worksheetId]
    )).rows[0];
    if (!worksheet) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Worksheet was not found for this student' });
    }
    const answersInput = (req.body || {}).answers;
    const answers = Array.isArray(answersInput)
      ? answersInput
      : Object.entries(answersInput && typeof answersInput === 'object' ? answersInput : {}).map(([questionId, answer]) => ({ question_id: questionId, answer }));
    const submission = (await client.query(
      `INSERT INTO bna_worksheet_submissions (
         worksheet_id, student_id, assignment_student_id, status,
         answer_snapshot, parent_visible, approval_status, metadata
       ) VALUES (
         $1, $2, $3, $4,
         $5::jsonb, FALSE, 'pending', $6::jsonb
       )
       RETURNING *`,
      [
        worksheet.id,
        student.id,
        (req.body || {}).assignment_student_id || null,
        (req.body || {}).completed === true ? 'completed' : 'submitted',
        JSON.stringify(answers),
        JSON.stringify({ source: 'student_portal_worksheet_submit' }),
      ]
    )).rows[0];
    for (const answer of answers.slice(0, 100)) {
      await client.query(
        `INSERT INTO bna_worksheet_answers (
           submission_id, question_id, answer_text, answer_json, metadata
         ) VALUES ($1, $2, $3, $4::jsonb, $5::jsonb)`,
        [
          submission.id,
          Number(answer.question_id || answer.questionId) || null,
          typeof answer.answer === 'string' ? limitText(answer.answer, 4000) : limitText(answer.answer_text || '', 4000),
          JSON.stringify(answer.answer && typeof answer.answer === 'object' ? answer.answer : {}),
          JSON.stringify({ source: 'student_portal' }),
        ]
      );
    }
    const submittedEvent = await createGamificationEvent({
      student_id: student.id,
      course_id: worksheet.course_id,
      lesson_id: worksheet.lesson_id,
      worksheet_id: worksheet.id,
      worksheet_submission_id: submission.id,
      event_type: 'worksheet_submitted',
      title: `Submitted ${worksheet.title}`,
      visibility: 'student',
      parent_visible: false,
      approval_status: 'approved',
      source: 'worksheet_submission',
      source_ref: `bna_worksheet_submissions:${submission.id}`,
      idempotency_key: `worksheet_submitted:student_${student.id}:submission_${submission.id}`,
    }, client);
    let completedEvent = null;
    if (submission.status === 'completed') {
      completedEvent = await createGamificationEvent({
        student_id: student.id,
        course_id: worksheet.course_id,
        lesson_id: worksheet.lesson_id,
        worksheet_id: worksheet.id,
        worksheet_submission_id: submission.id,
        event_type: 'worksheet_completed',
        title: `Completed ${worksheet.title}`,
        visibility: 'student',
        parent_visible: false,
        approval_status: 'approved',
        source: 'worksheet_submission',
        source_ref: `bna_worksheet_submissions:${submission.id}`,
        idempotency_key: `worksheet_completed:student_${student.id}:submission_${submission.id}`,
      }, client);
    }
    await client.query('COMMIT');
    res.json({
      success: true,
      submission,
      gamification_events: [submittedEvent, completedEvent].filter(Boolean).map(ws11GamificationEventView),
    });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/parent-portal/login', async (req, res) => {
  const parentIdentity = String((req.body || {}).parent_email || (req.body || {}).email || (req.body || {}).username || '').trim();
  const parentEmail = normalizeEmail(parentIdentity);
  const password = String((req.body || {}).password || '');
  if (!parentEmail || !password) {
    if (parentIdentity && password) {
      const handled = await maybeHandleOtherPortalLogin(req, res, {
        username: parentIdentity,
        password,
        currentPortal: 'parent',
        returnTo: req.body?.returnTo || req.body?.return_to || '/parent',
        source: 'parent_portal_login',
      });
      if (handled) return;
    }
    return res.status(400).json({ error: 'Parent email or username and password are required' });
  }

  const client = await pool.connect();
  try {
    const account = (await client.query(
      `SELECT parent_email, password_hash
       FROM bna_parent_password_accounts
       WHERE lower(parent_email) = $1
       LIMIT 1`,
      [parentEmail]
    )).rows[0];
    if (!account || !verifyParentPassword(password, account.password_hash)) {
      const handled = await maybeHandleOtherPortalLogin(req, res, {
        username: parentIdentity,
        password,
        currentPortal: 'parent',
        returnTo: req.body?.returnTo || req.body?.return_to || '/parent',
        source: 'parent_portal_login',
        db: client,
      });
      if (handled) return;
      return res.status(401).json({ error: 'Invalid email or password' });
    }
    const records = await findParentAccessRecords(parentEmail, client);
    if (!parentAccessEligible(records)) {
      return res.status(404).json({ error: 'No active student or signup is linked to this parent email' });
    }
    const sessionId = await issueParentSession(parentEmail, client);
    await client.query(
      `UPDATE bna_parent_password_accounts
       SET last_login_at = NOW(),
           updated_at = NOW()
       WHERE lower(parent_email) = $1`,
      [parentEmail]
    );
    await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, signup_id, student_id, channel, direction,
         summary, body, follow_up_required, occurred_at, created_by, source, metadata
       ) VALUES (
         COALESCE($1, 'general'), $2, $3, 'other', 'inbound',
         'Parent portal login', $4, FALSE, NOW(), 'parent_portal', 'dashboard', $5
       )`,
      [
        records.signups[0]?.id ? 'signup' : records.students[0]?.id ? 'student' : 'general',
        records.signups[0]?.id || null,
        records.students[0]?.id || null,
        `Parent ${parentEmail} logged into the parent portal with email/password.`,
        JSON.stringify({ parent_email: parentEmail, login_method: 'password' }),
      ]
    ).catch(() => {});
    setParentSessionCookie(res, sessionId);
    res.json({ success: true });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

