app.get('/api/bna/auth/me', async (req, res) => {
  try {
    const viewAsAuth = applyOneTimeViewAsRabbiRequest(req, res);
    if (viewAsAuth.handled) {
      if (viewAsAuth.authenticated) {
        return res.json(await buildBnaIdentityPayload({ identity: viewAsAuth.identity, req, actor: 'admin' }));
      }
      return;
    }
    const opsIdentity = await identifyOpsAssistantRequest(req).catch(() => null);
    if (opsIdentity) {
      return res.json(await buildBnaIdentityPayload({ identity: opsIdentity, req, actor: 'admin' }));
    }
    const cookies = parseCookies(req);
    const parentSession = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME]).catch(() => null);
    if (parentSession) {
      const household = await parentIdentityContextFromSession(parentSession).catch(() => null);
      return res.json({
        success: true,
        authenticated: true,
        role: 'parent',
        email: parentSession.parentEmail,
        person: household?.parent_person ? canonicalPersonView(household.parent_person) : null,
        activeWorkspace: household?.workspace ? workspaceProjectView(household.workspace) : null,
        active_workspace: household?.workspace ? workspaceProjectView(household.workspace) : null,
        household: household?.household ? householdView(household.household, household.members || []) : null,
        memberships: household?.memberships || [],
        allowedViews: ['overview', 'children', 'goals', 'attendance', 'providers', 'setup', 'assistant'],
      });
    }
    const providerSession = await getValidProviderSession(cookies[PROVIDER_SESSION_COOKIE_NAME]).catch(() => null);
    if (providerSession) {
      return res.json({
        success: true,
        authenticated: true,
        role: 'service_provider',
        provider_id: providerSession.providerId,
        provider_name: providerSession.providerName || null,
        allowedViews: ['overview', 'profile', 'services', 'media', 'comments', 'communications', 'google_business', 'upgrade'],
      });
    }
    res.json({ success: false, authenticated: false });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/parent-portal/session', async (req, res) => {
  const token = String(req.query.token || '').trim();
  if (!token) return res.status(400).json({ error: 'Magic link token is required' });
  const tokenHash = sha256Hex(token);
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const link = (await client.query(
      `UPDATE bna_parent_magic_links
       SET used_at = NOW()
       WHERE token_hash = $1
         AND used_at IS NULL
         AND expires_at > NOW()
       RETURNING id, parent_email`,
      [tokenHash]
    )).rows[0];
    if (!link) {
      await client.query('ROLLBACK');
      return res.status(401).json({ error: 'This parent link is invalid or expired' });
    }

    const sessionId = await issueParentSession(link.parent_email, client);
    const records = await findParentAccessRecords(link.parent_email, client);
    await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, signup_id, student_id, channel, direction,
         summary, body, follow_up_required, occurred_at, created_by, source, metadata
       ) VALUES (
         COALESCE($1, 'general'), $2, $3, 'other', 'inbound',
         'Parent portal login', $4, FALSE, NOW(), 'parent_portal', 'dashboard', $5
       )`,
      [
        records.signups[0]?.id ? 'signup' : records.students[0]?.id ? 'student' : 'general',
        records.signups[0]?.id || null,
        records.students[0]?.id || null,
        `Parent ${normalizeEmail(link.parent_email)} opened the parent portal.`,
        JSON.stringify({ parent_email: normalizeEmail(link.parent_email), link_id: link.id }),
      ]
    ).catch(() => {});
    await client.query('COMMIT');
    setParentSessionCookie(res, sessionId);
    res.json({ success: true });
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch {
      // Ignore rollback failures.
    }
    res.status(500).json({ error: err.message });
  } finally {
    client.release();
  }
});

