app.get('/api/parent-portal/students/:studentId/ws11-progress', async (req, res) => {
  const cookies = parseCookies(req);
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME]);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });
    const studentId = Number(req.params.studentId);
    if (!Number.isFinite(studentId)) return res.status(404).json({ error: 'Student was not found for this parent' });
    const records = await findParentAccessRecords(session.parentEmail);
    const links = await ensureParentStudentLinksForRecords(records);
    const explicitLinks = (await pool.query(
      `SELECT *
       FROM bna_parent_student_links
       WHERE status = 'active'
         AND (
           ($1::text <> '' AND lower(parent_email) = $1)
           OR ($2::int IS NOT NULL AND parent_account_id = $2)
         )`,
      [normalizeEmail(session.parentEmail) || '', session.parentAccountId || null]
    )).rows;
    const accessContext = { links: [...links, ...explicitLinks] };
    if (!parentCanAccessStudent(accessContext, studentId)) {
      return res.status(404).json({ error: 'Student was not found for this parent' });
    }
    res.json({
      success: true,
      ws11: await getWs11StudentProgress(studentId, {
        audience: 'parent',
        parentEmail: session.parentEmail,
      }),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

async function getParentPortalScopedWs11(req, db = pool) {
  const cookies = parseCookies(req);
  const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], db);
  if (!session) {
    const error = new Error('Parent session is required');
    error.statusCode = 401;
    throw error;
  }
  const studentId = Number(req.params.studentId);
  if (!Number.isFinite(studentId)) {
    const error = new Error('Student was not found for this parent');
    error.statusCode = 404;
    throw error;
  }
  const records = await findParentAccessRecords(session.parentEmail, db);
  const links = await ensureParentStudentLinksForRecords(records, db);
  const explicitLinks = (await db.query(
    `SELECT *
     FROM bna_parent_student_links
     WHERE status = 'active'
       AND (
         ($1::text <> '' AND lower(parent_email) = $1)
         OR ($2::int IS NOT NULL AND parent_account_id = $2)
       )`,
    [normalizeEmail(session.parentEmail) || '', session.parentAccountId || null]
  )).rows;
  const accessContext = { links: [...links, ...explicitLinks] };
  if (!parentCanAccessStudent(accessContext, studentId)) {
    const error = new Error('Student was not found for this parent');
    error.statusCode = 404;
    throw error;
  }
  const ws11 = await getWs11StudentProgress(studentId, {
    audience: 'parent',
    parentEmail: session.parentEmail,
  }, db);
  return { session, studentId, ws11 };
}

function parentPortalCommunityProgressView(studentId, ws11 = {}) {
  const summary = ws11.parent_progress?.summary || {};
  const byType = ws11.gamification?.summary?.by_type || {};
  const events = Array.isArray(ws11.gamification?.events) ? ws11.gamification.events : [];
  const worksheets = Array.isArray(ws11.worksheet_submissions) ? ws11.worksheet_submissions : [];
  const questions = Array.isArray(ws11.course_questions) ? ws11.course_questions : [];
  const shoutouts = Array.isArray(ws11.shoutouts) ? ws11.shoutouts : [];
  const recentWins = [...events, ...shoutouts]
    .sort((a, b) => Date.parse(b.occurred_at || b.approved_at || b.created_at || 0) - Date.parse(a.occurred_at || a.approved_at || a.created_at || 0))
    .slice(0, 12);
  return {
    student: {
      id: studentId,
      name: summary.student_name || '',
    },
    community: {
      title: ws11.community?.name || 'Rabbi Mishnah Learning Community',
      short_name: ws11.community?.short_name || 'Mishnah Community',
      primary_teacher: ws11.community?.primary_teacher || 'Rabbi Elie Scheller',
    },
    summary: {
      points: Number(summary.total_points || ws11.gamification?.summary?.total_points || 0),
      answered_questions: Number(byType.answer_question || 0),
      asked_questions: Number(byType.ask_question || 0),
      worksheets_submitted: Number(byType.worksheet_submitted || 0),
      worksheets_completed: Number(byType.worksheet_completed || 0),
      attendance_events: Number(byType.class_attended || 0),
      participation_events: Number(byType.referenced_in_class || 0),
      approved_shoutouts: shoutouts.length,
      current_streak: Number(byType.streak_continued || 0),
    },
    recent_wins: recentWins,
    worksheets,
    questions,
    shoutouts,
  };
}

