function parentContextChildren(context = {}) {
  return (context.members || []).filter((member) => member.role === 'child' && member.person?.id);
}

function findParentContextChild(context = {}, rawNameOrId = '') {
  const value = String(rawNameOrId || '').trim();
  if (!value) return { child: null, ambiguous: false, matches: [] };
  const children = parentContextChildren(context);
  const numeric = Number(value);
  const matches = Number.isFinite(numeric)
    ? children.filter((child) => Number(child.person_id || child.person?.id) === numeric)
    : children.filter((child) => {
      const name = `${child.person?.preferred_name || ''} ${child.person?.full_name || ''}`;
      const key = normalizePersonNameKey(name);
      const wanted = normalizePersonNameKey(value);
      return key === wanted || (wanted.length >= 3 && key.includes(wanted));
    });
  return { child: matches.length === 1 ? matches[0] : null, ambiguous: matches.length > 1, matches };
}

function parseParentAssistantAction(text = '', context = {}) {
  const raw = limitText(text, 2000);
  const normalized = raw.toLowerCase();
  const children = parentContextChildren(context);
  const childMatches = children.filter((child) => {
    const name = String(child.person?.preferred_name || child.person?.full_name || '').toLowerCase();
    return name && normalized.includes(name.toLowerCase());
  });
  const section = /diet/.test(normalized)
    ? 'diet'
    : /attendance|present|absent/.test(normalized)
      ? 'attendance'
      : /assignment|homework/.test(normalized)
        ? 'assignments'
        : /behavior|middos|middot/.test(normalized)
          ? 'behavior'
          : /torah|learning|mishn|gemara|chumash/.test(normalized)
            ? 'torah_learning'
            : /chore/.test(normalized)
              ? 'chores'
              : /goal/.test(normalized)
                ? 'goals'
                : slugifySectionKey((raw.match(/(?:create|add)\s+(?:a\s+)?([a-zA-Z ]+?)\s+section/i) || [])[1] || 'goals');
  const titleMatch = raw.match(/\bto\s+(.+?)(?:\.|$)/i);
  const title = titleMatch?.[1]
    ? titleMatch[1]
    : /attendance|present/.test(normalized)
      ? 'Attendance present today'
      : /diet/.test(normalized)
        ? 'Diet note'
        : /chore/.test(normalized)
          ? 'Chore'
          : raw.replace(/^(add|create|mark)\s+/i, '').slice(0, 180);
  if (childMatches.length !== 1) {
    return {
      ok: false,
      needs_review: true,
      reason: childMatches.length > 1 ? 'ambiguous_child_match' : 'missing_child_match',
      actions: [],
      matches: childMatches.map((child) => ({ person_id: child.person_id || child.person?.id, name: child.person?.preferred_name })),
      raw_text: raw,
    };
  }
  return {
    ok: true,
    actions: [{
      type: 'create_accountability_item',
      section_key: section,
      child_person_id: childMatches[0].person_id || childMatches[0].person?.id,
      child_name: childMatches[0].person?.preferred_name || childMatches[0].person?.full_name,
      title: limitText(title || raw, 240),
      details: raw,
      status: /mark|present|done|completed/.test(normalized) ? 'done' : 'open',
    }],
    raw_text: raw,
  };
}

