app.get('/api/parent/children/:personId/overview', async (req, res) => {
  try {
    const context = await requireParentIdentityContext(req);
    const match = findParentContextChild(context, req.params.personId);
    if (!match.child) return res.status(match.ambiguous ? 409 : 404).json({ error: match.ambiguous ? 'Child match is ambiguous' : 'Child not found in this household' });
    const personId = Number(match.child.person_id || match.child.person?.id);
    const students = (await pool.query(
      `SELECT id, name, grade, status, project_id
       FROM bna_students
       WHERE person_id = $1
          OR (household_id = $2 AND trim(regexp_replace(lower(regexp_replace(COALESCE(name, ''), '[^a-zA-Z0-9\u0590-\u05ff]+', ' ', 'g')), '\\s+', ' ', 'g')) = $3)
       ORDER BY id ASC`,
      [personId, context.household.id, normalizePersonNameKey(match.child.person?.preferred_name || '')]
    )).rows;
    const items = (await pool.query(
      `SELECT item.*, section.label AS section_label
       FROM bna_accountability_items item
       LEFT JOIN bna_accountability_sections section ON section.id = item.section_id
       WHERE item.household_id = $1
         AND item.person_id = $2
         AND item.parent_visible = TRUE
         AND item.status <> 'archived'
       ORDER BY item.created_at DESC
       LIMIT 100`,
      [context.household.id, personId]
    )).rows;
    res.json({ success: true, child: match.child, students, accountability_items: items });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.get('/api/parent/accountability', async (req, res) => {
  try {
    const context = await requireParentIdentityContext(req);
    const childIds = parentContextChildren(context).map((child) => Number(child.person_id || child.person?.id)).filter(Boolean);
    await ensureDefaultAccountabilitySections({ household_id: context.household.id, workspace_id: context.workspace?.id || null });
    const sections = (await pool.query(
      `SELECT *
       FROM bna_accountability_sections
       WHERE household_id = $1
         AND status = 'active'
       ORDER BY sort_order ASC, label ASC`,
      [context.household.id]
    )).rows;
    const items = (await pool.query(
      `SELECT item.*, section.label AS section_label
       FROM bna_accountability_items item
       LEFT JOIN bna_accountability_sections section ON section.id = item.section_id
       WHERE item.household_id = $1
         AND item.parent_visible = TRUE
         AND item.status <> 'archived'
       ORDER BY item.created_at DESC
       LIMIT 200`,
      [context.household.id]
    )).rows;
    const legacyEvents = childIds.length ? (await pool.query(
      `SELECT id, student_id, person_id, household_id, event_type, topic, notes AS details, occurred_at, section_key
       FROM bna_accountability_events
       WHERE (
           household_id = $1
           OR person_id = ANY($2::int[])
         )
         AND COALESCE(metadata->>'parent_visible', 'true') <> 'false'
       ORDER BY occurred_at DESC, id DESC
       LIMIT 100`,
      [context.household.id, childIds]
    )).rows : [];
    res.json({ success: true, sections, items, legacy_events: legacyEvents });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

