app.patch('/api/parent/accountability/items/:id', async (req, res) => {
  try {
    const context = await requireParentIdentityContext(req);
    const allowed = ['title', 'details', 'status', 'priority', 'due_date'];
    const updates = [];
    const values = [];
    for (const key of allowed) {
      if (!Object.prototype.hasOwnProperty.call(req.body || {}, key)) continue;
      values.push(key === 'title' ? limitText(req.body[key], 260) : key === 'details' ? limitText(req.body[key], 2000) : req.body[key]);
      updates.push(`${key} = $${values.length}`);
    }
    if (!updates.length) return res.status(400).json({ error: 'No supported fields supplied' });
    values.push(req.params.id, context.household.id);
    const item = (await pool.query(
      `UPDATE bna_accountability_items
       SET ${updates.join(', ')}, updated_at = NOW()
       WHERE id = $${values.length - 1}
         AND household_id = $${values.length}
       RETURNING *`,
      values
    )).rows[0];
    if (!item) return res.status(404).json({ error: 'Accountability item not found in this household' });
    res.json({ success: true, item });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

