app.post('/api/parent/assistant', async (req, res) => {
  try {
    const context = await requireParentIdentityContext(req);
    const parsed = parseParentAssistantAction((req.body || {}).message || (req.body || {}).text || '', context);
    if (!parsed.ok) {
      if ((req.body || {}).apply) {
        await createMergeReview({
          review_type: 'parent_assistant_ambiguous_action',
          household_id: context.household.id,
          reason: parsed.reason,
          signals: parsed,
          metadata: { source: 'parent_assistant' },
        });
      }
      return res.json({ success: true, applied: false, ...parsed });
    }
    if (!(req.body || {}).apply) return res.json({ success: true, applied: false, ...parsed });
    const applied = [];
    for (const action of parsed.actions) {
      const section = await ensureAccountabilitySection({
        household_id: context.household.id,
        workspace_id: context.workspace?.id || null,
        section_key: action.section_key,
        metadata: { source: 'parent_assistant' },
      });
      applied.push(await createAccountabilityItem({
        household_id: context.household.id,
        person_id: action.child_person_id,
        section_id: section.id,
        section_key: section.section_key,
        title: action.title,
        details: action.details,
        status: action.status,
        parent_visible: true,
        metadata: { source: 'parent_assistant', parsed_action: action },
      }));
    }
    res.json({ success: true, applied: true, actions: parsed.actions, items: applied });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

