app.post('/api/parent-portal/help', async (req, res) => {
  const cookies = parseCookies(req);
  const body = req.body || {};
  const message = String(body.message || body.body || '').trim();
  const category = parentHelpCategory(body.category || body.topic);
  const studentId = body.student_id ? Number(body.student_id) : null;
  const sourceRoute = limitText(body.route || body.path || '', 300);
  const sourceViewport = body.viewport && typeof body.viewport === 'object'
    ? {
        width: Number(body.viewport.width || 0) || null,
        height: Number(body.viewport.height || 0) || null,
        device_scale_factor: Number(body.viewport.deviceScaleFactor || body.viewport.device_scale_factor || 0) || null,
      }
    : {};
  const sourceLanguage = body.language ? normalizeLanguage(body.language) : '';
  if (!message) return res.status(400).json({ error: 'Help message is required' });
  if (message.length > 3000) return res.status(400).json({ error: 'Help message is too long' });

  const client = await pool.connect();
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], client);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });
    const records = await findParentAccessRecords(session.parentEmail, client);
    let student = null;
    if (studentId) {
      student = await getParentPortalStudentForSession(session.parentEmail, studentId, client);
      if (!student) return res.status(404).json({ error: 'Student was not found for this parent session' });
    }
    const tags = parentInteractionTags('portal_help', category, message);
    const summary = `${category === 'problem' ? 'Parent problem report' : category === 'technology' ? 'Parent technology help' : 'Parent help'}: ${records.students[0]?.parent_name || session.parentEmail}`;
    const sourceContext = {
      source: 'parent_portal_help',
      category,
      student_id: student?.id || null,
      route: sourceRoute || null,
      viewport: sourceViewport,
      language: sourceLanguage || null,
    };
    const communication = (await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, signup_id, student_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, source_context, metadata
       ) VALUES (
         $1, $2, $3, 'email', 'inbound', $4, $5,
         TRUE, NOW(), 'parent_portal', 'dashboard', $6, $7
       )
       RETURNING *`,
      [
        student ? 'student' : records.signups[0]?.id ? 'signup' : 'general',
        records.signups[0]?.id || null,
        student?.id || records.students[0]?.id || null,
        summary,
        message,
        JSON.stringify(sourceContext),
        JSON.stringify({
          parent_email: session.parentEmail,
          category,
          internal_tags: tags,
          student_id: student?.id || null,
          route: sourceRoute || null,
          viewport: sourceViewport,
          language: sourceLanguage || null,
        }),
      ]
    )).rows[0];

    await mergeParentRecordTags(session.parentEmail, tags, client);
    if (category === 'problem') {
      const bnaProject = await upsertProject({
        projectKey: DEFAULT_PROJECT_KEY,
        name: 'BNA',
        shortName: 'BNA',
        description: 'Bnei Neviim Academy operations, students, content, contacts, and accounting.',
      }, client);
      const ticketTitle = limitText(`Parent report problem: ${records.students[0]?.parent_name || session.parentEmail}`, 180);
      const ticket = (await client.query(
        `INSERT INTO bna_support_tickets (
           project_id, title, description, severity, status, category,
           reporter_name, reporter_role, assigned_to, source, source_context, created_by
         )
         VALUES ($1, $2, $3, 'normal', 'open', 'other', $4, 'parent', 'Shloimie', 'dashboard', $5::jsonb, 'parent_portal')
        RETURNING *`,
        [
          bnaProject.id,
          ticketTitle,
          message,
          records.students[0]?.parent_name || session.parentEmail,
          JSON.stringify({
            ...sourceContext,
            parent_email: session.parentEmail,
            communication_id: communication.id,
            internal_tags: tags,
            classification: 'parent_report_problem_review_ticket',
            codex_task_created: false,
          }),
        ]
      )).rows[0];

      let emailSent = false;
      let emailError = '';
      if (PARENT_HELP_EMAIL) {
        const emailText = [
          'Parent portal problem report',
          '',
          `Parent: ${session.parentEmail}`,
          student ? `Student: ${student.name}` : '',
          `Category: ${category}`,
          sourceRoute ? `Route: ${sourceRoute}` : '',
          `Communication: #${communication.id}`,
          `Support ticket: #${ticket.id}`,
          '',
          message,
        ].filter(Boolean).join('\n');
        const result = await sendEmail({
          to: PARENT_HELP_EMAIL,
          subject: 'BNA parent problem report',
          text: emailText,
          html: emailText.replace(/\n/g, '<br>'),
        }).then(async (mailResult) => {
          await logEmail({
            emailType: 'parent_problem_report',
            to: PARENT_HELP_EMAIL,
            subject: 'BNA parent problem report',
            text: emailText,
            html: emailText.replace(/\n/g, '<br>'),
            providerMessageId: mailResult.data?.id || null,
            provider: mailResult.provider,
            metadata: { communication_id: communication.id, support_ticket_id: ticket.id },
          });
          return { ok: true, id: mailResult.data?.id || '' };
        })
          .catch((error) => ({ ok: false, error: error instanceof Error ? error.message : String(error) }));
        emailSent = Boolean(result.ok);
        emailError = result.error || '';
      }

      return res.json({
        success: true,
        message: 'Problem report saved for review.',
        communication_id: communication.id,
        support_ticket_id: ticket.id,
        task_id: null,
        codex_task_created: false,
        email_sent: emailSent,
        email_error: emailError,
        tags,
      });
    }
    const task = await createTaskFromText({
      title: `${category === 'technology' ? 'Parent technology help' : 'Parent help'}: ${records.students[0]?.parent_name || session.parentEmail}`,
      raw_text: message,
      notes: [
        `Parent: ${session.parentEmail}`,
        student ? `Student: ${student.name}` : '',
        `Category: ${category}`,
        `Communication #${communication.id}`,
        '',
        message,
      ].filter(Boolean).join('\n'),
      stage: 'assigned',
      category: parentHelpTaskCategory(category),
      urgency: category === 'technology' || category === 'access' ? 'today' : 'this_week',
      assigned_to: 'Shloimie',
      source: 'web',
      created_by: 'parent_portal',
      source_context: {
        parent_email: session.parentEmail,
        student_id: student?.id || null,
        communication_id: communication.id,
        route: sourceRoute || null,
        viewport: sourceViewport,
        language: sourceLanguage || null,
        internal_tags: tags,
      },
      ai_parsed: {
        parser: 'parent-portal-help-v1',
        kind: 'parent_help',
        category,
        internal_tags: tags,
      },
    }, {}, client);

    let emailSent = false;
    let emailError = '';
    if (PARENT_HELP_EMAIL) {
      const emailText = [
        'Parent portal help request',
        '',
        `Parent: ${session.parentEmail}`,
        student ? `Student: ${student.name}` : '',
        `Category: ${category}`,
        `Communication: #${communication.id}`,
        `Task: #${task.id}`,
        '',
        message,
      ].filter(Boolean).join('\n');
      const result = await sendEmail({
        to: PARENT_HELP_EMAIL,
        subject: `BNA parent help: ${category}`,
        text: emailText,
        html: emailText.replace(/\n/g, '<br>'),
      }).then(async (mailResult) => {
        await logEmail({
          emailType: 'parent_help_request',
          to: PARENT_HELP_EMAIL,
          subject: `BNA parent help: ${category}`,
          text: emailText,
          html: emailText.replace(/\n/g, '<br>'),
          providerMessageId: mailResult.data?.id || null,
          provider: mailResult.provider,
          metadata: { communication_id: communication.id, task_id: task.id },
        });
        return { ok: true, id: mailResult.data?.id || '' };
      })
        .catch((error) => ({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      emailSent = Boolean(result.ok);
      emailError = result.error || '';
    }

    res.json({
      success: true,
      message: 'Help request sent.',
      communication_id: communication.id,
      task_id: task.id,
      email_sent: emailSent,
      email_error: emailError,
      tags,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/parent-accountability/onboarding', async (req, res) => {
  const body = req.body || {};
  const parentName = limitText(body.parent_name || body.parentName || body.name, 160);
  const parentEmail = normalizeEmail(body.parent_email || body.parentEmail || body.email);
  const parentPhone = limitText(body.parent_phone || body.parentPhone || body.phone || body.whatsapp, 80);
  const childName = limitText(body.child_name || body.childName || body.student_name || body.studentName, 160);
  const childAge = limitText(body.child_age || body.childAge || body.age, 80);
  const childAgeNumber = /^\d{1,2}$/.test(childAge) ? Number(childAge) : null;
  const childStruggles = limitText(body.child_struggles || body.childStruggles || body.struggles, 1200);
  const goals = limitText(body.goals || body.child_goals || body.childGoals, 1200);
  const importantToChild = limitText(body.important_to_child || body.importantToChild || body.motivators, 1200);
  const chores = limitText(body.chores || body.responsibilities, 1200);
  const mealPreferences = limitText(body.meal_preferences || body.mealPreferences || body.food_preferences || body.foodPreferences, 1200);
  const recordingContext = limitText(body.recording_context || body.recordingContext || body.recordings, 1200);
  const setupContext = limitText(body.setup_context || body.setupContext || body.setup, 1200);
  const rawIntake = limitText(body.raw_intake || body.rawIntake || body.intake_text || body.intakeText, 4000);
  const language = normalizeLanguage(body.language || '') || 'en';
  const sourceRoute = limitText(body.route || body.path || '', 300);
  const sourceViewport = body.viewport && typeof body.viewport === 'object'
    ? {
        width: Number(body.viewport.width || 0) || null,
        height: Number(body.viewport.height || 0) || null,
        device_scale_factor: Number(body.viewport.deviceScaleFactor || body.viewport.device_scale_factor || 0) || null,
      }
    : {};

  const description = limitText([
    'Parent accountability setup request from public conversational onboarding.',
    parentName ? `Parent name: ${parentName}` : '',
    parentEmail ? `Parent email: ${parentEmail}` : '',
    parentPhone ? `Parent phone/WhatsApp: ${parentPhone}` : '',
    childName ? `Child: ${childName}` : '',
    childAge ? `Child age/stage: ${childAge}` : '',
    childStruggles ? `What the child is struggling with: ${childStruggles}` : '',
    goals ? `Goals: ${goals}` : '',
    importantToChild ? `Important motivators/interests: ${importantToChild}` : '',
    chores ? `Chores/responsibilities: ${chores}` : '',
    mealPreferences ? `Meal/eating preferences: ${mealPreferences}` : '',
    recordingContext ? `Recording/upload context: ${recordingContext}` : '',
    setupContext ? `Setup context: ${setupContext}` : '',
    rawIntake ? `Raw intake:\n${rawIntake}` : '',
  ].filter(Boolean).join('\n'), 4000);

  if (!description || (!parentName && !parentEmail && !childName && !rawIntake)) {
    return res.status(400).json({ error: 'Parent name, email, child name, or intake details are required' });
  }

  if (body.dry_run === true || body.dryRun === true || String(body.dry_run || '').toLowerCase() === 'true') {
    return res.json({
      success: true,
      dry_run: true,
      local_write_performed: false,
      message: 'Parent accountability setup preview ready. No lead, ticket, communication, notification, send, or child-visible goal was created.',
      planned_records: [
        'bna_parent_leads accountability_interest',
        'bna_support_tickets student_parent_data',
        'bna_contact_communications lead inbound note',
        'bna_in_app_notifications parent_accountability_lead_submitted',
      ],
      preview: {
        lead_type: 'accountability_interest',
        status: 'new',
        interest_level: 'warm',
        source: 'website_form',
        parent_name: parentName || null,
        parent_email_present: Boolean(parentEmail),
        parent_phone_present: Boolean(parentPhone),
        child_name: childName || null,
        child_age_text: childAge || null,
        review_before_child_visibility: true,
        no_send: true,
        external_write_performed: false,
      },
    });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const bnaProject = await upsertProject({
      projectKey: DEFAULT_PROJECT_KEY,
      name: 'BNA',
      shortName: 'BNA',
      description: 'Bnei Neviim Academy operations, students, content, contacts, and accounting.',
    }, client);
    const sourceContext = {
      source: 'parent_accountability_onboarding',
      route: sourceRoute || null,
      viewport: sourceViewport,
      language,
      parent_email: parentEmail || null,
      parent_phone_present: Boolean(parentPhone),
      parent_name: parentName || null,
      child_name: childName || null,
      review_before_student_visibility: true,
      self_governance_onboarding: true,
    };
    const title = limitText(`Parent accountability setup: ${childName || parentName || parentEmail || 'new family'}`, 180);
    const leadTags = [
      'accountability-interest',
      'parent-accountability-onboarding',
      'self-governance-setup',
      'needs-review',
    ];
    const leadMetadata = {
      ...sourceContext,
      child_age_text: childAge || null,
      child_struggles: childStruggles || null,
      goals: goals || null,
      important_to_child: importantToChild || null,
      chores: chores || null,
      meal_preferences: mealPreferences || null,
      recording_context: recordingContext || null,
      setup_context: setupContext || null,
      no_send: true,
      external_write_performed: false,
      review_before_child_visibility: true,
    };
    const leadDisplayName = parentName || parentEmail || 'Parent accountability lead';
    const existingLead = parentEmail
      ? (await client.query(
        `SELECT id
         FROM bna_parent_leads
         WHERE project_id = $1
           AND lower(COALESCE(parent_email, '')) = lower($2)
           AND COALESCE(status, 'interested') <> 'archived'
         ORDER BY updated_at DESC NULLS LAST, created_at DESC
         LIMIT 1`,
        [bnaProject.id, parentEmail]
      )).rows[0]
      : parentName
        ? (await client.query(
          `SELECT id
           FROM bna_parent_leads
           WHERE project_id = $1
             AND lower(COALESCE(parent_name, '')) = lower($2)
             AND COALESCE(status, 'interested') <> 'archived'
           ORDER BY updated_at DESC NULLS LAST, created_at DESC
           LIMIT 1`,
          [bnaProject.id, parentName]
        )).rows[0]
        : null;
    const lead = existingLead
      ? (await client.query(
        `UPDATE bna_parent_leads
         SET parent_name = COALESCE(NULLIF($2, ''), parent_name),
             parent_phone = COALESCE(NULLIF(parent_phone, ''), NULLIF($3, ''), parent_phone),
             parent_email = COALESCE(NULLIF(parent_email, ''), NULLIF($4, ''), parent_email),
             student_name = COALESCE(NULLIF($5, ''), student_name),
             student_age = COALESCE($6, student_age),
             lead_type = 'accountability_interest',
             status = CASE
               WHEN COALESCE(status, 'new') IN ('new', 'lead_candidate', 'interested') THEN 'follow_up'
               ELSE status
             END,
             interest_level = CASE
               WHEN COALESCE(interest_level, 'unknown') = 'unknown' THEN 'warm'
               ELSE interest_level
             END,
             source = COALESCE(source, 'website_form'),
             source_detail = COALESCE(source_detail, 'Parent accountability app onboarding'),
             last_inbound_at = NOW(),
             owner = COALESCE(owner, 'Shloimie'),
             tags = (
               SELECT ARRAY(
                 SELECT DISTINCT tag_value
                 FROM unnest(COALESCE(tags, '{}'::text[]) || $7::text[]) AS tag_values(tag_value)
                 WHERE trim(tag_value) <> ''
               )
             ),
             notes = COALESCE(NULLIF($8, ''), notes),
             metadata = COALESCE(metadata, '{}'::jsonb) || $9::jsonb,
             updated_at = NOW()
         WHERE id = $1
         RETURNING *`,
        [
          existingLead.id,
          leadDisplayName,
          parentPhone || '',
          parentEmail || '',
          childName || '',
          childAgeNumber,
          leadTags,
          description,
          JSON.stringify({ ...leadMetadata, duplicate_guard: parentEmail ? 'email' : 'name' }),
        ]
      )).rows[0]
      : (await client.query(
        `INSERT INTO bna_parent_leads (
           project_id, parent_name, parent_phone, parent_email, student_name,
           student_age, lead_type, status, interest_level, source, source_detail,
           last_inbound_at, next_follow_up_date, owner, tags, notes, metadata
         ) VALUES (
           $1, $2, $3, $4, $5,
           $6, 'accountability_interest', 'new', 'warm', 'website_form',
           'Parent accountability app onboarding', NOW(), CURRENT_DATE + INTERVAL '2 days',
           'Shloimie', $7::text[], $8, $9::jsonb
         )
         RETURNING *`,
        [
          bnaProject.id,
          leadDisplayName,
          parentPhone || null,
          parentEmail || null,
          childName || null,
          childAgeNumber,
          leadTags,
          description,
          JSON.stringify(leadMetadata),
        ]
      )).rows[0];
    const ticket = (await client.query(
      `INSERT INTO bna_support_tickets (
         project_id, title, description, severity, status, category,
         reporter_name, reporter_role, assigned_to, source, source_context, created_by
       )
       VALUES ($1, $2, $3, 'normal', 'open', 'student_parent_data',
         $4, 'parent', 'Shloimie', 'api', $5::jsonb, 'parent_onboarding')
       RETURNING *`,
      [
        bnaProject.id,
        title,
        description,
        parentName || parentEmail || 'Parent onboarding',
        JSON.stringify({ ...sourceContext, parent_lead_id: lead.id }),
      ]
    )).rows[0];

    const communication = (await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, lead_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, source_context, metadata
       ) VALUES (
         'lead', $1, $2, 'inbound', $3, $4,
         TRUE, NOW(), 'parent_onboarding', 'dashboard', $5::jsonb, $6::jsonb
       )
       RETURNING *`,
      [
        lead.id,
        parentEmail ? 'email' : parentPhone ? 'whatsapp' : 'internal_note',
        title,
        description,
        JSON.stringify({ ...sourceContext, support_ticket_id: ticket.id, parent_lead_id: lead.id }),
        JSON.stringify({
          parent_email: parentEmail || null,
          parent_phone_present: Boolean(parentPhone),
          parent_name: parentName || null,
          child_name: childName || null,
          child_age: childAge || null,
          child_struggles: childStruggles || null,
          goals: goals || null,
          important_to_child: importantToChild || null,
          chores: chores || null,
          meal_preferences: mealPreferences || null,
          recording_context: recordingContext || null,
          setup_context: setupContext || null,
          internal_tags: ['parent_accountability_onboarding', 'self_governance_setup', 'needs_review'],
        }),
      ]
    )).rows[0];
    await createInAppNotification({
      eventType: 'parent_accountability_lead_submitted',
      projectId: bnaProject.id,
      workspaceKey: 'bna',
      recipientLabel: 'Shloimie',
      recipientRole: 'operator',
      title,
      body: limitText(description, 900),
      priority: childStruggles || setupContext ? 'high' : 'normal',
      relatedType: 'parent_lead',
      relatedId: lead.id,
      sourceTable: 'bna_parent_leads',
      sourceId: lead.id,
      sourceContext: {
        source: 'parent_accountability_onboarding',
        communication_id: communication.id,
        support_ticket_id: ticket.id,
        parent_lead_id: lead.id,
        parent_email_present: Boolean(parentEmail),
        review_before_student_visibility: true,
        no_send: true,
        external_write_performed: false,
      },
      createdBy: 'parent_onboarding',
    }, client);

    await client.query('COMMIT');
    res.json({
      success: true,
      message: 'Parent accountability setup received. BNA will review it and follow up before anything is shown to a child.',
      ticket: supportTicketView(ticket),
      lead_id: lead.id,
      communication_id: communication.id,
    });
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

function normalizeOneTimeOnboardingIntent(value) {
  const normalized = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  if (['family', 'home', 'parent_family'].includes(normalized)) return 'family';
  if (['school', 'yeshiva', 'classroom', 'rebbe', 'principal'].includes(normalized)) return 'school';
  if (['video', 'video_library', 'library', 'recordings'].includes(normalized)) return 'library';
  if (['future', 'future_cohort', 'later', 'waitlist'].includes(normalized)) return 'future_cohort';
  if (['question', 'ask_question', 'info', 'details'].includes(normalized)) return 'question';
  return 'live';
}

function oneTimeOnboardingIntentLabel(intent) {
  return ({
    family: 'Family onboarding',
    school: 'School onboarding',
    live: 'Live Mishnah membership',
    library: 'Video library preview',
    future_cohort: 'Future cohort / later',
    question: 'Question before joining',
  })[normalizeOneTimeOnboardingIntent(intent)] || 'Live Mishnah membership';
}

function oneTimePositiveIntegerId(value) {
  const text = String(value || '').trim();
  if (!/^[1-9]\d*$/.test(text)) return null;
  const parsed = Number(text);
  return Number.isSafeInteger(parsed) ? parsed : null;
}

function oneTimeJsonObject(value, fallback = {}) {
  const parsed = parseJsonMaybe(value);
  return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : fallback;
}

function oneTimeOnboardingTags(intent, audienceType = '') {
  const normalizedIntent = normalizeOneTimeOnboardingIntent(intent);
  const normalizedAudience = ['family', 'school'].includes(normalizeOneTimeOnboardingIntent(audienceType))
    ? normalizeOneTimeOnboardingIntent(audienceType)
    : '';
  return [
    'one-time-lead',
    'one-time-source:onboarding',
    `one-time-intent:${normalizedIntent}`,
    normalizedAudience ? `one-time-audience:${normalizedAudience}` : '',
    'one-time-needs-first-response',
    'one-time-no-payment-created',
    'one-time-access-not-granted',
  ].filter(Boolean);
}

function oneTimeOptionalAge(value) {
  const parsed = Number(String(value || '').match(/\d+/)?.[0] || 0);
  return Number.isFinite(parsed) && parsed > 0 && parsed < 120 ? parsed : null;
}

function buildOneTimeOnboardingFields(body = {}) {
  const parentName = limitText(body.parent_name || body.parentName || body.contact_name || body.contactName || body.name, 160);
  const parentEmail = normalizeEmail(body.parent_email || body.parentEmail || body.contact_email || body.contactEmail || body.email);
  const parentPhone = limitText(body.parent_phone || body.parentPhone || body.phone || body.whatsapp, 80);
  const learnerName = limitText(body.learner_name || body.learnerName || body.student_name || body.studentName || body.child_name || body.childName || body.member_name || body.memberName, 160);
  const learnerAgeRaw = limitText(body.learner_age || body.learnerAge || body.student_age || body.studentAge || body.child_age || body.childAge || body.age, 80);
  const learnerStage = limitText(body.learner_stage || body.learnerStage || body.grade || body.stage, 120);
  const city = limitText(body.city || body.location || body.neighborhood, 180);
  const timezone = limitText(body.timezone || body.time_zone || body.timeZone, 120);
  const intent = normalizeOneTimeOnboardingIntent(body.intent || body.interest || body.path || body.offer_interest || body.offerInterest);
  const audienceType = ['family', 'school'].includes(normalizeOneTimeOnboardingIntent(body.audience_type || body.audience || body.signup_audience))
    ? normalizeOneTimeOnboardingIntent(body.audience_type || body.audience || body.signup_audience)
    : (['family', 'school'].includes(intent) ? intent : 'family');
  const scheduleNotes = limitText(body.schedule_notes || body.scheduleNotes || body.schedule, 1200);
  const learningGoals = limitText(body.learning_goals || body.learningGoals || body.goals, 1200);
  const questions = limitText(body.questions || body.question || body.notes || body.message, 1800);
  const referralSource = limitText(body.referral_source || body.referralSource || body.source_detail || body.sourceDetail, 300);
  const rawIntake = limitText(body.raw_intake || body.rawIntake || body.intake_text || body.intakeText, 4000);
  const language = normalizeLanguage(body.language || '') || 'en';
  const sourceRoute = limitText(body.route || body.path_name || body.pathName || body.page_path || body.pagePath || '', 300);
  const originalCapture = oneTimeJsonObject(body.original_capture || body.originalCapture || body.capture || {});
  const productLeadId = oneTimePositiveIntegerId(
    body.product_lead_id || body.productLeadId || originalCapture.product_lead_id || originalCapture.productLeadId
  );
  const crmLeadId = oneTimePositiveIntegerId(
    body.crm_lead_id || body.crmLeadId || body.lead_id || body.leadId || originalCapture.crm_lead_id || originalCapture.crmLeadId
  );
  const sourceLandingPage = limitText(
    body.source_landing_page || body.sourceLandingPage || originalCapture.source_landing_page || originalCapture.sourceLandingPage || '',
    300
  );
  const referrer = limitText(body.referrer || body.referrer_url || body.referrerUrl || originalCapture.referrer || '', 500);
  const utm = oneTimeJsonObject(body.utm || body.utm_json || body.utmJson || originalCapture.utm || {});
  const viewport = body.viewport && typeof body.viewport === 'object'
    ? {
        width: Number(body.viewport.width || 0) || null,
        height: Number(body.viewport.height || 0) || null,
        device_scale_factor: Number(body.viewport.deviceScaleFactor || body.viewport.device_scale_factor || 0) || null,
      }
    : {};
  const transcript = [
    'One Time Mishnayos onboarding intake.',
    `Onboarding branch: ${oneTimeOnboardingIntentLabel(audienceType)}`,
    parentName ? `Contact name: ${parentName}` : '',
    parentEmail ? `Email: ${parentEmail}` : '',
    parentPhone ? `Phone/WhatsApp: ${parentPhone}` : '',
    learnerName ? `Learner/member: ${learnerName}` : '',
    learnerAgeRaw ? `Learner age/stage: ${learnerAgeRaw}` : '',
    learnerStage ? `Grade/stage: ${learnerStage}` : '',
    city ? `Location: ${city}` : '',
    timezone ? `Time zone: ${timezone}` : '',
    `Interest path: ${oneTimeOnboardingIntentLabel(intent)}`,
    productLeadId ? `Product lead ID: ${productLeadId}` : '',
    crmLeadId ? `CRM lead ID: ${crmLeadId}` : '',
    sourceLandingPage ? `Source landing page: ${sourceLandingPage}` : '',
    referrer ? `Referrer: ${referrer}` : '',
    Object.keys(utm).length ? `UTM: ${JSON.stringify(utm)}` : '',
    scheduleNotes ? `Schedule notes: ${scheduleNotes}` : '',
    learningGoals ? `Learning goals: ${learningGoals}` : '',
    questions ? `Questions/notes: ${questions}` : '',
    referralSource ? `Referral/source: ${referralSource}` : '',
    rawIntake ? `Raw intake:\n${rawIntake}` : '',
  ].filter(Boolean).join('\n');
  return {
    parentName,
    parentEmail,
    parentPhone,
    learnerName,
    learnerAgeRaw,
    learnerAge: oneTimeOptionalAge(learnerAgeRaw),
    learnerStage,
    city,
    timezone,
    intent,
    audienceType,
    scheduleNotes,
    learningGoals,
    questions,
    referralSource,
    rawIntake,
    productLeadId,
    crmLeadId,
    sourceLandingPage,
    referrer,
    utm,
    originalCapture: {
      product_lead_id: productLeadId,
      crm_lead_id: crmLeadId,
      source_landing_page: sourceLandingPage || null,
      referrer: referrer || null,
      utm,
    },
    language,
    sourceRoute,
    viewport,
    transcript: limitText(transcript, 5000),
    tags: oneTimeOnboardingTags(intent, audienceType),
  };
}

function oneTimeOnboardingValidationError(fields = {}) {
  if (!fields.parentName || !fields.parentEmail) return 'Contact name and email are required.';
  if (!fields.productLeadId || !fields.crmLeadId) return 'Saved product and CRM lead IDs are required to continue onboarding.';
  if (fields.audienceType === 'family' && (!fields.learnerName || !fields.learnerStage)) {
    return "Son's name and age or grade are required for family onboarding.";
  }
  if (fields.audienceType === 'school' && (!fields.learnerName || !fields.learnerStage)) {
    return 'School name and contact role are required for school onboarding.';
  }
  return '';
}

function oneTimeOnboardingPreview(fields = {}) {
  const leadTitle = `One Time Mishnayos lead: ${fields.parentName || fields.parentEmail || fields.parentPhone || 'new prospect'}`;
  return {
    lead_title: leadTitle,
    intent: fields.intent,
    intent_label: oneTimeOnboardingIntentLabel(fields.intent),
    tags: fields.tags,
    planned_records: [
      'bna_parent_leads scoped to one_time_mishnah_class',
      'bna_contacts in the Rabbi Sheller provider workspace',
      'bna_contact_communications transcript/internal note',
      'bna_support_tickets review ticket',
      'bna_tasks follow-up task for Shloimie/Rabbi review',
    ],
    next_step_preview: {
      status: 'queued_for_review',
      message: 'The One Time team will review the interest details before sending any payment link, access link, email, WhatsApp, or social message.',
      blocked_actions: [
        'no_checkout_created',
        'no_payment_link_sent',
        'no_member_access_granted',
        'no_email_sent',
        'no_whatsapp_sent',
      ],
    },
  };
}

async function upsertOneTimePreviewContact(fields = {}, db = pool) {
  const workspaceId = await getWorkspaceIdForProjectKey(ONE_TIME_PROJECT_KEY, db);
  const email = normalizeEmail(fields.parentEmail);
  const phoneDigits = normalizePhoneDigits(fields.parentPhone);
  let existing = null;
  if (workspaceId && (email || phoneDigits)) {
    existing = (await db.query(
      `SELECT *
       FROM bna_contacts
       WHERE workspace_id = $1
         AND (
           ($2 <> '' AND lower(COALESCE(primary_email, '')) = $2)
           OR ($3 <> '' AND regexp_replace(COALESCE(primary_phone, ''), '\\D', '', 'g') = $3)
         )
       ORDER BY updated_at DESC NULLS LAST, created_at ASC
       LIMIT 1`,
      [workspaceId, email || '', phoneDigits || '']
    )).rows[0] || null;
  }
  const metadata = {
    source: 'one_time_onboarding',
    project_key: ONE_TIME_PROJECT_KEY,
    intent: fields.intent,
    audience_type: fields.audienceType,
    family_school_classification: fields.audienceType,
    product_lead_id: fields.productLeadId || null,
    crm_lead_id: fields.crmLeadId || null,
    source_landing_page: fields.sourceLandingPage || null,
    referrer: fields.referrer || null,
    utm: fields.utm || {},
    original_capture: fields.originalCapture || null,
    exact_original_capture_required: true,
    learner_name: fields.learnerName || null,
    learner_age: fields.learnerAgeRaw || null,
    city: fields.city || null,
    timezone: fields.timezone || null,
  };
  const tags = fields.tags || oneTimeOnboardingTags(fields.intent);
  const result = existing
    ? await db.query(
        `UPDATE bna_contacts
         SET full_name = COALESCE(NULLIF($2, ''), full_name),
             primary_email = COALESCE(NULLIF($3, ''), primary_email),
             primary_phone = COALESCE(NULLIF($4, ''), primary_phone),
             status = CASE WHEN COALESCE(status, 'lead') IN ('lead', 'prospect') THEN 'lead' ELSE status END,
           source = COALESCE(source, 'one_time_onboarding'),
             tags = (
               SELECT ARRAY(
                 SELECT DISTINCT tag_value
                 FROM unnest(COALESCE(tags, ARRAY[]::text[]) || $5::text[]) AS tag_values(tag_value)
                 WHERE trim(tag_value) <> ''
               )
             ),
             metadata = COALESCE(metadata, '{}'::jsonb) || $6::jsonb,
             updated_at = NOW()
         WHERE id = $1
         RETURNING *`,
        [existing.id, fields.parentName || '', email || '', fields.parentPhone || '', tags, JSON.stringify(metadata)]
      )
    : await db.query(
        `INSERT INTO bna_contacts (
           workspace_id, full_name, primary_email, primary_phone, status, source, tags, metadata
         ) VALUES ($1, $2, $3, $4, 'lead', 'one_time_onboarding', $5, $6::jsonb)
         RETURNING *`,
        [workspaceId, fields.parentName || null, email || null, fields.parentPhone || null, tags, JSON.stringify(metadata)]
      );
  return result.rows[0] || null;
}

async function resolveOneTimeOnboardingOriginalCapture(fields = {}, project, db = pool) {
  if (!fields.productLeadId || !fields.crmLeadId) {
    const error = new Error('Saved product and CRM lead IDs are required to continue onboarding.');
    error.statusCode = 400;
    throw error;
  }
  const productLead = (await db.query(
    `SELECT *
     FROM bna_product_leads
     WHERE id = $1
       AND project_id = $2
       AND COALESCE(program_key, product_key, '') = $3
       AND COALESCE(status, 'new') <> 'archived'
     LIMIT 1`,
    [fields.productLeadId, project.id, ONE_TIME_PRODUCT_PROGRAM_KEY]
  )).rows[0] || null;
  if (!productLead) {
    const error = new Error('The saved product lead was not found for this One Time signup.');
    error.statusCode = 400;
    throw error;
  }
  const crmLead = (await db.query(
    `SELECT *
     FROM bna_parent_leads
     WHERE id = $1
       AND project_id = $2
       AND COALESCE(status, 'interested') <> 'archived'
     LIMIT 1`,
    [fields.crmLeadId, project.id]
  )).rows[0] || null;
  if (!crmLead) {
    const error = new Error('The saved CRM lead was not found for this One Time signup.');
    error.statusCode = 400;
    throw error;
  }
  const crmMetadata = oneTimeJsonObject(crmLead.metadata || {});
  const linkedProductLeadId = oneTimePositiveIntegerId(crmMetadata.product_lead_id || crmMetadata.productLeadId);
  if (linkedProductLeadId !== fields.productLeadId) {
    const error = new Error('The saved product lead and CRM lead do not match the original capture.');
    error.statusCode = 400;
    throw error;
  }
  return { productLead, crmLead };
}

async function upsertOneTimePreviewLead(fields = {}, project, db = pool, options = {}) {
  const email = normalizeEmail(fields.parentEmail);
  const phoneDigits = normalizePhoneDigits(fields.parentPhone);
  let existing = options.crmLead || null;
  if (!existing) {
    existing = (await db.query(
      `SELECT *
       FROM bna_parent_leads
       WHERE project_id = $1
         AND COALESCE(status, 'interested') <> 'archived'
         AND (
           ($2 <> '' AND lower(COALESCE(parent_email, '')) = $2)
           OR ($3 <> '' AND regexp_replace(COALESCE(parent_phone, ''), '\\D', '', 'g') = $3)
           OR ($4 <> '' AND lower(COALESCE(parent_name, '')) = lower($4))
         )
       ORDER BY updated_at DESC NULLS LAST, created_at ASC
       LIMIT 1`,
      [project.id, email || '', phoneDigits || '', fields.parentName || '']
    )).rows[0] || null;
  }
  const metadata = {
    source: 'one_time_onboarding',
    project_key: ONE_TIME_PROJECT_KEY,
    intent: fields.intent,
    intent_label: oneTimeOnboardingIntentLabel(fields.intent),
    audience_type: fields.audienceType,
    family_school_classification: fields.audienceType,
    product_lead_id: fields.productLeadId || null,
    crm_lead_id: fields.crmLeadId || null,
    source_landing_page: fields.sourceLandingPage || null,
    referrer: fields.referrer || null,
    utm: fields.utm || {},
    original_capture: fields.originalCapture || null,
    exact_original_capture_verified: Boolean(options.productLead && options.crmLead),
    learner_age_raw: fields.learnerAgeRaw || null,
    learner_stage: fields.learnerStage || null,
    city: fields.city || null,
    timezone: fields.timezone || null,
    schedule_notes: fields.scheduleNotes || null,
    learning_goals: fields.learningGoals || null,
    questions: fields.questions || null,
    referral_source: fields.referralSource || null,
    no_send: true,
    no_checkout: true,
    no_access_granted: true,
  };
  const notes = fields.transcript;
  if (existing) {
    const result = await db.query(
      `UPDATE bna_parent_leads
       SET parent_name = COALESCE(NULLIF($2, ''), parent_name),
           parent_phone = COALESCE(NULLIF($3, ''), parent_phone),
           parent_email = COALESCE(NULLIF($4, ''), parent_email),
           student_name = COALESCE(NULLIF($5, ''), student_name),
           student_age = COALESCE($6, student_age),
           student_grade = COALESCE(NULLIF($7, ''), student_grade),
           lead_type = 'group_member',
           status = CASE WHEN status = 'archived' THEN status ELSE 'follow_up' END,
           interest_level = CASE $8 WHEN 'live' THEN 'warm' WHEN 'question' THEN 'warm' ELSE COALESCE(interest_level, 'unknown') END,
           source = COALESCE(source, 'website_form'),
           source_detail = COALESCE(NULLIF($9, ''), source_detail),
           owner = 'Shloimie',
           tags = (
             SELECT ARRAY(
               SELECT DISTINCT tag_value
               FROM unnest(COALESCE(tags, '{}'::text[]) || $10::text[]) AS tag_values(tag_value)
               WHERE trim(tag_value) <> ''
             )
           ),
           notes = COALESCE(NULLIF($11, ''), notes),
           metadata = COALESCE(metadata, '{}'::jsonb) || $12::jsonb,
           updated_at = NOW()
       WHERE id = $1
       RETURNING *`,
      [
        existing.id,
        fields.parentName || '',
        fields.parentPhone || '',
        email || '',
        fields.learnerName || '',
        fields.learnerAge,
        fields.learnerStage || '',
        fields.intent,
        fields.referralSource || 'One Time onboarding page',
        fields.tags,
        notes || '',
        JSON.stringify(metadata),
      ]
    );
    return { lead: result.rows[0], merged_existing: true };
  }
  const result = await db.query(
    `INSERT INTO bna_parent_leads (
      project_id, parent_name, parent_phone, parent_email, student_name,
      student_age, student_grade, lead_type, status, interest_level, source,
      source_detail, owner, tags, notes, metadata
    ) VALUES (
      $1, $2, $3, $4, $5,
      $6, $7, 'group_member', 'new',
      CASE $8 WHEN 'live' THEN 'warm' WHEN 'question' THEN 'warm' ELSE 'unknown' END,
      'website_form', $9, 'Shloimie', $10, $11, $12::jsonb
    )
    RETURNING *`,
    [
      project.id,
      fields.parentName || fields.parentEmail || fields.parentPhone || 'One Time prospect',
      fields.parentPhone || null,
      email || null,
      fields.learnerName || null,
      fields.learnerAge,
      fields.learnerStage || null,
      fields.intent,
      fields.referralSource || 'One Time onboarding page',
      fields.tags,
      notes || null,
      JSON.stringify(metadata),
    ]
  );
  return { lead: result.rows[0], merged_existing: false };
}

app.post('/api/one-time/mishnah/onboarding', async (req, res) => {
  const fields = buildOneTimeOnboardingFields(req.body || {});
  const validationError = oneTimeOnboardingValidationError(fields);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }
  const dryRun = req.body?.dry_run === true || req.body?.dryRun === true || /^(?:1|true|yes)$/i.test(String(req.body?.dry_run || req.body?.dryRun || ''));
  const preview = oneTimeOnboardingPreview(fields);
  if (dryRun) {
    return res.json({
      success: true,
      dry_run: true,
      no_send: true,
      external_write_performed: false,
      local_write_performed: false,
      preview,
    });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const project = await getProjectByKey(ONE_TIME_PROJECT_KEY, client);
    const originalCapture = await resolveOneTimeOnboardingOriginalCapture(fields, project, client);
    const { lead, merged_existing: mergedLead } = await upsertOneTimePreviewLead(fields, project, client, originalCapture);
    const contact = await upsertOneTimePreviewContact(fields, client);
    const sourceContext = {
      source: 'one_time_onboarding',
      project_key: ONE_TIME_PROJECT_KEY,
      route: fields.sourceRoute || '/one-time-onboarding',
      viewport: fields.viewport,
      intent: fields.intent,
      audience_type: fields.audienceType,
      family_school_classification: fields.audienceType,
      product_lead_id: fields.productLeadId,
      crm_lead_id: fields.crmLeadId,
      source_landing_page: fields.sourceLandingPage || null,
      referrer: fields.referrer || null,
      utm: fields.utm || {},
      exact_original_capture_verified: true,
      lead_id: lead.id,
      contact_id: contact?.id || null,
      no_send: true,
      external_write_performed: false,
      no_checkout: true,
      no_access_granted: true,
    };
    const communication = (await client.query(
      `INSERT INTO bna_contact_communications (
         project_id, contact_type, lead_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, source_context, metadata
       ) VALUES (
         $1, 'lead', $2, 'internal_note', 'inbound', $3, $4,
         TRUE, NOW(), 'one_time_onboarding', 'dashboard', $5::jsonb, $6::jsonb
       )
       RETURNING *`,
      [
        project.id,
        lead.id,
        preview.lead_title,
        fields.transcript,
        JSON.stringify(sourceContext),
        JSON.stringify({
          tags: fields.tags,
          intent: fields.intent,
          language: fields.language,
          contact_id: contact?.id || null,
          product_lead_id: fields.productLeadId,
          crm_lead_id: fields.crmLeadId,
          family_school_classification: fields.audienceType,
          exact_original_capture_verified: true,
          no_send: true,
          external_write_performed: false,
        }),
      ]
    )).rows[0];
    const ticket = (await client.query(
      `INSERT INTO bna_support_tickets (
         project_id, title, description, severity, status, category,
         reporter_name, reporter_role, assigned_to, source, source_context, created_by
       )
       VALUES ($1, $2, $3, 'normal', 'open', 'other',
         $4, 'one_time_parent_member_lead', 'Shloimie', 'api', $5::jsonb, 'one_time_onboarding')
       RETURNING *`,
      [
        project.id,
        `Review One Time onboarding: ${fields.parentName || fields.learnerName || fields.parentEmail || lead.id}`,
        fields.transcript,
        fields.parentName || fields.parentEmail || 'One Time prospect',
        JSON.stringify({ ...sourceContext, communication_id: communication.id }),
      ]
    )).rows[0];
    const task = await createTaskFromText({
      title: `Review One Time Mishnayos onboarding lead: ${fields.parentName || fields.learnerName || fields.parentEmail || lead.id}`,
      raw_text: fields.transcript,
      notes: [
        fields.transcript,
        '',
        `Lead #${lead.id}`,
        contact?.id ? `Contact #${contact.id}` : '',
        `Communication #${communication.id}`,
        `Support ticket #${ticket.id}`,
        'No-send onboarding guardrails: no checkout, payment link, access grant, email, WhatsApp, Telegram, or social send was created.',
      ].filter(Boolean).join('\n'),
      stage: 'assigned',
      category: 'community',
      urgency: fields.intent === 'live' ? 'today' : 'this_week',
      source: 'web',
      source_channel: 'one_time_onboarding',
      created_by: 'one_time_onboarding',
      assigned_to: 'Shloimie',
      project: ONE_TIME_PROJECT_KEY,
      ai_parsed: {
        parser: 'one-time-onboarding-v2',
        kind: 'one_time_onboarding_review',
        display_title: `Review One Time Mishnayos onboarding lead: ${fields.parentName || fields.learnerName || fields.parentEmail || lead.id}`,
        original_text: fields.transcript,
        lead_id: lead.id,
        contact_id: contact?.id || null,
        communication_id: communication.id,
        support_ticket_id: ticket.id,
        project: ONE_TIME_PROJECT_KEY,
        product_lead_id: fields.productLeadId,
        crm_lead_id: fields.crmLeadId,
        audience_type: fields.audienceType,
        family_school_classification: fields.audienceType,
        exact_original_capture_verified: true,
        no_send: true,
        no_checkout: true,
        no_access_granted: true,
      },
    }, {}, client);
    await client.query(
      `UPDATE bna_support_tickets
       SET related_task_id = $2,
           updated_at = NOW()
       WHERE id = $1`,
      [ticket.id, task.id]
    );
    await createInAppNotification({
      eventType: 'one_time_lead_submitted',
      projectId: project.id,
      workspaceKey: 'rabbi_sheller_provider',
      recipientLabel: 'Shloimie',
      recipientRole: 'provider_admin',
      title: `One Time lead: ${fields.parentName || fields.learnerName || fields.parentEmail || lead.id}`,
      body: limitText(fields.transcript, 900),
      priority: fields.intent === 'live' ? 'high' : 'normal',
      relatedType: 'parent_lead',
      relatedId: lead.id,
      sourceTable: 'bna_parent_leads',
      sourceId: lead.id,
      sourceContext: {
        source: 'one_time_onboarding',
        contact_id: contact?.id || null,
        communication_id: communication.id,
        support_ticket_id: ticket.id,
        task_id: task.id,
        intent: fields.intent,
        audience_type: fields.audienceType,
        family_school_classification: fields.audienceType,
        product_lead_id: fields.productLeadId,
        crm_lead_id: fields.crmLeadId,
        exact_original_capture_verified: true,
        no_send: true,
        no_checkout: true,
        no_access_granted: true,
        external_write_performed: false,
      },
      createdBy: 'one_time_onboarding',
    }, client);
    await client.query('COMMIT');
    res.json({
      success: true,
      dry_run: false,
      no_send: true,
      external_write_performed: false,
      local_write_performed: true,
      merged_existing_lead: mergedLead,
      project_key: ONE_TIME_PROJECT_KEY,
      lead_id: lead.id,
      contact_id: contact?.id || null,
      communication_id: communication.id,
      ticket: supportTicketView({ ...ticket, related_task_id: task.id }),
      task_id: task.id,
      preview,
    });
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/parent-portal/provider-messages', async (req, res) => {
  const cookies = parseCookies(req);
  const providerId = Number((req.body || {}).provider_id || (req.body || {}).providerId);
  const serviceId = (req.body || {}).service_id || (req.body || {}).serviceId ? Number((req.body || {}).service_id || (req.body || {}).serviceId) : null;
  const studentId = (req.body || {}).student_id || (req.body || {}).studentId ? Number((req.body || {}).student_id || (req.body || {}).studentId) : null;
  const body = String((req.body || {}).body || (req.body || {}).message || '').trim();
  const subject = limitText((req.body || {}).subject || 'Provider inquiry', 220) || 'Provider inquiry';
  if (!Number.isFinite(providerId) || providerId <= 0) return res.status(400).json({ error: 'A valid provider_id is required' });
  if (serviceId !== null && !Number.isFinite(serviceId)) return res.status(400).json({ error: 'service_id must be numeric' });
  if (studentId !== null && !Number.isFinite(studentId)) return res.status(400).json({ error: 'student_id must be numeric' });
  if (!body) return res.status(400).json({ error: 'Message body is required' });
  if (body.length > 3000) return res.status(400).json({ error: 'Message body is too long' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], client);
    if (!session) {
      await client.query('ROLLBACK');
      return res.status(401).json({ error: 'Parent session is required' });
    }
    const records = await findParentAccessRecords(session.parentEmail, client);
    let student = null;
    if (studentId) {
      student = await getParentPortalStudentForSession(session.parentEmail, studentId, client);
      if (!student) {
        await client.query('ROLLBACK');
        return res.status(404).json({ error: 'Student was not found for this parent session' });
      }
    }
    const provider = (await client.query(
      `SELECT id, provider_name, can_receive_messages
       FROM bna_service_providers
       WHERE id = $1
         AND status = 'approved'
         AND public_listing_enabled IS NOT FALSE
       LIMIT 1`,
      [providerId]
    )).rows[0];
    if (!provider || provider.can_receive_messages === false) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Provider is not available for parent messages' });
    }
    const providerWithProject = await serviceProviderWithProject(providerId, client).catch(() => null);
    const providerScope = serviceProviderScopeFromProvider(providerWithProject || provider);
    let service = null;
    if (serviceId) {
      service = (await client.query(
        `SELECT id, title
         FROM bna_provider_services
         WHERE id = $1
           AND provider_id = $2
           AND status = 'approved'
         LIMIT 1`,
        [serviceId, providerId]
      )).rows[0];
      if (!service) {
        await client.query('ROLLBACK');
        return res.status(404).json({ error: 'Provider service is not available' });
      }
    }
    const message = (await client.query(
      `INSERT INTO bna_provider_messages (
         provider_id, service_id, parent_email, student_id, direction, channel,
         subject, body, status, source, source_context, metadata
       ) VALUES (
         $1, $2, $3, $4, 'parent_to_provider', 'portal',
         $5, $6, 'open', 'parent_portal', $7::jsonb, $8::jsonb
       )
       RETURNING *`,
      [
        providerId,
        service?.id || null,
        session.parentEmail,
        student?.id || records.students[0]?.id || null,
        subject,
        body,
        JSON.stringify({ source: 'parent_provider_directory', service_id: service?.id || null }),
        JSON.stringify({
          provider_name: provider.provider_name,
          service_title: service?.title || null,
          parent_email: session.parentEmail,
        }),
      ]
    )).rows[0];
    await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, student_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, source_context, metadata
       ) VALUES (
         'general', $1, 'email', 'inbound', $2, $3,
         TRUE, NOW(), 'parent_portal', 'dashboard', $4, $5
       )`,
      [
        student?.id || records.students[0]?.id || null,
        `Parent/provider message: ${provider.provider_name}`,
        body,
        JSON.stringify({ source: 'parent_provider_message', provider_id: providerId, provider_message_id: message.id }),
        JSON.stringify({ parent_email: session.parentEmail, provider_name: provider.provider_name, service_title: service?.title || null }),
      ]
    ).catch(() => {});
    await client.query('COMMIT');
    notifyRabbiCommunication({
      communication: {
        id: message.id,
        channel: 'portal',
        direction: 'inbound',
        subject,
        summary: `Parent/provider message: ${provider.provider_name}`,
        contact_label: 'Parent portal contact',
        workspace_key: providerScope.workspace_key,
        project_key: providerScope.project_key,
        provider_id: providerId,
      },
      context: {
        source: 'parent_portal_provider_message',
        workspaceKey: providerScope.workspace_key,
        projectKey: providerScope.project_key,
        reviewPath: '/provider.html?admin_provider=one-time&section=mailbox',
      },
    }).catch((error) => console.error('Rabbi provider message Telegram alert error:', error.message || error));
    res.json({ success: true, message });
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/parent-portal/students/:studentId/login-account', async (req, res) => {
  const cookies = parseCookies(req);
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME]);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });

    const studentId = Number(req.params.studentId);
    if (!Number.isFinite(studentId)) return res.status(400).json({ error: 'A valid student id is required' });
    const student = await getParentPortalStudentForSession(session.parentEmail, studentId);
    if (!student) return res.status(404).json({ error: 'Student was not found for this parent session' });

    const account = await setStudentPasswordAccountForParent({
      student,
      parentEmail: session.parentEmail,
      username: (req.body || {}).username,
      password: (req.body || {}).password,
    });
    const tags = parentInteractionTags('access_issue', 'access', 'student username password reset');
    await mergeParentRecordTags(session.parentEmail, tags);
    await pool.query(
      `INSERT INTO bna_contact_communications (
         contact_type, student_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, metadata
       ) VALUES (
         'student', $1, 'other', 'inbound', $2, $3,
         FALSE, NOW(), 'parent_portal', 'dashboard', $4::jsonb
       )`,
      [
        student.id,
        'Parent set student login',
        `Parent ${session.parentEmail} set or reset the student username/password login for ${student.name}.`,
        JSON.stringify({
          parent_email: session.parentEmail,
          student_id: student.id,
          internal_tags: tags,
          student_login_model: 'parent_managed_username_password',
          username_hash: sha256Hex(account.username || ''),
          raw_password_stored: false,
          password_returned_to_ui: false,
        }),
      ]
    ).catch(() => {});
    res.json({
      success: true,
      student_id: student.id,
      student_name: student.name,
      student_login: account,
      password_returned: false,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.post('/api/parent-portal/students/:studentId/access-code', async (req, res) => {
  const cookies = parseCookies(req);
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME]);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });

    const studentId = Number(req.params.studentId);
    if (!Number.isFinite(studentId)) return res.status(400).json({ error: 'A valid student id is required' });
    const student = await getParentPortalStudentForSession(session.parentEmail, studentId);
    if (!student) return res.status(404).json({ error: 'Student was not found for this parent session' });

    const regenerate = ['1', 'true', 'yes'].includes(String((req.body || {}).regenerate || '').trim().toLowerCase());
    const accessCode = await ensureStudentAccessCode(student.id, { regenerate });
    const tags = parentInteractionTags('access_issue', 'access', regenerate ? 'student access code reset' : 'student access code opened');
    await mergeParentRecordTags(session.parentEmail, tags);
    await pool.query(
      `INSERT INTO bna_contact_communications (
         contact_type, student_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, metadata
       ) VALUES (
         'student', $1, 'other', 'inbound', $2, $3,
         FALSE, NOW(), 'parent_portal', 'dashboard', $4
       )`,
      [
        student.id,
        regenerate ? 'Parent reset student access code' : 'Parent opened student portal link',
        regenerate
          ? `Parent ${session.parentEmail} regenerated the student access code for ${student.name}.`
          : `Parent ${session.parentEmail} requested the student portal link for ${student.name}.`,
        JSON.stringify({
          parent_email: session.parentEmail,
          student_id: student.id,
          internal_tags: tags,
          student_access_reset: regenerate,
        }),
      ]
    ).catch(() => {});
    res.json({
      success: true,
      student_id: student.id,
      student_name: student.name,
      access_code: accessCode,
      url: studentPortalUrl(req, accessCode),
      regenerated: regenerate,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

