app.post('/api/parent-portal/students/:studentId/meeting-recordings', async (req, res) => {
  const cookies = parseCookies(req);
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME]);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });

    const studentId = Number(req.params.studentId);
    if (!Number.isFinite(studentId)) return res.status(400).json({ error: 'A valid student id is required' });
    const student = await getParentPortalStudentForSession(session.parentEmail, studentId);
    if (!student) return res.status(404).json({ error: 'Student was not found for this parent session' });

    const isMultipart = /^multipart\/form-data/i.test(String(req.headers['content-type'] || ''));
    const parsedForm = isMultipart
      ? await parseMultipartFormRequest(req, { maxBytes: PARENT_MEETING_UPLOAD_MAX_BYTES })
      : { fields: req.body || {}, files: [] };
    const fields = parsedForm.fields || {};
    const recording = (parsedForm.files || []).find((file) => ['recording', 'file', 'media'].includes(file.name)) || null;
    const transcriptText = String(fields.transcript_text || fields.transcript || '').trim();

    if (!recording && !transcriptText) {
      return res.status(400).json({ error: 'Upload a recording file.' });
    }

    let localPath = null;
    let originalFilename = recording?.filename || '';
    let mimeType = recording ? mimeTypeFromFilename(originalFilename, recording.mimeType) : 'text/plain';
    let fileSize = recording?.size || 0;
    if (recording) {
      if (!isAudioVideoMime(mimeType)) {
        return res.status(400).json({ error: 'Meeting uploads must be audio or video files.' });
      }
      if (!recording.data?.length) {
        return res.status(400).json({ error: 'The uploaded recording was empty.' });
      }
      const meetingDate = safeIsoDateInput(fields.meeting_date || fields.date) || getTodayDateInTimeZone();
      const extension = path.extname(originalFilename) || (mimeType.startsWith('audio/') ? '.m4a' : '.mp4');
      const savedName = [
        new Date().toISOString().replace(/[:.]/g, '-'),
        sanitizeFileName(student.name),
        sanitizeFileName(path.basename(originalFilename, path.extname(originalFilename)) || 'meeting-recording'),
      ].filter(Boolean).join('-').slice(0, 180) + extension.toLowerCase();
      const targetDir = ensureDirectory(path.join(PARENT_MEETING_UPLOAD_DIR, meetingDate));
      const absolutePath = path.join(targetDir, savedName);
      fs.writeFileSync(absolutePath, recording.data);
      localPath = path.relative(__dirname, absolutePath).replace(/\\/g, '/');
      fileSize = recording.data.length;
      originalFilename = originalFilename || savedName;
    }

    const meetingDate = safeIsoDateInput(fields.meeting_date || fields.date) || getTodayDateInTimeZone();
    const upload = (await pool.query(
      `INSERT INTO bna_parent_meeting_uploads (
         parent_email, student_id, meeting_date, parent_notes,
         original_filename, local_path, mime_type, file_size_bytes,
         status, transcript_text, transcript_json, parse_json
       ) VALUES (
         $1, $2, $3::date, $4,
         $5, $6, $7, $8,
         $9, $10, $11, '{}'
       )
       RETURNING *`,
      [
        session.parentEmail,
        student.id,
        meetingDate,
        String(fields.notes || fields.parent_notes || fields.instruction || '').trim() || null,
        originalFilename || null,
        localPath,
        mimeType,
        fileSize || null,
        transcriptText ? 'transcribed' : 'uploaded',
        transcriptText || null,
        transcriptText ? JSON.stringify({ text: transcriptText, source: 'parent_portal_text_override' }) : null,
      ]
    )).rows[0];

    const processNow = ['1', 'true', 'yes'].includes(String(fields.process_now || fields.sync || '').trim().toLowerCase());
    if (processNow) {
      await processParentMeetingUpload(upload.id);
    } else {
      queueParentMeetingUploadProcessing(upload.id);
    }

    const latest = (await pool.query(
      `SELECT *
       FROM bna_parent_meeting_uploads
       WHERE id = $1`,
      [upload.id]
    )).rows[0] || upload;
    res.json({
      success: true,
      upload: parentMeetingUploadView(latest),
      message: processNow
        ? 'Meeting recording was processed.'
        : 'Meeting recording was uploaded and queued for transcription/accountability parsing.',
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.post('/api/parent-portal/students/:studentId/chat', async (req, res) => {
  const cookies = parseCookies(req);
  const message = String((req.body || {}).message || (req.body || {}).body || '').trim();
  if (!message) return res.status(400).json({ error: 'Message is required' });
  if (message.length > 3000) return res.status(400).json({ error: 'Message is too long' });

  const client = await pool.connect();
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], client);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });

    const studentId = Number(req.params.studentId);
    if (!Number.isFinite(studentId)) return res.status(400).json({ error: 'A valid student id is required' });
    const student = await getParentPortalStudentForSession(session.parentEmail, studentId, client);
    if (!student) return res.status(404).json({ error: 'Student was not found for this parent session' });

    await client.query('BEGIN');
    const saved = await createParentChatAccountabilityUpdate(client, {
      parentEmail: session.parentEmail,
      student,
      message,
    });
    await client.query('COMMIT');

    await sendTelegramNotification([
      `Parent portal chat: ${escapeTelegramHtml(student.name || 'Student')}`,
      `Parent: ${escapeTelegramHtml(session.parentEmail)}`,
      `Accountability event #${Number(saved.event.id)}`,
      escapeTelegramHtml(message.slice(0, 1000)),
    ].join('\n'));

    res.json({
      success: true,
      message: 'Update sent to BNA accountability.',
      chat_message: parentChatMessageView(saved.communication),
      accountability_event_id: saved.event.id,
    });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/parent-portal/notifications/:id/respond', async (req, res) => {
  const cookies = parseCookies(req);
  const action = String((req.body || {}).action || '').trim().toLowerCase();
  const responseText = String((req.body || {}).response || (req.body || {}).body || '').trim().slice(0, 1200);
  if (!['approve', 'deny'].includes(action)) {
    return res.status(400).json({ error: 'Action must be approve or deny' });
  }

  const client = await pool.connect();
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], client);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });

    const notification = await getParentActionNotificationById(req.params.id, client);
    if (!notification) return res.status(404).json({ error: 'Notification was not found for this parent session' });

    const metadata = parseJsonMaybe(notification.metadata);
    const notificationParentEmail = normalizeEmail(metadata.parent_email);
    if (notificationParentEmail && notificationParentEmail !== session.parentEmail) {
      return res.status(404).json({ error: 'Notification was not found for this parent session' });
    }

    const student = await getParentPortalStudentForSession(session.parentEmail, notification.student_id, client);
    if (!student) return res.status(404).json({ error: 'Notification was not found for this parent session' });

    await client.query('BEGIN');
    const saved = await applyParentNotificationAction(client, {
      communication: notification,
      parentEmail: session.parentEmail,
      action,
      response: responseText,
    });
    await client.query('COMMIT');

    res.json({
      success: true,
      notification: parentActionNotificationView(saved.communication),
      parent_action: saved.parent_action,
    });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/parent-portal/questions/:id/respond', async (req, res) => {
  const cookies = parseCookies(req);
  const responseText = String((req.body || {}).response || (req.body || {}).body || '').trim();
  if (!responseText) return res.status(400).json({ error: 'Response is required' });
  if (responseText.length > 2000) return res.status(400).json({ error: 'Response is too long' });

  const client = await pool.connect();
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], client);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });

    const question = (await client.query(
      `SELECT q.*, s.parent_email, s.parent_name, s.name AS student_record_name
       FROM bna_accountability_events q
       LEFT JOIN bna_students s ON s.id = q.student_id
       WHERE q.id = $1
         AND q.event_type = 'question'
       LIMIT 1`,
      [req.params.id]
    )).rows[0];
    if (!question || !eventParentVisible(question) || normalizeEmail(question.parent_email) !== session.parentEmail) {
      return res.status(404).json({ error: 'Question was not found for this parent session' });
    }

    await client.query('BEGIN');
    const metadata = eventMetadata(question);
    const questionMeta = metadata.question && typeof metadata.question === 'object' ? metadata.question : {};
    const internalTags = parentInteractionTags('parent_response', 'student', responseText);
    const parentResponses = Array.isArray(questionMeta.parent_responses) ? questionMeta.parent_responses.slice() : [];
    parentResponses.unshift({
      body: responseText,
      parent_email: session.parentEmail,
      parent_name: question.parent_name || '',
      created_at: new Date().toISOString(),
      source: 'parent_portal',
      internal_tags: internalTags,
    });
    const nextMetadata = {
      ...metadata,
      internal_tags: normalizeTextArray([...(Array.isArray(metadata.internal_tags) ? metadata.internal_tags : []), ...internalTags]),
      question: {
        ...questionMeta,
        parent_responses: parentResponses.slice(0, 20),
      },
    };
    const updated = (await client.query(
      `UPDATE bna_accountability_events
       SET metadata = $2,
           updated_at = NOW()
       WHERE id = $1
       RETURNING *`,
      [question.id, JSON.stringify(nextMetadata)]
    )).rows[0];
    await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, student_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, metadata
       ) VALUES (
         'student', $1, 'other', 'inbound', $2, $3,
         TRUE, NOW(), 'parent_portal', 'dashboard', $4
       )`,
      [
        question.student_id,
        `Parent response to ${question.student_record_name || question.student_name || 'student'} question`,
        responseText,
        JSON.stringify({ parent_email: session.parentEmail, question_id: question.id, internal_tags: internalTags }),
      ]
    );
    await mergeParentRecordTags(session.parentEmail, internalTags, client);
    await client.query('COMMIT');
    res.json({ success: true, question: safeQuestionView(updated, { audience: 'parent' }) });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(500).json({ error: err.message });
  } finally {
    client.release();
  }
});

