app.get('/api/bna/project-meetings', requireAdmin, async (req, res) => {
  const { project, status } = req.query;
  const params = [];
  const conditions = [];
  appendScopeCondition(req, conditions, params, 'm.project_id');

  const projectKey = project && project !== 'all' ? normalizeProjectKey(project) : '';
  if (projectKey) {
    params.push(projectKey);
    conditions.push(`p.project_key = $${params.length}`);
  }
  if (status) {
    params.push(status);
    conditions.push(`m.status = $${params.length}`);
  }

  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  try {
    const result = await pool.query(
      `SELECT m.*,
        p.project_key,
        p.name AS project_name,
        p.short_name AS project_short_name,
        row_to_json(j.*) AS content_job
       FROM bna_project_meetings m
       LEFT JOIN bna_projects p ON p.id = m.project_id
       LEFT JOIN bna_content_jobs j ON j.id = m.content_job_id
       ${whereClause}
       ORDER BY m.updated_at DESC, m.created_at DESC
       LIMIT 100`,
      params
    );
    res.json({ meetings: result.rows.map(projectMeetingView) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

