app.post('/api/bna/intake/review/:id/resolve', requireAdmin, async (req, res) => {
  const action = String(req.body?.action || 'resolve').trim();
  try {
    const review = (await pool.query(
      `SELECT q.*, i.payload AS item_payload
       FROM bna_parse_review_queue q
       LEFT JOIN bna_intake_parse_items i ON i.id = q.parse_item_id
       WHERE q.id = $1`,
      [req.params.id]
    )).rows[0];
    if (!review) return res.status(404).json({ error: 'Review item not found' });
    let resolution = req.body?.resolution || {};
    if (action === 'approve_custom_section') {
      const payload = intakeJson(review.item_payload, {}) || intakeJson(review.payload, {});
      const proposal = payload.section_key || payload.label
        ? payload
        : buildCustomSectionProposal(intakeJson(review.payload, {}));
      const section = await getOrCreateSectionDefinition(proposal.section_key || proposal.label, {
        label: proposal.label,
        scope: proposal.scope,
        schema_json: proposal.schema_json,
        visible_to: proposal.visible_to,
        status: 'active',
      });
      resolution = { ...resolution, action, section_id: section.id, section_key: section.section_key };
      if (review.parse_item_id) {
        await pool.query(
          `UPDATE bna_intake_parse_items
           SET status = 'filed',
               target_table = 'bna_section_definitions',
               target_id = $1,
               filed_at = NOW(),
               updated_at = NOW()
           WHERE id = $2`,
          [section.id, review.parse_item_id]
        );
      }
    } else if (action === 'ignore') {
      if (review.parse_item_id) {
        await pool.query('UPDATE bna_intake_parse_items SET status = $1, updated_at = NOW() WHERE id = $2', ['ignored', review.parse_item_id]);
      }
      resolution = { ...resolution, action };
    } else if (action === 'file_item' && review.parse_run_id) {
      if (review.parse_item_id) {
        await pool.query('UPDATE bna_intake_parse_items SET status = $1, updated_at = NOW() WHERE id = $2', ['parsed', review.parse_item_id]);
      }
      const applied = await fileIntakeParseRun(review.parse_run_id, { req });
      resolution = { ...resolution, action, applied: applied.counts };
    } else {
      resolution = { ...resolution, action };
    }
    const status = action === 'ignore' ? 'ignored' : 'resolved';
    const updated = (await pool.query(
      `UPDATE bna_parse_review_queue
       SET status = $1,
           resolution_json = $2::jsonb,
           resolved_by = $3,
           resolved_at = NOW(),
           updated_at = NOW()
       WHERE id = $4
       RETURNING *`,
      [status, JSON.stringify(resolution), req.adminIdentity?.username || 'dashboard', req.params.id]
    )).rows[0];
    res.json({ success: true, review: parseReviewQueueView(updated) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

async function listBnaSections(req, res) {
  const { status = 'all', scope } = req.query || {};
  const params = [];
  const conditions = [];
  if (status && status !== 'all') {
    params.push(status);
    conditions.push(`status = $${params.length}`);
  }
  if (scope) {
    params.push(scope);
    conditions.push(`scope = $${params.length}`);
  }
  const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  try {
    const result = await pool.query(
      `SELECT * FROM bna_section_definitions
       ${where}
       ORDER BY CASE status WHEN 'proposed' THEN 0 WHEN 'active' THEN 1 ELSE 2 END, scope, label`,
      params
    );
    res.json({ success: true, sections: result.rows.map(sectionDefinitionView) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}

async function createBnaSection(req, res) {
  const body = req.body || {};
  try {
    const proposal = buildCustomSectionProposal({
      section_key: body.section_key || body.sectionKey || body.label,
      label: body.label,
      scope: body.scope,
      schema_json: body.schema_json || body.schema,
      visible_to: body.visible_to || body.visibility,
      metadata: { created_by: req.adminIdentity?.username || 'dashboard', ...(body.metadata || {}) },
    });
    const section = await getOrCreateSectionDefinition(proposal.section_key, {
      label: proposal.label,
      scope: proposal.scope,
      schema_json: proposal.schema_json,
      visible_to: proposal.visible_to,
      status: body.status || 'proposed',
    });
    res.json({ success: true, section });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
}

async function updateBnaSection(req, res) {
  const allowed = ['label', 'scope', 'schema_json', 'visible_to', 'status', 'metadata'];
  const fields = [];
  const values = [];
  for (const key of allowed) {
    if (!Object.prototype.hasOwnProperty.call(req.body || {}, key)) continue;
    values.push(['schema_json', 'visible_to', 'metadata'].includes(key) ? JSON.stringify(req.body[key] || {}) : req.body[key]);
    fields.push(`${key} = $${values.length}${['schema_json', 'visible_to', 'metadata'].includes(key) ? '::jsonb' : ''}`);
  }
  if (!fields.length) return res.status(400).json({ error: 'No valid section fields provided' });
  values.push(req.params.id);
  try {
    const result = await pool.query(
      `UPDATE bna_section_definitions
       SET ${fields.join(', ')}, updated_at = NOW()
       WHERE id = $${values.length}
       RETURNING *`,
      values
    );
    if (!result.rows[0]) return res.status(404).json({ error: 'Section not found' });
    res.json({ success: true, section: sectionDefinitionView(result.rows[0]) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}

app.get('/api/bna/intake/sections', requireAdmin, listBnaSections);
app.post('/api/bna/intake/sections', requireAdmin, createBnaSection);
app.patch('/api/bna/intake/sections/:id', requireAdmin, updateBnaSection);
