app.post('/api/bna/sections', requireAdmin, createBnaSection);
app.patch('/api/bna/sections/:id', requireAdmin, updateBnaSection);

app.post('/api/bna/content-jobs/:id/parse-mixed-recording', requireAdmin, async (req, res) => {
  const { id } = req.params;
  const {
    dry_run = false,
    force = false,
    instruction = '',
    archive_source_after_parse = false,
    no_ai = false,
    no_progress_writes = false,
  } = req.body || {};

  try {
    await assertProjectOwnedRowAccess(req, 'bna_content_jobs', id);
    const job = (await pool.query('SELECT * FROM bna_content_jobs WHERE id = $1', [id])).rows[0];
    if (!job) return res.status(404).json({ error: 'Content job not found' });
    if (!String(job.transcript_text || '').trim()) {
      return res.status(400).json({ error: 'Content job does not have a transcript yet' });
    }
    const previousParse = typeof job.parse_json === 'string' ? safeJsonParse(job.parse_json) : (job.parse_json || {});
    if (!force && previousParse?.mixed_recording_parse?.parsed_at) {
      if (!dry_run && archive_source_after_parse && job.status !== 'archived') {
        await pool.query(
          `UPDATE bna_content_jobs
           SET status = 'archived',
               drive_stage = '04 Parsed',
               updated_at = NOW()
           WHERE id = $1`,
          [job.id]
        );
      }
      return res.json({
        success: true,
        skipped: true,
        dry_run: Boolean(dry_run),
        message: dry_run
          ? 'This recording was already parsed; dry-run reused the stored parse. Use force if you intentionally want to reparse.'
          : 'This recording was already parsed. Use force if you intentionally want to reparse and create new records.',
        report: previousParse.mixed_recording_parse.report || {},
        counts: previousParse.mixed_recording_parse.counts || {},
      });
    }

    const result = await parseMixedRecordingSource({
      job,
      instruction,
      previousParse,
      dryRun: Boolean(dry_run),
      archiveSourceAfterParse: Boolean(archive_source_after_parse),
      contentBacked: true,
      projectKey: opsScopeProjectKey(req) || '',
      noAi: Boolean(no_ai),
      noProgressWrites: Boolean(no_progress_writes),
    });
    return res.json(result);
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

