app.post('/api/bna/operator-setup/bootstrap-package', requireAdmin, async (req, res) => {
  if (req.opsIdentity?.scope?.type !== 'all') {
    return res.status(403).json({ error: 'Only the platform admin can create operator setup packages.' });
  }
  const body = req.body || {};
  const includeSecrets = body.include_secrets === true || body.includeSecrets === true;
  const ttlMs = Math.max(
    60 * 1000,
    Math.min(Number(body.ttl_ms || body.ttlMs || OPERATOR_BOOTSTRAP_TTL_MS), OPERATOR_BOOTSTRAP_MAX_TTL_MS)
  );
  const expiresAt = new Date(Date.now() + ttlMs);

  try {
    let packageObject;
    let filename;
    if (includeSecrets) {
      const approvalPhrase = String(body.approval_phrase || body.approvalPhrase || '').trim();
      const passphrase = String(body.passphrase || '');
      if (approvalPhrase !== OPERATOR_BOOTSTRAP_SECRET_EXPORT_APPROVAL) {
        return res.status(400).json({
          error: `Secret export requires approval_phrase: ${OPERATOR_BOOTSTRAP_SECRET_EXPORT_APPROVAL}`,
          hint: 'Use the non-secret package unless you are intentionally exporting encrypted environment values.',
        });
      }
      if (passphrase.length < OPERATOR_BOOTSTRAP_PASSPHRASE_MIN) {
        return res.status(400).json({
          error: `Passphrase must be at least ${OPERATOR_BOOTSTRAP_PASSPHRASE_MIN} characters.`,
          hint: 'The passphrase is used only for encryption and is not stored.',
        });
      }
      packageObject = buildEncryptedOperatorBootstrap({ req, expiresAt, passphrase });
      filename = `bna-operator-bootstrap-encrypted-${Date.now()}.json`;
    } else {
      packageObject = buildPlainOperatorBootstrap({ req, expiresAt });
      filename = `bna-operator-bootstrap-safe-${Date.now()}.json`;
    }

    const download = await createSecureDownload({
      kind: 'operator_bootstrap',
      filename,
      payload: JSON.stringify(packageObject, null, 2),
      expiresAt,
      requestedBy: req.opsUser || 'admin',
      req,
      metadata: {
        include_secrets: includeSecrets,
        encrypted: includeSecrets,
        purpose: body.purpose || 'operator_laptop_bootstrap',
      },
    });
    res.json({
      success: true,
      url: download.url,
      filename: download.filename,
      expires_at: download.expiresAt.toISOString(),
      one_time: true,
      encrypted: includeSecrets,
      includes_secret_values: includeSecrets,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/bna/operator-setup/download/:token', requireAdmin, async (req, res) => {
  if (req.opsIdentity?.scope?.type !== 'all') {
    return res.status(403).json({ error: 'Only the platform admin can download operator setup packages.' });
  }
  const token = String(req.params.token || '').trim();
  if (!token) return res.status(404).send('Download not found or expired.');

  try {
    const download = await redeemSecureDownload(token, 'operator_bootstrap');
    if (!download) return res.status(404).send('Download not found or expired.');
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('Content-Type', download.content_type || 'application/json; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="${String(download.filename || 'bna-operator-bootstrap.json').replace(/"/g, '')}"`);
    res.send(download.payload);
  } catch (err) {
    res.status(500).send('Could not prepare secure download.');
  }
});

async function buildExternalAccessPreview(body = {}, req = {}) {
  const personInput = body.person && typeof body.person === 'object' ? body.person : body;
  const preferredName = limitText(
    personInput.preferred_name || personInput.preferredName || personInput.display_name || personInput.displayName || personInput.name || body.person_name || body.personName,
    180
  );
  const fullName = limitText(personInput.full_name || personInput.fullName || preferredName, 220);
  const email = normalizeEmail(personInput.email || body.email || '');
  const phone = limitText(personInput.phone || body.phone || '', 80);
  const noContactReason = limitText(body.no_contact_reason || body.noContactReason || personInput.no_contact_reason || '', 320);
  const workspaceKey = normalizeWorkspaceKey(body.workspace_key || body.workspaceKey || body.workspace || 'rabbi_sheller_provider');
  const accountType = String(body.account_type || body.accountType || 'external_operations_user')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_');
  const role = limitText(body.role || 'external account admin', 120);
  const accessLevel = safeProjectMemberAccessLevel(body.access_level || body.accessLevel || 'viewer');
  const loginUsername = limitText(body.login_username || body.loginUsername || body.username || '', 120);
  const allowedViews = normalizeTextArray(body.allowed_views || body.allowedViews);
  const createAccessLink = Boolean(body.create_access_link || body.createAccessLink);
  const deliveryPolicy = limitText(body.delivery_policy || body.deliveryPolicy || 'no_send', 120);
  const accessReason = limitText(body.access_reason || body.accessReason || '', 600);
  const reviewBy = limitText(body.review_by || body.reviewBy || '', 80);
  const rollbackOwner = limitText(body.rollback_owner || body.rollbackOwner || '', 120);
  const approvalPhrase = String(body.approval_phrase || body.approvalPhrase || '').trim();
  const workspace = workspaceKey ? await getWorkspaceProjectByKey(workspaceKey) : null;
  const projectKey = workspace?.project_key || workspaceProjectKey(workspaceKey) || workspaceKey;
  const missingFields = [];
  if (!preferredName) missingFields.push('person.preferred_name');
  if (!email && !phone && !noContactReason) missingFields.push('person.email_or_phone_or_no_contact_reason');
  if (!workspaceKey || !workspace) missingFields.push('workspace_key');
  if (!accountType) missingFields.push('account_type');
  if (!role) missingFields.push('role');
  if (!accessLevel) missingFields.push('access_level');
  if (!loginUsername) missingFields.push('login_username');
  if (!accessReason) missingFields.push('access_reason');
  if (!reviewBy) missingFields.push('review_by');
  if (!rollbackOwner) missingFields.push('rollback_owner');

  let existingPerson = null;
  if (email) {
    existingPerson = (await pool.query(
      `SELECT id, preferred_name, full_name, email, phone, status
       FROM bna_people
       WHERE lower(email) = lower($1)
       ORDER BY id ASC
       LIMIT 1`,
      [email]
    )).rows[0] || null;
  }
  if (!existingPerson && phone) {
    const phoneDigits = normalizePhoneDigits(phone);
    if (phoneDigits) {
      existingPerson = (await pool.query(
        `SELECT id, preferred_name, full_name, email, phone, status
         FROM bna_people
         WHERE regexp_replace(COALESCE(phone, ''), '\\D', '', 'g') = $1
         ORDER BY id ASC
         LIMIT 1`,
        [phoneDigits]
      )).rows[0] || null;
    }
  }
  if (!existingPerson && preferredName) {
    existingPerson = (await pool.query(
      `SELECT id, preferred_name, full_name, email, phone, status
       FROM bna_people
       WHERE trim(regexp_replace(lower(regexp_replace(COALESCE(preferred_name, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $1
          OR trim(regexp_replace(lower(regexp_replace(COALESCE(full_name, ''), '[^a-zA-Z0-9]+', ' ', 'g')), '\\s+', ' ', 'g')) = $1
       ORDER BY id ASC
       LIMIT 1`,
      [personLookupName(preferredName)]
    )).rows[0] || null;
  }

  let existingMembership = null;
  if (workspace?.id && existingPerson?.id) {
    existingMembership = (await pool.query(
      `SELECT id, workspace_id, person_id, role, access_level, active
       FROM bna_workspace_memberships
       WHERE workspace_id = $1
         AND person_id = $2
         AND role = $3
       LIMIT 1`,
      [workspace.id, existingPerson.id, role]
    )).rows[0] || null;
  }

  let existingProjectMember = null;
  if (workspace?.id && (loginUsername || preferredName)) {
    const params = [workspace.id];
    const conditions = [];
    if (loginUsername) {
      params.push(loginUsername);
      conditions.push(`lower(login_username) = lower($${params.length})`);
    }
    if (preferredName) {
      params.push(preferredName);
      conditions.push(`lower(person_name) = lower($${params.length})`);
    }
    if (conditions.length) {
      existingProjectMember = (await pool.query(
        `SELECT id, project_id, person_name, role, access_level, login_username, active, metadata
         FROM bna_project_members
         WHERE project_id = $1
           AND (${conditions.join(' OR ')})
         ORDER BY id ASC
         LIMIT 1`,
        params
      )).rows[0] || null;
    }
  }

  return {
    success: true,
    status: missingFields.length ? 'preview_incomplete' : 'preview_ready',
    dry_run: true,
    external_write_performed: false,
    no_send: true,
    approval_phrase_supplied: approvalPhrase === 'APPROVE_EXTERNAL_ACCESS_PERSISTENCE_WORKFLOW',
    missing_fields: missingFields,
    person: {
      preferred_name: preferredName,
      full_name: fullName,
      email: email || null,
      phone: phone || null,
      no_contact_reason: noContactReason || null,
      existing_person_id: existingPerson?.id || null,
      would_upsert: missingFields.length === 0,
    },
    memberships: [{
      workspace_key: workspaceKey,
      project_key: projectKey,
      workspace_id: workspace?.id || null,
      role,
      access_level: accessLevel,
      active: true,
      allowed_views: allowedViews,
      existing_membership_id: existingMembership?.id || null,
      would_upsert: missingFields.length === 0,
    }],
    project_member: {
      project_key: projectKey,
      project_id: workspace?.id || null,
      person_name: preferredName,
      role,
      access_level: accessLevel,
      login_username: loginUsername || null,
      account_type: accountType,
      existing_project_member_id: existingProjectMember?.id || null,
      metadata: {
        account_type: 'external_user',
        requested_account_type: accountType,
        project_scope: projectKey,
        allowed_views: allowedViews,
        access_reason: accessReason,
        review_by: reviewBy,
        rollback_owner: rollbackOwner,
      },
      would_upsert: missingFields.length === 0,
    },
    access_link: {
      requested: createAccessLink,
      status: createAccessLink ? 'not_created_dry_run' : 'not_requested',
      delivery_policy: deliveryPolicy,
      no_send: true,
      would_create_short_lived_link: createAccessLink && missingFields.length === 0,
    },
    audit: {
      actor: req.opsUser || 'admin',
      source: 'external_access_preview_only',
      approval_phrase: approvalPhrase ? 'supplied_or_partial' : 'not_supplied',
      audit_write_performed: false,
      would_record_on_approved_write: missingFields.length === 0,
    },
    guardrails: {
      dry_run_only: true,
      no_parent_account_created: true,
      no_student_account_created: true,
      no_provider_portal_password_created: true,
      no_member_library_access_created: true,
      no_billing_or_checkout_created: true,
      no_rabbi_live_app_credentials_created: true,
      no_email_whatsapp_sms_telegram_send: true,
      no_google_drive_buffer_wapi_external_crm_write: true,
      external_write_performed: false,
    },
    required_readback: [
      'Confirm the person row or planned person row belongs to the intended external Operations user.',
      'Confirm the workspace/project key, role, access level, and login username.',
      'Confirm this is not a parent, student, provider-portal, billing, member-library, or Rabbi-owned app credential.',
      'Confirm rollback owner and review date before any approved write.',
      'Run a live readback after any future approved write before marking done.',
    ],
  };
}

app.post('/api/bna/admin/external-access', requireAdmin, async (req, res) => {
  if (req.opsIdentity?.scope?.type !== 'all') {
    return res.status(403).json({
      success: false,
      dry_run: true,
      external_write_performed: false,
      error: 'Only the platform admin can preview external Operations access changes.',
    });
  }
  const body = req.body || {};
  const dryRun = body.dry_run !== false && body.dryRun !== false;
  try {
    const preview = await buildExternalAccessPreview(body, req);
    if (!dryRun) {
      if (String(body.approval_phrase || body.approvalPhrase || '').trim() !== 'APPROVE_EXTERNAL_ACCESS_PERSISTENCE_WORKFLOW') {
        return res.status(403).json({
          ...preview,
          success: false,
          dry_run: false,
          error: 'APPROVE_EXTERNAL_ACCESS_PERSISTENCE_WORKFLOW is required for any real external-access write.',
          external_write_performed: false,
        });
      }
      return res.status(409).json({
        ...preview,
        success: false,
        dry_run: false,
        error: 'External access persistence writes are not enabled yet. This endpoint is preview-only in the current deployed workflow.',
        external_write_performed: false,
      });
    }
    res.json(preview);
  } catch (err) {
    res.status(err.statusCode || 500).json({
      success: false,
      dry_run: true,
      external_write_performed: false,
      error: err.message,
    });
  }
});

