function agentJobOrderSQL() {
  return `CASE j.status
    WHEN 'running' THEN 1
    WHEN 'queued' THEN 2
    WHEN 'blocked_needs_human_decision' THEN 3
    WHEN 'failed' THEN 5
    WHEN 'completed' THEN 7
    ELSE 8
  END`;
}

async function listObservableAgentJobs(req, filters = {}) {
  const params = [];
  const conditions = [];
  appendScopeCondition(req, conditions, params, 'COALESCE(t.project_id, bt.project_id)');
  const status = filters.status ? safeAgentJobStatus(filters.status, null) : null;
  if (status) {
    params.push(status);
    conditions.push(`j.status = $${params.length}`);
  } else if (filters.openOnly) {
    conditions.push(`j.status IN ('queued', 'running', 'blocked_needs_human_decision', 'failed')`);
  }
  if (filters.ticket_id || filters.ticketId) {
    params.push(Number(filters.ticket_id || filters.ticketId));
    conditions.push(`j.ticket_id = $${params.length}`);
  }
  if (filters.task_id || filters.taskId) {
    params.push(Number(filters.task_id || filters.taskId));
    conditions.push(`j.task_id = $${params.length}`);
  }
  const limit = Math.max(1, Math.min(Number(filters.limit || 50), 200));
  params.push(limit);
  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  const result = await pool.query(
    `SELECT j.*,
            t.title AS task_title,
            t.stage AS task_stage,
            t.agent_status AS task_agent_status,
            t.verification_notes AS task_verification_notes,
            bt.title AS ticket_title,
            bt.status AS ticket_status,
            p.project_key,
            p.name AS project_name,
            p.short_name AS project_short_name
     FROM bna_agent_jobs j
     LEFT JOIN bna_tasks t ON t.id = j.task_id
     LEFT JOIN bna_tickets bt ON bt.id = j.ticket_id
     LEFT JOIN bna_projects p ON p.id = COALESCE(t.project_id, bt.project_id)
     ${whereClause}
     ORDER BY ${agentJobOrderSQL()},
              CASE j.priority WHEN 'urgent' THEN 1 WHEN 'today' THEN 2 WHEN 'normal' THEN 3 ELSE 4 END,
              COALESCE(j.queued_at, j.created_at) ASC
     LIMIT $${params.length}`,
    params
  );
  return result.rows.map(observableAgentJobView);
}

async function fetchObservableAgentJob(jobId, db = pool) {
  const result = await db.query(
    `SELECT j.*,
            t.title AS task_title,
            t.stage AS task_stage,
            t.agent_status AS task_agent_status,
            bt.title AS ticket_title,
            bt.status AS ticket_status,
            p.project_key,
            p.name AS project_name,
            p.short_name AS project_short_name
     FROM bna_agent_jobs j
     LEFT JOIN bna_tasks t ON t.id = j.task_id
     LEFT JOIN bna_tickets bt ON bt.id = j.ticket_id
     LEFT JOIN bna_projects p ON p.id = COALESCE(t.project_id, bt.project_id)
     WHERE j.id = $1`,
    [jobId]
  );
  return result.rows[0] ? observableAgentJobView(result.rows[0]) : null;
}

async function applyAgentJobLinkedStatus(job, status, { summary = '', blocker = '', resultPayload = null, reportPath = null, ledgerRef = null, changelogRef = null, actor = 'agent-fleet' } = {}, db = pool) {
  if (!job?.id) return null;
  const canonicalStatus = safeAgentJobStatus(status, 'queued');
  const taskStatus = taskAgentStatusFromJobStatus(canonicalStatus);
  let taskStage = taskStageFromJobStatus(canonicalStatus);
  const ticketStatus = ticketStatusFromAgentJobStatus(canonicalStatus);
  const result = await db.query(
    `UPDATE bna_agent_jobs
     SET status = $1,
         result_summary = COALESCE($2, result_summary),
         current_blocker = COALESCE($3, current_blocker),
         error_message = CASE WHEN $1 = 'failed' THEN COALESCE($3, error_message) ELSE error_message END,
         result_payload = COALESCE($4::jsonb, result_payload),
         report_path = COALESCE($5, report_path),
         ledger_ref = COALESCE($6, ledger_ref),
         changelog_ref = COALESCE($7, changelog_ref),
         heartbeat_at = CASE WHEN $1 = 'running' THEN NOW() ELSE heartbeat_at END,
         claimed_at = CASE WHEN $1 = 'running' THEN COALESCE(claimed_at, NOW()) ELSE claimed_at END,
         started_at = CASE WHEN $1 = 'running' THEN COALESCE(started_at, NOW()) ELSE started_at END,
         completed_at = CASE WHEN $1 IN ('completed', 'blocked_needs_human_decision', 'failed') THEN COALESCE(completed_at, NOW()) ELSE completed_at END,
         blocked_at = CASE WHEN $1 = 'blocked_needs_human_decision' THEN COALESCE(blocked_at, NOW()) ELSE blocked_at END,
         failed_at = CASE WHEN $1 = 'failed' THEN COALESCE(failed_at, NOW()) ELSE failed_at END,
         updated_at = NOW()
     WHERE id = $8
     RETURNING *`,
    [
      canonicalStatus,
      summary || null,
      blocker || null,
      resultPayload ? JSON.stringify(resultPayload) : null,
      reportPath || null,
      ledgerRef || null,
      changelogRef || null,
      job.id,
    ]
  );
  const updated = result.rows[0] || null;
  if (!updated) return null;
  if (updated.task_id) {
    const blockerText = [blocker, summary, updated.current_blocker, updated.error_message].filter(Boolean).join('\n');
    const blockedByAccess = ['blocked_needs_human_decision', 'failed'].includes(canonicalStatus) && hasAccessBlockerIntent(blockerText);
    const blockedTaskKind = blockedByAccess ? 'pending_access' : 'decision';
    const blockedWaitingOn = blockedByAccess
      ? normalizeTaskWaitingOnKey(blockerText, 'external')
      : 'shloimie';
    if (blockedByAccess) taskStage = 'assigned';
    const taskFields = [
      `agent_status = $1`,
      `stage = $2`,
      `agent_job_id = $3`,
      `last_activity_at = NOW()`,
      `updated_at = NOW()`,
    ];
    const taskValues = [taskStatus, taskStage, updated.id];
    if (canonicalStatus === 'running') {
      taskFields.push(`started_at = COALESCE(started_at, NOW())`);
      taskFields.push(`task_kind = 'agent_job'`);
      taskFields.push(`next_action = COALESCE(next_action, 'Watch agent job status')`);
    }
    if (canonicalStatus === 'completed') {
      const proofLinks = mergeArtifactLinks(
        reportPath ? [{ label: 'Agent fleet report', kind: 'report', repo_path: reportPath, source: 'agent_fleet', status: 'valid' }] : null,
        ledgerRef ? [{ label: 'Agent ledger', kind: 'verification', repo_path: ledgerRef, source: 'agent_fleet', status: 'valid' }] : null,
        changelogRef ? [{ label: 'Agent changelog', kind: 'verification', repo_path: changelogRef, source: 'agent_fleet', status: 'valid' }] : null,
        extractArtifactLinksFromText(summary)
      );
      const proofState = doneLinkStatusForLinks(proofLinks);
      taskFields.push(`completed_at = COALESCE(completed_at, NOW())`);
      taskFields.push(`verified_at = CASE WHEN $6 IN ('valid', 'not_required') THEN COALESCE(verified_at, NOW()) ELSE verified_at END`);
      taskFields.push(`verification_notes = COALESCE($4, verification_notes)`);
      taskFields.push(`task_kind = 'history'`);
      taskFields.push(`workflow_status = $5`);
      taskFields.push(`status_detail = $5`);
      taskFields.push(`artifact_links = (
        SELECT COALESCE(jsonb_agg(DISTINCT value), '[]'::jsonb)
        FROM jsonb_array_elements(COALESCE(artifact_links, '[]'::jsonb) || $7::jsonb) AS value
      )`);
      taskFields.push(`proof_links_json = (
        SELECT COALESCE(jsonb_agg(DISTINCT value), '[]'::jsonb)
        FROM jsonb_array_elements(COALESCE(proof_links_json, '[]'::jsonb) || $7::jsonb) AS value
      )`);
      taskFields.push(`done_link_status = $5`);
      taskFields.push(`proof_status = $6`);
      taskFields.push(`done_link_checked_at = NOW()`);
      taskFields.push(`proof_checked_at = NOW()`);
      taskFields.push(`next_action = 'Review completed result'`);
      taskValues.push(summary || 'Codex completed this task.', proofState.doneLinkStatus, proofState.proofStatus, JSON.stringify(proofLinks));
    } else if (['blocked_needs_human_decision', 'failed'].includes(canonicalStatus)) {
      taskFields.push(`decision_required = ${blockedByAccess ? 'FALSE' : 'TRUE'}`);
      taskFields.push(`verification_notes = COALESCE($4, verification_notes)`);
      taskFields.push(`task_kind = '${blockedTaskKind}'`);
      taskFields.push(`blocked_reason = COALESCE($4, blocked_reason)`);
      taskFields.push(`blocked_at = COALESCE(blocked_at, NOW())`);
      taskFields.push(`needs_review = TRUE`);
      taskFields.push(`waiting_on = '${blockedWaitingOn}'`);
      taskFields.push(`workflow_status = '${blockedByAccess ? 'pending_access' : 'blocked'}'`);
      taskFields.push(`status_detail = '${blockedByAccess ? 'pending_access' : 'blocked'}'`);
      taskFields.push(`next_action = '${blockedByAccess ? 'Request the missing access or material' : 'Choose a path or ask for more information'}'`);
      taskFields.push(`why_exists = '${blockedByAccess ? 'Missing access, assets, or outside input is blocking progress.' : 'A human choice is needed before this can move.'}'`);
      taskValues.push(blocker || summary || 'Codex needs a human decision before continuing.');
    }
    taskValues.push(updated.task_id);
    await db.query(
      `UPDATE bna_tasks SET ${taskFields.join(', ')} WHERE id = $${taskValues.length}`,
      taskValues
    );
    await recordTaskActivity(updated.task_id, `agent_job_${canonicalStatus}`, {
      actor,
      summary: summary || blocker || `Agent job #${updated.id} moved to ${canonicalStatus}.`,
      metadata: { agent_job_id: updated.id, ticket_id: updated.ticket_id || null, status: canonicalStatus, task_kind: ['blocked_needs_human_decision', 'failed'].includes(canonicalStatus) ? blockedTaskKind : null },
    }, db);
  }
  if (updated.ticket_id) {
    await db.query(
      `UPDATE bna_tickets
       SET status = $1,
           task_id = COALESCE(task_id, $2),
           related_task_id = COALESCE(related_task_id, $2),
           agent_job_id = COALESCE(agent_job_id, $3),
           current_blocker = CASE WHEN $1 IN ('needs_decision', 'failed') THEN COALESCE($4, current_blocker) ELSE current_blocker END,
           report_path = COALESCE($5, report_path),
           ledger_ref = COALESCE($6, ledger_ref),
           changelog_ref = COALESCE($7, changelog_ref),
           resolved_at = CASE WHEN $1 = 'done' THEN COALESCE(resolved_at, NOW()) ELSE resolved_at END,
           updated_at = NOW()
       WHERE id = $8`,
      [ticketStatus, updated.task_id || null, updated.id, blocker || null, reportPath || null, ledgerRef || null, changelogRef || null, updated.ticket_id]
    );
  }
  await appendAgentJobEvent(updated, `job_${canonicalStatus}`, {
    actor,
    status: canonicalStatus,
    summary: summary || blocker || `Job moved to ${canonicalStatus}.`,
    metadata: { report_path: reportPath || null, ledger_ref: ledgerRef || null, changelog_ref: changelogRef || null },
  }, db);
  return updated;
}

async function staleAgentJobCandidates(req, db = pool) {
  const queuedMinutes = Math.max(5, Number(process.env.BNA_CODEX_QUEUE_STALE_MINUTES || 20));
  const runningMinutes = Math.max(10, Number(process.env.BNA_CODEX_RUNNING_STALE_MINUTES || 45));
  const params = [queuedMinutes, runningMinutes];
  const conditions = [
    `(
      (j.status = 'queued' AND COALESCE(j.queued_at, j.created_at) < NOW() - ($1 * INTERVAL '1 minute'))
      OR
      (j.status = 'running' AND COALESCE(j.heartbeat_at, j.started_at, j.claimed_at, j.updated_at, j.created_at) < NOW() - ($2 * INTERVAL '1 minute'))
    )`,
  ];
  appendScopeCondition(req, conditions, params, 'COALESCE(t.project_id, bt.project_id)');
  const result = await db.query(
    `SELECT j.*,
            CASE
              WHEN j.status = 'queued' THEN 'Queued for Codex without claim heartbeat'
              ELSE 'Codex job in progress without a fresh heartbeat'
            END AS stale_reason,
            t.title AS task_title,
            bt.title AS ticket_title,
            p.project_key
     FROM bna_agent_jobs j
     LEFT JOIN bna_tasks t ON t.id = j.task_id
     LEFT JOIN bna_tickets bt ON bt.id = j.ticket_id
     LEFT JOIN bna_projects p ON p.id = COALESCE(t.project_id, bt.project_id)
     WHERE ${conditions.join(' AND ')}
     ORDER BY COALESCE(j.queued_at, j.created_at) ASC
     LIMIT 50`,
    params
  );
  return result.rows.map(observableAgentJobView);
}

async function buildCodexQueueSnapshot(req, { limit = 50 } = {}) {
  const jobs = await listObservableAgentJobs(req, { openOnly: true, limit });
  const staleCandidates = await staleAgentJobCandidates(req);
  const counts = jobs.reduce((acc, job) => {
    acc[job.status] = (acc[job.status] || 0) + 1;
    return acc;
  }, {});
  const ticketParams = [];
  const ticketConditions = [`bt.status IN ('open', 'created_ticket', 'classified', 'queued_for_codex', 'in_progress', 'blocked', 'needs_decision', 'failed')`];
  appendScopeCondition(req, ticketConditions, ticketParams, 'bt.project_id');
  ticketParams.push(25);
  const ticketRows = (await pool.query(
    `SELECT bt.*, p.project_key, p.name AS project_name, p.short_name AS project_short_name
     FROM bna_tickets bt
     LEFT JOIN bna_projects p ON p.id = bt.project_id
     WHERE ${ticketConditions.join(' AND ')}
     ORDER BY bt.updated_at DESC
     LIMIT $${ticketParams.length}`,
    ticketParams
  )).rows.map(observableTicketView);
  const latestTask = jobs.find((job) => job.task_id) || null;
  return {
    success: true,
    counts,
    queue: {
      pending: Number(counts.queued || 0),
      queued: Number(counts.queued || 0),
      in_progress: Number(counts.running || 0),
      running: Number(counts.running || 0),
      blocked: Number(counts.blocked_needs_human_decision || 0),
      blocked_needs_human_decision: Number(counts.blocked_needs_human_decision || 0),
      needs_decision: Number(counts.blocked_needs_human_decision || 0),
      failed: Number(counts.failed || 0),
      completed: Number(counts.completed || 0),
      latest_task: latestTask ? { id: latestTask.task_id, title: latestTask.task_title || latestTask.title, agent_job_id: latestTask.id, status: latestTask.status } : null,
      jobs,
      stale_candidates: staleCandidates,
    },
    tickets: ticketRows,
  };
}

async function listAgentRuns(req, filters = {}) {
  const params = [];
  const conditions = [];
  appendScopeCondition(req, conditions, params, 'COALESCE(r.project_id, t.project_id)');
  const status = filters.status ? normalizeAgentRunStatus(filters.status, null) : null;
  if (status) {
    params.push(status);
    conditions.push(`r.status = $${params.length}`);
  }
  const verificationMode = filters.verification_mode || filters.verificationMode
    ? normalizeVerificationMode(filters.verification_mode || filters.verificationMode, null)
    : null;
  if (verificationMode) {
    params.push(verificationMode);
    conditions.push(`r.verification_mode = $${params.length}`);
  }
  if (filters.task_id || filters.taskId) {
    params.push(Number(filters.task_id || filters.taskId));
    conditions.push(`r.task_id = $${params.length}`);
  }
  if (filters.workspace_id || filters.workspaceId) {
    params.push(Number(filters.workspace_id || filters.workspaceId));
    conditions.push(`r.workspace_id = $${params.length}`);
  }
  if (filters.openOnly || filters.open_only) {
    conditions.push(`r.status IN ('draft', 'ready', 'claimed', 'running', 'waiting_operator', 'submitted', 'blocked')`);
  }
  const limit = Math.max(1, Math.min(Number(filters.limit || 100), 250));
  params.push(limit);
  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  const result = await pool.query(
    `SELECT r.*,
            t.title AS task_title,
            t.display_title AS task_display_title,
            t.stage AS task_stage,
            t.implementation_status AS task_implementation_status,
            t.verification_status AS task_verification_status,
            t.required_verification_mode AS task_required_verification_mode,
            p.project_key,
            p.name AS project_name,
            p.short_name AS project_short_name,
            ap.agent_key,
            ap.display_name AS agent_display_name,
            ap.agent_type,
            ap.capabilities,
            COALESCE(artifact_counts.artifact_count, 0)::int AS artifact_count,
            COALESCE(event_counts.event_count, 0)::int AS event_count
     FROM bna_agent_runs r
     LEFT JOIN bna_tasks t ON t.id = r.task_id
     LEFT JOIN bna_projects p ON p.id = COALESCE(r.project_id, t.project_id)
     LEFT JOIN bna_agent_profiles ap ON ap.id = r.agent_profile_id
     LEFT JOIN (
       SELECT run_id, COUNT(*) AS artifact_count
       FROM bna_agent_run_artifacts
       GROUP BY run_id
     ) artifact_counts ON artifact_counts.run_id = r.id
     LEFT JOIN (
       SELECT run_id, COUNT(*) AS event_count
       FROM bna_agent_run_events
       GROUP BY run_id
     ) event_counts ON event_counts.run_id = r.id
     ${whereClause}
     ORDER BY
       CASE r.status
         WHEN 'ready' THEN 1
         WHEN 'claimed' THEN 2
         WHEN 'running' THEN 3
         WHEN 'waiting_operator' THEN 4
         WHEN 'submitted' THEN 5
         WHEN 'blocked' THEN 6
         WHEN 'sealed_fail' THEN 7
         WHEN 'sealed_pass' THEN 8
         ELSE 9
       END,
       r.updated_at DESC,
       r.created_at DESC
     LIMIT $${params.length}`,
    params
  );
  const runs = result.rows.map(agentRunView);
  const summary = runs.reduce((acc, run) => {
    acc[run.status] = (acc[run.status] || 0) + 1;
    return acc;
  }, {});
  return { runs, summary };
}

