app.get('/api/bna/agent-jobs/:id', requireAdmin, async (req, res) => {
  try {
    const job = await fetchObservableAgentJob(req.params.id);
    if (!job) return res.status(404).json({ error: 'Agent job not found' });
    assertProjectAccess(req, { project_key: job.project_key });
    const events = (await pool.query('SELECT * FROM bna_agent_job_events WHERE job_id = $1 ORDER BY created_at ASC', [req.params.id])).rows;
    const task = job.task_id ? await fetchTaskWithProject(job.task_id) : null;
    const ticket = job.ticket_id
      ? (await pool.query('SELECT * FROM bna_tickets WHERE id = $1', [job.ticket_id])).rows[0] || null
      : null;
    res.json({ success: true, job, task, ticket: observableTicketView(ticket), events });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.post('/api/bna/agent-jobs/:id/claim', requireAdmin, async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const claimed = (await client.query(
      `UPDATE bna_agent_jobs
       SET status = 'running',
           owner = COALESCE($2, owner, 'Codex'),
           claimed_at = COALESCE(claimed_at, NOW()),
           started_at = COALESCE(started_at, NOW()),
           heartbeat_at = NOW(),
           attempt_count = COALESCE(attempt_count, 0) + 1,
           updated_at = NOW()
       WHERE id = $1
         AND status = 'queued'
       RETURNING *`,
      [req.params.id, req.body?.owner || req.opsUser || 'Codex']
    )).rows[0] || null;
    if (!claimed) {
      const current = (await client.query('SELECT * FROM bna_agent_jobs WHERE id = $1', [req.params.id])).rows[0];
      await client.query('ROLLBACK');
      return res.status(current ? 409 : 404).json({ error: current ? `Job is ${current.status}, not queued.` : 'Agent job not found', job: current ? observableAgentJobView(current) : null });
    }
    await applyAgentJobLinkedStatus(claimed, 'running', {
      summary: `Codex started job #${claimed.id}.`,
      actor: req.opsUser || 'agent-fleet',
    }, client);
    await client.query('COMMIT');
    const job = await fetchObservableAgentJob(req.params.id);
    res.json({ success: true, job, task: job?.task_id ? await fetchTaskWithProject(job.task_id) : null });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/bna/agent-jobs/:id/heartbeat', requireAdmin, async (req, res) => {
  try {
    const result = await pool.query(
      `UPDATE bna_agent_jobs
       SET heartbeat_at = NOW(),
           current_blocker = COALESCE($2, current_blocker),
           metadata = COALESCE(metadata, '{}'::jsonb) || $3::jsonb,
           updated_at = NOW()
       WHERE id = $1
       RETURNING *`,
      [req.params.id, req.body?.current_blocker || req.body?.blocker || null, JSON.stringify(req.body?.metadata || {})]
    );
    const job = result.rows[0] || null;
    if (!job) return res.status(404).json({ error: 'Agent job not found' });
    await appendAgentJobEvent(job, 'heartbeat', {
      actor: req.opsUser || 'agent-fleet',
      status: job.status,
      summary: req.body?.summary || 'Codex heartbeat recorded.',
      metadata: req.body?.metadata || {},
    });
    res.json({ success: true, job: observableAgentJobView(job) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.post('/api/bna/agent-jobs/:id/result', requireAdmin, async (req, res) => {
  try {
    const job = await fetchObservableAgentJob(req.params.id);
    if (!job) return res.status(404).json({ error: 'Agent job not found' });
    assertProjectAccess(req, { project_key: job.project_key });
    const body = req.body || {};
    const workspaceKey = assertWorkspaceAccess(req, body.workspace_key || body.workspace || defaultWorkspaceKeyForRequest(req));
    const result = await runAction({
      action_id: 'record_agent_result',
      inputs: {
        ...body,
        agent_job_id: req.params.id,
        task_id: body.task_id || body.taskId || job.task_id || null,
      },
      source: body.source || 'agent_result_api',
      dry_run: Boolean(body.dry_run || body.dryRun),
      approved: true,
      actor: {
        user_id: req.opsUser || body.user_id || 'admin',
        role: body.actor_role || body.role || req.opsIdentity?.role || 'technical_agent',
        workspace_id: workspaceKey,
      },
    }, actionRunnerContext(req, body.source || 'agent_result_api'));
    res.status(result.success ? 200 : 400).json(result);
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});


