app.post('/api/bna/agent-jobs/:id/block', requireAdmin, async (req, res) => {
  try {
    const job = await fetchObservableAgentJob(req.params.id);
    if (!job) return res.status(404).json({ error: 'Agent job not found' });
    assertProjectAccess(req, { project_key: job.project_key });
    const requestedStatus = safeAgentJobStatus(req.body?.status || (req.body?.failed ? 'failed' : 'blocked_needs_human_decision'), 'blocked_needs_human_decision');
    const blockStatus = ['blocked_needs_human_decision', 'failed'].includes(requestedStatus) ? requestedStatus : 'blocked_needs_human_decision';
    const blocker = String(req.body?.blocker || req.body?.current_blocker || req.body?.summary || 'Codex needs a human decision before continuing.').slice(0, 4000);
    const updated = await applyAgentJobLinkedStatus(job, blockStatus, {
      summary: req.body?.summary || blocker,
      blocker,
      resultPayload: req.body?.result_payload || req.body?.resultPayload || {},
      reportPath: req.body?.report_path || req.body?.reportPath || null,
      ledgerRef: req.body?.ledger_ref || req.body?.ledgerRef || null,
      changelogRef: req.body?.changelog_ref || req.body?.changelogRef || null,
      actor: req.opsUser || 'agent-fleet',
    });
    res.json({ success: true, job: observableAgentJobView(updated) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

async function staleSweepRoute(req, res) {
  try {
    const dryRun = req.method === 'GET' || req.body?.dry_run !== false && req.body?.dryRun !== false;
    const candidates = await staleAgentJobCandidates(req);
    if (!dryRun) {
      for (const job of candidates) {
        // eslint-disable-next-line no-await-in-loop
        await applyAgentJobLinkedStatus(job, 'blocked_needs_human_decision', {
          blocker: job.stale_reason || 'Codex job went stale without a fresh heartbeat.',
          summary: job.stale_reason || 'Stale Codex job blocked by detector.',
          actor: req.opsUser || 'stale-detector',
        });
      }
    }
    res.json({ success: true, dry_run: dryRun, stale_jobs: candidates, updated: dryRun ? 0 : candidates.length });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
}

