app.get('/api/bna/automations/:id', requireAdmin, async (req, res) => {
  try {
    const automation = await fetchAutomationById(req, req.params.id);
    if (!automation) return res.status(404).json({ error: 'Automation was not found' });
    const runs = (await pool.query(
      `SELECT *
       FROM bna_automation_runs
       WHERE automation_id = $1
       ORDER BY COALESCE(completed_at, started_at, created_at) DESC
       LIMIT 30`,
      [automation.id]
    )).rows.map((run) => ({
      ...run,
      metadata: automationJsonObject(run.metadata),
    }));
    const relatedTaskIds = automation.related_task_ids || [];
    let relatedTasks = [];
    if (relatedTaskIds.length) {
      const params = [relatedTaskIds];
      let query = `
        SELECT t.id, t.title, t.display_title, t.summary, t.stage, t.task_kind, t.status_detail,
               t.assigned_to, t.waiting_on, t.updated_at, p.project_key, p.name AS project_name
        FROM bna_tasks t
        LEFT JOIN bna_projects p ON p.id = t.project_id
        WHERE t.id = ANY($1::int[])`;
      const scopedProjectKey = opsScopeProjectKey(req);
      if (scopedProjectKey) {
        params.push(scopedProjectKey);
        query += ` AND p.project_key = $2`;
      }
      query += ` ORDER BY t.updated_at DESC, t.id DESC`;
      relatedTasks = (await pool.query(query, params)).rows.map(taskApiView);
    }
    res.json({
      success: true,
      automation,
      runs,
      related_tasks: relatedTasks,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.patch('/api/bna/automations/:id', requireAdmin, async (req, res) => {
  try {
    if (req.opsIdentity?.scope?.type === 'project') {
      return res.status(403).json({ error: 'Scoped Operations users can read automation metadata but cannot edit it.' });
    }
    const automation = await fetchAutomationById(req, req.params.id);
    if (!automation) return res.status(404).json({ error: 'Automation was not found' });

    const body = req.body || {};
    const updates = [];
    const params = [];
    const addUpdate = (field, value, cast = '') => {
      params.push(value);
      updates.push(`${field} = $${params.length}${cast}`);
    };

    for (const field of AUTOMATION_PATCH_FIELDS) {
      if (!Object.prototype.hasOwnProperty.call(body, field)) continue;
      const value = body[field];
      if (['name', 'summary', 'description', 'package_name', 'service_name', 'owner', 'responsible_person', 'trigger_label', 'audience'].includes(field)) {
        const max = field === 'description' ? 4000 : field === 'summary' || field === 'audience' ? 900 : 180;
        addUpdate(field, limitText(value, max) || null);
      } else if (['package_key', 'service_key', 'trigger_type', 'channel'].includes(field)) {
        addUpdate(field, automationSlug(value, '') || null);
      } else if (field === 'scope_type') {
        addUpdate(field, safeAutomationScopeType(value));
      } else if (field === 'status') {
        addUpdate(field, safeAutomationStatus(value));
      } else if (field === 'automation_type') {
        addUpdate(field, safeAutomationType(value));
      } else if (field === 'project_id') {
        const projectId = Number(value);
        addUpdate(field, Number.isFinite(projectId) && projectId > 0 ? projectId : null);
      } else if (field === 'permissions' || field === 'metadata') {
        addUpdate(field, JSON.stringify(automationJsonObject(value)), '::jsonb');
      } else if (field === 'setup_blockers') {
        addUpdate(field, JSON.stringify(toJsonArray(value).map((item) => limitText(item, 300))), '::jsonb');
      } else if (field === 'related_task_ids') {
        addUpdate(field, JSON.stringify(numberArray(value)), '::jsonb');
      } else if (field === 'next_run_at') {
        const raw = String(value || '').trim();
        const parsed = raw ? new Date(raw) : null;
        addUpdate(field, parsed && Number.isFinite(parsed.getTime()) ? parsed.toISOString() : null);
      }
    }

    if (!updates.length) return res.status(400).json({ error: 'No safe automation metadata fields were supplied' });
    addUpdate('updated_by', limitText(req.opsUser || 'dashboard', 120) || 'dashboard');
    params.push(automation.id);
    const result = await pool.query(
      `UPDATE bna_automations
       SET ${updates.join(', ')},
           updated_at = NOW()
       WHERE id = $${params.length}
       RETURNING id`,
      params
    );
    const updated = result.rows[0] ? await fetchAutomationById(req, result.rows[0].id) : null;
    res.json({ success: true, automation: updated });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

