app.get('/api/bna/courses', requireAdmin, async (req, res) => {
  try {
    await ensureWs11CommunityFoundation();
    const projectKey = requestedProjectKeyForScopedList(req);
    const params = [];
    const conditions = [`c.status <> 'archived'`];
    if (projectKey) {
      params.push(projectKey);
      conditions.push(`c.project_key = $${params.length}`);
    }
    if (req.query.community_id) {
      params.push(Number(req.query.community_id));
      conditions.push(`c.community_id = $${params.length}`);
    }
    const result = await pool.query(
      `SELECT c.*,
              COUNT(DISTINCT l.id)::int AS lesson_count,
              COUNT(DISTINCT w.id)::int AS worksheet_count,
              COALESCE(
                json_agg(
                  json_build_object(
                    'id', e.id,
                    'student_id', e.student_id,
                    'status', e.status,
                    'progress_percent', e.progress_percent,
                    'points_total', e.points_total
                  )
                ) FILTER (WHERE e.id IS NOT NULL),
                '[]'
              ) AS enrollments
       FROM bna_courses c
       LEFT JOIN bna_course_lessons l ON l.course_id = c.id AND l.status <> 'archived'
       LEFT JOIN bna_worksheets w ON w.course_id = c.id AND w.status <> 'archived'
       LEFT JOIN bna_course_enrollments e ON e.course_id = c.id AND e.status <> 'archived'
       WHERE ${conditions.join(' AND ')}
       GROUP BY c.id
       ORDER BY c.sort_order ASC, c.id ASC`,
      params
    );
    res.json({ success: true, courses: result.rows.map(ws11CourseView) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

