app.get('/api/bna/worksheets', requireAdmin, async (req, res) => {
  try {
    const params = [];
    const conditions = [`w.status <> 'archived'`];
    const projectKey = requestedProjectKeyForScopedList(req);
    if (projectKey) {
      params.push(projectKey);
      conditions.push(`c.project_key = $${params.length}`);
    }
    if (req.query.course_id) {
      params.push(Number(req.query.course_id));
      conditions.push(`w.course_id = $${params.length}`);
    }
    if (req.query.lesson_id) {
      params.push(Number(req.query.lesson_id));
      conditions.push(`w.lesson_id = $${params.length}`);
    }
    const worksheets = (await pool.query(
      `SELECT w.*
       FROM bna_worksheets w
       LEFT JOIN bna_courses c ON c.id = w.course_id
       WHERE ${conditions.join(' AND ')}
       ORDER BY w.updated_at DESC, w.id DESC
       LIMIT 200`,
      params
    )).rows;
    const ids = worksheets.map((row) => Number(row.id)).filter(Number.isFinite);
    const questions = ids.length ? (await pool.query(
      `SELECT *
       FROM bna_worksheet_questions
       WHERE worksheet_id = ANY($1::int[])
       ORDER BY worksheet_id ASC, sort_order ASC, id ASC`,
      [ids]
    )).rows : [];
    const byWorksheet = new Map();
    for (const question of questions) {
      const key = Number(question.worksheet_id);
      if (!byWorksheet.has(key)) byWorksheet.set(key, []);
      byWorksheet.get(key).push(question);
    }
    res.json({
      success: true,
      worksheets: worksheets.map((worksheet) => ws11WorksheetView(worksheet, byWorksheet.get(Number(worksheet.id)) || [])),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

