app.post('/api/bna/gamification-events/backfill', requireAdmin, async (req, res) => {
  const limit = Math.max(1, Math.min(Number((req.body || {}).limit || 200), 1000));
  try {
    const rows = (await pool.query(
      `SELECT *
       FROM bna_accountability_events
       WHERE student_id IS NOT NULL
         AND event_type IN ('question', 'student_goal', 'class_session', 'learning_note')
       ORDER BY occurred_at DESC, id DESC
       LIMIT $1`,
      [limit]
    )).rows;
    const created = [];
    for (const row of rows) {
      const metadata = eventMetadata(row);
      let eventType = normalizeGamificationEventType(row.event_type);
      if (row.event_type === 'student_goal' && Number(row.progress_percent || 0) < 100) continue;
      if (row.event_type === 'class_session' && !['present', 'attended', 'late'].includes(String(row.attendance_status || metadata.attendance_status || '').toLowerCase())) continue;
      if (row.event_type === 'learning_note' && !/source|sheet|review/i.test(`${row.topic || ''} ${row.title || ''} ${row.notes || ''}`)) eventType = 'source_reviewed';
      const event = await createGamificationEvent({
        student_id: row.student_id,
        event_type: eventType,
        title: row.title || row.question_text || eventType.replace(/_/g, ' '),
        notes: row.notes || '',
        visibility: eventType === 'parent_visible_milestone' ? 'student_parent' : 'student',
        parent_visible: eventType === 'parent_visible_milestone',
        approval_status: 'approved',
        source: 'accountability_backfill',
        source_ref: `bna_accountability_events:${row.id}`,
        idempotency_key: `${eventType}:student_${row.student_id}:accountability_${row.id}`,
        occurred_at: row.occurred_at || row.created_at,
        metadata: { accountability_event_id: row.id, legacy_event_type: row.event_type },
      });
      created.push(ws11GamificationEventView(event));
    }
    res.json({ success: true, considered: rows.length, mirrored: created.length, events: created });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

