function parentAnnouncementView(row = {}) {
  const update = weeklyUpdateView(row);
  if (!update) return null;
  return {
    ...update,
    announcement_type: 'parent',
    approved_for_parent_portal: Boolean(update.selected_for_parent_portal),
    no_send: true,
    external_write_performed: false,
  };
}

async function getParentAnnouncementRows(workspaceKey, limit = 20, db = pool) {
  const result = await db.query(
    `SELECT *
     FROM bna_weekly_updates
     WHERE workspace_key = $1
       AND status <> 'archived'
     ORDER BY selected_for_parent_portal DESC, week_start DESC NULLS LAST, created_at DESC, id DESC
     LIMIT $2`,
    [workspaceKey, Math.max(1, Math.min(Number(limit || 20), 80))]
  );
  return result.rows;
}

async function buildParentAnnouncementRecipientPreview({ req, workspaceKey } = {}, db = pool) {
  const normalizedWorkspace = normalizeWorkspaceKey(workspaceKey) || 'bna';
  const projectKey = workspaceProjectKey(normalizedWorkspace);
  const project = await getProjectByKey(
    projectKey && !['super_admin', 'dratler_family'].includes(projectKey)
      ? projectKey
      : DEFAULT_PROJECT_KEY,
    db
  );
  assertProjectAccess(req, project);
  const fallbackProjectId = normalizeProjectKey(project.project_key) === DEFAULT_PROJECT_KEY ? project.id : -1;
  const [studentsResult, signupsResult] = await Promise.all([
    db.query(
      `SELECT id, name, parent_name, parent_email, parent_phone, current_school, tags, status, project_id
       FROM bna_students
       WHERE COALESCE(project_id, $2) = $1
         AND COALESCE(status, 'active') NOT IN ('inactive', 'archived')
       ORDER BY lower(name), id`,
      [project.id, fallbackProjectId]
    ),
    db.query(
      `SELECT id, parent_name, parent_email, parent_phone, parent2_name, parent2_email, parent2_phone,
              student_name, status, form_language, project_id, created_at, updated_at
       FROM signups
       WHERE COALESCE(project_id, $2) = $1
         AND COALESCE(status, 'new') <> 'archived'
       ORDER BY updated_at DESC NULLS LAST, created_at DESC, id DESC`,
      [project.id, fallbackProjectId]
    ),
  ]);

  const recipientsByEmail = new Map();
  const missingStudentEmail = [];
  const excludedExternalStudents = [];
  const duplicateEmailRecords = [];
  const reviewOnlySignupCandidates = [];
  const spousePolicyReviewCandidates = [];

  const addRecipient = (emailValue, row, sourceType) => {
    const email = normalizeEmail(emailValue);
    if (!email) return null;
    const sourceRecord = {
      type: sourceType,
      id: row.id,
      student_name: row.student_name || row.name || '',
      parent_name: row.parent_name || '',
      status: row.status || '',
    };
    if (!recipientsByEmail.has(email)) {
      recipientsByEmail.set(email, {
        parent_email: email,
        parent_name: row.parent_name || '',
        parent_phone: row.parent_phone || '',
        student_names: [],
        source_records: [],
        preferred_language: row.form_language || '',
        send_status: 'preview_only_not_sent',
      });
    } else {
      duplicateEmailRecords.push(sourceRecord);
    }
    const recipient = recipientsByEmail.get(email);
    if (!recipient.parent_name && row.parent_name) recipient.parent_name = row.parent_name;
    if (!recipient.parent_phone && row.parent_phone) recipient.parent_phone = row.parent_phone;
    if (!recipient.preferred_language && row.form_language) recipient.preferred_language = row.form_language;
    const studentName = row.student_name || row.name || '';
    if (studentName && !recipient.student_names.includes(studentName)) recipient.student_names.push(studentName);
    recipient.source_records.push(sourceRecord);
    return recipient;
  };

  for (const student of studentsResult.rows) {
    if (studentIsExternalAccountabilityPerson(student)) {
      excludedExternalStudents.push({
        id: student.id,
        student_name: student.name || '',
        reason: 'external_accountability_student',
      });
      continue;
    }
    if (!normalizeEmail(student.parent_email)) {
      missingStudentEmail.push({
        id: student.id,
        student_name: student.name || '',
        parent_name: student.parent_name || '',
        reason: 'missing_parent_email',
      });
      continue;
    }
    addRecipient(student.parent_email, student, 'student');
  }

  for (const signup of signupsResult.rows) {
    const primaryEmail = normalizeEmail(signup.parent_email);
    if (primaryEmail && !recipientsByEmail.has(primaryEmail)) {
      reviewOnlySignupCandidates.push({
        signup_id: signup.id,
        parent_email: primaryEmail,
        parent_name: signup.parent_name || '',
        student_name: signup.student_name || '',
        status: signup.status || 'new',
        reason: 'signup_parent_not_current_student_recipient',
      });
    }
    const spouseEmail = normalizeEmail(signup.parent2_email);
    if (spouseEmail && !recipientsByEmail.has(spouseEmail)) {
      spousePolicyReviewCandidates.push({
        signup_id: signup.id,
        parent_email: spouseEmail,
        parent_name: signup.parent2_name || signup.parent_name || '',
        student_name: signup.student_name || '',
        status: signup.status || 'new',
        reason: 'spouse_or_second_parent_policy_not_confirmed',
      });
    }
  }

  const recipients = Array.from(recipientsByEmail.values())
    .sort((a, b) => (a.parent_name || a.parent_email).localeCompare(b.parent_name || b.parent_email))
    .map((recipient) => ({
      ...recipient,
      student_names: recipient.student_names.slice(0, 8),
      source_records: recipient.source_records.slice(0, 8),
    }));

  return {
    success: true,
    dry_run: true,
    no_send: true,
    local_write_performed: false,
    external_write_performed: false,
    workspace_key: normalizedWorkspace,
    project_key: project.project_key,
    project_id: project.id,
    audience: 'current_bna_student_parents',
    send_enabled: false,
    send_blocked_reason: 'Weekly update test-send/live-send rules, recipient policy, copy, media, and approval phrase are not enabled from this preview.',
    future_confirm_required: 'APPROVE_PARENT_WEEKLY_UPDATE_SEND',
    summary: {
      eligible_recipients: recipients.length,
      active_student_records: studentsResult.rows.length - excludedExternalStudents.length,
      missing_student_parent_email: missingStudentEmail.length,
      excluded_external_students: excludedExternalStudents.length,
      review_only_signup_candidates: reviewOnlySignupCandidates.length,
      spouse_policy_review_candidates: spousePolicyReviewCandidates.length,
      duplicate_email_records: duplicateEmailRecords.length,
    },
    recipients,
    review_only_signup_candidates: reviewOnlySignupCandidates.slice(0, 40),
    spouse_policy_review_candidates: spousePolicyReviewCandidates.slice(0, 40),
    missing_student_email: missingStudentEmail.slice(0, 40),
    excluded_external_students: excludedExternalStudents.slice(0, 40),
    duplicate_email_records: duplicateEmailRecords.slice(0, 40),
  };
}

