async function createOrUpdateUniversalStudentGoal({ actor, body, message, thread, context, userMessage, db = pool }) {
  const actionName = body.action_alias || 'create_or_update_student_goal';
  const studentId = Number(context.student?.id || body.student_id || body.studentId || actor.student_id || actor.id || 0);
  assertAssistantPermission(actor, actionName, { student_id: studentId });
  if (!studentId) {
    return universalAssistantToolResult(actionName, { ok: false, status: 'needs_clarification', reply: 'Choose a student before saving a goal.' });
  }
  const title = limitText(body.title || body.goal || universalAssistantFirstLine(message, ''), 220);
  if (!title) {
    return universalAssistantToolResult(actionName, { ok: false, status: 'needs_clarification', reply: 'I need the goal title before I can save it.' });
  }
  const student = context.student || (await db.query('SELECT * FROM bna_students WHERE id = $1 LIMIT 1', [studentId])).rows[0];
  if (!student) {
    return universalAssistantToolResult(actionName, { ok: false, status: 'failed', reply: 'The student was not found.' });
  }
  const accountabilityEvent = (await db.query(
    `INSERT INTO bna_accountability_events (
       event_type, student_id, student_name, title, notes, topic,
       goal_target_value, goal_actual_value, goal_unit, progress_percent,
       follow_up_required, metadata, source, occurred_at
     ) VALUES (
       'student_goal', $1, $2, $3, $4, $5,
       $6, NULL, $7, 0,
       TRUE, $8::jsonb, 'universal_assistant', NOW()
     )
     RETURNING *`,
    [
      student.id,
      student.name,
      title,
      body.description || body.notes || message,
      body.category || body.topic || null,
      body.target_value || body.targetValue || null,
      body.target_unit || body.targetUnit || null,
      JSON.stringify({ source: 'universal_assistant', assistant_thread_id: thread.id, actor_type: actor.type }),
    ]
  )).rows[0];
  const goal = (await db.query(
    `INSERT INTO bna_student_goals (
       workspace_id, household_id, student_id, title, description, category, target_value, target_unit,
       progress_percent, due_date, status, visibility, source_event_id, metadata
     ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 0, $9, 'active', $10, $11, $12::jsonb)
     RETURNING *`,
    [
      context.workspace?.id || null,
      context.household?.id || null,
      student.id,
      title,
      body.description || body.notes || message,
      body.category || body.topic || null,
      body.target_value || body.targetValue || null,
      body.target_unit || body.targetUnit || null,
      safeIsoDateInput(body.due_date || body.dueDate),
      actor.type === 'student' ? 'student' : 'family',
      accountabilityEvent.id,
      JSON.stringify({ source: 'universal_assistant', accountability_event_id: accountabilityEvent.id }),
    ]
  )).rows[0];
  const action = await recordUniversalAssistantAction({
    thread,
    message: userMessage,
    actor,
    actionType: actionName,
    targetType: 'student_goal',
    targetId: goal.id,
    payload: { student_id: student.id, title },
    result: { goal_id: goal.id, accountability_event_id: accountabilityEvent.id },
    db,
  });
  return universalAssistantToolResult(actionName, { action, goal, accountability_event: accountabilityEvent });
}

async function logUniversalCheckInProgress({ actor, body, message, thread, context, userMessage, db = pool }) {
  const actionName = body.action_alias || 'log_check_in_progress';
  const studentId = Number(context.student?.id || body.student_id || body.studentId || actor.student_id || actor.id || 0);
  assertAssistantPermission(actor, actionName, { student_id: studentId });
  if (!studentId) {
    return universalAssistantToolResult(actionName, { ok: false, status: 'needs_clarification', reply: 'Choose a student before logging progress.' });
  }
  const progressPercent = Number.isFinite(Number(body.progress_percent ?? body.progressPercent))
    ? Math.max(0, Math.min(100, Number(body.progress_percent ?? body.progressPercent)))
    : null;
  const title = limitText(body.title || 'Assistant check-in progress', 220);
  const event = (await db.query(
    `INSERT INTO bna_accountability_events (
       event_type, student_id, student_name, title, notes, topic,
       goal_actual_value, goal_unit, progress_percent, follow_up_required, metadata, source, occurred_at
     ) VALUES ('check_in_progress', $1, $2, $3, $4, $5, $6, $7, $8, TRUE, $9::jsonb, 'universal_assistant', NOW())
     RETURNING *`,
    [
      studentId,
      context.student?.name || actor.name || 'Student',
      title,
      message,
      body.category || body.topic || null,
      body.actual_value || body.actualValue || null,
      body.unit || body.goal_unit || body.goalUnit || null,
      progressPercent,
      JSON.stringify({ source: 'universal_assistant', goal_id: body.goal_id || body.goalId || null, actor_type: actor.type }),
    ]
  )).rows[0];
  if ((body.goal_id || body.goalId) && progressPercent !== null) {
    await db.query(
      `UPDATE bna_student_goals
       SET progress_percent = $2,
           progress_value = COALESCE($3, progress_value),
           status = CASE WHEN $2 >= 100 THEN 'done' ELSE status END,
           updated_at = NOW()
       WHERE id = $1
         AND student_id = $4`,
      [body.goal_id || body.goalId, progressPercent, body.actual_value || body.actualValue || null, studentId]
    );
  }
  const action = await recordUniversalAssistantAction({
    thread,
    message: userMessage,
    actor,
    actionType: actionName,
    targetType: 'accountability_event',
    targetId: event.id,
    payload: { student_id: studentId, progress_percent: progressPercent },
    result: { accountability_event_id: event.id },
    db,
  });
  return universalAssistantToolResult(actionName, { action, event });
}

