async function showUniversalAccessPaymentStatus({ actor, body, thread, context, userMessage, db = pool }) {
  const actionName = body.action_alias || 'show_access_payment_status';
  assertAssistantPermission(actor, actionName, {});
  const result = await db.query(
    `SELECT
       COUNT(*)::int AS signup_count,
       COUNT(*) FILTER (WHERE payment_status IN ('paid', 'completed'))::int AS paid_count,
       COUNT(*) FILTER (WHERE payment_status IS NULL OR payment_status NOT IN ('paid', 'completed'))::int AS unpaid_or_unknown_count
     FROM signups
     WHERE COALESCE(project_id, $1) = $1`,
    [context.project.id]
  );
  const paymentRows = await db.query(
    `SELECT status, COUNT(*)::int AS count, COALESCE(SUM(amount), 0)::numeric AS amount
     FROM bna_payment_log
     GROUP BY status
     ORDER BY status`
  ).catch(() => ({ rows: [] }));
  const payload = { signups: result.rows[0] || {}, payment_log: paymentRows.rows };
  const action = await recordUniversalAssistantAction({
    thread,
    message: userMessage,
    actor,
    actionType: actionName,
    targetType: 'payment_status',
    status: 'completed',
    payload: { project_id: context.project.id },
    result: payload,
    db,
  });
  return universalAssistantToolResult(actionName, { action, payment_status: payload });
}

async function showUniversalAgentStatus({ req, actor, thread, userMessage, db = pool }) {
  assertAssistantPermission(actor, 'show_agent_status', {});
  const statusReq = Object.create(req || {});
  statusReq.opsUser = actor.id || actor.name || 'assistant';
  statusReq.opsIdentity = req?.opsIdentity || identifyOpsUser(actor.id || OPS_USERNAME);
  const snapshot = await buildCodexQueueSnapshot(statusReq, { limit: 12 });
  let ledgerTail = '';
  let changelogTail = '';
  try {
    ledgerTail = fs.existsSync(path.join(__dirname, 'ops', 'agent-task-ledger.jsonl'))
      ? fs.readFileSync(path.join(__dirname, 'ops', 'agent-task-ledger.jsonl'), 'utf8').trim().split(/\r?\n/).slice(-5).join('\n')
      : '';
  } catch {}
  try {
    changelogTail = fs.existsSync(path.join(__dirname, 'ops', 'agent-changelog.md'))
      ? fs.readFileSync(path.join(__dirname, 'ops', 'agent-changelog.md'), 'utf8').trim().split(/\r?\n/).slice(-18).join('\n')
      : '';
  } catch {}
  const result = {
    queue: snapshot.queue,
    counts: snapshot.counts,
    tickets: snapshot.tickets,
    ledger_tail: ledgerTail,
    changelog_tail: changelogTail,
  };
  const action = await recordUniversalAssistantAction({
    thread,
    message: userMessage,
    actor,
    actionType: 'show_agent_status',
    targetType: 'agent_status',
    status: 'completed',
    result,
    db,
  });
  return universalAssistantToolResult('show_agent_status', { action, agent_status: result });
}

async function refuseUniversalPublicTier3Action({ actor, body, message, thread, userMessage, db = pool }) {
  const reply = publicAssistantTier3UnsafeActionReply(body, actor);
  const metadata = publicAssistantTier3UnsafeActionMetadata(body);
  const action = await recordUniversalAssistantAction({
    thread,
    message: userMessage,
    actor,
    actionType: 'public_tier3_action_refused',
    status: 'denied',
    payload: {
      tier: metadata.tier,
      page_path: metadata.page_path,
      surface: metadata.surface,
      message_length: String(message || '').length,
    },
    result: {
      ...metadata,
      reply,
    },
    db,
  });
  return universalAssistantToolResult('public_tier3_action_refused', {
    ok: false,
    status: 'denied',
    action,
    reply,
    ...metadata,
  });
}

function universalAssistantArgsWithAlias(args = {}, actionAlias = '') {
  return {
    ...args,
    body: {
      ...(args.body || {}),
      action_alias: actionAlias,
    },
  };
}

