const UNIVERSAL_ASSISTANT_TOOLS = {
  public_tier3_action_refused: refuseUniversalPublicTier3Action,
  create_ticket: createUniversalAssistantTicket,
  create_task: createUniversalAssistantTask,
  create_codex_job: createUniversalAssistantCodexJob,
  create_or_update_person: createOrUpdateUniversalPerson,
  create_or_update_household: createOrUpdateUniversalHousehold,
  create_or_update_student_goal: createOrUpdateUniversalStudentGoal,
  create_student_goal: createUniversalStudentGoal,
  log_check_in_progress: logUniversalCheckInProgress,
  log_student_checkin: logUniversalStudentCheckin,
  create_provider_profile_item: createUniversalProviderProfileItem,
  upload_or_link_content: uploadOrLinkUniversalContent,
  create_content_link: createUniversalContentLink,
  create_class: createUniversalClass,
  create_class_session: createUniversalClassSession,
  add_class_material_url: addUniversalClassMaterialUrl,
  add_worksheet_or_media_url: addUniversalWorksheetOrMediaUrl,
  ask_provider_question: askUniversalProviderQuestion,
  show_access_payment_status: showUniversalAccessPaymentStatus,
  show_access_status: showUniversalAccessStatus,
  show_payment_status: showUniversalPaymentStatus,
  show_agent_status: showUniversalAgentStatus,
};

function planUniversalAssistantActions(message = '', actor = {}, body = {}, context = {}) {
  if (!assistantRoleCanUseCodex(actor) && publicAssistantTier3UnsafeActionRequest(message)) {
    return ['public_tier3_action_refused'];
  }
  const explicitTool = String(body.tool || body.action || body.action_type || body.actionType || '').trim();
  if (explicitTool && UNIVERSAL_ASSISTANT_TOOLS[explicitTool]) return [explicitTool];
  const text = String(message || '').toLowerCase();
  if (/\b(what did codex do|codex status|agent status|what is codex doing|queue status|stale jobs?|running jobs?)\b/.test(text)) return ['show_agent_status'];
  if (/\b(payment status|who paid|tuition status|signup payment)\b/.test(text)) return ['show_payment_status'];
  if (/\b(access status|login status|grant status)\b/.test(text)) return ['show_access_status'];
  if (/\b(add|create|set|make|save)\b/.test(text) && /\b(goal|commitment|accountability)\b/.test(text)) return ['create_student_goal'];
  if (/\b(log|check[ -]?in|progress|completed|done)\b/.test(text) && /\b(goal|progress|check[ -]?in|today|finished)\b/.test(text)) return ['log_student_checkin'];
  if (/\b(add|attach|save|link)\b/.test(text) && /\b(worksheet|source sheet|material|url|link|media)\b/.test(text) && (context.class_session?.id || body.class_session_id || body.classSessionId)) return ['add_worksheet_or_media_url'];
  if (/\b(create|add|save)\b/.test(text) && /\b(class|session|shiur|lesson)\b/.test(text)) return ['create_class'];
  if (/\b(upload|link|recording|transcript|content|drive|video)\b/.test(text)) return ['create_content_link'];
  if (/\b(provider|profile|bio|service|faq|testimonial)\b/.test(text) && /\b(add|save|update|create)\b/.test(text)) return ['create_provider_profile_item'];
  if (/\b(question for provider|ask provider|provider question)\b/.test(text)) return ['ask_provider_question'];
  if (/\b(codex job|queue codex|coding job|system job)\b/.test(text) && assistantRoleCanUseCodex(actor)) return ['create_codex_job'];
  if (/\b(task|todo|to do|remind|assign)\b/.test(text) && assistantRoleCanUseCodex(actor)) return ['create_task'];
  if (/\b(ticket|issue|problem|bug|broken|stuck|not working|fix|codex|deploy|build|database|server|api|route|ui)\b/.test(text)) return ['create_ticket'];
  if (actor.type === 'student') return ['create_ticket'];
  return [];
}

function universalAssistantReply({ actor = {}, actions = [], language = 'en', message = '' } = {}) {
  const primary = actions.find((action) => action?.ok !== false) || actions[0] || null;
  if (!primary) {
    return actor.type === 'student'
      ? 'I can help save a goal, log progress, or send a clear help ticket. Tell me what changed or what is stuck.'
      : `${assistantIntroForRole(actor)} I can save scoped BNA records, create tickets, and show allowed status. Tell me the concrete thing to record or fix.`;
  }
  if (primary.ok === false) {
    return primary.reply || `I did not complete ${String(primary.action_name || primary.action_type || 'that action').replace(/_/g, ' ')}. ${primary.error || primary.summary || 'The backend action returned a failure.'}`;
  }
  if (primary.reply) return primary.reply;
  if (primary.action_type === 'show_agent_status') {
    const counts = primary.agent_status?.queue || {};
    return `Codex queue: ${Number(counts.queued || counts.pending || 0)} queued, ${Number(counts.running || counts.in_progress || 0)} running, ${Number(counts.blocked || counts.needs_decision || 0)} blocked, ${Number(counts.failed || 0)} failed.`;
  }
  if (['show_access_payment_status', 'show_access_status', 'show_payment_status'].includes(primary.action_type)) {
    const signups = primary.payment_status?.signups || {};
    return `Payment/access snapshot: ${Number(signups.paid_count || 0)} paid, ${Number(signups.unpaid_or_unknown_count || 0)} unpaid or unknown, ${Number(signups.signup_count || 0)} signup records.`;
  }
  if (primary.action_type === 'create_ticket') {
    const ticketId = primary.ticket?.id || primary.ticket?.ticket_id || primary.action?.target_id;
    const taskId = primary.task?.id || primary.action?.result?.task_id;
    if (primary.queued_codex) return `Created ticket #${ticketId} and queued Codex task #${taskId}. I will track it in the agent queue.`;
    return `Created ticket #${ticketId}. It is saved for review without giving this chat any extra access.`;
  }
  if (primary.action_type === 'create_task') return `Created task #${primary.task?.id || primary.action?.target_id}.`;
  if (primary.action_type === 'create_codex_job') return `Created Codex job #${primary.agent_job?.id || primary.created_object_id || 'pending'} from task #${primary.task?.id || primary.data?.task_id || 'unknown'}.`;
  if (['create_or_update_student_goal', 'create_student_goal'].includes(primary.action_type)) return `Saved student goal #${primary.goal?.id || primary.action?.target_id}.`;
  if (['log_check_in_progress', 'log_student_checkin'].includes(primary.action_type)) return `Logged progress event #${primary.event?.id || primary.action?.target_id}.`;
  if (['create_class_session', 'create_class'].includes(primary.action_type)) return `Created class session #${primary.class_session?.id || primary.action?.target_id}.`;
  if (['add_class_material_url', 'add_worksheet_or_media_url'].includes(primary.action_type)) return `Saved class material #${primary.material?.id || primary.action?.target_id}.`;
  if (['upload_or_link_content', 'create_content_link'].includes(primary.action_type)) return `Saved content job #${primary.content_job?.id || primary.action?.target_id}.`;
  if (primary.action_type === 'create_provider_profile_item') return `Saved provider profile item #${primary.item?.id || primary.action?.target_id}.`;
  if (primary.action_type === 'ask_provider_question') return `Saved provider question #${primary.provider_question?.id || primary.action?.target_id}.`;
  return 'Saved the requested assistant action.';
}

async function handleUniversalAssistantMessage(req, res, options = {}) {
  const body = req.body || {};
  const messageText = limitText(body.message || body.body || body.text || '', 8000);
  if (!messageText) return res.status(400).json({ error: 'message is required' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const actor = options.actorOverride || await resolveAssistantActor(req, body, client);
    const language = detectLanguage(messageText, body.language || body.lang || actor.language || 'en');
    const context = options.contextOverride || await loadAssistantContext(actor, body.context || body, client);
    const actorType = safeAssistantActorType(actor.type);
    const requestPagePath = body.page_path || body.path || body.context?.path || body.context?.page_path || null;
    const { thread, project } = await ensureUniversalAssistantThread({ actor, body: { ...body, language }, context, db: client });
    const userMessage = await insertUniversalAssistantMessage({
      threadId: thread.id,
      senderType: actor.type || 'anonymous',
      authorType: 'user',
      authorRole: actor.role || actor.type,
      content: messageText,
      language,
      metadata: {
        page_path: actorType === 'developer_tester' ? limitText(redactValue(requestPagePath), 700) : requestPagePath,
        surface: normalizeAssistantSurface(body.surface || body.page || body.context?.surface),
        mode: universalAssistantModeForActor(actor, body),
        student_portal: Boolean(options.studentPortal),
      },
      rawRequest: {
        has_context: Boolean(body.context),
        action: body.action || body.tool || null,
        access_code_supplied: Boolean(body.access_code || body.accessCode || body.code),
      },
      db: client,
    });
    const plannedActions = planUniversalAssistantActions(messageText, actor, body, context);
    const results = [];
    if (!plannedActions.length) {
      await recordUniversalAssistantAction({
        thread,
        message: userMessage,
        actor,
        actionType: 'none',
        status: 'needs_clarification',
        payload: { message: messageText },
        result: { reply: 'needs_more_specific_request' },
        db: client,
      });
    }
    for (const actionType of plannedActions) {
      const tool = UNIVERSAL_ASSISTANT_TOOLS[actionType];
      if (!tool) continue;
      try {
        const result = await tool({
          req,
          actor,
          body,
          message: messageText,
          thread,
          project,
          context,
          userMessage,
          db: client,
        });
        results.push(result);
      } catch (error) {
        const failedAction = await recordUniversalAssistantAction({
          thread,
          message: userMessage,
          actor,
          actionType,
          status: error.statusCode === 403 ? 'denied' : 'failed',
          payload: { message: messageText },
          result: {},
          error: error.message,
          db: client,
        });
        results.push(universalAssistantToolResult(actionType, {
          ok: false,
          status: failedAction.status,
          action: failedAction,
          error: error.message,
          reply: error.statusCode === 403 ? 'That action is outside this role or context.' : error.message,
        }));
      }
    }
    const replyBody = universalAssistantReply({ actor, actions: results, language, message: messageText });
    const assistantMessage = await insertUniversalAssistantMessage({
      threadId: thread.id,
      senderType: 'assistant',
      authorType: 'assistant',
      authorRole: actor.canUseCodex ? 'super_admin_assistant' : 'scoped_assistant',
      content: replyBody,
      language,
      toolResults: results.map((result) => ({
        action_type: result.action_type,
        status: result.status,
        ok: result.ok !== false,
        target_id: result.action?.target_id || null,
      })),
      metadata: {
        intent: 'universal_assistant_mvp',
        planned_actions: plannedActions,
        context_card_count: context.cards?.length || 0,
      },
      rawResponse: {
        action_count: results.length,
        actions: results.map((result) => ({ action_type: result.action_type, status: result.status, ok: result.ok !== false })),
      },
      db: client,
    });
    const memorySummary = limitText([
      `Last user request: ${messageText}`,
      `Last assistant reply: ${replyBody}`,
    ].join('\n'), 2000);
    await client.query(
      `UPDATE bna_assistant_threads
       SET memory_summary = $2,
           last_message_at = NOW(),
           updated_at = NOW()
       WHERE id = $1`,
      [thread.id, memorySummary]
    );
    await client.query(
      `INSERT INTO bna_assistant_memory_summaries (thread_id, actor_type, actor_id, scope_key, summary, metadata)
       VALUES ($1, $2, $3, 'thread', $4, $5::jsonb)
       ON CONFLICT (thread_id, scope_key) DO UPDATE SET
         summary = EXCLUDED.summary,
         metadata = bna_assistant_memory_summaries.metadata || EXCLUDED.metadata,
         updated_at = NOW()`,
      [
        thread.id,
        actor.type || null,
        actor.id || actor.anonymousId || null,
        memorySummary,
        JSON.stringify({ source: 'universal_assistant_mvp' }),
      ]
    );
    await client.query(
      `INSERT INTO bna_assistant_memories (
         thread_id, workspace_id, household_id, person_id, provider_profile_id, student_id,
         memory_type, language, summary, visibility, metadata
       )
       VALUES ($1, $2, $3, $4, $5, $6, 'summary', $7, $8, $9, $10::jsonb)
       ON CONFLICT (thread_id, memory_type) DO UPDATE SET
         workspace_id = COALESCE(EXCLUDED.workspace_id, bna_assistant_memories.workspace_id),
         household_id = COALESCE(EXCLUDED.household_id, bna_assistant_memories.household_id),
         person_id = COALESCE(EXCLUDED.person_id, bna_assistant_memories.person_id),
         provider_profile_id = COALESCE(EXCLUDED.provider_profile_id, bna_assistant_memories.provider_profile_id),
         student_id = COALESCE(EXCLUDED.student_id, bna_assistant_memories.student_id),
         language = EXCLUDED.language,
         summary = EXCLUDED.summary,
         visibility = EXCLUDED.visibility,
         metadata = bna_assistant_memories.metadata || EXCLUDED.metadata,
         updated_at = NOW()`,
      [
        thread.id,
        context.workspace?.id || null,
        context.household?.id || null,
        context.person?.id || null,
        context.provider_profile?.id || null,
        context.student?.id || null,
        language,
        memorySummary,
        context.household?.id ? 'household' : context.provider_profile?.id ? 'provider' : 'thread',
        JSON.stringify({ source: 'universal_assistant_mvp', actor_type: actor.type || null }),
      ]
    );
    const refreshedThread = (await client.query('SELECT * FROM bna_assistant_threads WHERE id = $1', [thread.id])).rows[0] || thread;
    await client.query('COMMIT');
    return res.json({
      success: true,
      actor: { type: actor.type, role: actor.role, can_use_codex: Boolean(actor.canUseCodex) },
      thread: assistantThreadView(refreshedThread),
      user_message: assistantMessageView(userMessage),
      assistant_message: assistantMessageView(assistantMessage),
      actions: results.map((result) => ({
        ...result,
        action: result.action ? universalAssistantActionView(result.action) : null,
      })),
      context_cards: context.cards || [],
      anonymous_id: actor.anonymousId || null,
    });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    return res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
}

