function isHelperGmailConfigured() {
  return Boolean(process.env.GOOGLE_REFRESH_TOKEN || readLocalSecretFile('google-refresh-token.txt'));
}

function helperRegistryDeps(db = pool) {
  return {
    db,
    assertProjectAccess,
    assertProjectOwnedRowAccess,
    assertTaskAccess,
    buildCodexQueueSnapshot,
    createRawIntakeRecord,
    createLinkedDecisionTask,
    createTaskFromText,
    fetchTaskWithProject,
    isGmailConfigured: isHelperGmailConfigured,
    patchTaskAndReturn,
    recordTaskActivity,
    resolveProjectFromInput,
    sendGmailMessage,
    updateRawIntakeRecordAfterParse,
    updateLatestAgentJobForTask,
  };
}

function helperRequestId(prefix = 'helper') {
  return `${prefix}_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;
}

async function helperRequestContext(req, body = {}) {
  const identity = req.opsIdentity || identifyOpsUser(req.opsUser || OPS_USERNAME);
  const requestedWorkspace = body.workspace_key || body.workspace || req.query?.workspace_key || req.query?.workspace || defaultWorkspaceKeyForRequest(req);
  const workspaceKey = assertWorkspaceAccess(req, requestedWorkspace || defaultWorkspaceKeyForRequest(req), 'use helper');
  const scopedProjectKey = opsScopeProjectKey(req);
  const pageContext = sanitizeHelperPageContext(body.pageContext || body.page_context || body.context || {});
  const projectKey = normalizeProjectKey(
    body.project_key ||
    body.project ||
    pageContext.workspace?.projectKey ||
    workspaceProjectKey(workspaceKey) ||
    scopedProjectKey ||
    DEFAULT_PROJECT_KEY
  ) || DEFAULT_PROJECT_KEY;
  const project = await getProjectByKey(projectKey);
  assertProjectAccess(req, project);
  const helperContext = {
    req,
    identity,
    userName: req.opsUser || identity?.username || 'BNA Helper',
    userRole: identity?.role || 'admin',
    workspaceKey,
    projectKey: project.project_key,
    project,
    allowedViews: Array.isArray(identity?.allowedViews) ? identity.allowedViews.slice() : [],
    view: pageContext.view || body.view || null,
    pageContext,
    selectedRecord: pageContext.selectedRecord || null,
  };
  helperContext.helperScope = resolveHelperScope(helperContext);
  return helperContext;
}

function helperActionRequiresConfirmation(tool) {
  return requiresHelperConfirmation(tool || {});
}

function helperActionSummary(tool, args = {}, fallback = '') {
  const title = args.title || args.subject || args.prompt || args.text || args.body || fallback || tool?.description || tool?.name || 'Action';
  return String(title || '').replace(/\s+/g, ' ').trim().slice(0, 240);
}

function helperNoStore(res) {
  res.set('Cache-Control', 'no-store');
}

function helperConfirmationToken() {
  return crypto.randomBytes(18).toString('base64url');
}

function helperConfirmationTokenHash(token = '') {
  return stableHash(String(token || ''));
}

function helperActorPayload(context = {}) {
  return {
    role: context.userRole || 'admin',
    scope: context.identity?.scope || { type: 'all' },
    allowedViews: context.allowedViews || [],
    username: context.userName || 'BNA Helper',
  };
}

function helperWorkspacePayload(context = {}) {
  return {
    workspaceKey: context.workspaceKey || null,
    projectKey: context.projectKey || null,
  };
}

function helperContextResponse(context = {}, registry) {
  const tools = registry.metadata(context);
  const helperScope = context.helperScope || resolveHelperScope(context);
  return {
    helperName: helperScope.helperName,
    helperScope,
    accessSummary: helperScope.accessSummary,
    suggestedActions: helperScope.suggestedActions,
    knowledgeSources: helperScope.knowledgeSources,
    toneProfile: helperScope.toneProfile,
    safetyPolicy: helperScope.safetyPolicy,
    actor: helperActorPayload(context),
    workspace: helperWorkspacePayload(context),
    allowedTools: tools.filter((tool) => tool.available).map((tool) => tool.name),
    tools,
    integrationReadiness: getIntegrationReadiness({
      configured: {
        openai: Boolean(OPENAI_API_KEY),
        kimi: Boolean(KIMI_API_KEY),
        google: Boolean(process.env.GOOGLE_REFRESH_TOKEN || readLocalSecretFile('google-refresh-token.txt')),
        gmail: isHelperGmailConfigured(),
        telegram: Boolean(TELEGRAM_BOT_TOKEN || TELEGRAM_BOT_TOKEN_BNA),
        buffer: Boolean(BUFFER_API_KEY),
        resend: Boolean(RESEND_API_KEY),
        stripe: Boolean(process.env.STRIPE_SECRET_KEY || process.env.RABBI_STRIPE_SECRET_KEY),
        zoom: Boolean(process.env.ZOOM_ACCOUNT_ID || process.env.ZOOM_CLIENT_ID || process.env.ZOOM_API_KEY),
        vimeo: Boolean(process.env.VIMEO_ACCESS_TOKEN || process.env.VIMEO_CLIENT_ID),
      },
    }),
    pageContext: context.pageContext || {},
  };
}

function helperRunResponse(planId, plan = {}, options = {}) {
  const actions = Array.isArray(plan.actions) ? plan.actions : [];
  const state = options.state || helperStateFromActions(actions);
  return {
    runId: planId,
    requestId: plan.request_id || null,
    state,
    reply: plan.reply || '',
    planner: plan.planner || 'deterministic',
    actor: options.includeContext ? helperActorPayload(options.context || {}) : undefined,
    workspace: options.includeContext ? helperWorkspacePayload(options.context || {}) : undefined,
    messages: [
      {
        role: 'assistant',
        body: plan.reply || '',
      },
    ],
    toolCalls: actions.map((action) => safeActionForClient(action, { includeConfirmationTokens: Boolean(options.includeConfirmationTokens) })),
    resultLinks: resultLinksFromActions(actions),
    confirmation: firstConfirmationForActions(planId, actions, { includeConfirmationTokens: Boolean(options.includeConfirmationTokens) }),
    missingInput: Array.isArray(plan.missing_input) ? plan.missing_input : [],
  };
}

async function planHelperActions({ req, body, context, registry, requestId, planId, message }) {
  const plannerResult = await buildHelperPlan(message, registry, context);
  const messageHash = stableHash(message);
  const pageContext = context.pageContext || sanitizeHelperPageContext(body.pageContext || body.page_context || body.context || {});
  const plannedActions = [];
  const rawActions = Array.isArray(plannerResult.actions) ? plannerResult.actions.slice(0, 8) : [];

  for (let index = 0; index < rawActions.length; index += 1) {
    const rawAction = rawActions[index] || {};
    const tool = registry.get(rawAction.tool);
    const actionId = `act_${index + 1}`;
    if (!tool) {
      plannedActions.push({
        id: actionId,
        tool: String(rawAction.tool || 'unknown'),
        label: rawAction.label || 'Unknown action',
        summary: 'The requested helper tool does not exist.',
        risk: 'high',
        requires_confirmation: true,
        args: {},
        args_preview: {},
        status: 'tool_not_found',
        error: 'tool_not_found',
      });
      continue;
    }
    const validation = registry.validate(tool.name, rawAction.args || {});
    const permission = validation.ok
      ? helperPermissionForTool(tool, context, validation.args)
      : { allowed: false, reason: validation.errors.join('; ') };
    const requiresConfirmation = helperActionRequiresConfirmation(tool);
    const status = !validation.ok
      ? 'schema_validation_failed'
      : !permission.allowed
        ? 'permission_denied'
        : requiresConfirmation
          ? 'needs_confirmation'
          : 'planned';
    const confirmationToken = requiresConfirmation ? helperConfirmationToken() : '';
    const action = {
      id: actionId,
      tool: tool.name,
      label: String(rawAction.label || tool.description || tool.name).slice(0, 160),
      summary: helperActionSummary(tool, validation.args, rawAction.reason),
      reason: String(rawAction.reason || '').slice(0, 500),
      risk: tool.risk || 'low',
      requires_confirmation: requiresConfirmation,
      args: validation.args,
      args_preview: redactValue(validation.args),
      available: Boolean(tool.available),
      unavailable_reason: tool.available ? null : tool.unavailableReason || 'unavailable',
      status,
      error: validation.ok ? (permission.allowed ? null : permission.reason) : validation.errors.join('; '),
      confirmation_token_hash: confirmationToken ? helperConfirmationTokenHash(confirmationToken) : null,
      _confirmationToken: confirmationToken || null,
    };
    plannedActions.push(action);
    await insertHelperAudit(pool, {
      request_id: requestId,
      client_request_id: body.client_request_id || body.clientRequestId || null,
      plan_id: planId,
      tool_call_id: actionId,
      conversation_id: body.conversation_id || null,
      message_hash: messageHash,
      tool_name: tool.name,
      action_label: action.label,
      risk_level: action.risk,
      status: status === 'needs_confirmation' ? 'confirmation_required' : status,
      requires_confirmation: requiresConfirmation,
      user_name: context.userName,
      user_role: context.userRole,
      workspace_key: context.workspaceKey,
      project_key: context.projectKey,
      confirmation_token_hash: action.confirmation_token_hash,
      idempotency_key: `${planId}:${actionId}:planned`,
      page_context: pageContext,
      args: validation.args,
      error_message: action.error || null,
    });
  }

  if (!plannedActions.length) {
    plannedActions.push({
      id: 'act_1',
      tool: 'request_missing_input',
      label: 'Need clarification',
      summary: 'The Helper needs a clearer request before it can choose a tool.',
      risk: 'low',
      requires_confirmation: false,
      args: {},
      args_preview: {},
      status: 'needs_input',
      error: 'missing_input',
    });
  }

  return {
    reply: plannerResult.reply || 'I found a possible plan.',
    planner: plannerResult.planner || 'deterministic',
    missing_input: plannerResult.missing_input || [],
    notes: plannerResult.notes || '',
    actions: plannedActions,
  };
}

async function executeStoredHelperAction({ action, context, registry, planId, requestId, clientRequestId, conversationId, messageHash, confirmed, confirmationText, pageContext }) {
  if (!['planned', 'needs_confirmation'].includes(String(action.status || 'planned'))) {
    return action;
  }
  const tool = registry.get(action.tool);
  if (!tool) {
    return {
      ...action,
      status: 'tool_not_found',
      result: null,
      error: 'tool_not_found',
    };
  }
  if (action.requires_confirmation && !confirmed) {
    await insertHelperAudit(pool, {
      request_id: requestId,
      client_request_id: clientRequestId || null,
      plan_id: planId,
      tool_call_id: action.id,
      conversation_id: conversationId || null,
      message_hash: messageHash || null,
      tool_name: tool.name,
      action_label: action.label,
      risk_level: action.risk,
      status: 'confirmation_required',
      requires_confirmation: true,
      confirmed: false,
      user_name: context.userName,
      user_role: context.userRole,
      workspace_key: context.workspaceKey,
      project_key: context.projectKey,
      confirmation_token_hash: action.confirmation_token_hash || null,
      idempotency_key: `${planId}:${action.id}:confirmation_required`,
      page_context: pageContext || context.pageContext || {},
      args: action.args || {},
    });
    return {
      ...action,
      status: 'needs_confirmation',
      result: null,
      error: 'confirmation_required',
    };
  }

  try {
    const result = await registry.execute(tool.name, action.args || {}, context, pool);
    const status = result.status === 'missing_integration'
      ? 'missing_integration'
      : result.status === 'fallback_created'
        ? 'fallback_created'
        : 'executed';
    await insertHelperAudit(pool, {
      request_id: requestId,
      client_request_id: clientRequestId || null,
      plan_id: planId,
      tool_call_id: action.id,
      conversation_id: conversationId || null,
      message_hash: messageHash || null,
      tool_name: tool.name,
      action_label: action.label,
      risk_level: action.risk,
      status,
      requires_confirmation: Boolean(action.requires_confirmation),
      confirmed: Boolean(confirmed),
      confirmed_by: confirmed ? context.userName : null,
      confirmed_at: confirmed ? new Date().toISOString() : null,
      user_name: context.userName,
      user_role: context.userRole,
      workspace_key: context.workspaceKey,
      project_key: context.projectKey,
      record_type: result.record_type || null,
      record_id: result.record_id || null,
      confirmation_token_hash: action.confirmation_token_hash || null,
      idempotency_key: `${planId}:${action.id}:${confirmed ? 'confirmed' : 'execute'}`,
      page_context: pageContext || context.pageContext || {},
      args: action.args || {},
      result,
    });
    return {
      ...action,
      status,
      result,
      error: null,
      confirmation_text_used: confirmationText ? true : undefined,
    };
  } catch (error) {
    const status = error.code || (error.statusCode === 403 ? 'permission_denied' : 'execution_failed');
    await insertHelperAudit(pool, {
      request_id: requestId,
      client_request_id: clientRequestId || null,
      plan_id: planId,
      tool_call_id: action.id,
      conversation_id: conversationId || null,
      message_hash: messageHash || null,
      tool_name: tool.name,
      action_label: action.label,
      risk_level: action.risk,
      status,
      requires_confirmation: Boolean(action.requires_confirmation),
      confirmed: Boolean(confirmed),
      confirmed_by: confirmed ? context.userName : null,
      confirmed_at: confirmed ? new Date().toISOString() : null,
      user_name: context.userName,
      user_role: context.userRole,
      workspace_key: context.workspaceKey,
      project_key: context.projectKey,
      confirmation_token_hash: action.confirmation_token_hash || null,
      idempotency_key: `${planId}:${action.id}:${confirmed ? 'confirmed_failed' : 'execute_failed'}`,
      page_context: pageContext || context.pageContext || {},
      args: action.args || {},
      error_message: error.message || String(error),
    });
    return {
      ...action,
      status,
      result: null,
      error: error.message || String(error),
    };
  }
}

async function executeHelperPlanActions({
  planRecord,
  context,
  registry,
  planId,
  requestId,
  clientRequestId,
  conversationId,
  messageHash,
  confirmed = false,
  confirmationText = '',
  filter = () => true,
}) {
  const results = [];
  const updatedActions = [];
  for (const action of planRecord.actions || []) {
    if (!filter(action)) {
      updatedActions.push(action);
      continue;
    }
    // eslint-disable-next-line no-await-in-loop
    const executed = await executeStoredHelperAction({
      action,
      context,
      registry,
      planId,
      requestId,
      clientRequestId,
      conversationId,
      messageHash,
      confirmed,
      confirmationText,
      pageContext: planRecord.page_context || context.pageContext || {},
    });
    updatedActions.push(executed);
    if (executed.result) results.push(executed.result);
  }
  planRecord.actions = updatedActions;
  return {
    actions: updatedActions,
    results,
    state: helperStateFromActions(updatedActions),
  };
}

function legacyHelperPlanStatus(state = 'completed') {
  if (state === 'needs_confirmation') return 'confirmation_required';
  if (state === 'completed') return 'executed';
  if (state === 'planning') return 'planned';
  return state;
}

