async function handleHelperMessageRoute(req, res) {
  helperNoStore(res);
  const body = req.body || {};
  const message = String(body.message || body.text || '').trim();
  if (!message) return res.status(400).json({ success: false, error: 'message is required', code: 'schema_validation_failed' });

  try {
    const context = await helperRequestContext(req, body);
    const registry = buildToolRegistry(helperRegistryDeps(pool));
    const requestId = helperRequestId('helper_req');
    const planId = helperRequestId('helper_run');
    const clientRequestId = body.client_request_id || body.clientRequestId || null;
    const plan = await planHelperActions({ req, body, context, registry, requestId, planId, message });
    const planRecord = {
      ...plan,
      request_id: requestId,
      client_request_id: clientRequestId,
      conversation_id: body.conversation_id || null,
      message_hash: stableHash(message),
      workspace_key: context.workspaceKey,
      project_key: context.projectKey,
      page_context: context.pageContext || {},
      created_at: new Date().toISOString(),
    };
    await saveHelperPlan(pool, {
      id: planId,
      requestId,
      conversationId: body.conversation_id || null,
      userName: context.userName,
      userRole: context.userRole,
      workspaceKey: context.workspaceKey,
      projectKey: context.projectKey,
      message,
      plan: planRecord,
      status: 'planning',
      expiresAt: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
    });

    const autoExecuteSafe = body.auto_execute_safe !== false && body.autoExecuteSafe !== false;
    if (autoExecuteSafe) {
      const execution = await executeHelperPlanActions({
        planRecord,
        context,
        registry,
        planId,
        requestId,
        clientRequestId,
        conversationId: body.conversation_id || null,
        messageHash: planRecord.message_hash,
        filter: (action) => action.status === 'planned' && !action.requires_confirmation,
      });
      await updateHelperPlan(pool, planId, planRecord, execution.state);
    }

    res.json({
      success: true,
      ...helperRunResponse(planId, planRecord, {
        context,
        includeContext: true,
        includeConfirmationTokens: true,
      }),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ success: false, error: err.message, code: err.code || 'execution_failed' });
  }
}

