app.post('/api/bna/helper/confirm', requireAdmin, async (req, res) => {
  helperNoStore(res);
  const body = req.body || {};
  const toolCallId = String(body.toolCallId || body.tool_call_id || '').trim();
  const rawRunId = String(body.runId || body.run_id || body.plan_id || '').trim();
  const separator = toolCallId.lastIndexOf(':');
  const planId = separator > -1 ? toolCallId.slice(0, separator) : rawRunId;
  const actionId = separator > -1 ? toolCallId.slice(separator + 1) : String(body.actionId || body.action_id || '').trim();
  const confirmationToken = String(body.confirmationToken || body.confirmation_token || '').trim();
  if (!planId || !actionId || !confirmationToken) {
    return res.status(400).json({ success: false, error: 'toolCallId and confirmationToken are required', code: 'schema_validation_failed' });
  }

  try {
    const stored = await loadHelperPlan(pool, planId);
    if (!stored) return res.status(404).json({ success: false, error: 'helper run not found or expired', code: 'record_not_found' });
    const plan = stored.plan || {};
    const action = (plan.actions || []).find((item) => String(item.id || '') === actionId);
    if (!action) return res.status(404).json({ success: false, error: 'helper action not found', code: 'record_not_found' });
    if (action.confirmation_token_hash !== helperConfirmationTokenHash(confirmationToken)) {
      return res.status(409).json({ success: false, error: 'Confirmation token does not match this pending helper action.', code: 'confirmation_mismatch' });
    }
    const context = await helperRequestContext(req, {
      workspace_key: plan.workspace_key || stored.workspace_key,
      project_key: plan.project_key || stored.project_key,
      pageContext: plan.page_context || {},
      view: plan.page_context?.view || null,
    });
    const registry = buildToolRegistry(helperRegistryDeps(pool));
    const execution = await executeHelperPlanActions({
      planRecord: plan,
      context,
      registry,
      planId,
      requestId: plan.request_id || stored.request_id,
      clientRequestId: body.client_request_id || body.clientRequestId || plan.client_request_id || null,
      conversationId: plan.conversation_id || stored.conversation_id,
      messageHash: plan.message_hash || stored.message_hash,
      confirmed: true,
      confirmationText: 'CONFIRM',
      filter: (item) => String(item.id || '') === actionId,
    });
    await updateHelperPlan(pool, planId, plan, execution.state);
    res.json({
      success: true,
      ...helperRunResponse(planId, plan, {
        context,
        includeContext: true,
      }),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ success: false, error: err.message, code: err.code || 'execution_failed' });
  }
});

