app.post('/api/bna/helper/execute', requireAdmin, async (req, res) => {
  helperNoStore(res);
  const body = req.body || {};
  const planId = String(body.plan_id || body.planId || '').trim();
  if (!planId) return res.status(400).json({ success: false, error: 'plan_id is required', code: 'schema_validation_failed' });

  try {
    const stored = await loadHelperPlan(pool, planId);
    if (!stored) return res.status(404).json({ success: false, error: 'helper plan not found or expired', code: 'record_not_found' });
    const plan = stored.plan || {};
    const context = await helperRequestContext(req, {
      workspace_key: plan.workspace_key || stored.workspace_key,
      project_key: plan.project_key || stored.project_key,
      pageContext: plan.page_context || {},
      view: plan.page_context?.view || null,
    });
    const registry = buildToolRegistry(helperRegistryDeps(pool));
    const selected = Array.isArray(body.action_ids) && body.action_ids.length
      ? new Set(body.action_ids.map(String))
      : new Set((plan.actions || []).map((action) => action.id));
    const confirmed = body.confirmed === true || body.confirm === true || String(body.confirmation_text || '').trim().toUpperCase() === 'CONFIRM';
    const execution = await executeHelperPlanActions({
      planRecord: plan,
      context,
      registry,
      planId,
      requestId: plan.request_id || stored.request_id,
      clientRequestId: body.client_request_id || body.clientRequestId || plan.client_request_id || null,
      conversationId: plan.conversation_id || stored.conversation_id,
      messageHash: plan.message_hash || stored.message_hash,
      confirmed,
      confirmationText: body.confirmation_text || '',
      filter: (action) => selected.has(String(action.id)),
    });
    await updateHelperPlan(pool, planId, plan, execution.state);
    res.json({
      success: true,
      plan_id: planId,
      status: legacyHelperPlanStatus(execution.state),
      results: execution.results,
      actions: (plan.actions || []).map((action) => safeActionForClient(action)),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ success: false, error: err.message, code: err.code || 'execution_failed' });
  }
});

