app.get('/api/bna/one-time/classes', requireAdmin, async (req, res) => {
  try {
    const project = await assertOneTimeLibraryAdminAccess(req);
    const limit = Math.min(Math.max(Number(req.query.limit || 80) || 80, 1), 200);
    const requestedStatus = String(req.query.status || '').trim();
    const packageStatus = requestedStatus && requestedStatus !== 'all'
      ? normalizeOneTimePackageStatus(requestedStatus)
      : '';
    const params = [project.id];
    const conditions = ['cs.project_id = $1'];
    if (packageStatus) {
      params.push(packageStatus);
      conditions.push(`cs.package_status = $${params.length}`);
    }
    const sessions = (await pool.query(
      `SELECT cs.*
       FROM bna_class_sessions cs
       WHERE ${conditions.join(' AND ')}
       ORDER BY COALESCE(cs.class_date, cs.created_at::date) DESC, cs.updated_at DESC, cs.id DESC
       LIMIT ${limit}`,
      params
    )).rows;
    const ids = sessions.map((session) => Number(session.id)).filter(Boolean);
    const assets = ids.length
      ? (await pool.query(
        `SELECT *
         FROM one_time_class_assets
         WHERE project_id = $1
           AND class_session_id = ANY($2::int[])
         ORDER BY created_at DESC, id DESC`,
        [project.id, ids]
      )).rows
      : [];
    const libraryItems = ids.length
      ? (await pool.query(
        `SELECT *
         FROM one_time_member_library_items
         WHERE project_id = $1
           AND class_session_id = ANY($2::int[])
         ORDER BY updated_at DESC, id DESC`,
        [project.id, ids]
      )).rows
      : [];
    const events = ids.length
      ? (await pool.query(
        `SELECT *
         FROM one_time_library_publish_events
         WHERE project_id = $1
           AND class_session_id = ANY($2::int[])
         ORDER BY created_at DESC, id DESC
         LIMIT 300`,
        [project.id, ids]
      )).rows
      : [];
    const classes = sessions.map((session) => {
      const classId = Number(session.id);
      return {
        ...oneTimeClassSessionView(session),
        assets: assets.filter((asset) => Number(asset.class_session_id) === classId).map(oneTimeClassAssetView),
        library_items: libraryItems.filter((item) => Number(item.class_session_id) === classId).map(oneTimeLibraryItemView),
        publish_events: events.filter((event) => Number(event.class_session_id) === classId).map(oneTimePublishEventView),
      };
    });
    res.json({
      success: true,
      project_key: ONE_TIME_PROJECT_KEY,
      approval_flag: ONE_TIME_LIBRARY_APPROVAL_FLAG,
      classes,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

