app.post('/api/one-time-classroom/threads/:id/responses', async (req, res) => {
  const body = req.body || {};
  const accessCode = String(body.code || body.access_code || body.accessCode || '').trim();
  const responseBody = limitText(body.body || body.message || body.response || '', 2000);
  if (!responseBody) return res.status(400).json({ error: 'Response is required' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const auth = accessCode ? null : await rabbiMemberFromSessionToken(bearerOrBodyToken(req));
    const memberLibrary = accessCode
      ? await getOneTimeMemberLibraryForAccessCode(accessCode, client)
      : await getOneTimeMemberLibraryForMemberEmail(auth.member.email, client);
    const classroom = {
      access: memberLibrary.access,
      member_library_items: memberLibrary.items,
      ...(await getOneTimeClassroomData({ db: client, memberLibrary, memberSafe: true })),
    };
    const project = await getProjectByKey(ONE_TIME_PROJECT_KEY, client);
    const thread = (await client.query(
      `SELECT *
       FROM bna_community_threads
       WHERE id = $1
         AND project_id = $2
         AND status = 'active'
         AND COALESCE(moderation_status, 'approved') = 'approved'
       LIMIT 1`,
      [Number(req.params.id || 0), project.id]
    )).rows[0];
    if (!thread) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Classroom thread was not found' });
    }
    const screen = oneTimeClassroomScreenResponse(responseBody);
    const privateToPublicState = screen.parent_visible_safety ? 'held_for_safety_review' : 'needs_human_review';
    const inserted = (await client.query(
      `INSERT INTO bna_community_messages (
         thread_id, parent_message_id, author_type, author_id, author_email, author_name,
         body, visibility, status, moderation_status, ai_moderation_json,
         parent_visible_safety, parent_escalation_status, leaderboard_eligible,
         metadata_json, original_body, visibility_decision, private_to_public_state,
         report_flags_json, temporary_hold_recommended
       ) VALUES (
         $1, $2, 'member', NULL, NULL, $3,
         $4, 'members', 'hidden', $5, $6::jsonb,
         $7, $8, FALSE,
         $9::jsonb, $4, 'private', $10,
         $11::jsonb, $12
       )
       RETURNING *`,
      [
        thread.id,
        body.parent_message_id ? Number(body.parent_message_id) : null,
        limitText(classroom.access.member_label || 'One Time member', 180),
        responseBody,
        screen.status,
        JSON.stringify(screen),
        screen.parent_visible_safety,
        screen.parent_escalation_status,
        JSON.stringify({
          source: 'one_time_classroom_member_response',
          access_tier: classroom.access.tier,
          no_student_to_student_chat: true,
          visible_after_review_only: true,
        }),
        privateToPublicState,
        JSON.stringify(screen.flags || []),
        Boolean(screen.parent_visible_safety),
      ]
    )).rows[0];
    await client.query(
      `INSERT INTO bna_community_moderation_events (
         workspace_key, project_id, community_thread_id, community_message_id,
         action, actor_type, actor_label,
         visibility_after, moderation_status_after,
         original_body_present, published_body_present, anonymized_body_present,
         report_flags_json, metadata
       ) VALUES (
         'rabbi_sheller_provider', $1, $2, $3,
         'submitted_private', 'member', $4,
         'private', $5,
         TRUE, FALSE, FALSE,
         $6::jsonb, $7::jsonb
       )`,
      [
        project.id,
        thread.id,
        inserted.id,
        limitText(classroom.access.member_label || 'One Time member', 180),
        screen.status,
        JSON.stringify(screen.flags || []),
        JSON.stringify({
          requirement_id: 'REQ-20260619-311',
          safe_for_auto_publish: false,
          no_student_to_student_chat: true,
        }),
      ]
    );
    await client.query('UPDATE bna_community_threads SET updated_at = NOW() WHERE id = $1', [thread.id]);
    await client.query('COMMIT');
    res.json({
      success: true,
      message: 'Response submitted for Rabbi/admin review.',
      moderation_status: screen.status,
      parent_visible_safety: screen.parent_visible_safety,
      visible_to_classroom: false,
      submitted: oneTimeClassroomMessageView(inserted, { includePrivate: false }),
    });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

