app.post('/api/bna/one-time/source-prep-jobs', requireAdmin, async (req, res) => {
  const body = req.body || {};
  try {
    const project = await assertRabbiAdminAccess(req);
    const program = await getOneTimeProductProgram(project.id);
    const requestedRefs = oneTimeProductArray(body.requested_refs || body.requestedRefs || body.refs);
    const draft = buildSourcePrepDraft({
      ...body,
      requested_refs: requestedRefs,
      title: body.title || body.class_title || body.classTitle || 'One Time Mishnayos Source Prep',
    });
    const eventId = body.calendar_event_id || body.calendarEventId || null;
    if (eventId) {
      const ownedEvent = (await pool.query(
        `SELECT id FROM bna_program_calendar_events
         WHERE id = $1 AND project_id = $2 AND program_key = $3
         LIMIT 1`,
        [eventId, project.id, ONE_TIME_PRODUCT_PROGRAM_KEY]
      )).rows[0] || null;
      if (!ownedEvent) return res.status(404).json({ error: 'One Time calendar event was not found' });
    }
    const row = (await pool.query(
      `INSERT INTO bna_source_prep_jobs (
         project_id, program_id, calendar_event_id, class_session_id, program_key,
         natural_language_prompt, requested_refs, source_lookup_status,
         worksheet_status, slides_status, approval_status, visibility,
         source_sheet_draft, worksheet_draft, slides_outline, generated_artifacts,
         blockers, errors, created_by, updated_at
       ) VALUES (
         $1, $2, $3, $4, $5,
         $6, $7::text[], $8,
         $9, $10, $11, $12,
         $13::jsonb, $14::jsonb, $15::jsonb, $16::jsonb,
         $17::jsonb, $18::jsonb, $19, NOW()
       )
       RETURNING *`,
      [
        project.id,
        program?.id || null,
        eventId ? Number(eventId) : null,
        body.class_session_id || body.classSessionId ? Number(body.class_session_id || body.classSessionId) : null,
        ONE_TIME_PRODUCT_PROGRAM_KEY,
        limitText(body.natural_language_prompt || body.prompt || '', 3000),
        requestedRefs,
        draft.source_lookup_status,
        draft.worksheet_status,
        draft.slides_status,
        draft.approval_status,
        normalizeOneTimeVisibility(body.visibility || draft.visibility),
        JSON.stringify(draft.source_sheet_draft),
        JSON.stringify(draft.worksheet_draft),
        JSON.stringify(draft.slides_outline),
        JSON.stringify(draft.generated_artifacts),
        JSON.stringify(draft.blockers),
        JSON.stringify(draft.errors),
        limitText(req.opsUser || body.created_by || 'dashboard', 120),
      ]
    )).rows[0];
    res.json({
      success: true,
      source_prep_job: oneTimeSourcePrepJobView(row),
      external_write_performed: false,
      message: 'Fixture source-prep draft created for Rabbi/admin review only.',
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

