app.post('/api/bna/rabbi/checkouts/manual', requireAdmin, async (req, res) => {
  const body = req.body || {};
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const project = await assertRabbiAdminAccess(req, client);
    const tier = await getRabbiTierOr404(project.id, body.tier_key || body.tierKey || RABBI_TIER_KEYS.LIBRARY_ONLY, client);
    const member = await ensureRabbiMember({
      projectId: project.id,
      displayName: body.display_name || body.name || body.customer_name || '',
      email: body.email || body.customer_email || '',
      phone: body.phone || body.customer_phone || '',
      notes: body.member_notes || 'Created by manual Rabbi checkout override.',
      metadata: { source: 'manual_checkout_override' },
      db: client,
    });
    const checkout = (await client.query(
      `INSERT INTO bna_checkout_records (
         project_id, member_id, tier_id, tier_key, provider, provider_mode,
         checkout_key, customer_name, customer_email, customer_phone, amount_cents,
         currency, status, source, notes, metadata, paid_at, updated_at
       ) VALUES (
         $1, $2, $3, $4, 'manual', 'test',
         $5, $6, $7, $8, $9,
         $10, 'paid', 'manual_override', $11, $12::jsonb, NOW(), NOW()
       )
       RETURNING *`,
      [
        project.id,
        member.id,
        tier.id,
        normalizeRabbiTierKey(tier.tier_key),
        `manual-${crypto.randomUUID()}`,
        member.display_name,
        member.email,
        member.phone,
        body.amount_cents !== undefined ? Number(body.amount_cents) : centsFromMajorAmount(body.amount),
        body.currency || tier.currency || 'USD',
        limitText(body.notes || 'Manual paid checkout override.', 2000),
        JSON.stringify({ actor: req.opsUser || 'dashboard', manual_override: true }),
      ]
    )).rows[0];
    const event = (await client.query(
      `INSERT INTO bna_payment_events (
         project_id, checkout_record_id, member_id, provider, provider_mode,
         event_type, event_key, status, amount_cents, currency, raw_payload,
         metadata, processed_at
       ) VALUES ($1, $2, $3, 'manual', 'test', 'manual_paid_override', $4, 'processed', $5, $6, $7::jsonb, $8::jsonb, NOW())
       RETURNING *`,
      [
        project.id,
        checkout.id,
        member.id,
        `manual:${checkout.id}`,
        checkout.amount_cents,
        checkout.currency,
        JSON.stringify(body),
        JSON.stringify({ actor: req.opsUser || 'dashboard' }),
      ]
    )).rows[0];
    const grant = await createRabbiAccessGrant({
      projectId: project.id,
      memberId: member.id,
      tier,
      checkoutRecordId: checkout.id,
      paymentEventId: event.id,
      source: 'manual_override',
      notes: body.notes || 'Manual checkout override granted access.',
      metadata: { actor: req.opsUser || 'dashboard' },
      db: client,
    });
    await client.query('COMMIT');
    await maybeSendRabbiEmail({
      projectId: project.id,
      member,
      checkoutRecord: checkout,
      accessGrant: grant,
      templateKey: 'manual_grant',
      dryRun: body.dryRun !== false && body.dry_run !== false,
      context: { memberUrl: rabbiAdminUrl(req, '/rabbi-member') },
    });
    res.json({ success: true, member: rabbiMemberView(member, [grant], req), checkout: rabbiCheckoutView(checkout), event, grant: rabbiGrantView(grant) });
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch {}
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

