app.patch('/api/bna/rabbi/library-items/:id', requireAdmin, async (req, res) => {
  const body = req.body || {};
  try {
    const project = await assertRabbiAdminAccess(req);
    await assertProjectOwnedRowAccess(req, 'bna_library_items', req.params.id);
    const fields = [];
    const values = [];
    const add = (field, value) => {
      values.push(value);
      fields.push(`${field} = $${values.length}`);
    };
    if (body.title !== undefined) add('title', limitText(body.title || '', 240));
    if (body.description !== undefined) add('description', limitText(body.description || '', 4000) || null);
    if (body.media_url !== undefined || body.vimeo_url !== undefined) {
      const url = hostedHttpUrl(body.media_url || body.vimeo_url || '', 'library media URL', { required: false });
      add('media_url', url);
      add('vimeo_url', url);
    }
    if (body.thumbnail_url !== undefined) add('thumbnail_url', hostedHttpUrl(body.thumbnail_url || '', 'thumbnail URL', { required: false }));
    if (body.required_scope !== undefined) add('required_scope', ['library', 'live'].includes(String(body.required_scope)) ? String(body.required_scope) : 'library');
    if (body.visibility !== undefined) {
      const visibility = ['draft', 'published', 'hidden', 'archived'].includes(String(body.visibility)) ? String(body.visibility) : 'draft';
      add('visibility', visibility);
      fields.push(`published_at = CASE WHEN '${visibility}' = 'published' THEN COALESCE(published_at, NOW()) ELSE published_at END`);
    }
    if (body.metadata !== undefined) add('metadata', JSON.stringify(body.metadata && typeof body.metadata === 'object' ? body.metadata : {}));
    if (!fields.length) return res.status(400).json({ error: 'No supported library item fields supplied' });
    fields.push('updated_at = NOW()');
    values.push(req.params.id, project.id);
    const row = (await pool.query(
      `UPDATE bna_library_items SET ${fields.join(', ')}
       WHERE id = $${values.length - 1} AND project_id = $${values.length}
       RETURNING *`,
      values
    )).rows[0];
    res.json({ success: true, item: rabbiLibraryItemView(row) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

