app.post('/api/bna/one-time/parent-trial-invite', requireAdmin, async (req, res) => {
  const body = req.body || {};
  const dryRun = body.dry_run === true || body.dryRun === true || /^(?:1|true|yes)$/i.test(String(body.dry_run || body.dryRun || ''));
  const smokeMode = body.test_mode === true
    || body.testMode === true
    || body.smoke_mode === true
    || body.smokeMode === true
    || /^(?:1|true|yes|test|smoke)$/i.test(String(body.invite_mode || body.inviteMode || ''));
  const inviteMode = smokeMode ? 'smoke_test' : 'production';
  const parentEmail = normalizeEmail(body.parent_email || body.parentEmail || body.email);
  const rawParentName = String(body.parent_name || body.parentName || body.name || '').trim();
  const rawStudentName = String(body.student_name || body.studentName || body.child_name || body.childName || '').trim();
  const parentName = limitText(rawParentName || (dryRun ? 'One Time Parent' : ''), 160);
  const studentName = limitText(rawStudentName || (dryRun ? 'One Time student' : ''), 160);
  const trialDays = Math.max(1, Math.min(Number(body.trial_days || body.trialDays || 30) || 30, 90));
  const rawLiveClassUrl = body.live_class_url || body.liveClassUrl || body.zoom_url || body.zoomUrl || '';
  const requestedLiveClassUrl = normalizeHttpsExternalUrl(rawLiveClassUrl);
  const liveClassUrl = requestedLiveClassUrl || (!String(rawLiveClassUrl || '').trim() ? configuredOneTimeLiveClassUrl() : '');
  const oneTimeBaseUrl = configuredOneTimePublicBaseUrl();
  const preflight = oneTimeParentTrialInvitePreflight({
    parentEmail,
    rawParentName,
    rawStudentName,
    rawLiveClassUrl,
    liveClassUrl,
    dryRun,
    smokeMode,
    inviteMode,
    trialDays,
    oneTimeBaseUrl,
  });
  if (!parentEmail) return res.status(400).json({ error: 'parent_email is required', preflight });
  if (preflight.blocker_codes.includes('invalid_live_class_url')) {
    return res.status(400).json({ error: 'live_class_url/zoom_url must be a valid https URL', preflight });
  }
  if (!dryRun && preflight.blockers.length) {
    return res.status(400).json({
      error: 'One Time parent trial invite is not launch-ready',
      hint: 'Resolve the listed preflight blockers before using SEND_ONE_TIME_PARENT_TRIAL_INVITE.',
      preflight,
    });
  }
  try {
    const project = await assertRabbiAdminAccess(req);
    const preview = {
      parent_email: parentEmail,
      parent_name: parentName,
      student_name: studentName,
      trial_days: trialDays,
      invite_mode: inviteMode,
      test_labeled: smokeMode,
      launch_ready: !smokeMode,
      subject: buildRabbiEmailTemplate('parent_trial_invite', { recipientName: parentName, studentName, programName: ONE_TIME_EMAIL_FROM_NAME }).subject,
      one_time_public_base_url: oneTimeBaseUrl,
      links_will_use: {
        parent_portal: scopedPublicUrl(oneTimeBaseUrl, '/one-time-parent'),
        member_library: scopedPublicUrl(oneTimeBaseUrl, '/member-library'),
        classroom: scopedPublicUrl(oneTimeBaseUrl, '/one-time-classroom'),
      },
      live_class_url_included: Boolean(liveClassUrl),
      confirm_required: ONE_TIME_PARENT_TRIAL_INVITE_CONFIRM,
      no_payment_created: true,
      no_checkout_created: true,
      no_vimeo_upload: true,
      scoped_to: {
        workspace_key: 'rabbi_sheller_provider',
        project_key: ONE_TIME_PROJECT_KEY,
      },
      preflight,
    };
    if (dryRun) {
      return res.json({
        success: true,
        dry_run: true,
        no_send: true,
        external_write_performed: false,
        local_write_performed: false,
        preflight,
        preview,
      });
    }
    if (String(body.confirm || '').trim() !== ONE_TIME_PARENT_TRIAL_INVITE_CONFIRM) {
      return res.status(400).json({
        error: `One Time parent trial invite emails require confirm: ${ONE_TIME_PARENT_TRIAL_INVITE_CONFIRM}`,
        hint: 'Use this only for an explicit per-parent One Time invite. It creates scoped trial access but does not create a payment or checkout.',
        preflight,
        preview,
      });
    }

    const client = await pool.connect();
    let committed = false;
    try {
      await client.query('BEGIN');
      const tags = smokeMode
        ? ['TEST', 'codex-test', 'one-time-trial', 'one-time-parent-trial']
        : ['one-time-trial', 'one-time-parent-trial', 'one-time-live-invite'];
      const tagsToRemove = smokeMode ? [] : ['test', 'codex-test'];
      const studentNotes = smokeMode
        ? 'TEST One Time parent trial student created from approved Codex smoke invite flow. Safe to archive after walkthrough.'
        : 'One Time parent trial student created from approved launch-ready parent invite flow.';
      const memberNotes = smokeMode
        ? 'TEST One Time parent trial member access for operator walkthrough.'
        : 'One Time parent trial member access created from approved launch-ready parent invite flow.';
      let student = (await client.query(
        `SELECT *
         FROM bna_students
         WHERE project_id = $1
           AND lower(COALESCE(parent_email, '')) = lower($2)
           AND 'one-time-parent-trial' = ANY(COALESCE(tags, '{}'::text[]))
         ORDER BY updated_at DESC NULLS LAST, id DESC
         LIMIT 1`,
        [project.id, parentEmail]
      )).rows[0] || null;
      if (student) {
        student = (await client.query(
          `UPDATE bna_students
           SET name = COALESCE(NULLIF($2, ''), name),
               parent_name = COALESCE(NULLIF($3, ''), parent_name),
               parent_email = $4,
               tags = (
                 SELECT ARRAY(
                   SELECT DISTINCT tag_value
                   FROM unnest(COALESCE(tags, '{}'::text[]) || $5::text[]) AS tag_values(tag_value)
                   WHERE trim(tag_value) <> ''
                      AND NOT (lower(trim(tag_value)) = ANY($6::text[]))
                 )
               ),
               notes = $7,
               status = 'active',
               updated_at = NOW()
           WHERE id = $1
           RETURNING *`,
          [student.id, studentName, parentName, parentEmail, tags, tagsToRemove, studentNotes]
        )).rows[0];
      } else {
        student = (await client.query(
          `INSERT INTO bna_students (
             project_id, name, parent_name, parent_email, tags, status, notes
           ) VALUES ($1, $2, $3, $4, $5::text[], 'active', $6)
           RETURNING *`,
          [project.id, studentName, parentName, parentEmail, tags, studentNotes]
        )).rows[0];
      }
      const studentAccessCode = await ensureStudentAccessCode(student.id, { regenerate: false }, client);

      let lead = (await client.query(
        `SELECT *
         FROM bna_parent_leads
         WHERE project_id = $1
           AND lower(COALESCE(parent_email, '')) = lower($2)
           AND 'one-time-parent-trial' = ANY(COALESCE(tags, '{}'::text[]))
         ORDER BY updated_at DESC NULLS LAST, id DESC
         LIMIT 1`,
        [project.id, parentEmail]
      )).rows[0] || null;
      const leadMetadata = {
        source: 'one_time_parent_trial_invite',
        project_key: ONE_TIME_PROJECT_KEY,
        trial_days: trialDays,
        student_id: student.id,
        no_payment_created: true,
        no_checkout_created: true,
        invite_mode: inviteMode,
        test_labeled: smokeMode,
        launch_ready: !smokeMode,
      };
      if (lead) {
        lead = (await client.query(
          `UPDATE bna_parent_leads
           SET parent_name = COALESCE(NULLIF($2, ''), parent_name),
               parent_email = $3,
               student_name = COALESCE(NULLIF($4, ''), student_name),
               lead_type = 'group_member',
               status = 'follow_up',
               interest_level = 'warm',
               source = 'manual',
               source_detail = 'Approved One Time parent trial invite',
               owner = 'Shloimie',
               tags = (
                 SELECT ARRAY(
                   SELECT DISTINCT tag_value
                   FROM unnest(COALESCE(tags, '{}'::text[]) || $5::text[]) AS tag_values(tag_value)
                   WHERE trim(tag_value) <> ''
                     AND NOT (lower(trim(tag_value)) = ANY($7::text[]))
                 )
               ),
               notes = $8,
               metadata = COALESCE(metadata, '{}'::jsonb) || $6::jsonb,
               updated_at = NOW()
           WHERE id = $1
           RETURNING *`,
          [lead.id, parentName, parentEmail, studentName, tags, JSON.stringify(leadMetadata), tagsToRemove, studentNotes]
        )).rows[0];
      } else {
        lead = (await client.query(
          `INSERT INTO bna_parent_leads (
             project_id, parent_name, parent_email, student_name,
             lead_type, status, interest_level, source, source_detail,
             owner, tags, notes, metadata
           ) VALUES (
             $1, $2, $3, $4,
             'group_member', 'follow_up', 'warm', 'manual', 'Approved One Time parent trial invite',
             'Shloimie', $5::text[], $6, $7::jsonb
           )
           RETURNING *`,
          [project.id, parentName, parentEmail, studentName, tags, studentNotes, JSON.stringify(leadMetadata)]
        )).rows[0];
      }

      let member = await ensureRabbiMember({
        projectId: project.id,
        displayName: parentName,
        email: parentEmail,
        notes: memberNotes,
        metadata: {
          source: 'one_time_parent_trial_invite',
          trial_days: trialDays,
          student_id: student.id,
          lead_id: lead.id,
          invite_mode: inviteMode,
          test_labeled: smokeMode,
          launch_ready: !smokeMode,
        },
        db: client,
      });
      if (!smokeMode) {
        member = (await client.query(
          `UPDATE bna_members
           SET notes = $2,
               metadata = COALESCE(metadata, '{}'::jsonb) || $3::jsonb,
               updated_at = NOW()
           WHERE id = $1
           RETURNING *`,
          [
            member.id,
            memberNotes,
            JSON.stringify({ invite_mode: inviteMode, test_labeled: false, launch_ready: true }),
          ]
        )).rows[0];
      }

      const expiresAt = new Date(Date.now() + trialDays * 24 * 60 * 60 * 1000);
      let memberAccess = (await client.query(
        `SELECT *
         FROM one_time_member_access
         WHERE lower(COALESCE(member_email, '')) = lower($1)
           AND COALESCE(metadata->>'source', '') = 'one_time_parent_trial_invite'
           AND status = 'active'
         ORDER BY updated_at DESC NULLS LAST, id DESC
         LIMIT 1`,
        [parentEmail]
      )).rows[0] || null;
      if (memberAccess) {
        memberAccess = (await client.query(
          `UPDATE one_time_member_access
           SET member_label = $2,
               tier = 'live_class',
               expires_at = $3,
               notes = $4,
               metadata = COALESCE(metadata, '{}'::jsonb) || $5::jsonb,
               updated_at = NOW()
           WHERE id = $1
           RETURNING *`,
          [
            memberAccess.id,
            `${parentName} / ${studentName}`,
            expiresAt,
            memberNotes,
            JSON.stringify({ source: 'one_time_parent_trial_invite', student_id: student.id, member_id: member.id, trial_days: trialDays, invite_mode: inviteMode, test_labeled: smokeMode, launch_ready: !smokeMode }),
          ]
        )).rows[0];
      } else {
        memberAccess = (await client.query(
          `INSERT INTO one_time_member_access (
             access_code, member_label, member_email, tier, status,
             expires_at, notes, metadata
           ) VALUES ($1, $2, $3, 'live_class', 'active', $4, $5, $6::jsonb)
           RETURNING *`,
          [
            `OT-${generateSecureToken(12)}`,
            `${parentName} / ${studentName}`,
            parentEmail,
            expiresAt,
            memberNotes,
            JSON.stringify({ source: 'one_time_parent_trial_invite', student_id: student.id, member_id: member.id, lead_id: lead.id, trial_days: trialDays, invite_mode: inviteMode, test_labeled: smokeMode, launch_ready: !smokeMode }),
          ]
        )).rows[0];
      }

      let accessGrant = (await client.query(
        `SELECT *
         FROM bna_access_grants
         WHERE project_id = $1
           AND member_id = $2
           AND tier_key = 'live_library'
           AND status = 'active'
           AND COALESCE(metadata->>'source', '') = 'one_time_parent_trial_invite'
         ORDER BY updated_at DESC NULLS LAST, id DESC
         LIMIT 1`,
        [project.id, member.id]
      )).rows[0] || null;
      if (!accessGrant) {
        accessGrant = await createRabbiAccessGrant({
          projectId: project.id,
          memberId: member.id,
          tier: { tier_key: 'live_library' },
          source: 'one_time_parent_trial_invite',
          notes: memberNotes,
          metadata: {
            source: 'one_time_parent_trial_invite',
            trial_days: trialDays,
            student_id: student.id,
            member_access_id: memberAccess.id,
            invite_mode: inviteMode,
            test_labeled: smokeMode,
            launch_ready: !smokeMode,
          },
          db: client,
        });
      }

      const reset = await createParentPasswordResetToken({
        parentEmail,
        req,
        metadata: {
          source: 'one_time_parent_trial_invite',
          project_key: ONE_TIME_PROJECT_KEY,
          student_id: student.id,
          lead_id: lead.id,
          member_id: member.id,
          member_access_id: memberAccess.id,
          no_generic_email_sent: true,
          invite_mode: inviteMode,
          test_labeled: smokeMode,
        },
        sendEmail: false,
        ttlMs: ONE_TIME_PARENT_TRIAL_PASSWORD_SETUP_TTL_MS,
      }, client);

      const passwordSetupUrl = oneTimeParentPortalPasswordResetUrl(reset.token) || reset.url;
      const memberLibraryUrl = scopedPublicUrl(oneTimeBaseUrl, `/member-library?code=${encodeURIComponent(memberAccess.access_code)}`);
      const classroomUrl = scopedPublicUrl(oneTimeBaseUrl, `/one-time-classroom?code=${encodeURIComponent(memberAccess.access_code)}`);
      const template = buildRabbiEmailTemplate('parent_trial_invite', {
        programName: ONE_TIME_EMAIL_FROM_NAME,
        recipientName: parentName,
        studentName,
        passwordSetupUrl,
        liveClassUrl,
        memberLibraryUrl,
        classroomUrl,
      });
      await client.query('COMMIT');
      committed = true;
      let emailResult = { ok: false, provider: 'not_sent', providerMessageId: null, error: null };
      try {
        const sent = await sendEmail({
          workspace: 'one_time_mishnah_class',
          to: parentEmail,
          subject: template.subject,
          text: template.text,
          html: template.html,
        });
        emailResult = {
          ok: true,
          provider: sent?.provider || EMAIL_PROVIDER || 'gmail',
          providerMessageId: sent?.data?.id || null,
          error: null,
        };
      } catch (error) {
        emailResult = {
          ok: false,
          provider: EMAIL_PROVIDER || 'gmail',
          providerMessageId: null,
          error: error.message,
        };
      }
      await logEmail({
        projectId: project.id,
        memberId: member.id,
        emailType: 'one_time_parent_trial_invite',
        templateKey: 'parent_trial_invite',
        to: parentEmail,
        recipientName: parentName,
        subject: template.subject,
        text: template.text,
        html: template.html,
        provider: emailResult.provider,
        providerMessageId: emailResult.providerMessageId,
        status: emailResult.ok ? 'sent' : 'failed',
        error: emailResult.error,
        metadata: {
          workspace_key: 'rabbi_sheller_provider',
          project_key: ONE_TIME_PROJECT_KEY,
          source: 'one_time_parent_trial_invite',
          student_id: student.id,
          lead_id: lead.id,
          member_access_id: memberAccess.id,
          one_time_public_base_url: oneTimeBaseUrl,
          live_class_url_included: Boolean(liveClassUrl),
          invite_mode: inviteMode,
          test_labeled: smokeMode,
          no_payment_created: true,
          no_checkout_created: true,
        },
      });
      await pool.query(
        `INSERT INTO bna_contact_communications (
           project_id, contact_type, lead_id, student_id, channel, direction,
           summary, body, follow_up_required, occurred_at, created_by, source,
           source_context, metadata
         ) VALUES (
           $1, 'lead', $2, $3, 'email', 'outbound',
           $4, $5, FALSE, NOW(), $6, 'dashboard',
           $7::jsonb, $8::jsonb
         )`,
        [
          project.id,
          lead.id,
          student.id,
          emailResult.ok ? 'One Time parent trial invite sent' : 'One Time parent trial invite attempted',
          emailResult.ok
            ? 'Sent One Time parent trial invite with parent password setup, classroom, and member library links.'
            : `One Time parent trial invite send failed: ${emailResult.error || 'unknown error'}`,
          req.opsUser || 'admin',
          JSON.stringify({ source: 'one_time_parent_trial_invite', member_access_id: memberAccess.id, member_id: member.id }),
          JSON.stringify({
            parent_email: parentEmail,
            student_id: student.id,
            trial_days: trialDays,
            email_sent: Boolean(emailResult.ok),
            email_error: emailResult.error || null,
            one_time_public_base_url: oneTimeBaseUrl,
            live_class_url_included: Boolean(liveClassUrl),
            invite_mode: inviteMode,
            test_labeled: smokeMode,
            no_payment_created: true,
            no_checkout_created: true,
          }),
        ]
      ).catch(() => {});
      res.json({
        success: true,
        dry_run: false,
        no_payment_created: true,
        no_checkout_created: true,
        external_write_performed: Boolean(emailResult.ok),
        local_write_performed: true,
        parent_email: parentEmail,
        student_id: student.id,
        student_name: student.name,
        invite_mode: inviteMode,
        test_labeled: smokeMode,
        student_access_code_created: Boolean(studentAccessCode),
        lead_id: lead.id,
        member_id: member.id,
        member_access_id: memberAccess.id,
        member_access_expires_at: memberAccess.expires_at,
        email_sent: Boolean(emailResult.ok),
        email_error: emailResult.error || null,
        one_time_public_base_url: oneTimeBaseUrl,
        live_class_url_included: Boolean(liveClassUrl),
        preflight,
        member_library_url: memberLibraryUrl,
        classroom_url: classroomUrl,
        parent_password_setup_expires_at: reset.expires_at,
      });
    } catch (error) {
      if (!committed) await client.query('ROLLBACK').catch(() => {});
      res.status(error.statusCode || 500).json({ error: error.message });
    } finally {
      client.release();
    }
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

