app.patch('/api/bna/rabbi/site', requireAdmin, async (req, res) => {
  const body = req.body || {};
  try {
    const project = await assertRabbiAdminAccess(req);
    const current = (await pool.query(
      `SELECT * FROM bna_project_public_pages WHERE project_id = $1 AND page_key = $2 LIMIT 1`,
      [project.id, RABBI_PAGE_KEY]
    )).rows[0] || {};
    const content = body.content && typeof body.content === 'object'
      ? body.content
      : rabbiJson(current.content, defaultRabbiLandingContent());
    const status = ['draft', 'preview', 'approved', 'published', 'archived'].includes(String(body.status || current.status || 'preview'))
      ? String(body.status || current.status || 'preview')
      : 'preview';
    const row = (await pool.query(
      `INSERT INTO bna_project_public_pages (
         project_id, page_key, route_path, title, status, allow_public_replacement,
         content, metadata, updated_at
       ) VALUES ($1, $2, '/rabbi', $3, $4, FALSE, $5::jsonb, $6::jsonb, NOW())
       ON CONFLICT (project_id, page_key)
       DO UPDATE SET
         title = EXCLUDED.title,
         status = CASE WHEN EXCLUDED.status = 'published' THEN 'preview' ELSE EXCLUDED.status END,
         allow_public_replacement = FALSE,
         content = EXCLUDED.content,
         metadata = EXCLUDED.metadata,
         updated_at = NOW()
       RETURNING *`,
      [
        project.id,
        RABBI_PAGE_KEY,
        limitText(body.title || current.title || RABBI_DEFAULT_TITLE, 200),
        status === 'published' ? 'preview' : status,
        JSON.stringify(content),
        JSON.stringify({ ...(body.metadata && typeof body.metadata === 'object' ? body.metadata : {}), preview_only: true }),
      ]
    )).rows[0];
    res.json({ success: true, site: rabbiPageView({ ...row, content: rabbiJson(row.content), metadata: rabbiJson(row.metadata) }) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.post('/api/bna/rabbi/site/approve-public-replacement', requireAdmin, async (req, res) => {
  try {
    const project = await assertRabbiAdminAccess(req);
    const approval = String(req.body?.approval || req.body?.approval_flag || '').trim();
    if (approval !== 'APPROVE_RABBI_PUBLIC_REPLACEMENT_PREVIEW') {
      return res.status(400).json({ error: 'Public replacement approval requires APPROVE_RABBI_PUBLIC_REPLACEMENT_PREVIEW.' });
    }
    const allowEnv = String(process.env.RABBI_ALLOW_PUBLIC_REPLACEMENT || '').toLowerCase() === 'true';
    const row = (await pool.query(
      `UPDATE bna_project_public_pages
       SET status = 'approved',
           allow_public_replacement = $3,
           approved_by = $4,
           approved_at = NOW(),
           metadata = COALESCE(metadata, '{}'::jsonb) || $5::jsonb,
           updated_at = NOW()
       WHERE project_id = $1 AND page_key = $2
       RETURNING *`,
      [
        project.id,
        RABBI_PAGE_KEY,
        allowEnv,
        req.opsUser || 'dashboard',
        JSON.stringify({ env_flag_required: true, env_flag_present: allowEnv }),
      ]
    )).rows[0];
    res.json({ success: true, public_replacement_allowed: publicReplacementAllowed({ page: row, env: process.env }), site: rabbiPageView(row) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

