app.get('/api/rabbi/member/library', async (req, res) => {
  try {
    const auth = await rabbiMemberFromSessionToken(bearerOrBodyToken(req));
    const scopes = activeGrantScopes(auth.grants);
    if (!scopes.includes('library')) {
      return res.json({ success: true, member: publicMemberView(auth.member, auth.grants), items: [], access_pending: true });
    }
    const firstPartyRows = (await pool.query(
      `SELECT * FROM bna_library_items
       WHERE project_id = $1
         AND visibility = 'published'
         AND required_scope = ANY($2::text[])
       ORDER BY COALESCE(published_at, created_at) DESC, id DESC
       LIMIT 200`,
      [auth.project.id, scopes]
    )).rows.map(rabbiLibraryItemView);
    const publishedOneTime = (await pool.query(
      `SELECT * FROM one_time_member_library_items
       WHERE project_id = $1
         AND publish_status = 'published'
       ORDER BY COALESCE(published_at, created_at) DESC, id DESC
       LIMIT 200`,
      [auth.project.id]
    )).rows.map((row) => rabbiLibraryItemView({
      id: `one_time_${row.id}`,
      project_id: row.project_id,
      title: row.title,
      description: row.description,
      item_type: 'video',
      media_url: row.media_url,
      vimeo_url: row.media_url,
      thumbnail_url: row.thumbnail_url,
      required_scope: 'library',
      visibility: 'published',
      source_table: 'one_time_member_library_items',
      source_id: row.id,
      metadata: row.package_snapshot,
      published_at: row.published_at,
      created_at: row.created_at,
      updated_at: row.updated_at,
    }));
    res.json({ success: true, member: publicMemberView(auth.member, auth.grants), items: [...firstPartyRows, ...publishedOneTime] });
  } catch (err) {
    res.status(err.statusCode || 500).json({ success: false, error: err.message });
  }
});

