app.patch('/api/bna/members/:id', requireAdmin, async (req, res) => {
  const body = req.body || {};
  try {
    await assertProjectOwnedRowAccess(req, 'bna_members', req.params.id);
    const fields = [];
    const values = [];
    const add = (field, value) => {
      values.push(value);
      fields.push(`${field} = $${values.length}`);
    };
    if (Object.prototype.hasOwnProperty.call(body, 'display_name') || Object.prototype.hasOwnProperty.call(body, 'displayName')) add('display_name', limitText(body.display_name || body.displayName, 180));
    if (Object.prototype.hasOwnProperty.call(body, 'email')) add('email', normalizeEmail(body.email || ''));
    if (Object.prototype.hasOwnProperty.call(body, 'phone')) add('phone', limitText(body.phone || '', 80) || null);
    if (Object.prototype.hasOwnProperty.call(body, 'access_tier') || Object.prototype.hasOwnProperty.call(body, 'accessTier')) add('access_tier', requireLiveAccessTier(body.access_tier || body.accessTier));
    if (Object.prototype.hasOwnProperty.call(body, 'access_status') || Object.prototype.hasOwnProperty.call(body, 'accessStatus')) add('access_status', requireLiveAccessStatus(body.access_status || body.accessStatus));
    if (Object.prototype.hasOwnProperty.call(body, 'access_enabled') || Object.prototype.hasOwnProperty.call(body, 'accessEnabled')) add('access_enabled', liveClassBoolean(body.access_enabled ?? body.accessEnabled, true));
    if (Object.prototype.hasOwnProperty.call(body, 'notes')) add('notes', limitText(body.notes || '', 2000) || null);
    if (Object.prototype.hasOwnProperty.call(body, 'metadata')) add('metadata', JSON.stringify(liveClassMetadata(body.metadata)));
    if (!fields.length) return res.status(400).json({ error: 'No supported member fields supplied' });
    add('updated_at', new Date());
    values.push(req.params.id);
    const result = await pool.query(
      `UPDATE bna_members SET ${fields.join(', ')} WHERE id = $${values.length} RETURNING *`,
      values
    );
    if (!result.rows[0]) return res.status(404).json({ error: 'Member not found' });
    res.json({ success: true, member: liveMemberView(result.rows[0], req) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

