app.patch('/api/bna/live-sessions/:id', requireAdmin, async (req, res) => {
  const body = req.body || {};
  try {
    await assertProjectOwnedRowAccess(req, 'bna_live_class_sessions', req.params.id);
    const current = await getLiveSessionOr404(req.params.id);
    const fields = [];
    const values = [];
    const add = (field, value) => {
      values.push(value);
      fields.push(`${field} = $${values.length}`);
    };
    if (Object.prototype.hasOwnProperty.call(body, 'title')) add('title', limitText(body.title, 220));
    if (Object.prototype.hasOwnProperty.call(body, 'description')) add('description', limitText(body.description || '', 2000) || null);
    if (Object.prototype.hasOwnProperty.call(body, 'start_at') || Object.prototype.hasOwnProperty.call(body, 'startAt')) add('start_at', body.start_at || body.startAt);
    if (Object.prototype.hasOwnProperty.call(body, 'end_at') || Object.prototype.hasOwnProperty.call(body, 'endAt')) add('end_at', body.end_at || body.endAt || null);
    if (Object.prototype.hasOwnProperty.call(body, 'timezone')) add('timezone', limitText(body.timezone || 'Asia/Jerusalem', 80));
    if (Object.prototype.hasOwnProperty.call(body, 'required_tier') || Object.prototype.hasOwnProperty.call(body, 'requiredTier')) add('required_tier', requireLiveAccessTier(body.required_tier || body.requiredTier, LIVE_ACCESS_TIERS.LIVE_PLUS_LIBRARY));
    if (Object.prototype.hasOwnProperty.call(body, 'status')) add('status', requireLiveSessionStatus(body.status, current.status));
    if (Object.prototype.hasOwnProperty.call(body, 'reminders_enabled') || Object.prototype.hasOwnProperty.call(body, 'remindersEnabled')) add('reminders_enabled', liveClassBoolean(body.reminders_enabled ?? body.remindersEnabled, true));
    if (Object.prototype.hasOwnProperty.call(body, 'reminder_minutes_before') || Object.prototype.hasOwnProperty.call(body, 'reminderMinutesBefore')) add('reminder_minutes_before', liveClassInt(body.reminder_minutes_before || body.reminderMinutesBefore, 60));
    if (Object.prototype.hasOwnProperty.call(body, 'zoom_meeting_id') || Object.prototype.hasOwnProperty.call(body, 'zoomMeetingId')) add('zoom_meeting_id', limitText(body.zoom_meeting_id || body.zoomMeetingId || '', 120) || null);
    if (Object.prototype.hasOwnProperty.call(body, 'vimeo_recording_url') || Object.prototype.hasOwnProperty.call(body, 'vimeoRecordingUrl')) add('vimeo_recording_url', hostedHttpUrl(body.vimeo_recording_url || body.vimeoRecordingUrl || '', 'Vimeo recording URL', { required: false }));
    if (Object.prototype.hasOwnProperty.call(body, 'recording_status') || Object.prototype.hasOwnProperty.call(body, 'recordingStatus')) {
      const nextStatus = requireLiveRecordingStatus(body.recording_status || body.recordingStatus, current.recording_status);
      add('recording_status', nextStatus);
      if (nextStatus === 'published' && !current.published_at) add('published_at', new Date());
      if (nextStatus !== 'published') add('published_at', null);
    }
    if (Object.prototype.hasOwnProperty.call(body, 'notes')) add('notes', limitText(body.notes || '', 2000) || null);
    if (Object.prototype.hasOwnProperty.call(body, 'metadata')) add('metadata', JSON.stringify(liveClassMetadata(body.metadata)));
    if (Object.prototype.hasOwnProperty.call(body, 'zoom_meeting_url') || Object.prototype.hasOwnProperty.call(body, 'zoomMeetingUrl')) {
      const nextZoom = hostedHttpUrl(body.zoom_meeting_url || body.zoomMeetingUrl || '', 'Zoom meeting URL', { required: false });
      if (String(nextZoom || '') !== String(current.zoom_meeting_url || '')) {
        add('zoom_meeting_url', nextZoom);
        fields.push('link_version = COALESCE(link_version, 0) + 1');
        fields.push('zoom_link_updated_at = NOW()');
        fields.push('last_zoom_link_sent_at = NULL');
      }
    }
    if (!fields.length) return res.status(400).json({ error: 'No supported live session fields supplied' });
    fields.push('updated_at = NOW()');
    values.push(req.params.id);
    const result = await pool.query(
      `UPDATE bna_live_class_sessions SET ${fields.join(', ')} WHERE id = $${values.length} RETURNING *`,
      values
    );
    res.json({ success: true, session: await liveSessionWithCountsView(result.rows[0], req) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

