app.post('/api/bna/live-sessions/:id/send-zoom-link', requireAdmin, async (req, res) => {
  const body = req.body || {};
  try {
    await assertProjectOwnedRowAccess(req, 'bna_live_class_sessions', req.params.id);
    const session = await getLiveSessionOr404(req.params.id);
    const dryRun = body.dryRun === undefined && body.dry_run === undefined
      ? true
      : liveClassBoolean(body.dryRun ?? body.dry_run, true);
    const memberId = liveClassInt(body.member_id || body.memberId);
    const params = [];
    const conditions = ['1=1'];
    if (memberId) {
      params.push(memberId);
      conditions.push(`id = $${params.length}`);
    } else {
      conditions.push("access_status IN ('active', 'trial')");
      conditions.push('access_enabled = TRUE');
    }
    if (session.project_id) {
      params.push(session.project_id);
      conditions.push(`project_id = $${params.length}`);
    } else {
      appendScopeCondition(req, conditions, params, 'project_id');
    }
    const members = (await pool.query(
      `SELECT * FROM bna_members WHERE ${conditions.join(' AND ')} ORDER BY display_name ASC LIMIT 1000`,
      params
    )).rows;
    if (memberId && !members.length) return res.status(404).json({ error: 'Member not found for this live session project' });
    const results = [];
    for (const member of members) {
      results.push(await sendLiveZoomLinkToMember({
        member,
        session,
        dryRun,
        createdBy: req.opsUser || 'dashboard',
      }));
    }
    if (!dryRun && results.some((item) => item.status === 'sent')) {
      await pool.query('UPDATE bna_live_class_sessions SET last_zoom_link_sent_at = NOW(), updated_at = NOW() WHERE id = $1', [session.id]);
    }
    const summary = results.reduce((acc, item) => {
      acc[item.status] = (acc[item.status] || 0) + 1;
      return acc;
    }, {});
    res.json({ success: true, dryRun, setup_required: Boolean(summary.setup_required), summary, results });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

