app.patch('/api/bna/pipeline-cards/:id', requireAdmin, async (req, res) => {
  try {
    const existing = (await pool.query('SELECT * FROM bna_pipeline_cards WHERE id = $1', [req.params.id])).rows[0];
    if (!existing) return res.status(404).json({ error: 'Pipeline card not found' });
    assertWorkspaceAccess(req, existing.workspace_key);

    const fields = [];
    const values = [];
    const body = req.body || {};
    const textFields = {
      pipeline_key: 100,
      stage_key: 100,
      title: 220,
      summary: 1200,
      contact_type: 80,
      owner_name: 120,
      next_action: 400,
      source: 80,
    };
    for (const [key, max] of Object.entries(textFields)) {
      if (body[key] !== undefined) {
        values.push(limitText(body[key], max) || null);
        fields.push(`${key} = $${values.length}`);
      }
    }
    if (body.contact_id !== undefined) {
      values.push(body.contact_id === '' || body.contact_id === null ? null : Number(body.contact_id));
      fields.push(`contact_id = $${values.length}`);
    }
    if (body.status !== undefined) {
      values.push(safePipelineStatus(body.status, existing.status));
      fields.push(`status = $${values.length}`);
    }
    if (body.due_at !== undefined || body.dueAt !== undefined) {
      values.push(body.due_at || body.dueAt || null);
      fields.push(`due_at = $${values.length}::timestamp`);
    }
    if (body.metadata !== undefined || body.metadata_json !== undefined) {
      const metadata = body.metadata !== undefined ? body.metadata : body.metadata_json;
      values.push(JSON.stringify(metadata && typeof metadata === 'object' ? metadata : {}));
      fields.push(`metadata_json = COALESCE(metadata_json, '{}'::jsonb) || $${values.length}::jsonb`);
    }
    if (!fields.length) return res.status(400).json({ error: 'No supported pipeline fields supplied' });
    values.push(req.params.id);
    const result = await pool.query(
      `UPDATE bna_pipeline_cards
       SET ${fields.join(', ')},
           updated_at = NOW()
       WHERE id = $${values.length}
       RETURNING *`,
      values
    );
    res.json({ success: true, card: pipelineCardView(result.rows[0]) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.get('/api/bna/internal-dialogue', requireAdmin, async (req, res) => {
  try {
    await ensureWorkspacePlatformDefaultsOnce();
    const requestedWorkspace = normalizeWorkspaceKey(req.query.workspace || req.query.workspace_key || '');
    const scopedWorkspace = opsScopeProjectKey(req) ? defaultWorkspaceKeyForRequest(req) : '';
    if (scopedWorkspace && requestedWorkspace && requestedWorkspace !== scopedWorkspace) assertWorkspaceAccess(req, requestedWorkspace);
    const workspaceFilter = scopedWorkspace || requestedWorkspace;
    if (workspaceFilter) assertWorkspaceAccess(req, workspaceFilter);
    const threadParams = [];
    const threadConditions = [`status <> 'archived'`];
    if (workspaceFilter) {
      threadParams.push(workspaceFilter);
      threadConditions.push(`workspace_key = $${threadParams.length}`);
    }
    if (req.query.thread_id) {
      threadParams.push(Number(req.query.thread_id));
      threadConditions.push(`id = $${threadParams.length}`);
    }
    const threads = (await pool.query(
      `SELECT * FROM bna_internal_threads
       WHERE ${threadConditions.join(' AND ')}
       ORDER BY updated_at DESC, id DESC
       LIMIT 100`,
      threadParams
    )).rows;
    const threadIds = threads.map((thread) => Number(thread.id)).filter(Number.isFinite);
    let messages = [];
    if (threadIds.length) {
      const messageResult = await pool.query(
        `SELECT * FROM bna_internal_messages
         WHERE thread_id = ANY($1::int[])
         ORDER BY created_at DESC, id DESC
         LIMIT 300`,
        [threadIds]
      );
      messages = messageResult.rows;
    }
    res.json({
      success: true,
      threads: threads.map(internalThreadView),
      messages: messages.map(internalMessageView),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.post('/api/bna/internal-dialogue/messages', requireAdmin, async (req, res) => {
  try {
    await ensureWorkspacePlatformDefaultsOnce();
    const body = req.body || {};
    const workspaceKey = assertWorkspaceAccess(req, body.workspace_key || body.workspace || defaultWorkspaceKeyForRequest(req));
    const text = limitText(body.body || body.message || body.note, 5000);
    if (!text) return res.status(400).json({ error: 'body is required' });

    let thread = null;
    if (body.thread_id) {
      thread = (await pool.query('SELECT * FROM bna_internal_threads WHERE id = $1', [body.thread_id])).rows[0];
      if (!thread) return res.status(404).json({ error: 'Thread not found' });
      assertWorkspaceAccess(req, thread.workspace_key);
    } else {
      const threadKey = limitText(body.thread_key || body.threadKey || 'general-operations', 140)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '') || 'general-operations';
      const threadTitle = limitText(body.thread_title || body.title || 'Operations dialogue', 220) || 'Operations dialogue';
      thread = (await pool.query(
        `INSERT INTO bna_internal_threads (
           workspace_key, thread_key, title, related_type, related_id, metadata_json
         ) VALUES ($1, $2, $3, $4, $5, $6::jsonb)
         ON CONFLICT (workspace_key, thread_key) DO UPDATE SET
           title = EXCLUDED.title,
           updated_at = NOW()
         RETURNING *`,
        [
          workspaceKey,
          threadKey,
          threadTitle,
          body.related_type || null,
          body.related_id === undefined || body.related_id === '' ? null : Number(body.related_id),
          JSON.stringify(body.thread_metadata || {}),
        ]
      )).rows[0];
    }

    const result = await pool.query(
      `INSERT INTO bna_internal_messages (
         thread_id, author_name, author_role, body, message_type, metadata_json
       ) VALUES ($1, $2, $3, $4, $5, $6::jsonb)
       RETURNING *`,
      [
        thread.id,
        limitText(body.author_name || req.opsUser || 'admin', 120) || 'admin',
        limitText(body.author_role || req.opsIdentity?.role || 'admin', 80) || 'admin',
        text,
        safeInternalMessageType(body.message_type || body.type),
        JSON.stringify(body.metadata || {}),
      ]
    );
    await pool.query('UPDATE bna_internal_threads SET updated_at = NOW() WHERE id = $1', [thread.id]);
    res.json({
      success: true,
      thread: internalThreadView(thread),
      message: internalMessageView(result.rows[0]),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

