app.post('/api/bna/bot-actions/execute', requireAdmin, async (req, res) => {
  try {
    const body = req.body || {};
    const logId = body.log_id || body.id;
    if (!logId) return res.status(400).json({ error: 'log_id is required for audited execution' });
    const existing = (await pool.query('SELECT * FROM bna_bot_action_logs WHERE id = $1', [logId])).rows[0];
    if (!existing) return res.status(404).json({ error: 'Bot action log not found' });
    assertWorkspaceAccess(req, existing.workspace_key);
    const approved = String(body.confirm || '').trim() === 'APPROVE_TYPED_ACTION';
    if (!approved) return res.status(400).json({ error: 'Typed action execution requires confirm: APPROVE_TYPED_ACTION' });
    const preview = parseJsonMaybe(existing.preview_json);
    const result = await runAction({
      action_id: existing.action_key,
      inputs: body.payload || body.inputs || preview.input_summary || {},
      source: body.source || 'ui_bot',
      approved: true,
      dry_run: false,
      actor: {
        user_id: req.opsUser || 'admin',
        role: body.actor_role || req.opsIdentity?.role || existing.actor_role || 'admin',
        workspace_id: existing.workspace_key,
      },
    }, actionRunnerContext(req, body.source || 'ui_bot'));
    await pool.query(
      `UPDATE bna_bot_action_logs
       SET status = $2,
           result_json = $3::jsonb
       WHERE id = $1`,
      [
        logId,
        result.success && result.executed ? 'approved' : 'failed',
        JSON.stringify({
          forwarded_to_action_run_id: result.audit_log?.action_run_id || null,
          result_status: result.success ? 'executed' : 'failed',
          result_summary: result.audit_log?.result_summary || null,
          error: result.error || null,
        }),
      ]
    );
    res.status(result.success ? 200 : 400).json({
      success: result.success,
      log: result.audit_log?.persisted_log ? botActionLogView(result.audit_log.persisted_log) : null,
      result,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.get('/api/bna/notifications', requireAdmin, async (req, res) => {
  const conditions = [];
  const params = [];
  appendScopeCondition(req, conditions, params, 'n.project_id');
  const status = String(req.query.status || '').trim();
  if (status && status !== 'all') {
    params.push(safeNotificationStatus(status));
    conditions.push(`n.status = $${params.length}`);
  } else {
    conditions.push(`n.status <> 'archived'`);
  }
  if (req.query.event_type) {
    params.push(safeNotificationEventType(req.query.event_type));
    conditions.push(`n.event_type = $${params.length}`);
  }
  if (req.query.workspace || req.query.workspace_key) {
    const workspaceKey = assertWorkspaceAccess(req, req.query.workspace || req.query.workspace_key);
    params.push(workspaceKey);
    conditions.push(`n.workspace_key = $${params.length}`);
  }
  const limit = Math.max(10, Math.min(Number(req.query.limit || 80), 200));
  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  try {
    const result = await pool.query(
      `SELECT n.*,
              p.project_key,
              p.name AS project_name
       FROM bna_in_app_notifications n
       LEFT JOIN bna_projects p ON p.id = n.project_id
       ${whereClause}
       ORDER BY
         CASE n.status WHEN 'unread' THEN 1 WHEN 'read' THEN 2 ELSE 3 END,
         CASE n.priority WHEN 'urgent' THEN 1 WHEN 'high' THEN 2 WHEN 'normal' THEN 3 ELSE 4 END,
         n.created_at DESC,
         n.id DESC
       LIMIT ${limit}`,
      params
    );
    const notifications = result.rows.map(inAppNotificationView);
    res.json({
      success: true,
      notifications,
      summary: {
        total: notifications.length,
        unread: notifications.filter((item) => item.status === 'unread').length,
        urgent: notifications.filter((item) => item.priority === 'urgent').length,
        high: notifications.filter((item) => item.priority === 'high').length,
      },
      channel: 'in_app',
      no_send: true,
      external_write_performed: false,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

