app.get('/api/bna/task-artifact', requireAdmin, async (req, res) => {
  try {
    const safePath = normalizeRepoArtifactPath(req.query.path || '');
    if (!safePath) return res.status(400).json({ error: 'Artifact path is not allowed' });
    const absolutePath = path.resolve(__dirname, safePath);
    const repoRoot = path.resolve(__dirname);
    if (!absolutePath.startsWith(repoRoot + path.sep)) {
      return res.status(400).json({ error: 'Artifact path is outside the repository' });
    }
    if (!fs.existsSync(absolutePath) || !fs.statSync(absolutePath).isFile()) {
      return res.status(404).json({ error: 'Artifact not found' });
    }
    res.sendFile(absolutePath);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/bna/tasks/:id', requireAdmin, async (req, res) => {
  try {
    await assertTaskAccess(req, req.params.id);
    const result = await pool.query(
      `WITH latest_jobs AS (
         SELECT DISTINCT ON (task_id)
           *
         FROM bna_agent_jobs
         WHERE task_id = $1
         ORDER BY task_id, created_at DESC
       )
       SELECT t.*,
              p.project_key,
              p.name AS project_name,
              p.short_name AS project_short_name,
              lj.id AS latest_agent_job_id,
              lj.status AS agent_job_status,
              lj.title AS agent_job_title,
              lj.result_summary AS agent_result_summary,
              lj.current_blocker AS agent_current_blocker,
              lj.error_message AS agent_error_message,
              lj.report_path AS agent_report_path,
              lj.ledger_ref AS agent_ledger_ref,
              lj.changelog_ref AS agent_changelog_ref,
              lj.heartbeat_at AS agent_job_heartbeat_at,
              lj.created_at AS agent_job_created_at,
              lj.updated_at AS agent_job_updated_at
       FROM bna_tasks t
       LEFT JOIN bna_projects p ON p.id = t.project_id
       LEFT JOIN latest_jobs lj ON lj.task_id = t.id
       WHERE t.id = $1
       LIMIT 1`,
      [req.params.id]
    );
    const task = taskApiView(result.rows[0] || null);
    if (!task) return res.status(404).json({ error: 'Task not found' });
    const comments = (await pool.query(
      `SELECT *
       FROM bna_task_comments
       WHERE task_id = $1
       ORDER BY created_at ASC`,
      [req.params.id]
    )).rows;
    const activity = (await pool.query(
      `SELECT *
       FROM bna_task_activity
       WHERE task_id = $1
       ORDER BY created_at DESC
       LIMIT 80`,
      [req.params.id]
    )).rows;
    const linkedTaskParams = [req.params.id];
    const linkedTaskWhere = ['child.parent_task_id = $1'];
    const linkedTaskScopedProjectKey = opsScopeProjectKey(req);
    if (linkedTaskScopedProjectKey) {
      linkedTaskParams.push(linkedTaskScopedProjectKey);
      linkedTaskWhere.push(`p.project_key = $${linkedTaskParams.length}`);
    }
    const linkedTasks = (await pool.query(
      `SELECT child.id, child.title, child.display_title, child.stage, child.task_kind, child.assigned_to, child.agent_status, child.decision_required, child.created_at, child.updated_at
       FROM bna_tasks child
       LEFT JOIN bna_projects p ON p.id = child.project_id
       WHERE ${linkedTaskWhere.join(' AND ')}
       ORDER BY child.updated_at DESC, child.created_at DESC
       LIMIT 40`,
      linkedTaskParams
    )).rows;
    const activeDecisionQueue = (await pool.query(
      `SELECT *
       FROM bna_decision_reprocess_queue
       WHERE task_id = $1
       ORDER BY CASE status WHEN 'processing' THEN 1 WHEN 'queued' THEN 2 ELSE 3 END, updated_at DESC
       LIMIT 10`,
      [req.params.id]
    )).rows;
    res.json({ success: true, task, comments, activity, linked_tasks: linkedTasks, decision_queue: activeDecisionQueue, latest_agent_job: task.latest_agent_job_id ? observableAgentJobView({
      id: task.latest_agent_job_id,
      task_id: task.id,
      status: task.agent_job_status,
      title: task.agent_job_title,
      result_summary: task.agent_result_summary,
      current_blocker: task.agent_current_blocker,
      error_message: task.agent_error_message,
      report_path: task.agent_report_path,
      ledger_ref: task.agent_ledger_ref,
      changelog_ref: task.agent_changelog_ref,
      heartbeat_at: task.agent_job_heartbeat_at,
      created_at: task.agent_job_created_at,
      updated_at: task.agent_job_updated_at,
    }) : null });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

