app.post('/api/bna/tasks/:id/actions/archive-duplicate', requireAdmin, async (req, res) => {
  taskActionResponse(req, res, async () => {
    const current = await fetchTaskWithProject(req.params.id);
    if (!current) {
      const error = new Error('Task not found');
      error.statusCode = 404;
      throw error;
    }
    let canonicalId = Number(req.body?.canonical_task_id || req.body?.canonicalTaskId || req.body?.canonical_id || req.body?.canonicalId || 0);
    if (!canonicalId && current.dedupe_key) {
      const canonical = (await pool.query(
        `SELECT id
         FROM bna_tasks
         WHERE dedupe_key = $1
           AND id <> $2
           AND COALESCE(stage, '') NOT IN ('archive', 'done')
           AND duplicate_archived_at IS NULL
           AND canonical_task_id IS NULL
           AND duplicate_of_task_id IS NULL
         ORDER BY COALESCE(updated_at, created_at) DESC, created_at ASC, id ASC
         LIMIT 1`,
        [current.dedupe_key, req.params.id]
      )).rows[0];
      canonicalId = Number(canonical?.id || 0);
    }
    if (!canonicalId || canonicalId === Number(req.params.id)) {
      const error = new Error('Archive duplicate requires a different canonical task ID.');
      error.statusCode = 400;
      throw error;
    }
    await assertTaskAccess(req, canonicalId);
    const canonical = await fetchTaskWithProject(canonicalId);
    if (!canonical) {
      const error = new Error('Canonical task not found');
      error.statusCode = 404;
      throw error;
    }
    const reason = String(req.body?.reason || `Duplicate of task #${canonicalId} collapsed during pending/access dedupe cleanup.`).slice(0, 1000);
    const task = await patchTaskAndReturn(req.params.id, {
      stage: 'archive',
      task_kind: current.task_kind || 'pending_access',
      workflow_status: 'duplicate_archived',
      status_detail: 'duplicate_archived',
      canonical_task_id: canonicalId,
      duplicate_of_task_id: canonicalId,
      duplicate_archived_at: new Date().toISOString(),
      duplicate_reason: reason,
      archived_at: new Date().toISOString(),
      decision_required: false,
      agent_status: 'none',
      next_action_label: 'Duplicate archived',
      next_action: `See canonical task #${canonicalId}`,
    }, {
      actor: req.opsUser || 'dashboard',
      eventType: 'duplicate_archived',
      eventSummary: reason,
    });
    await addTaskSystemComment(req.params.id, `${reason} Canonical task: #${canonicalId}.`, {
      author: req.opsUser || 'dashboard',
      visibility: isOneTimeProjectKey(current?.project_key) ? 'project' : 'internal',
      metadata: { action: 'archive_duplicate', canonical_task_id: canonicalId },
    });
    await addTaskSystemComment(canonicalId, `Duplicate task #${req.params.id} was archived and linked here.`, {
      author: req.opsUser || 'dashboard',
      visibility: isOneTimeProjectKey(canonical?.project_key) ? 'project' : 'internal',
      metadata: { action: 'canonical_duplicate_linked', duplicate_task_id: Number(req.params.id) },
    });
    return task;
  });
});

