app.post('/api/bna/tasks/:id/actions/choose-decision', requireAdmin, async (req, res) => {
  taskActionResponse(req, res, async () => {
    const current = await fetchTaskWithProject(req.params.id);
    if (!current) {
      const error = new Error('Task not found');
      error.statusCode = 404;
      throw error;
    }
    const optionLabel = String(req.body?.option_label || req.body?.label || 'Chosen option').slice(0, 160);
    const optionValue = String(req.body?.option_value || req.body?.value || '').slice(0, 1000);
    const decisionLine = `Decision chosen: ${optionLabel}${optionValue ? ` - ${optionValue}` : ''}`;
    const workRemains = Boolean(req.body?.work_remains || req.body?.workRemains || req.body?.assigned_to || req.body?.agent_executable);
    const assignedTo = normalizeTaskAssignee(req.body?.assigned_to || req.body?.assignedTo || (req.body?.agent_executable ? 'Codex' : 'Shloimie'));
    const updates = workRemains
      ? {
        item_type: 'task',
        task_kind: isAgentAssignee(assignedTo) ? 'agent_job' : 'task',
        stage: 'assigned',
        assigned_to: assignedTo,
        waiting_on: null,
        decision_required: false,
        agent_status: isAgentAssignee(assignedTo) ? 'queued' : 'none',
        notes: [current.notes, decisionLine, req.body?.notes].filter(Boolean).join('\n\n'),
        verification_notes: decisionLine,
        next_action_label: isAgentAssignee(assignedTo) ? 'Agent working' : 'Start task',
        next_action: isAgentAssignee(assignedTo) ? 'Watch agent job status' : 'Start the next task step',
      }
      : {
        stage: 'done',
        task_kind: 'history',
        completed_at: new Date().toISOString(),
        verified_at: new Date().toISOString(),
        decision_required: false,
        agent_status: 'completed',
        notes: [current.notes, decisionLine, req.body?.notes].filter(Boolean).join('\n\n'),
        verification_notes: decisionLine,
        next_action_label: 'Decision resolved',
        next_action: 'Review completed result',
      };
    const task = await patchTaskAndReturn(req.params.id, updates, {
      actor: req.opsUser || 'dashboard',
      eventType: 'decision_chosen',
      eventSummary: decisionLine,
    });
    await pool.query(
      `INSERT INTO bna_task_comments (task_id, author, body, visibility, source, source_context)
       VALUES ($1, $2, $3, $4, 'system', $5::jsonb)`,
      [
        req.params.id,
        req.opsUser || 'dashboard',
        decisionLine,
        isOneTimeProjectKey(current?.project_key) ? 'project' : 'workspace',
        JSON.stringify({ action: 'choose_decision', option_label: optionLabel, option_value: optionValue }),
      ]
    );
    if (workRemains && isAgentAssignee(assignedTo)) await ensureAgentJobForTask(task, { agent_executable: true, source: 'choose_decision' });
    if (!workRemains) await updateLatestAgentJobForTask(req.params.id, 'completed', { result_summary: decisionLine });
    return task;
  });
});

// Database migration endpoint
app.post('/api/bna/migrate-db', requireAdmin, async (req, res) => {
  const MIGRATION_SQL = `
    DROP TABLE IF EXISTS bna_payment_log CASCADE;
    DROP TABLE IF EXISTS bna_tasks CASCADE;
    DROP TABLE IF EXISTS signups CASCADE;
    
    CREATE TABLE signups (
      id SERIAL PRIMARY KEY,
      parent_name TEXT NOT NULL,
      parent_email TEXT,
      parent_phone TEXT,
      student_name TEXT NOT NULL,
      student_age INTEGER,
      student_grade TEXT,
      previous_school TEXT,
      reason_applying TEXT,
      special_needs TEXT,
      payment_method TEXT DEFAULT 'green_invoice',
      payment_status TEXT DEFAULT 'pending',
      payment_amount DECIMAL(10,2),
      payment_currency TEXT DEFAULT 'ILS',
      green_invoice_id TEXT,
      cash_receipt_photo_url TEXT,
      cash_received_at TIMESTAMP,
      cash_notes TEXT,
      form_language TEXT DEFAULT 'en',
      waiver_accepted BOOLEAN DEFAULT FALSE,
      waiver_accepted_at TIMESTAMP,
      waiver_version TEXT,
      tuition_agreement_accepted BOOLEAN DEFAULT FALSE,
      tuition_agreement_accepted_at TIMESTAMP,
      tuition_agreement_version TEXT,
      tuition_agreement_signer_name TEXT,
      tuition_agreement_signer_email TEXT,
      tuition_agreement_client_signed_at TIMESTAMP,
      legacy_crm_parent_contact_id TEXT,
      legacy_crm_student_contact_id TEXT,
      legacy_crm_synced_at TIMESTAMP,
      legacy_crm_sync_error TEXT,
      status TEXT DEFAULT 'new',
      tags TEXT[] DEFAULT '{}',
      notes TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE bna_signup_agreement_signatures (
      id SERIAL PRIMARY KEY,
      signup_id INTEGER NOT NULL REFERENCES signups(id) ON DELETE CASCADE,
      agreement_type TEXT NOT NULL,
      agreement_title TEXT NOT NULL,
      agreement_version TEXT NOT NULL,
      agreement_text TEXT,
      signer_name TEXT NOT NULL,
      signer_email TEXT,
      signed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      client_signed_at TIMESTAMP,
      ip_address TEXT,
      user_agent TEXT,
      metadata JSONB DEFAULT '{}',
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      UNIQUE (signup_id, agreement_type, agreement_version)
    );
    
    CREATE TABLE bna_tasks (
      id SERIAL PRIMARY KEY,
      title TEXT NOT NULL,
      notes TEXT,
      stage TEXT DEFAULT 'raw_input' CHECK (stage IN ('raw_input', 'needs_decision', 'assigned', 'in_progress', 'done', 'archive')),
      category TEXT DEFAULT 'operations' CHECK (category IN ('admin', 'marketing', 'parent_coaching', 'student_operations', 'finance', 'legal', 'communications', 'operations', 'accountability', 'content', 'technology', 'accounting', 'community_setup', 'community', 'general', 'torah_class_prep', 'torah_research', 'source_sheets', 'shiur_ideas')),
      urgency TEXT DEFAULT 'this_week' CHECK (urgency IN ('urgent', 'today', 'this_week', 'low')),
      energy_required TEXT CHECK (energy_required IN ('high', 'medium', 'low')),
      estimated_minutes INTEGER,
      due_date DATE,
      planned_at TIMESTAMP,
      started_at TIMESTAMP,
      completed_at TIMESTAMP,
      archived_at TIMESTAMP,
      source TEXT DEFAULT 'manual',
      source_context TEXT,
      ai_parsed JSONB,
      parent_task_id INTEGER REFERENCES bna_tasks(id),
      related_contact_email TEXT,
      related_signup_id INTEGER,
      created_by TEXT DEFAULT 'system',
      assigned_to TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
    
    CREATE TABLE bna_payment_log (
      id SERIAL PRIMARY KEY,
      signup_id INTEGER REFERENCES signups(id) ON DELETE CASCADE,
      payment_type TEXT DEFAULT 'registration',
      amount DECIMAL(10,2) NOT NULL,
      currency TEXT DEFAULT 'ILS',
      method TEXT,
      green_invoice_id TEXT,
      green_invoice_url TEXT,
      receipt_photo_url TEXT,
      received_by TEXT,
      received_at TIMESTAMP,
      notes TEXT,
      status TEXT DEFAULT 'completed',
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
    
    INSERT INTO bna_tasks (title, stage, category, urgency, source) 
    VALUES ('Welcome to BNA Operations. Telegram rambles land here as raw input.', 'raw_input', 'operations', 'this_week', 'manual');
  `;
  
  try {
    await pool.query(MIGRATION_SQL);
    await pool.query(createProjectsSQL);
    await pool.query(createProjectMembersSQL);
    await pool.query(createWorkspacePlatformSQL);
    await pool.query(createWorkspaceAccountsSQL);
    await pool.query(createWorkspaceIntegrationsSQL);
    await pool.query(createProjectBrandingSQL);
    await pool.query(createContactIdentityAuditSQL);
    await pool.query(createWorkspaceNotesSQL);
    await pool.query(createWorkspaceNoteItemsSQL);
    await pool.query(createStudentsSQL);
    await pool.query(createLearningCommunitiesSQL);
    await pool.query(createStudentPortalAuthAttemptsSQL);
    await pool.query(createStudentPasswordAuthSQL);
    await pool.query(createStudentBotSettingsSQL);
    await pool.query(createParentMagicLinksSQL);
    await pool.query(createParentPasswordAccountsSQL);
    await pool.query(createParentSessionsSQL);
    await pool.query(createTaskCommentsSQL);
    await pool.query(createTaskWorkflowExtensionsSQL);
    await pool.query(createAgentJobsSQL);
    await pool.query(createAgentControlSQL);
    await pool.query(createTaskEventsSQL);
    await pool.query(createSupportTicketsSQL);
    await pool.query(createTicketCompatibilityViewsSQL);
    await pool.query(createAssistantSQL);
    await pool.query(createContentJobsSQL);
    await pool.query(createProjectMeetingsSQL);
    await pool.query(createClassSessionsSQL);
    await pool.query(createOneTimeQuestionReviewsSQL);
    await pool.query(createOneTimeMemberLibrarySQL);
    await pool.query(createLiveClassInfrastructureSQL);
    await pool.query(createRabbiCheckoutAccessSQL);
    await pool.query(createOneTimeProductSystemSQL);
    await pool.query(createOneTimeTrialReferralConfigSQL);
    await pool.query(createServiceProviderStudioSQL);
    await pool.query(createServiceProvidersSQL);
    if (createServiceProviderScopesSQL) await pool.query(createServiceProviderScopesSQL);
    await pool.query(createProviderIndexMvpSQL);
    await pool.query(createCommunicationsIntegrationsSQL);
    await pool.query(createAssignmentPromptsSQL);
    await pool.query(createAssignmentPromptVersionsSQL);
    await pool.query(createAssignmentsSQL);
    await pool.query(createAssignmentStudentsSQL);
    await pool.query(createCliBridgeSQL);
    await pool.query(createInAppNotificationsSQL);
    await pool.query(createSessionsSQL);
    await pool.query(createOpsAccessLinksSQL);
    await pool.query(createSecureDownloadsSQL);
    await pool.query(createAgentReviewSessionsSQL);
    await pool.query(createBnaIndexesSQL);
    await pool.query(createWorkspaceLinkedColumnsSQL);
    await pool.query(createIdentityLinkingCompatibilitySQL);
    await pool.query(createWs11CommunityGamificationSQL);
    await pool.query(normalizeTasksCategoryCheckSQL);
    await pool.query(normalizeTasksStageCheckSQL);
    await pool.query(normalizeTasksSourceCheckSQL);
    await ensureDefaultProjects();
    await ensureDefaultLearningCommunity();
    await ensureWs11CommunityFoundation();
    await ensureDefaultServiceProviderDirectoryOnce();
    await backfillProviderIndexSlugs();
    res.json({ success: true, message: 'Database migrated to BNA schema!' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Login endpoint for operations
app.post('/api/operations/login', async (req, res) => {
  const { username, password } = req.body;
  const returnTo = String((req.body || {}).returnTo || (req.body || {}).return_to || '/operations');
  const rateStatus = opsLoginRateStatus(req, username);
  if (rateStatus.blocked) {
    const retryAfterSeconds = Math.max(1, Math.ceil((rateStatus.reset_at - Date.now()) / 1000));
    res.setHeader('Retry-After', String(retryAfterSeconds));
    return res.status(429).json({ success: false, error: 'Too many login attempts. Try again shortly.' });
  }

  const identity = identifyOpsUser(username, password);
  if (identity) {
    clearOpsLoginRate(req, username);
    const sessionId = await issueSession(identity.username);
    setSessionCookie(res, sessionId);
    res.json({
      success: true,
      sessionId,
      user: identity.username,
      role: identity.role,
      scope: identity.scope,
      allowedViews: identity.allowedViews,
    });
  } else {
    const destinations = (await collectPortalLoginDestinations({ username, password }))
      .filter((destination) => destination.portal !== 'operations');
    if (destinations.length > 1) {
      clearOpsLoginRate(req, username);
      return res.json({
        success: true,
        chooser_required: true,
        message: 'Choose which portal or workspace to open.',
        destinations: destinations.map((destination) => publicPortalDestination(destination, returnTo)),
      });
    }
    if (destinations.length === 1) {
      clearOpsLoginRate(req, username);
      const destination = destinations[0];
      const payload = await issuePortalDestinationSession(destination, res, { returnTo });
      return res.json({
        success: true,
        portal_redirect: true,
        role: destination.role,
        destination: publicPortalDestination(destination, returnTo),
        redirect_to: payload.redirect_to,
      });
    }
    recordOpsLoginFailure(req, username);
    clearSessionCookie(res);
    res.status(401).json({ success: false, error: 'Invalid credentials' });
  }
});

