async function handleTelegramCallback(query) {
  const chatId = query.message?.chat?.id;
  const data = query.callback_data;
  
  // Answer callback
  await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/answerCallbackQuery`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ callback_query_id: query.id })
  });

  const dashboardUrl = 'https://bneineviimacademy.org/operations';
  const replies = {
    view_inbox: `Tasks:\n${dashboardUrl}?view=tasks`,
    view_urgent: `Tasks needing attention:\n${dashboardUrl}?view=tasks`,
    view_pipeline: `Tasks: Decisions, Pending, Tasks, Calendar, and Done.\n${dashboardUrl}?view=tasks`,
    quick_add: 'Quick add: send a task or ramble in this chat. I will capture it into BNA Operations.',
    view_billing: `Accounting:\n${dashboardUrl}?view=accounting`,
    view_signups: `Contacts:\n${dashboardUrl}?view=contacts`,
    view_accountability: `Students:\n${dashboardUrl}?view=students`,
  };

  if (replies[data]) {
    await sendTelegramMessage(chatId, replies[data]);
    return;
  }
}

async function handleTelegramMessage(msg) {
  const chatId = msg.chat?.id;
  const text = msg.text || msg.caption || '';
  
  if (text === '/start') {
    await sendTelegramMenu(chatId);
    return;
  }
  
  try {
    const capture = await captureIncomingBotMessage({
      text,
      source: 'telegram',
      source_channel: 'telegram',
      source_chat_id: chatId,
      source_message_id: msg.message_id,
      source_message_created_at: msg.date ? new Date(Number(msg.date) * 1000).toISOString() : null,
      message_type: msg.text ? 'text' : 'caption',
      raw_update: msg,
      created_by: 'telegram',
    }, { parser: 'telegram-webhook-observable-v1' });
    await sendTelegramMessage(chatId, capture.reply || 'Created ticket.');
  } catch (err) {
    console.error('Telegram task capture error:', err);
    await sendTelegramMessage(chatId, `Captured the message, but the observable ticket flow hit a blocker: ${err.message || String(err)}`);
  }
  return;
  
  // Simple task parsing
  if (text.toLowerCase().includes('urgent') || text.toLowerCase().includes('asap')) {
    await sendTelegramMessage(chatId, `ðŸ”´ Got it! Urgent task recorded: "${text}"\n\nView in dashboard: https://bneineviimacademy.org/operations`);
  } else {
    await sendTelegramMessage(chatId, `âœ… Task recorded: "${text}"\n\nView in dashboard: https://bneineviimacademy.org/operations`);
  }
}

async function sendTelegramMenu(chatId) {
  const keyboard = {
    inline_keyboard: [
      [{ text: 'Tasks', callback_data: 'view_pipeline' }, { text: 'Students', callback_data: 'view_accountability' }],
      [{ text: 'Content', url: 'https://bneineviimacademy.org/operations?view=content' }],
      [{ text: 'Contacts', callback_data: 'view_signups' }, { text: 'Accounting', callback_data: 'view_billing' }],
      [{ text: 'Open Operations', url: 'https://bneineviimacademy.org/operations' }]
    ]
  };

  await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: chatId,
      text: 'BNA Operations Bot\n\nWhat would you like to do?',
      reply_markup: keyboard
    })
  });
}

async function sendTelegramMessage(chatId, text) {
  if (!TELEGRAM_BOT_TOKEN || !chatId) return;
  
  await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: chatId,
      text: text,
      parse_mode: 'HTML'
    })
  });
}

